pub const NativeWindow = struct {
    instance: *anyopaque,
    window: *anyopaque,
    width: u32,
    height: u32,
};

pub const Options = struct {
    enable_validation: bool = builtin.mode == .Debug,
    /// Diagnostic-only fixed shaders used to prove the DCB graphics submission
    /// and color-target path before guest vertex/pixel lowering is connected.
    enable_graphics_probe: bool = false,
    /// One-shot diagnostic readback after the first guest graphics draw.
    /// Disabled by default because a 4K target costs roughly 32 MiB of PCIe
    /// traffic and a queue synchronization.
    capture_first_graphics_frame: bool = false,
    /// Expensive per-draw readback and PPM capture for one selected guest
    /// frame. Kept opt-in because a busy 4K frame can transfer several GiB.
    trace_graphics_frame: ?u64 = null,
    /// Replaces translated guest pixel shaders with an opaque diagnostic
    /// colour while retaining the guest target and pipeline state.
    force_probe_fragment: bool = false,
    /// Replaces a guest pixel shader with a minimal sample from its first T#/S#
    /// binding. This separates texture staging/sampling from guest PS ALU.
    force_probe_fragment_texture: bool = false,
    /// Displays PARAM0 directly, separating vertex export/interpolation from
    /// fragment texture sampling and ALU.
    force_probe_fragment_parameter: bool = false,
    /// Samples with PARAM1.xy and multiplies by PARAM0. This mirrors the common
    /// Unity UI pixel path while omitting its constant-buffer and packed-export
    /// tail, making those two halves independently diagnosable.
    force_probe_fragment_ui: bool = false,
    /// Diagnostic fast path for graphics bring-up. Command processing and
    /// draws continue, but guest compute dispatches are not submitted.
    skip_compute_dispatches: bool = false,
    /// Suppresses only the bounded startup interval. Unlike the diagnostic
    /// all-frame switch, complete compute rendering resumes automatically.
    skip_compute_until_flip: u64 = 0,
    /// Diagnostic bisection aid: execute at most this many guest compute
    /// dispatches, then keep command processing without submitting later ones.
    compute_execution_limit: ?u64 = null,
    /// Diagnostic fast path for UI/input bring-up. One complete frame out of
    /// every sixteen is rendered while command processing and guest logic keep
    /// advancing. Full rendering resumes at the bounded handoff so gameplay
    /// does not keep dropping its render-to-texture work.
    sparse_graphics_draws: bool = false,
    /// Translates guest compute programs and prepares their resources without
    /// submitting them to Vulkan. This isolates translation and binding gaps
    /// from GPU execution faults while preserving later command processing.
    translate_compute_only: bool = false,
    /// Diagnostic device override for systems with both discrete and integrated
    /// Vulkan adapters.
    prefer_integrated_gpu: bool = false,
    /// Writes NVIDIA-guarded compute modules to `out` for offline validation.
    dump_compute_spirv: bool = false,
    /// Writes translated guest graphics modules to `out` for offline validation.
    dump_graphics_spirv: bool = false,
    /// Extends automatic PPM checkpoints beyond the small startup set. This is
    /// diagnostic I/O and remains opt-in for normal game runs.
    capture_extended_progress_frames: bool = false,
    /// Emits runtime shaders through the typed RDNA2 IR. When disabled the
    /// decoded-instruction SPIR-V backend remains the executable path.
    enable_shader_ir: bool = false,
    /// Experimental shader SSA/constant-fold/DCE emission. Disabled for live
    /// titles until implicit RDNA2 register effects are fully represented.
    enable_shader_ssa_optimization: bool = false,
    /// Runs first-use Vulkan pipeline creation on the compiler worker.
    enable_async_pipeline_compilation: bool = false,
    /// Tracks overlapping image caches and selects one canonical writer.
    enable_canonical_image_aliases: bool = false,
    /// Allows multiple Vulkan submissions to remain in flight and retires
    /// their transient resources by timeline tick. Compatibility mode waits
    /// for each submitted tick before continuing.
    enable_timeline_scheduler: bool = false,
    /// Keeps even small compute outputs GPU-authoritative until an exact guest
    /// consumer requests them. The compatibility default eagerly publishes
    /// small control buffers after dispatch.
    defer_small_storage_writes: bool = false,
    /// Imports and writes back single-sample guest depth/stencil allocations.
    enable_depth_transfer: bool = false,
    /// Enables read-only barrier elision and compatible aspect merging in the
    /// subresource image-state tracker. The default keeps conservative hazards.
    enable_image_state_optimization: bool = false,
    /// Optional Win32 output window. Supplying it enables the required surface
    /// and swapchain extensions and constrains device selection to a queue that
    /// can present to this exact surface.
    native_window: ?NativeWindow = null,
};

