const command_buffer_pending_tick = std.math.maxInt(u64);

// Guest vertex/constant ranges are highly transient. A bounded LRU avoids
// keeping hundreds of individual Vulkan allocations alive after the title has
// moved its ring buffers on, while still covering every descriptor in a draw.
const maximum_guest_buffers = maximum_storage_descriptors;
pub const maximum_storage_descriptors = 64;
const maximum_storage_images = rdna2.spirv.maximum_storage_images;
const dynamic_scalar_descriptor_binding = 2 + maximum_storage_images;
const sampled_image_3d_descriptor_binding = dynamic_scalar_descriptor_binding + 1;
const sampled_image_cube_descriptor_binding = dynamic_scalar_descriptor_binding + 2;
const sampled_image_2d_array_descriptor_binding = dynamic_scalar_descriptor_binding + 3;
const gds_descriptor_binding = sampled_image_2d_array_descriptor_binding + 1;
const dynamic_scalar_words_per_stage = gpu.scalar_provenance.maximum_scalar_specializations;
const dynamic_scalar_buffer_words = dynamic_scalar_words_per_stage * 2;
const dynamic_scalar_buffer_bytes = dynamic_scalar_buffer_words * @sizeOf(u32);
/// Descriptor contents are consumed when the queued command executes, not
/// when it is recorded. Give every graphics draw its own set and scalar slice
/// so a later draw can prepare state while the earlier commands remain queued.
/// Larger frames are split only when this ring wraps. Keep enough slots for
/// draw-heavy 2D titles such as Jets 'n' Guns 2, which regularly exceeds 256
/// draws in one guest frame.
const maximum_frame_descriptor_sets = 512;
const descriptor_scalar_stride = std.mem.alignForward(usize, dynamic_scalar_buffer_bytes, 256);
const descriptor_scalar_ring_bytes = descriptor_scalar_stride * maximum_frame_descriptor_sets;
const gds_slot_bytes = 64 * 1024;
const gds_ring_bytes = gds_slot_bytes * maximum_frame_descriptor_sets;
/// Read-only vertex/constant ranges are copied into one persistently mapped
/// per-frame arena. It snapshots guest data for queued draws without creating
/// and freeing one Vulkan allocation per binding.
// REANIMAL's steady frame has about 247 MiB of unique read-only vertex and
// constant ranges (two 96 MiB buffers, one 48 MiB buffer, plus small tables).
// A 128 MiB arena wrapped in the middle of every draw, cleared its exact-range
// cache, and copied that same working set about five times per frame. Keep one
// complete modern-frame working set so repeated bindings remain snapshots.
const draw_upload_ring_bytes = 256 * 1024 * 1024;
const draw_upload_alignment = 256;
const maximum_async_command_buffers = 512;
const maximum_storage_mappings = 1024;

fn reserveAlignedRange(cursor: *usize, capacity: usize, bytes: usize, alignment: usize) ?usize {
    if (bytes == 0 or bytes > capacity) return null;
    const offset = std.mem.alignForward(usize, cursor.*, alignment);
    const end = std.math.add(usize, offset, bytes) catch return null;
    if (end > capacity) return null;
    cursor.* = end;
    return offset;
}
/// Modern Unity titles specialize hundreds of compute kernels during scene
/// bootstrap. Keep those pipelines resident instead of stopping the DCB queue
/// as soon as the initial 256-entry bring-up bound is reached.
const maximum_compute_pipelines = 2048;
/// Titles that specialize transform and colour constants reach thousands of
/// shader variants in seconds: Terminator 2D passes six thousand within a
/// minute of play. At 256 the cache recycled entries the next frame needed and
/// every draw paid a driver compile. The bound stays large until those
/// constants stop being specialized, at which point a title needs one pipeline
/// per program and this can come back down.
const maximum_graphics_pipelines = 8192;
/// Distinct guest shader programs kept in decoded form.
const maximum_analyzed_programs = 512;
/// Shader headers put an exact bound around modern generated programs. Keep a
/// conservative fallback for headerless captures, while permitting large UE
/// material shaders when their AGC allocation proves the read is safe.
const headerless_shader_instruction_limit = 4096;
const maximum_shader_code_bytes = 1024 * 1024;
const maximum_shader_instructions = maximum_shader_code_bytes / @sizeOf(u32);
const maximum_staged_buffer_bytes = 128 * 1024 * 1024;
/// Large compute outputs are overwhelmingly GPU-only working sets. Reading
/// them over PCIe after every dispatch serializes work that remains resident
/// on the console; keep those allocations authoritative until an actual guest
/// or resource read needs their bytes.
// Large UAV outputs are normally consumed by later GPU work. Keeping them
// resident avoids a device -> guest -> device round trip on every frame while
// smaller control/label buffers retain eager CPU visibility. Cat Quest III's
// recurring generated-geometry buffer is 640 KiB, so a 1 MiB cutoff missed
// the dominant transfer despite already having exact-address readback paths.
const deferred_storage_write_min_bytes = 256 * 1024;
const maximum_frame_bytes = 128 * 1024 * 1024;
const maximum_completed_frames = 16;
// Unreal's post-processing graph keeps dozens of transient color attachments
// live in one frame (Tetris Effect reaches 42 before its second flip). Keeping
// only 16 forced GPU -> CPU -> tiled guest-memory -> GPU round trips while an
// attachment was still part of the active graph. A 64-entry working set keeps
// those targets resident and lets the existing direct sampled-target path bind
// the same Vulkan image for the next pass.
const maximum_render_targets = 64;
const maximum_color_passes = 16;
const maximum_depth_targets = 16;
const maximum_sampled_images = maximum_storage_descriptors;
const maximum_compute_sampled_mappings = 256;
// Descriptor arrays are limited per shader, but the cross-draw texture cache
// must cover a complete modern frame. Tying cache capacity to the 32 live
// descriptor slots evicts large static textures before their next use and
// uploads them again on every flip.
const maximum_cached_sampled_images = 1024;
/// Storage images form long compute chains in modern Unity render graphs. A
/// dispatch may write one image only for the next dispatch to read it; keeping
/// those images resident avoids a GPU -> tiled guest memory -> GPU round trip
/// at every edge of the graph. Ghost of Yotei's first steady render graph uses
/// 94 distinct views (about 920 MiB of linear image data); the old 64-view cap
/// evicted half of that graph and re-detiled/re-uploaded roughly 814 MiB every
/// frame. These are capacity ceilings, not eager allocations.
const maximum_cached_storage_images = 128;
/// Counts linear image bytes (the cache also owns one transfer allocation per
/// image). The limit is soft while every resident entry is in use by the same
/// dispatch, so a legal 32-image descriptor set is never rejected solely by
/// the cache budget. Leave headroom above Yotei's measured 920 MiB set for
/// alignment and short-lived views without turning transient churn into an
/// unbounded cache.
const maximum_cached_storage_image_bytes = 1280 * 1024 * 1024;
/// One DCC key byte covers this many bytes of the compressed colour surface.
const dcc_block_bytes = 256;
/// Bounds the key read for a fast-clear probe; covers surfaces up to 1 GiB.
const maximum_dcc_key_bytes = 4 * 1024 * 1024;
/// CMASK is one nibble per 8x8 pixel region; this cap covers extremely large
/// render targets while rejecting corrupt descriptors before allocation.
const maximum_cmask_bytes = 4 * 1024 * 1024;
/// HTILE is one dword per 8x8 region. This cap covers depth arrays far larger
/// than the current attachment path while rejecting corrupt dimensions.
const maximum_htile_bytes = 8 * 1024 * 1024;
/// On-disk driver pipeline cache. Reused across runs so per-title shader
/// compilation is paid once instead of on every launch.
const pipeline_cache_path = "vulkan_pipeline_cache.bin";
/// Sanity cap: a pipeline cache payload this large is not ours.
const maximum_pipeline_cache_bytes = 64 * 1024 * 1024;

/// Reads the persisted driver pipeline cache, if any. Any failure — missing
/// file, unreadable file, unreasonable size — returns null; the caller then
/// creates an empty cache and saves over it later.
fn loadPipelineCacheBytes(allocator: std.mem.Allocator) ?[]u8 {
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const file = std.Io.Dir.cwd().openFile(io, pipeline_cache_path, .{}) catch return null;
    defer file.close(io);
    const size = file.length(io) catch return null;
    if (size == 0 or size > maximum_pipeline_cache_bytes) return null;
    const bytes = allocator.alloc(u8, @intCast(size)) catch return null;
    errdefer allocator.free(bytes);
    const read = file.readPositionalAll(io, bytes, 0) catch return null;
    if (read != bytes.len) return null;
    return bytes;
}

/// Writes the current driver pipeline cache to disk. Failure is deliberately
/// silent: a cache is an optimization, and losing it only costs compilation
/// time on the next run.
fn savePipelineCacheBytes(self: *Renderer) void {
    var data_size: usize = 0;
    if (self.device_functions.get_pipeline_cache_data(self.device, self.driver_pipeline_cache, &data_size, null) != vk.success) {
        return;
    }
    if (data_size == 0 or data_size > maximum_pipeline_cache_bytes) return;
    const bytes = self.allocator.alloc(u8, data_size) catch return;
    defer self.allocator.free(bytes);
    if (self.device_functions.get_pipeline_cache_data(self.device, self.driver_pipeline_cache, &data_size, bytes.ptr) != vk.success) {
        return;
    }
    var threaded = std.Io.Threaded.init(self.allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const file = std.Io.Dir.cwd().createFile(io, pipeline_cache_path, .{ .truncate = true }) catch return;
    defer file.close(io);
    file.writePositionalAll(io, bytes, 0) catch return;
}

