const GraphicsPipelineState = extern struct {
    width: u32,
    height: u32,
    color_attachment_count: u32,
    color_attachment_formats: [gpu.resources.color_target_count]u32,
    topology: u32,
    viewport_x_bits: u32,
    viewport_y_bits: u32,
    viewport_width_bits: u32,
    viewport_height_bits: u32,
    viewport_min_depth_bits: u32,
    viewport_max_depth_bits: u32,
    scissor_x: i32,
    scissor_y: i32,
    scissor_width: u32,
    scissor_height: u32,
    cull_mode: u32,
    front_face: u32,
    rasterizer_discard: u32,
    color_write_masks: [gpu.resources.color_target_count]u32,
    blend_enables: [gpu.resources.color_target_count]u32,
    source_color_blend_factors: [gpu.resources.color_target_count]u32,
    destination_color_blend_factors: [gpu.resources.color_target_count]u32,
    color_blend_operations: [gpu.resources.color_target_count]u32,
    source_alpha_blend_factors: [gpu.resources.color_target_count]u32,
    destination_alpha_blend_factors: [gpu.resources.color_target_count]u32,
    alpha_blend_operations: [gpu.resources.color_target_count]u32,
    /// Zero when the draw has no depth attachment. A pipeline is only
    /// compatible with a render pass that agrees about depth, so this belongs
    /// in the cache key.
    depth_attachment_format: u32,
    depth_test_enable: u32,
    depth_write_enable: u32,
    depth_compare_operation: u32,
    /// Non-zero when the draw is a rectangle list and the pipeline carries the
    /// stage that completes its missing corner. Both this and the varyings
    /// that stage forwards belong in the key, because they change the pipeline.
    rectangle_completion: u32,
    rectangle_parameter_mask: u32,
    /// Vulkan sample-count flag for the pass. Colour and depth attachments of
    /// one draw share this value.
    rasterization_samples: u32,
    stencil_test_enable: u32,
    stencil_front_fail: u32,
    stencil_front_pass: u32,
    stencil_front_depth_fail: u32,
    stencil_front_compare: u32,
    stencil_front_compare_mask: u32,
    stencil_front_write_mask: u32,
    stencil_front_reference: u32,
    stencil_back_fail: u32,
    stencil_back_pass: u32,
    stencil_back_depth_fail: u32,
    stencil_back_compare: u32,
    stencil_back_compare_mask: u32,
    stencil_back_write_mask: u32,
    stencil_back_reference: u32,

    fn default(width: u32, height: u32) GraphicsPipelineState {
        return .{
            .width = width,
            .height = height,
            .color_attachment_count = 1,
            .color_attachment_formats = .{ vk.format_r8g8b8a8_unorm, 0, 0, 0, 0, 0, 0, 0 },
            .topology = vk.primitive_topology_triangle_list,
            .rectangle_completion = 0,
            .rectangle_parameter_mask = 0,
            .viewport_x_bits = @bitCast(@as(f32, 0)),
            .viewport_y_bits = @bitCast(@as(f32, 0)),
            .viewport_width_bits = @bitCast(@as(f32, @floatFromInt(width))),
            .viewport_height_bits = @bitCast(@as(f32, @floatFromInt(height))),
            .viewport_min_depth_bits = @bitCast(@as(f32, 0)),
            .viewport_max_depth_bits = @bitCast(@as(f32, 1)),
            .scissor_x = 0,
            .scissor_y = 0,
            .scissor_width = width,
            .scissor_height = height,
            .cull_mode = 0,
            .front_face = 1,
            .rasterizer_discard = 0,
            .color_write_masks = .{ vk.color_component_rgba_bits, 0, 0, 0, 0, 0, 0, 0 },
            .blend_enables = @splat(0),
            .source_color_blend_factors = @splat(0),
            .destination_color_blend_factors = @splat(0),
            .color_blend_operations = @splat(0),
            .source_alpha_blend_factors = @splat(0),
            .destination_alpha_blend_factors = @splat(0),
            .alpha_blend_operations = @splat(0),
            .depth_attachment_format = 0,
            .depth_test_enable = 0,
            .depth_write_enable = 0,
            .depth_compare_operation = 0,
            .rasterization_samples = vk.sample_count_1_bit,
            .stencil_test_enable = 0,
            .stencil_front_fail = 0,
            .stencil_front_pass = 0,
            .stencil_front_depth_fail = 0,
            .stencil_front_compare = 0,
            .stencil_front_compare_mask = 0,
            .stencil_front_write_mask = 0,
            .stencil_front_reference = 0,
            .stencil_back_fail = 0,
            .stencil_back_pass = 0,
            .stencil_back_depth_fail = 0,
            .stencil_back_compare = 0,
            .stencil_back_compare_mask = 0,
            .stencil_back_write_mask = 0,
            .stencil_back_reference = 0,
        };
    }
};

const ComputePipelineCompileJob = struct {
    job: pipeline_compiler.Job = .{ .run = run },
    renderer: *Renderer,
    words: []const u32,
    shader: vk.ShaderModule = 0,
    pipeline: vk.Pipeline = 0,
    failure: ?Error = null,

    fn run(base: *pipeline_compiler.Job) void {
        const work: *@This() = @fieldParentPtr("job", base);
        work.shader = work.renderer.createShader(work.words) catch |err| {
            work.failure = err;
            return;
        };
        const stage = vk.PipelineShaderStageCreateInfo{
            .stage = vk.shader_stage_compute_bit,
            .module = work.shader,
            .name = "main",
        };
        const info = vk.ComputePipelineCreateInfo{
            .stage = stage,
            .layout = work.renderer.compute_pipeline_layout,
        };
        if (work.renderer.device_functions.create_compute_pipelines(
            work.renderer.device,
            0,
            1,
            @ptrCast(&info),
            null,
            @ptrCast(&work.pipeline),
        ) != vk.success) {
            work.renderer.device_functions.destroy_shader_module(work.renderer.device, work.shader, null);
            work.shader = 0;
            work.failure = Error.ComputePipelineCreationFailed;
        }
    }
};

const GraphicsPipelineCompileJob = struct {
    job: pipeline_compiler.Job = .{ .run = run },
    renderer: *Renderer,
    render_pass: vk.RenderPass,
    state: GraphicsPipelineState,
    vertex_words: []const u32,
    fragment_words: []const u32,
    pipeline: vk.Pipeline = 0,
    failure: ?Error = null,

    fn run(base: *pipeline_compiler.Job) void {
        const work: *@This() = @fieldParentPtr("job", base);
        work.pipeline = work.renderer.createGraphicsPipeline(
            work.render_pass,
            work.state,
            work.vertex_words,
            work.fragment_words,
        ) catch |err| {
            work.failure = err;
            return;
        };
    }
};

const ColorTargetFormat = struct {
    vulkan: u32,
    bytes_per_texel: u8,
};

const GuestColorTarget = struct {
    descriptor: gpu.resources.ColorTarget,
    layout: gpu.SurfaceLayout,
    format: ColorTargetFormat,
};

/// How a graphics packet wants geometry issued on the host.
const GuestDraw = struct {
    /// Non-indexed `DRAW_INDEX_AUTO` path (diagnostic triangle is count 3).
    vertex_count: u32 = 3,
    instance_count: u32 = 1,
    first_vertex: u32 = 0,
    first_instance: u32 = 0,
    /// Signed base-vertex applied to an indexed draw.
    vertex_offset: i32 = 0,
    /// When set, issue `vkCmdDrawIndexed` from guest memory at `index_address`.
    index_count: ?u32 = null,
    index_address: u64 = 0,
    /// `false` = UINT16, `true` = UINT32. AGC defaults to 16-bit indices.
    index_uint32: bool = false,
};

const maximum_guest_draw_elements: u32 = 1 << 28;
const maximum_guest_draw_instances: u32 = 1 << 20;

/// Rejects corrupted/stale indirect arguments before shader resource staging.
/// A multi-billion-element command cannot complete before the Windows GPU
/// watchdog and often makes the backend copy equally implausible descriptor
/// extents first. Zero-sized commands remain valid Vulkan no-ops.
fn guestDrawWithinExecutionLimits(draw: GuestDraw) bool {
    const elements = draw.index_count orelse draw.vertex_count;
    return elements <= maximum_guest_draw_elements and
        draw.instance_count <= maximum_guest_draw_instances;
}

fn guestPrimitiveTopology(primitive_type: u32, draw: GuestDraw) u32 {
    return switch (primitive_type) {
        1 => vk.primitive_topology_point_list,
        2 => vk.primitive_topology_line_list,
        3, 18 => vk.primitive_topology_line_strip,
        5 => vk.primitive_topology_triangle_fan,
        6 => vk.primitive_topology_triangle_strip,
        // PS5 NGG rectangle lists use a four-vertex auto draw as a host
        // triangle strip. Indexed and batched rectangle lists already carry
        // expanded triangle-list indices and must retain triangle-list order.
        7 => if (draw.index_count == null and draw.vertex_count <= 4)
            vk.primitive_topology_triangle_strip
        else
            vk.primitive_topology_triangle_list,
        17 => if (draw.index_count == null)
            vk.primitive_topology_triangle_strip
        else
            vk.primitive_topology_triangle_list,
        else => vk.primitive_topology_triangle_list,
    };
}

/// Prospero RECT_LIST auto draws describe one logical rectangle with counts
/// 1/3/4. The NGG/export shader uses the system vertex index to synthesize the
/// missing corner, so the host must actually invoke it four times. Completing
/// a fourth corner after the VS loses guest-computed position and UV logic.
fn expandRectangleListDraw(primitive_type: u32, draw: GuestDraw) GuestDraw {
    if (draw.index_count != null) return draw;
    var expanded = draw;
    if (primitive_type == 7 and
        (draw.vertex_count == 1 or draw.vertex_count == 3 or draw.vertex_count == 4))
    {
        expanded.vertex_count = 4;
    } else if (primitive_type == 17 and draw.vertex_count == 3) {
        expanded.vertex_count = 4;
    }
    return expanded;
}

fn rectangleCompletionMode(
    vertex_stage: gpu.resources.ShaderStage,
    primitive_type: u32,
    draw: GuestDraw,
    fullscreen_corner: bool,
) u32 {
    // Unity's merged NGG path sometimes submits three indexed corners as an
    // ordinary TRI_LIST even though the hardware is expected to complete the
    // rectangle. The resource-backed corner check is deliberately performed
    // by the caller; mode 2 completes the corner opposite v0.
    if (fullscreen_corner and vertex_stage == .export_shader and
        primitive_type == 4 and draw.index_count == 3)
    {
        return 2;
    }
    if (primitive_type == 7 or primitive_type == 17) {
        return @intFromBool(draw.index_count == null and draw.vertex_count == 3);
    }
    return 0;
}

/// Some graphics passes omit CB registers because the following VideoOut flip
/// names the scanout allocation. Preserve every draw and its complete state so
/// the pass can be replayed in order once that allocation is known.
const PendingGuestDraw = struct {
    state: gpu.State,
    draw: GuestDraw,
    vertex_stage: gpu.resources.ShaderStage,
};

const maximum_pending_targetless_draws: usize = 256;

/// The colour targets one frame's draws bound directly. It answers a single
/// question at flip time: did this frame already composite into the scanout
/// buffer itself? A frame binds far more attachments than this holds, so it
/// keeps the most recently bound ones -- the scanout composite is the end of
/// the frame, behind every G-buffer and post-process attachment, and an early
/// G-buffer address falling out is exactly what should be forgotten.
const BatchColorTargets = struct {
    const capacity = 32;

    addresses: [capacity]u64 = @splat(0),
    count: usize = 0,
    next: usize = 0,

    fn note(self: *BatchColorTargets, address: u64) void {
        if (address == 0 or self.contains(address)) return;
        self.addresses[self.next] = address;
        self.next = (self.next + 1) % capacity;
        self.count = @min(self.count + 1, capacity);
    }

    fn contains(self: *const BatchColorTargets, address: u64) bool {
        for (self.addresses[0..self.count]) |existing| {
            if (existing == address) return true;
        }
        return false;
    }

    fn reset(self: *BatchColorTargets) void {
        self.count = 0;
        self.next = 0;
    }
};

const ComputeShaderFailure = struct {
    address: u64,
    err: anyerror,
};

const GraphicsShaderFailure = struct {
    address: u64,
    stage: gpu.resources.ShaderStage,
    err: anyerror,
};

fn colorTargetFormat(descriptor: gpu.resources.ColorTarget) ?ColorTargetFormat {
    return switch (descriptor.format) {
        // DATA_FORMAT_8 + NUMBER_FORMAT_UNORM. Yotei uses R8 attachments for
        // its cubemap visibility mask and as the leading slots of two MRT
        // post-process passes. Dropping slot zero makes the complete draw look
        // targetless even though the remaining outputs are optional.
        1 => if (descriptor.number_type == 0)
            .{ .vulkan = vk.format_r8_unorm, .bytes_per_texel = 1 }
        else
            null,
        // DATA_FORMAT_16 + NUMBER_FORMAT_UINT. Unreal uses this as a full-size
        // integer render target before reading the same allocation through an
        // IMG_DATA_FORMAT_16_UINT texture descriptor.
        2 => switch (descriptor.number_type) {
            0 => .{ .vulkan = vk.format_r16_unorm, .bytes_per_texel = 2 },
            4 => .{ .vulkan = vk.format_r16_uint, .bytes_per_texel = 2 },
            7 => .{ .vulkan = vk.format_r16_sfloat, .bytes_per_texel = 2 },
            else => null,
        },
        // DATA_FORMAT_8_8. Yotei's G-buffer keeps a two-channel 4K plane next
        // to its ID and colour targets.
        3 => switch (descriptor.number_type) {
            0 => .{ .vulkan = vk.format_r8g8_unorm, .bytes_per_texel = 2 },
            4 => .{ .vulkan = vk.format_r8g8_uint, .bytes_per_texel = 2 },
            else => null,
        },
        // DATA_FORMAT_32. Yotei's object-ID plane is R32_UINT; the following
        // depth reconstruction samples it as unified format 20.
        4 => switch (descriptor.number_type) {
            4 => .{ .vulkan = vk.format_r32_uint, .bytes_per_texel = 4 },
            5 => .{ .vulkan = vk.format_r32_sint, .bytes_per_texel = 4 },
            7 => .{ .vulkan = vk.format_r32_sfloat, .bytes_per_texel = 4 },
            else => null,
        },
        // DATA_FORMAT_16_16. Yotei's G-buffer uses UNORM; deferred lighting
        // uses FLOAT for the same two-channel layout.
        5 => switch (descriptor.number_type) {
            0 => .{ .vulkan = vk.format_r16g16_unorm, .bytes_per_texel = 4 },
            7 => .{ .vulkan = vk.format_r16g16_sfloat, .bytes_per_texel = 4 },
            else => null,
        },
        // DATA_FORMAT_10_11_11. FLOAT is the native packing; Yotei also binds
        // NUMBER_FORMAT_UNORM on the same 32-bit layout, and Vulkan has no
        // 11-11-10 UNORM format, so keep the packed 32-bit attachment.
        6 => switch (descriptor.number_type) {
            0, 7 => .{ .vulkan = vk.format_b10g11r11_ufloat_pack32, .bytes_per_texel = 4 },
            else => null,
        },
        // DATA_FORMAT_10_10_10_2 + NUMBER_FORMAT_UNORM. COMP_SWAP is handled
        // in the fragment export epilogue while the packed byte layout stays
        // resident in one host image.
        9 => if (descriptor.number_type == 0)
            .{ .vulkan = vk.format_a2b10g10r10_unorm_pack32, .bytes_per_texel = 4 }
        else
            null,
        // DATA_FORMAT_8_8_8_8. Preserve the existing UNORM attachment path
        // for the number-type variants titles have already exercised.
        10 => .{ .vulkan = vk.format_r8g8b8a8_unorm, .bytes_per_texel = 4 },
        // DATA_FORMAT_16_16_16_16 + NUMBER_FORMAT_FLOAT.
        12 => if (descriptor.number_type == 7)
            .{ .vulkan = vk.format_r16g16b16a16_sfloat, .bytes_per_texel = 8 }
        else
            null,
        // DATA_FORMAT_32_32_32_32 + NUMBER_FORMAT_FLOAT. Unity uses this for
        // tiny exposure/luminance render targets that feed the final tonemap.
        14 => if (descriptor.number_type == 7)
            .{ .vulkan = vk.format_r32g32b32a32_sfloat, .bytes_per_texel = 16 }
        else
            null,
        else => null,
    };
}

const color_export_identity: u8 = 0xe4;

fn colorTargetComponentCount(format: u8) ?usize {
    return switch (format) {
        1, 2, 4 => 1,
        3, 5 => 2,
        6 => 3,
        9, 10, 12, 14 => 4,
        else => null,
    };
}

/// CB_COLOR_INFO.COMP_SWAP selects the logical fragment export placed in each
/// physical surface component. Unused selectors complete a permutation so the
/// same mapping can also translate CB_TARGET_MASK into Vulkan write-mask bits.
fn colorTargetExportMapping(descriptor: gpu.resources.ColorTarget) u8 {
    const component_count = colorTargetComponentCount(descriptor.format) orelse
        return color_export_identity;
    const mappings = [4][4]u8{
        .{ 0xe4, 0xe4, 0xe4, 0xe4 },
        .{ 0xe1, 0x6c, 0xb4, 0xc6 },
        .{ 0xc6, 0xe1, 0xc6, 0x1b },
        .{ 0x27, 0x63, 0x87, 0x93 },
    };
    return mappings[descriptor.component_swap][component_count - 1];
}

fn mapColorWriteMask(logical_mask: u8, mapping: u8) u32 {
    var physical_mask: u32 = 0;
    for (0..4) |physical| {
        const shift: u3 = @intCast(physical * 2);
        const logical: u2 = @truncate(mapping >> shift);
        physical_mask |= @as(u32, (logical_mask >> logical) & 1) << @intCast(physical);
    }
    return physical_mask;
}

/// The Vulkan attachment format for a guest depth plane.
///
/// DB_Z_INFO.FORMAT names the stored precision: 1 is sixteen-bit unorm and 3 is
/// thirty-two bit float. When an S8 stencil plane is bound the host uses a
/// packed depth+stencil format. D16+S8 is stored as D24_UNORM_S8 because that
/// pair is the one desktop devices actually expose as an attachment.
fn depthTargetFormat(descriptor: gpu.resources.DepthTarget) ?u32 {
    const has_stencil = descriptor.stencil_format == 1 and
        (descriptor.stencil_read_address != 0 or descriptor.stencil_write_address != 0);
    return switch (descriptor.format) {
        1 => if (has_stencil) vk.format_d24_unorm_s8_uint else vk.format_d16_unorm,
        3 => if (has_stencil) vk.format_d32_sfloat_s8_uint else vk.format_d32_sfloat,
        else => null,
    };
}

fn depthAttachmentHasStencil(format: u32) bool {
    return format == vk.format_d24_unorm_s8_uint or format == vk.format_d32_sfloat_s8_uint;
}

fn depthAttachmentAspect(format: u32) vk.Flags {
    return if (depthAttachmentHasStencil(format))
        vk.image_aspect_depth_bit | vk.image_aspect_stencil_bit
    else
        vk.image_aspect_depth_bit;
}

const DepthTransferPlan = struct {
    depth_bytes: usize,
    stencil_offset: usize,
    stencil_bytes: usize,
    total_bytes: usize,
};

fn depthTransferPlan(target: GuestDepthTarget) ?DepthTransferPlan {
    if (target.samples_log2 != 0) return null;
    const texels = std.math.mul(usize, target.width, target.height) catch return null;
    const depth_bpp: usize = switch (target.format) {
        vk.format_d16_unorm => 2,
        vk.format_d24_unorm_s8_uint, vk.format_d32_sfloat, vk.format_d32_sfloat_s8_uint => 4,
        else => return null,
    };
    const depth_bytes = std.math.mul(usize, texels, depth_bpp) catch return null;
    const stencil_offset = std.mem.alignForward(usize, depth_bytes, 4);
    const stencil_bytes = if (target.has_stencil) texels else 0;
    const total_bytes = std.math.add(usize, stencil_offset, stencil_bytes) catch return null;
    if (total_bytes == 0 or total_bytes > maximum_frame_bytes) return null;
    return .{
        .depth_bytes = depth_bytes,
        .stencil_offset = stencil_offset,
        .stencil_bytes = stencil_bytes,
        .total_bytes = total_bytes,
    };
}

fn expandDepth16To24(source: []const u8, destination: []u8) bool {
    if (source.len % 2 != 0 or destination.len != source.len * 2) return false;
    for (0..source.len / 2) |index| {
        const value = std.mem.readInt(u16, source[index * 2 ..][0..2], .little);
        const expanded: u32 = @intCast((@as(u64, value) * 0x00ff_ffff + 0x7fff) / 0xffff);
        std.mem.writeInt(u32, destination[index * 4 ..][0..4], expanded, .little);
    }
    return true;
}

fn compactDepth24To16(source: []const u8, destination: []u8) bool {
    if (source.len % 4 != 0 or destination.len * 2 != source.len) return false;
    for (0..source.len / 4) |index| {
        const value = std.mem.readInt(u32, source[index * 4 ..][0..4], .little) & 0x00ff_ffff;
        const compact: u16 = @intCast((@as(u64, value) * 0xffff + 0x007f_ffff) / 0x00ff_ffff);
        std.mem.writeInt(u16, destination[index * 2 ..][0..2], compact, .little);
    }
    return true;
}

fn depthSampledFormatCompatible(depth_format: u32, sampled_format: u32) bool {
    const depth16 = depth_format == vk.format_d16_unorm or depth_format == vk.format_d24_unorm_s8_uint;
    const depth32 = depth_format == vk.format_d32_sfloat or depth_format == vk.format_d32_sfloat_s8_uint;
    return (depth16 and sampled_format == vk.format_r16_unorm) or
        (depth32 and sampled_format == vk.format_r32_sfloat);
}

/// Expands the DB_DEPTH_SIZE_XY 1x1 reset sentinel from the viewport or,
/// when that is missing, the scissor. Returns true when the extent changed.
fn recoverResetDepthExtent(
    bound: *gpu.resources.DepthTarget,
    render_state: gpu.resources.RenderState,
) bool {
    if (bound.width != 1 or bound.height != 1) return false;
    if (render_state.viewport) |viewport| {
        const viewport_width = @abs(viewport.x_scale * 2.0);
        const viewport_height = @abs(viewport.y_scale * 2.0);
        if (std.math.isFinite(viewport_width) and std.math.isFinite(viewport_height) and
            viewport_width > 1 and viewport_height > 1 and
            viewport_width <= 16384 and viewport_height <= 16384)
        {
            bound.width = @intFromFloat(@ceil(viewport_width));
            bound.height = @intFromFloat(@ceil(viewport_height));
            return true;
        }
    }
    if (render_state.scissor) |scissor| {
        const scissor_width = @as(u32, scissor.right) -| @as(u32, scissor.left);
        const scissor_height = @as(u32, scissor.bottom) -| @as(u32, scissor.top);
        if (scissor_width > 1 and scissor_height > 1 and
            scissor_width <= 16384 and scissor_height <= 16384)
        {
            bound.width = scissor_width;
            bound.height = scissor_height;
            return true;
        }
    }
    return false;
}

/// The guest depth-compare selector and Vulkan's `VkCompareOp` enumerate the
/// same eight functions in the same order, so the raw field is the host value.
fn depthCompareOperation(function: u8) u32 {
    return @as(u32, function & 0x7);
}

/// Guest sample/fragment encodings are log2 of 1/2/4/8. The matching Vulkan
/// sample-count flag is the same power of two.
fn rasterSampleCount(samples_log2: u8) ?u32 {
    return switch (samples_log2) {
        0 => vk.sample_count_1_bit,
        1 => vk.sample_count_2_bit,
        2 => vk.sample_count_4_bit,
        3 => vk.sample_count_8_bit,
        else => null,
    };
}

fn colorTargetSamplesLog2(descriptor: gpu.resources.ColorTarget) ?u8 {
    if (descriptor.samples_log2 > 3 or descriptor.fragments_log2 > 3) return null;
    if (descriptor.samples_log2 != descriptor.fragments_log2) return null;
    return descriptor.fragments_log2;
}

/// Guest stencil operations that Vulkan can express. Ones, bitwise AND/OR,
/// and NAND/NOR/XNOR have no host counterpart and stay as keep so a title
/// that never hits them still draws.
fn hostStencilOperation(operation: u8, write_mask: u8, op_value: u8) u32 {
    if (write_mask == 0) return vk.stencil_op_keep;
    return switch (operation) {
        0 => vk.stencil_op_keep,
        1 => vk.stencil_op_zero,
        3, 4 => vk.stencil_op_replace,
        5 => vk.stencil_op_increment_and_clamp,
        6 => vk.stencil_op_decrement_and_clamp,
        7 => vk.stencil_op_invert,
        8 => vk.stencil_op_increment_and_wrap,
        9 => vk.stencil_op_decrement_and_wrap,
        0xc => if ((write_mask & ~op_value) == 0)
            vk.stencil_op_invert
        else
            vk.stencil_op_keep,
        else => vk.stencil_op_keep,
    };
}

/// FMASK is still ignored. Sample and fragment counts stay on the
/// descriptor so the host image can match the guest attachment.
fn hostColorTargetDescriptor(descriptor: gpu.resources.ColorTarget) gpu.resources.ColorTarget {
    var host = descriptor;
    host.fmask_compression = false;
    host.fmask_address = 0;
    // A Vulkan 2D attachment represents one selected slice. Until layered
    // rendering/geometry-stage exports are exposed, retain the guest base
    // slice but narrow an array view to that slice instead of rejecting the
    // whole draw. This keeps Unity's small RGBA16F luminance/bloom MRT passes
    // alive and preserves the correct physical source offset on readback.
    if (host.last_array_slice > host.base_array_slice) {
        host.last_array_slice = host.base_array_slice;
    }
    return host;
}

fn guestColorTarget(descriptor_: gpu.resources.ColorTarget) anyerror!GuestColorTarget {
    _ = colorTargetSamplesLog2(descriptor_) orelse return Error.UnsupportedColorTarget;
    const descriptor = hostColorTargetDescriptor(descriptor_);
    const format = colorTargetFormat(descriptor) orelse return Error.UnsupportedColorTarget;
    // CPU tiling still names one sample per pixel. The host image carries the
    // real sample count; this layout is only identity and 1x staging size.
    var layout_descriptor = descriptor;
    layout_descriptor.samples_log2 = 0;
    layout_descriptor.fragments_log2 = 0;
    const layout = try gpu.SurfaceLayout.fromColorTarget(layout_descriptor);
    if (layout.layers != 1 or layout.block.bytes_per_element != format.bytes_per_texel) {
        return Error.UnsupportedColorTarget;
    }
    return .{ .descriptor = descriptor, .layout = layout, .format = format };
}

fn displayColorTarget(buffer: DisplayBuffer) ?gpu.resources.ColorTarget {
    if (buffer.address == 0 or buffer.width == 0 or buffer.height == 0) return null;
    const pitch = if (buffer.pitch_in_pixels != 0) buffer.pitch_in_pixels else buffer.width;
    if (pitch < buffer.width) return null;
    const tile_mode: gpu.resources.TileMode = switch (buffer.tiling_mode) {
        0 => .render_target,
        1 => .linear,
        else => return null,
    };
    var target = std.mem.zeroes(gpu.resources.ColorTarget);
    target.address = buffer.address;
    target.width = buffer.width;
    target.height = buffer.height;
    target.depth = 1;
    target.pitch = pitch;
    // DATA_FORMAT_8_8_8_8. VideoOut's pixel format is a separate unified
    // format enum; the colour-target descriptor stores the data format only.
    target.format = 10;
    target.tile_mode = tile_mode;
    target.write_mask = 0xf;
    target.force_destination_alpha_one = true;
    return target;
}

/// One guest color allocation kept resident as a Vulkan attachment across
/// draws.  The old path recreated this entire object graph and round-tripped
/// every pixel through the CPU after each draw, which both destroyed
/// multi-pass composition and serialized the host GPU.
const CachedRenderTarget = struct {
    alias_token: image_alias.Token,
    target: GuestColorTarget,
    image: OwnedImage,
    view: vk.ImageView,
    render_pass: vk.RenderPass,
    framebuffer: vk.Framebuffer,
    depth_pass: ?DepthPass = null,
    readback: OwnedBuffer,
    initialized: bool = false,
    shader_read_layout: bool = false,
    gpu_generation: u64 = 0,
    host_generation: u64 = 0,
    last_used_sequence: u64 = 0,
    /// The matched guest compositor uses a negative-height viewport. Keep its
    /// attachment resident and apply that orientation only at scanout/readback.
    scanout_flip_vertical: bool = false,
};

/// A guest depth allocation reduced to what a Vulkan attachment needs.
///
/// The guest describes depth as a base allocation plus an optional separate
/// stencil allocation and an HTILE metadata surface. Stencil rides in a
/// packed depth+stencil host format when the guest binds an S8 plane. HTILE
/// is still resolved into the base allocations by the metadata path rather
/// than being handed to the rasterizer.
const GuestDepthTarget = struct {
    descriptor: gpu.resources.DepthTarget = std.mem.zeroes(gpu.resources.DepthTarget),
    address: u64,
    allocation_bytes: u64,
    stencil_address: u64 = 0,
    stencil_allocation_bytes: u64 = 0,
    width: u32,
    height: u32,
    /// DB_Z_INFO.FORMAT, kept so a re-decode of the same registers matches.
    guest_format: u8,
    format: u32,
    tile_mode: gpu.resources.TileMode,
    base_array_slice: u16,
    mip_level: u8,
    samples_log2: u8 = 0,
    has_stencil: bool = false,
    clear_depth: f32,
    clear_stencil: u8 = 0,

    fn sameAllocation(self: GuestDepthTarget, other: GuestDepthTarget) bool {
        return self.address == other.address and
            self.allocation_bytes == other.allocation_bytes and
            self.stencil_address == other.stencil_address and
            self.stencil_allocation_bytes == other.stencil_allocation_bytes and
            self.width == other.width and
            self.height == other.height and
            self.guest_format == other.guest_format and
            self.format == other.format and
            self.tile_mode == other.tile_mode and
            self.base_array_slice == other.base_array_slice and
            self.mip_level == other.mip_level and
            self.samples_log2 == other.samples_log2 and
            self.has_stencil == other.has_stencil;
    }

    fn aspectMask(self: GuestDepthTarget) vk.Flags {
        return depthAttachmentAspect(self.format);
    }
};

/// One guest depth allocation kept resident as a Vulkan attachment.
///
const CachedDepthTarget = struct {
    alias_token: image_alias.Token,
    stencil_alias_token: ?image_alias.Token = null,
    target: GuestDepthTarget,
    image: OwnedImage,
    view: vk.ImageView,
    readback: ?OwnedBuffer = null,
    /// False until the image has been transitioned out of `undefined`.
    initialized: bool = false,
    /// Depth written by rasterization may be consumed by a later compute or
    /// fragment pass without first being materialized into guest memory.
    shader_read_layout: bool = false,
    gpu_generation: u64 = 0,
    host_generation: u64 = 0,
    last_used_sequence: u64 = 0,
};

/// A render pass and framebuffer pairing one colour attachment with one depth
/// attachment.
///
/// Held on the colour target because that is what owns the framebuffer. A title
/// keeps the same pair bound across long runs of draws, so the single slot is
/// rebuilt only when the depth allocation actually changes.
const DepthPass = struct {
    depth_view: vk.ImageView,
    depth_format: u32,
    render_pass: vk.RenderPass,
    framebuffer: vk.Framebuffer,
};

/// A render pass and framebuffer for more than one colour slot.
///
/// Hardware CB slot *n* is Vulkan colour attachment *n*. Unused slots between
/// 0 and the highest bound target stay as `ATTACHMENT_UNUSED` so fragment
/// Location *n* still names the matching CB.
const ColorPass = struct {
    color_views: [gpu.resources.color_target_count]vk.ImageView = @splat(0),
    color_count: u8,
    depth_view: vk.ImageView = 0,
    depth_format: u32 = 0,
    render_pass: vk.RenderPass,
    framebuffer: vk.Framebuffer,
    last_used_sequence: u64 = 0,
};

const CmaskSeed = struct {
    texel: [4]u8,
    clear_blocks: u32,
    expanded_blocks: u32,
};

const DccClearTexel = struct {
    bytes: [16]u8,
    length: u8,
};

const CachedHtileTarget = struct {
    target: gpu.resources.DepthTarget,
    resolved: bool = false,
    last_used_sequence: u64 = 0,
};

const HtileResolveStats = struct {
    clear_zero_blocks: u32 = 0,
    clear_one_blocks: u32 = 0,
    base_blocks: u32 = 0,

    fn clearBlocks(self: HtileResolveStats) u32 {
        return self.clear_zero_blocks +| self.clear_one_blocks;
    }
};

/// One remembered content probe of a sampled source.
///
/// The probe reads a spread of cache lines out of guest memory, and a frame
/// samples the same few textures from many draws. Repeating the read for every
/// draw costs more than the comparison it feeds, so the result is remembered
/// for as long as the source cannot have changed: the same span, and the same
/// render-target generation behind it.
const TextureProbe = struct {
    address: u64 = 0,
    span: usize = 0,
    full_content: bool = false,
    page_generation: u64 = 0,
    source_generation: u64 = 0,
    hash: u64 = 0,
    hash_valid: bool = false,
    valid: bool = false,
};

/// Distinct sampled sources remembered per frame. A title binding more than
/// this many in one frame simply re-probes the ones that fall out.
const maximum_texture_probes = 256;

/// Whether guest memory still holds the words a program was decoded from.
fn programWordsMatch(reader: gpu.ShaderMemoryReader, address: u64, words: []const u32) bool {
    const expected = std.mem.sliceAsBytes(words);
    var chunk: [1024]u8 = undefined;
    var offset: usize = 0;
    while (offset < expected.len) {
        const span = @min(chunk.len, expected.len - offset);
        if (!reader.read_fn(reader.context, address + offset, chunk[0..span])) return false;
        if (!std.mem.eql(u8, chunk[0..span], expected[offset..][0..span])) return false;
        offset += span;
    }
    return true;
}

fn traceShaderAnalysisFailure(
    reader: gpu.ShaderMemoryReader,
    stage: gpu.resources.ShaderStage,
    program_address: u64,
    header_address: ?u64,
    err: anyerror,
) void {
    const header = header_address orelse {
        std.debug.print(
            "[vulkan dcb] shader analysis failed stage={s} program=0x{x} header=missing error={s}\n",
            .{ @tagName(stage), program_address, @errorName(err) },
        );
        return;
    };
    const code_address = reader.readU64(header + 0x10) catch 0;
    const header_size = reader.readU32(header + 0x40) catch 0;
    const shader_size = reader.readU32(header + 0x44) catch 0;
    const trailing = reader.readU32(header + 0x58) catch 0;
    std.debug.print(
        "[vulkan dcb] shader analysis failed stage={s} program=0x{x} header=0x{x} code=0x{x} header_size=0x{x} shader_size=0x{x} type={d} sh_regs={d} error={s}\n",
        .{
            @tagName(stage),
            program_address,
            header,
            code_address,
            header_size,
            shader_size,
            (trailing >> 16) & 0xff,
            trailing >> 24,
            @errorName(err),
        },
    );
}

fn shaderProgramByteLimit(
    reader: gpu.ShaderMemoryReader,
    header_address: ?u64,
    program_address: u64,
) ?usize {
    const header = header_address orelse return null;
    const code_address = reader.readU64(header + 0x10) catch return null;
    const shader_size = reader.readU32(header + 0x44) catch return null;
    if (program_address < code_address) return null;
    const program_offset = program_address - code_address;
    if (program_offset >= shader_size) return null;
    const remaining = @as(u64, shader_size) - program_offset;
    if (remaining < @sizeOf(u32) or remaining > maximum_shader_code_bytes) return null;
    return @intCast(remaining);
}

/// One guest shader program in decoded form.
///
/// `analysis` owns the words it was decoded from, and those words are what a
/// later lookup compares against guest memory, so no separate copy is kept.
const AnalyzedProgram = struct {
    address: u64,
    analysis: gpu.ShaderAnalysis,
    last_used_sequence: u64 = 0,
};

