    acquire_fence: vk.Fence,
};

const PreparedSampledImage = struct {
    image: OwnedImage,
    view: vk.ImageView,
    sampler: vk.Sampler,
    descriptor_layout: u32 = vk.image_layout_shader_read_only_optimal,
    owns_view: bool = false,
    owns_sampler: bool = false,
    storage_cache_index: ?usize = null,
};

const SampledStagingLayout = union(enum) {
    surface: gpu.SurfaceLayout,
    subresource: gpu.TextureSubresourceLayout,

    fn fromImage(descriptor: gpu.resources.ImageDescriptor) anyerror!SampledStagingLayout {
        const base_level = descriptor.viewBaseLevel();
        if (descriptor.image_type == .color_3d or base_level != 0) {
            const texture = try gpu.TextureLayout.fromImage(descriptor);
            const layers: u32 = if (descriptor.image_type == .color_3d) 1 else texture.layers;
            return .{ .subresource = try texture.subresource(base_level, 0, layers) };
        }
        return .{ .surface = try gpu.SurfaceLayout.fromImage(descriptor) };
    }

    fn depthOrLayers(self: SampledStagingLayout) u32 {
        return switch (self) {
            .surface => |layout| layout.layers,
            .subresource => |layout| layout.depth_or_layers,
        };
    }

    fn bytesPerElement(self: SampledStagingLayout) u8 {
        return switch (self) {
            .surface => |layout| layout.block.bytes_per_element,
            .subresource => |layout| layout.block.bytes_per_element,
        };
    }

    fn isLinear(self: SampledStagingLayout) bool {
        return switch (self) {
            .surface => |layout| layout.block.tile_mode.isLinear(),
            .subresource => |layout| layout.block.family == .linear,
        };
    }

    fn stagingBytes(self: SampledStagingLayout) anyerror!u64 {
        return switch (self) {
            .surface => |layout| layout.staging_bytes,
            .subresource => |layout| try layout.stagingBytes(),
        };
    }

    fn requiredSourceBytes(self: SampledStagingLayout) u64 {
        return switch (self) {
            .surface => |layout| layout.required_source_bytes,
            .subresource => |layout| layout.required_source_bytes,
        };
    }

    fn stage(
        self: SampledStagingLayout,
        reader: gpu.ShaderMemoryReader,
        address: u64,
        destination: []u8,
    ) anyerror!void {
        return switch (self) {
            .surface => |layout| try layout.stage(reader, address, destination),
            .subresource => |layout| try layout.stage(reader, address, destination),
        };
    }

    fn detile(self: SampledStagingLayout, source: []const u8, destination: []u8) anyerror!void {
        return switch (self) {
            .surface => |layout| try layout.detile(source, destination),
            .subresource => |layout| try layout.detile(source, destination),
        };
    }
};

/// First-use sampled upload of one T# view: the guest mip range packed into a
/// Vulkan image whose mip 0 is the view's base level.
const SampledViewPlan = struct {
    texture: gpu.TextureLayout,
    base_level: u8,
    level_count: u8,
    first_layer: u32,
    layer_count: u32,
    texel_width: u32,
    texel_height: u32,
    texel_depth: u32,
    volume: bool,

    fn fromDescriptor(
        descriptor: gpu.resources.ImageDescriptor,
        dimension: rdna2.spirv.SampledImageDimension,
    ) ?SampledViewPlan {
        if (descriptor.samplesLog2() != 0) return null;
        const wants_chain = descriptor.viewBaseLevel() != 0 or
            descriptor.viewMipLevels() > 1 or
            (descriptor.extended and descriptor.resourceMipLevels() > 1);
        if (!wants_chain) return null;
        const texture = gpu.TextureLayout.fromImage(descriptor) catch return null;
        const base_level = descriptor.viewBaseLevel();
        if (base_level >= texture.mip_levels) return null;
        var level_count = descriptor.viewMipLevels();
        const remaining = texture.mip_levels - base_level;
        if (level_count == 0 or level_count > remaining) level_count = remaining;
        const available_layers = texture.layers;
        const layer_count: u32 = switch (dimension) {
            .two_d => 1,
            .three_d => 1,
            .cube => if (available_layers >= 6) 6 else return null,
            .two_d_array => available_layers,
        };
        if (dimension != .three_d and (layer_count == 0 or layer_count > available_layers)) return null;
        return .{
            .texture = texture,
            .base_level = base_level,
            .level_count = level_count,
            .first_layer = 0,
            .layer_count = layer_count,
            .texel_width = shiftTexels(descriptor.width, base_level),
            .texel_height = shiftTexels(descriptor.height, base_level),
            .texel_depth = if (dimension == .three_d)
                shiftTexels(descriptor.depth_or_layers, base_level)
            else
                1,
            .volume = dimension == .three_d,
        };
    }

    fn view(self: SampledViewPlan, level_index: u8) gpu.tiling.Error!gpu.TextureSubresourceLayout {
        return self.texture.subresource(
            self.base_level + level_index,
            self.first_layer,
            if (self.volume) 1 else self.layer_count,
        );
    }

    fn stagingBytes(self: SampledViewPlan) gpu.tiling.Error!u64 {
        var total: u64 = 0;
        var index: u8 = 0;
        while (index < self.level_count) : (index += 1) {
            const packed_bytes = try (try self.view(index)).stagingBytes();
            total += std.mem.alignForward(u64, packed_bytes, 16);
        }
        return total;
    }

    fn mipTexels(self: SampledViewPlan, level_index: u8) struct { u32, u32, u32 } {
        return .{
            shiftTexels(self.texel_width, level_index),
            shiftTexels(self.texel_height, level_index),
            if (self.volume) shiftTexels(self.texel_depth, level_index) else 1,
        };
    }
};

fn shiftTexels(value: u32, level: u8) u32 {
    if (level >= 31) return 1;
    return @max(value >> @as(u5, @intCast(level)), 1);
}

const PreparedStorageImage = struct {
    descriptor: gpu.ImageDescriptor,
    subresource: gpu.TextureSubresourceLayout,
    image: OwnedImage,
