    writable: bool,
    cache_index: ?usize = null,
    render_target_index: ?usize = null,
};

const CachedStorageImage = struct {
    alias_token: image_alias.Token,
    descriptor: gpu.ImageDescriptor,
    subresource: gpu.TextureSubresourceLayout,
    image: OwnedImage,
    view: vk.ImageView,
    transfer: OwnedBuffer,
    allocation_bytes: usize,
    staging_bytes: usize,
    last_used_sequence: u64,
    guest_content_hash: u64 = 0,
    guest_content_hash_valid: bool = false,
    guest_page_generation: u64 = 0,
    gpu_dirty: bool = false,
    in_use: bool = false,
    valid: bool = true,
};

const GraphicsResources = struct {
    images: [maximum_storage_descriptors]PreparedSampledImage = undefined,
    image_count: usize = 0,
    descriptors: [maximum_storage_descriptors]gpu.ImageDescriptor = undefined,
    mappings: [maximum_storage_descriptors]gpu.ShaderSpirvSampledImageBinding = undefined,
    mapping_count: usize = 0,

    fn deinit(self: *GraphicsResources, renderer: *Renderer) void {
        for (self.images[0..self.image_count]) |image| {
            if (image.owns_view) renderer.destroyImageView(image.view);
            if (image.owns_sampler) renderer.destroySampler(image.sampler);
            if (image.storage_cache_index) |cache_index| renderer.releaseStorageImage(cache_index);
        }
        self.* = undefined;
    }
};

const PlanarVideoPass = struct {
    luma: gpu.ImageDescriptor,
    chroma_u: gpu.ImageDescriptor,
    chroma_v: ?gpu.ImageDescriptor,
    source_width: u32,
    source_height: u32,
    fills_target: bool,

    fn layoutName(self: PlanarVideoPass) []const u8 {
        return if (self.chroma_v == null) "NV12" else "I420";
    }
};

fn recognizePlanarVideoPass(
    target_width: u32,
    target_height: u32,
    descriptors: []const gpu.ImageDescriptor,
) ?PlanarVideoPass {
    if (target_width == 0 or target_height == 0 or
        (descriptors.len != 2 and descriptors.len != 3))
    {
        return null;
    }

    var luma_index: ?usize = null;
    var largest_pixels: u64 = 0;
    for (descriptors, 0..) |plane, index| {
        if (!plane.tile_mode.isLinear() or plane.unified_format != 1 or
            plane.width == 0 or plane.height == 0 or plane.pitch < plane.width)
        {
            continue;
        }
        const pixels = @as(u64, plane.width) * plane.height;
        if (luma_index == null or pixels > largest_pixels) {
            luma_index = index;
            largest_pixels = pixels;
        }
    }
    const y_index = luma_index orelse return null;
    const luma = descriptors[y_index];

    var chroma_indices: [2]usize = undefined;
    var chroma_count: usize = 0;
    for (descriptors, 0..) |_, index| {
        if (index == y_index) continue;
        chroma_indices[chroma_count] = index;
        chroma_count += 1;
    }
    const chroma_u = descriptors[chroma_indices[0]];
    const chroma_v: ?gpu.ImageDescriptor = if (chroma_count == 2)
        descriptors[chroma_indices[1]]
    else
        null;

    if (!chroma_u.tile_mode.isLinear() or chroma_u.width * 2 != luma.width or
        chroma_u.height * 2 != luma.height)
    {
        return null;
    }
    if (chroma_v) |plane| {
        if (chroma_u.unified_format != 1 or plane.unified_format != 1 or
            !plane.tile_mode.isLinear() or plane.width != chroma_u.width or
            plane.height != chroma_u.height or plane.pitch < plane.width)
        {
            return null;
        }
    } else if (chroma_u.unified_format != 14) {
        return null;
    }

    // The visible movie can be narrower than its decoder allocation. Unity's
    // texture descriptors retain the padded pitch (1984/2048 for a 1920-wide
    // movie), while the render target retains the cropped display aspect. Use
    // that aspect to recover 1920 from 1984x1080 and 1280 from 1344x720 even
    // when the latter is scaled to a 1920x1080 target.
    const visible_width_numerator = @as(u64, target_width) * luma.height;
    if (visible_width_numerator % target_height == 0) {
        const visible_width = std.math.cast(u32, visible_width_numerator / target_height) orelse return null;
        if (visible_width != 0 and luma.width >= visible_width and
            luma.width - visible_width < 256)
        {
            return .{
                .luma = luma,
                .chroma_u = chroma_u,
                .chroma_v = chroma_v,
                .source_width = visible_width,
                .source_height = luma.height,
                .fills_target = true,
            };
        }
    }
    // Decoder planes can also be placed inside a Unity UI quad (game preview
    // videos use 540x360 inside a 3840x2160 target). The plane signature is
    // still unambiguous, but that draw must retain its guest vertex geometry
    // instead of being replaced by the fullscreen probe rectangle.
    return .{
        .luma = luma,
        .chroma_u = chroma_u,
        .chroma_v = chroma_v,
        .source_width = luma.width,
        .source_height = luma.height,
        .fills_target = false,
    };
}

const PipelineLookup = struct {
    pipeline: vk.Pipeline,
    cache_hit: bool,
};

const ComputeResources = struct {
    mappings: [maximum_storage_mappings]gpu.ShaderSpirvStorageBufferBinding = undefined,
    mapping_count: usize = 0,
    scalar_registers: [gpu.scalar_provenance.maximum_scalar_specializations]gpu.ShaderSpirvScalarRegister = undefined,
    scalar_count: usize = 0,
    addresses: [maximum_storage_descriptors]u64 = @splat(0),
    sizes: [maximum_storage_descriptors]usize = @splat(0),
    occupied: [maximum_storage_descriptors]bool = @splat(false),
    writable: [maximum_storage_descriptors]bool = @splat(false),
    specialized_scalar_prefix_end: u32 = 0,
    storage_images: [maximum_storage_images]PreparedStorageImage = undefined,
    storage_image_count: usize = 0,
    // One resident image may be loaded into the same T# SGPR range at several
    // instruction PCs. Keep physical Vulkan images bounded separately from the
    // larger PC-specific mapping table used by generated Unity kernels.
    storage_image_mappings: [maximum_storage_descriptors]gpu.ShaderSpirvStorageImageBinding = undefined,
    storage_image_mapping_count: usize = 0,
    sampled_images: [maximum_storage_descriptors]PreparedSampledImage = undefined,
    sampled_image_count: usize = 0,
    sampled_image_descriptors: [maximum_storage_descriptors]gpu.ImageDescriptor = undefined,
    sampled_image_samplers: [maximum_storage_descriptors]gpu.resources.SamplerDescriptor = undefined,
    sampled_image_dimensions: [maximum_storage_descriptors]rdna2.spirv.SampledImageDimension = undefined,
    sampled_image_mappings: [maximum_compute_sampled_mappings]gpu.ShaderSpirvSampledImageBinding = undefined,
    sampled_image_mapping_count: usize = 0,

    fn descriptorForRange(self: *const ComputeResources, address: u64, size: usize) ?u32 {
        for (self.occupied, 0..) |used, index| {
            if (used and self.addresses[index] == address and self.sizes[index] == size) return @intCast(index);
        }
        return null;
    }

    fn freeDescriptor(self: *const ComputeResources) ?u32 {
        for (self.occupied, 0..) |used, index| {
            if (!used) return @intCast(index);
        }
        return null;
    }

    fn mappingForSgpr(self: *const ComputeResources, resource_sgpr: u32) ?u32 {
        for (self.mappings[0..self.mapping_count]) |mapping| {
            if (mapping.resource_sgpr == resource_sgpr) return mapping.descriptor_index;
        }
        return null;
    }

    /// Whether a translated dispatch can change state that the emulator will
    /// make visible after it completes. Stores whose V# could not be recovered
    /// are deliberately lowered as no-ops, so merely seeing a store opcode in
    /// the guest program is not enough to justify executing a large shader.
    fn hasWritableExternalState(self: *const ComputeResources) bool {
        for (self.writable, self.occupied) |writable, occupied| {
            if (occupied and writable) return true;
        }
        for (self.storage_images[0..self.storage_image_count]) |image| {
            if (image.writable) return true;
        }
        return false;
    }

    fn sampledImageMappingForInstruction(
        self: *const ComputeResources,
        resource_sgpr: u32,
        sampler_sgpr: u32,
        instruction_pc: u32,
    ) ?u32 {
        for (self.sampled_image_mappings[0..self.sampled_image_mapping_count]) |mapping| {
            if (mapping.resource_sgpr == resource_sgpr and
                mapping.sampler_sgpr == sampler_sgpr and
                mapping.instruction_pc != null and mapping.instruction_pc.? == instruction_pc)
            {
                return mapping.descriptor_index;
            }
        }
        return null;
    }

    fn deinit(self: *ComputeResources, renderer: *Renderer) void {
        for (self.storage_images[0..self.storage_image_count]) |image| {
            if (image.cache_index) |cache_index| renderer.releaseStorageImage(cache_index);
            if (image.render_target_index) |target_index| {
                renderer.transitionRenderTargetToColorAttachment(target_index) catch {};
            }
        }
        self.storage_image_count = 0;
        self.storage_image_mapping_count = 0;
        // Cached sampled images survive this dispatch. Direct render-target
        // views and samplers retire after the frame batch fence signals.
        for (self.sampled_images[0..self.sampled_image_count]) |image| {
            if (image.owns_view) renderer.destroyImageView(image.view);
            if (image.owns_sampler) renderer.destroySampler(image.sampler);
            if (image.storage_cache_index) |cache_index| renderer.releaseStorageImage(cache_index);
        }
        self.sampled_image_count = 0;
        self.sampled_image_mapping_count = 0;
    }
};

fn isFullscreenCornerTriangle(
    reader: gpu.ShaderMemoryReader,
    resources: *const ComputeResources,
    draw: GuestDraw,
) bool {
    if (draw.index_count == null or draw.index_count.? != 3 or draw.index_address == 0) return false;

    var indices: [3]u32 = undefined;
    const index_stride: u64 = if (draw.index_uint32) 4 else 2;
    for (&indices, 0..) |*index, element| {
        const index_address = draw.index_address + @as(u64, @intCast(element)) * index_stride;
        index.* = if (draw.index_uint32)
            reader.readU32(index_address) catch return false
        else
            reader.readU16(index_address) catch return false;
    }

    for (resources.mappings[0..resources.mapping_count]) |mapping| {
        if (!mapping.use_vertex_index or mapping.unified_format != 77 or mapping.stride < 16) continue;
        const source_offset = mapping.soffset_value orelse 0;
        if (source_offset != 0) continue;
        const slot: usize = @intCast(mapping.descriptor_index);
        var corners: [3][4]f32 = undefined;
        var valid = true;
        for (indices, 0..) |index, corner| {
            const byte_offset = std.math.mul(u64, index, mapping.stride) catch {
                valid = false;
                break;
            };
            if (byte_offset + 16 > @as(u64, @intCast(resources.sizes[slot]))) {
                valid = false;
                break;
            }
            var words: [4]u32 = undefined;
            reader.readWords(resources.addresses[slot] + byte_offset, &words) catch {
                valid = false;
                break;
            };
            for (&corners[corner], words) |*component, word| component.* = @bitCast(word);
        }
        if (!valid) continue;

        for (corners) |corner| {
            if (@abs(@abs(corner[0]) - 1.0) > 0.0001 or
                @abs(@abs(corner[1]) - 1.0) > 0.0001 or
                @abs(corner[2]) > 0.0001 or @abs(corner[3] - 1.0) > 0.0001)
            {
                valid = false;
                break;
            }
        }
        if (!valid) continue;
        // Mode 2 reconstructs v3 = v1 + v2 - v0. Require v0 to be the
        // shared corner and v1/v2 to be the diagonal pair so that equation is
        // exactly the missing fourth clip-space corner.
        const first_adjacent = corners[0][0] == corners[1][0] or corners[0][1] == corners[1][1];
        const second_adjacent = corners[0][0] == corners[2][0] or corners[0][1] == corners[2][1];
        const others_diagonal = corners[1][0] != corners[2][0] and corners[1][1] != corners[2][1];
        if (first_adjacent and second_adjacent and others_diagonal) return true;
    }
    return false;
}

const DrawVertexRange = struct {
    minimum: i64,
    maximum: i64,
};

/// Return the effective Vulkan VertexIndex range for this draw. AGC attribute
/// tables also describe small per-draw lookup buffers; those buffers must keep
/// the guest-computed MUBUF index instead of being indexed by a mesh index that
/// lies outside their descriptor.
fn drawVertexRange(reader: gpu.ShaderMemoryReader, draw: GuestDraw) ?DrawVertexRange {
    if (draw.index_count) |count| {
        if (count == 0 or draw.index_address == 0) return null;
        const stride: u64 = if (draw.index_uint32) 4 else 2;
        var minimum: u32 = std.math.maxInt(u32);
        var maximum: u32 = 0;
        var element: u32 = 0;
        while (element < count) : (element += 1) {
            const byte_offset = std.math.mul(u64, element, stride) catch return null;
            const index = if (draw.index_uint32)
                reader.readU32(draw.index_address + byte_offset) catch return null
            else
                reader.readU16(draw.index_address + byte_offset) catch return null;
            minimum = @min(minimum, index);
            maximum = @max(maximum, index);
        }
        return .{
            .minimum = @as(i64, minimum) + draw.vertex_offset,
            .maximum = @as(i64, maximum) + draw.vertex_offset,
        };
    }
    if (draw.vertex_count == 0) return null;
    return .{
        .minimum = draw.first_vertex,
        .maximum = @as(i64, draw.first_vertex) + draw.vertex_count - 1,
    };
}

fn validateVertexIndexMappings(
    reader: gpu.ShaderMemoryReader,
    resources: *ComputeResources,
    draw: GuestDraw,
) void {
    const range = drawVertexRange(reader, draw) orelse return;
    for (resources.mappings[0..resources.mapping_count]) |*mapping| {
        if (!mapping.use_vertex_index or mapping.stride == 0) continue;
        if (range.minimum < 0 or range.maximum < range.minimum) {
            mapping.use_vertex_index = false;
            continue;
        }
        const required = std.math.mul(
            u64,
            @as(u64, @intCast(range.maximum)) + 1,
            mapping.stride,
        ) catch {
            mapping.use_vertex_index = false;
            continue;
        };
        const extent = mapping.extent_bytes orelse continue;
        if (required > extent) {
            // This is a lookup/indirection buffer from the same AGC attribute
            // table, not a record array indexed by the draw's mesh indices.
            mapping.use_vertex_index = false;
        }
    }
}

fn canReuseStorageMapping(attribute_specific: bool, previous: ?u32, current: u32) bool {
    return !attribute_specific and previous != null and previous.? == current;
}

/// AGC's attribute table uses the sparse VertexAttribFormat numbering while a
/// live V# uses the compact BufferFormat enum. Converting here lets a shader
/// fetch be paired with the right table entry even when fetch order differs
/// from semantic/location order.
fn vertexAttributeBufferFormat(format: u16) u16 {
    return switch (format) {
        0 => 0,
        4 => 1,
        8 => 2,
        12 => 3,
        16 => 4,
        20 => 5,
        24 => 6,
        28 => 7,
        32 => 8,
        36 => 9,
        40 => 10,
        44 => 11,
        48 => 12,
        52 => 13,
        57 => 14,
        61 => 15,
        65 => 16,
        69 => 17,
        73 => 18,
        77 => 19,
        80 => 20,
        84 => 21,
        88 => 22,
        93 => 23,
        97 => 24,
        101 => 25,
        105 => 26,
        109 => 27,
        113 => 28,
        117 => 29,
        122 => 30,
        126 => 31,
        130 => 32,
        134 => 33,
        138 => 34,
        142 => 35,
        146 => 36,
        150 => 37,
        154 => 38,
        158 => 39,
        162 => 40,
        166 => 41,
        170 => 42,
        174 => 43,
        179 => 44,
        183 => 45,
        187 => 46,
        191 => 47,
        195 => 48,
        199 => 49,
        203 => 50,
        207 => 51,
        211 => 52,
        215 => 53,
        219 => 54,
        223 => 55,
        227 => 56,
        231 => 57,
        235 => 58,
        239 => 59,
        243 => 60,
        247 => 61,
        249 => 62,
        253 => 63,
        257 => 64,
        263 => 65,
        267 => 66,
        271 => 67,
        275 => 68,
        279 => 69,
        283 => 70,
        287 => 71,
        290 => 72,
        294 => 73,
        298 => 74,
        303 => 75,
        307 => 76,
        311 => 77,
        else => format,
    };
}

const maximum_vertex_attributes = 32;

fn matchVertexAttribute(
    table: *const gpu.VertexBindings,
    used: *[maximum_vertex_attributes]bool,
    descriptor: gpu.BufferDescriptor,
) ?gpu.VertexAttribute {
    var best_index: ?usize = null;
    var best_score: u8 = 0;
    for (table.slice(), 0..) |attribute, index| {
        if (used[index] or attribute.buffer.address != descriptor.address) continue;
        var score: u8 = 1;
        if (attribute.buffer.stride == descriptor.stride) score += 2;
        if (vertexAttributeBufferFormat(attribute.attribute_format) == descriptor.unified_format) score += 4;
        if (best_index == null or score > best_score) {
            best_index = index;
            best_score = score;
        }
    }
    const index = best_index orelse return null;
    used[index] = true;
    return table.attributes[index];
}

fn takeNextVertexAttribute(
    table: *const gpu.VertexBindings,
    used: *[maximum_vertex_attributes]bool,
) ?gpu.VertexAttribute {
    for (table.slice(), 0..) |attribute, index| {
        if (used[index]) continue;
        used[index] = true;
        return attribute;
    }
    return null;
}

fn dumpComputeSpirv(allocator: std.mem.Allocator, program_address: u64, words: []const u32) void {
    var path_buffer: [96]u8 = undefined;
    const path = std.fmt.bufPrintZ(
        &path_buffer,
        "out\\compute-0x{x}.spv",
        .{program_address},
    ) catch return;
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    // A diagnostic run must reflect the current translator. Keeping the first
    // module forever made validation silently inspect stale SPIR-V after fixes.
    const file = std.Io.Dir.cwd().createFile(io, path, .{ .truncate = true }) catch return;
    defer file.close(io);
    file.writePositionalAll(io, std.mem.sliceAsBytes(words), 0) catch {};
}

fn dumpGraphicsSpirv(
    allocator: std.mem.Allocator,
    stage: []const u8,
    program_address: u64,
    words: []const u32,
) void {
    var path_buffer: [96]u8 = undefined;
    const path = std.fmt.bufPrintZ(
        &path_buffer,
        "out\\graphics-{s}-0x{x}.spv",
        .{ stage, program_address },
    ) catch return;
    var threaded = std.Io.Threaded.init(allocator, .{});
    defer threaded.deinit();
    const io = threaded.io();
    const file = std.Io.Dir.cwd().createFile(io, path, .{ .truncate = true }) catch return;
    defer file.close(io);
    file.writePositionalAll(io, std.mem.sliceAsBytes(words), 0) catch {};
}

fn shouldDumpProgressFrame(flip: u64, enabled: bool) bool {
    // PPM capture forces a GPU-to-CPU materialization and writes roughly
    // width * height * 3 bytes synchronously. Keep every checkpoint opt-in so
    // a normal 4K run does not spend its startup producing diagnostic files.
    if (!enabled) return false;
    return switch (flip) {
        2, 8, 16, 32, 64, 96, 128 => true,
        256, 512, 768, 1024, 1152, 1200, 1216, 1280, 1536, 2048 => true,
        else => flip >= 800 and flip % 64 == 0,
    };
}

const maximum_sparse_deferred_ui_age: u64 = 256;
const sparse_graphics_handoff_flip: u64 = 1536;

fn shouldPresentDeferredCompositeUi(sparse: bool, flip: u64, last_ui_flip: u64) bool {
    if (!sparse) return true;
    return flip -| last_ui_flip <= maximum_sparse_deferred_ui_age;
}

fn shouldElideSparseGraphics(sparse: bool, flip: u64) bool {
    return sparse and flip >= 80 and flip < sparse_graphics_handoff_flip and flip % 16 != 0;
}

fn sampledImageDimensionForInstruction(
    dimension: rdna2.isa.ImageDimension,
    image_type: gpu.resources.ImageType,
) ?rdna2.spirv.SampledImageDimension {
    // GFX10's DIM selects the coordinate payload while the T# resource type is
    // the authoritative view kind. Unity uses three-coordinate MIMG forms for
    // both volumes and ordinary 2D render targets; Vulkan requires the view
    // dimension to match the descriptor, so refine it after materializing T#.
    switch (image_type) {
        .color_3d => return .three_d,
        .color_2d_array => return .two_d_array,
        .color_1d, .color_2d => return .two_d,
        else => {},
    }
    return switch (dimension) {
        .dim_1d => .two_d,
        .dim_2d => .two_d,
        .dim_3d => .three_d,
        // GFX10 MIMG DIM=3 denotes a cubemap. The decoder's historical enum
        // label is kept to avoid changing the instruction representation.
        .dim_2d_array => .cube,
        .dim_2d_array_alt => .two_d_array,
        else => null,
    };
}

const CachedSampledImage = struct {
    alias_token: image_alias.Token,
    guest_address: u64,
    width: u32,
    height: u32,
    depth: u32,
    image_type: u8,
    dimension: rdna2.spirv.SampledImageDimension,
    tile_mode: u8,
    base_level: u8,
    last_level: u8,
    mip_levels: u8,
    state_hash: u64,
    image_state_hash: u64,
    source_generation: u64,
    content_hash: u64,
    image: OwnedImage,
    view: vk.ImageView,
    sampler: vk.Sampler,
    last_used_frame: u64,
};

const CachedResidentImageView = struct {
    image: vk.Image,
    view_type: u32,
    format: u32,
    components: vk.ComponentMapping,
    aspect_mask: vk.Flags,
    layer_count: u32,
    view: vk.ImageView,
};

const CachedResidentSampler = struct {
    descriptor: gpu.resources.SamplerDescriptor,
    sampler: vk.Sampler,
};

fn aliasRange(address: u64, byte_count: anytype) image_alias.Range {
    return .{ .address = address, .size = @intCast(byte_count) };
}

fn colorTargetAliasSignature(target: GuestColorTarget) image_alias.Signature {
    return .{
        .format = target.format.vulkan,
        .width = target.descriptor.width,
        .height = target.descriptor.height,
        .tile_mode = @intFromEnum(target.descriptor.tile_mode),
        .samples_log2 = target.descriptor.fragments_log2,
    };
}

fn depthTargetAliasSignature(target: GuestDepthTarget) image_alias.Signature {
    return .{
        .format = target.format,
        .width = target.width,
        .height = target.height,
        .tile_mode = @intFromEnum(target.tile_mode),
        .samples_log2 = target.samples_log2,
        .aspect = if (target.has_stencil) .depth_stencil else .depth,
    };
}

fn descriptorAliasSignature(
    descriptor: gpu.ImageDescriptor,
    image_format: u32,
    mip_levels: u8,
) image_alias.Signature {
    return .{
        .format = image_format,
        .width = descriptor.width,
        .height = descriptor.height,
        .depth = if (descriptor.image_type == .color_3d) descriptor.depth_or_layers else 1,
        .mip_levels = mip_levels,
        .layers = if (descriptor.image_type == .color_3d)
            1
        else
            @intCast(@min(descriptor.depth_or_layers, std.math.maxInt(u16))),
        .tile_mode = @intFromEnum(descriptor.tile_mode),
        .samples_log2 = descriptor.samplesLog2(),
    };
}

