    pipeline_cache_misses: u64 = 0,
    graphics_pipeline_cache_hits: u64 = 0,
    graphics_pipeline_cache_misses: u64 = 0,
    graphics_pipeline_sequence: u64 = 0,
    frame_profile: FrameProfile = .{},
    last_flip_profile_ns: u64 = 0,
    reported_shader_failures: [64]?GraphicsShaderFailure = @splat(null),
    reported_vertex_resource_programs: [4]u64 = @splat(0),
    reported_fragment_resource_programs: [4]u64 = @splat(0),
    last_interface_vertex_address: u64 = 0,
    last_interface_fragment_address: u64 = 0,
    reported_interface_pairs: u8 = 0,
    reported_vertex_storage_bindings: bool = false,
    reported_fragment_storage_bindings: bool = false,
    reported_first_graphics_draw_checkpoints: bool = false,
    captured_targeted_fragment_probe: bool = false,
    reported_planar_video_pass: bool = false,
    captured_planar_video_pass: bool = false,
    reported_crt_composite_fallback: bool = false,
    reported_first_scissor_state: bool = false,
    reported_draw_errors: [16]?anyerror = @splat(null),
    reported_compute_shader_failures: [32]?ComputeShaderFailure = @splat(null),
    reported_compute_resource_programs: [8]u64 = @splat(0),
    reported_yotei_gds_dispatches: u8 = 0,
    reported_yotei_visibility_dispatches: u8 = 0,
    yotei_packed_visibility_seeds: u8 = 0,
    excessive_draw_reports: u8 = 0,
    last_dispatch_error: ?anyerror = null,
    last_draw_error: ?anyerror = null,
    last_sync_error: ?anyerror = null,
    last_flip_error: ?anyerror = null,

    fn traceCurrentGraphicsFrame(self: *const Renderer) bool {
        const requested = self.trace_graphics_frame orelse return false;
        const target = if (requested == 0)
            self.auto_trace_graphics_frame orelse return false
        else
            requested;
        return self.flip_callbacks +% 1 == target;
    }

    pub fn init(allocator: std.mem.Allocator, options: Options) (Error || std.mem.Allocator.Error)!Renderer {
        const wants_presentation = options.native_window != null;
        if (wants_presentation and builtin.os.tag != .windows) return Error.UnsupportedPresentationPlatform;
        var loader = try Loader.init();
        errdefer loader.deinit();

        const enumerate_version = try loader.global(vk.PfnEnumerateInstanceVersion, "vkEnumerateInstanceVersion");
        var loader_api_version: u32 = 0;
        if (enumerate_version(&loader_api_version) != vk.success or loader_api_version < vk.api_version_1_2) {
            return Error.VulkanVersionTooOld;
        }

        const enumerate_layers = try loader.global(vk.PfnEnumerateInstanceLayerProperties, "vkEnumerateInstanceLayerProperties");
        const validation_enabled = options.enable_validation and layerAvailable(enumerate_layers, "VK_LAYER_KHRONOS_validation");
        const validation_name: [*:0]const u8 = "VK_LAYER_KHRONOS_validation";
        const layer_names = [_][*:0]const u8{validation_name};
        const instance_extension_names = [_][*:0]const u8{
            "VK_KHR_surface",
            "VK_KHR_win32_surface",
        };

        const application_info = vk.ApplicationInfo{
            .application_name = "PS5PCEM",
            .application_version = vk.makeApiVersion(0, 0, 4, 0),
            .engine_name = "PS5PCEM",
            .engine_version = vk.makeApiVersion(0, 0, 4, 0),
            .api_version = vk.api_version_1_2,
        };
        const instance_info = vk.InstanceCreateInfo{
            .application_info = &application_info,
            .enabled_layer_count = @intFromBool(validation_enabled),
            .enabled_layer_names = if (validation_enabled) &layer_names else null,
            .enabled_extension_count = if (wants_presentation) instance_extension_names.len else 0,
            .enabled_extension_names = if (wants_presentation) &instance_extension_names else null,
        };
        const create_instance = try loader.global(vk.PfnCreateInstance, "vkCreateInstance");
        var maybe_instance: ?vk.Instance = null;
        if (create_instance(&instance_info, null, &maybe_instance) != vk.success) return Error.InstanceCreationFailed;
        const instance_handle = maybe_instance orelse return Error.InstanceCreationFailed;
        const instance_functions = try InstanceFunctions.load(&loader, instance_handle);
        errdefer instance_functions.destroy_instance(instance_handle, null);

        const surface_functions: ?SurfaceFunctions = if (wants_presentation)
            try SurfaceFunctions.load(&loader, instance_handle)
        else
            null;
        var surface: vk.Surface = 0;
        if (options.native_window) |window| {
            const surface_info = vk.Win32SurfaceCreateInfoKHR{
                .instance = window.instance,
                .window = window.window,
            };
            if (surface_functions.?.create_win32_surface(instance_handle, &surface_info, null, &surface) != vk.success) {
                return Error.SurfaceCreationFailed;
            }
        }
        errdefer if (surface != 0) surface_functions.?.destroy_surface(instance_handle, surface, null);

        const candidate = try choosePhysicalDevice(
            allocator,
            instance_handle,
            &instance_functions,
            surface,
            if (surface_functions) |*functions| functions else null,
            options.prefer_integrated_gpu,
        );
        const queue_priority: f32 = 1.0;
        const queue_info = vk.DeviceQueueCreateInfo{
            .queue_family_index = candidate.queue_family_index,
            .queue_count = 1,
            .queue_priorities = @ptrCast(&queue_priority),
        };
        const shader_atomic_float2_extension = physicalDeviceSupportsExtension(
            allocator,
            &instance_functions,
            candidate.physical_device,
            "VK_EXT_shader_atomic_float2",
        );
        var shader_atomic_float2_support = vk.PhysicalDeviceShaderAtomicFloat2FeaturesEXT{};
        var descriptor_indexing_support = vk.PhysicalDeviceDescriptorIndexingFeatures{
            .p_next = if (shader_atomic_float2_extension) &shader_atomic_float2_support else null,
        };
        var timeline_support = vk.PhysicalDeviceTimelineSemaphoreFeatures{
            .p_next = &descriptor_indexing_support,
        };
        var supported_features_2 = vk.PhysicalDeviceFeatures2{ .p_next = &timeline_support };
        instance_functions.get_physical_device_features_2(candidate.physical_device, &supported_features_2);
        if (timeline_support.timeline_semaphore == 0) return Error.TimelineSemaphoreUnavailable;
        const descriptor_partially_bound = descriptor_indexing_support.descriptor_binding_partially_bound != 0;
        const image_float32_atomic_min_max = shader_atomic_float2_extension and
            shader_atomic_float2_support.shader_image_float32_atomic_min_max != 0;
        const supported_features = supported_features_2.features;
        var enabled_features = vk.PhysicalDeviceFeatures{};
        if (supported_features.values[vk.feature_robust_buffer_access] != 0) {
            enabled_features.values[vk.feature_robust_buffer_access] = vk.true_value;
        }
        if (supported_features.values[vk.feature_shader_storage_image_extended_formats] != 0) {
            enabled_features.values[vk.feature_shader_storage_image_extended_formats] = vk.true_value;
        }
        if (supported_features.values[vk.feature_fragment_stores_and_atomics] != 0) {
            enabled_features.values[vk.feature_fragment_stores_and_atomics] = vk.true_value;
        }
        if (supported_features.values[vk.feature_shader_image_gather_extended] != 0) {
            enabled_features.values[vk.feature_shader_image_gather_extended] = vk.true_value;
        }
        // A rectangle list needs a stage that sees the whole primitive, so
        // that the corner it leaves out can be completed from the three it
        // gives. Without the feature those draws keep their single triangle.
        const geometry_shaders = supported_features.values[vk.feature_geometry_shader] != 0;
        if (geometry_shaders) {
            enabled_features.values[vk.feature_geometry_shader] = vk.true_value;
        }
        const shader_float64 = supported_features.values[vk.feature_shader_float64] != 0;
        if (shader_float64) {
            enabled_features.values[vk.feature_shader_float64] = vk.true_value;
        }
        var shader_atomic_float2_enable = vk.PhysicalDeviceShaderAtomicFloat2FeaturesEXT{
            .shader_image_float32_atomic_min_max = if (image_float32_atomic_min_max) vk.true_value else 0,
        };
        var descriptor_indexing_enable = vk.PhysicalDeviceDescriptorIndexingFeatures{
            .p_next = if (image_float32_atomic_min_max) &shader_atomic_float2_enable else null,
            .descriptor_binding_partially_bound = if (descriptor_partially_bound) vk.true_value else 0,
        };
        var timeline_enable = vk.PhysicalDeviceTimelineSemaphoreFeatures{
            .p_next = if (descriptor_partially_bound)
                &descriptor_indexing_enable
            else if (image_float32_atomic_min_max)
                &shader_atomic_float2_enable
            else
                null,
            .timeline_semaphore = vk.true_value,
        };
        var device_extension_names: [2][*:0]const u8 = undefined;
        var device_extension_count: u32 = 0;
        if (wants_presentation) {
            device_extension_names[device_extension_count] = "VK_KHR_swapchain";
            device_extension_count += 1;
        }
        if (image_float32_atomic_min_max) {
            device_extension_names[device_extension_count] = "VK_EXT_shader_atomic_float2";
            device_extension_count += 1;
        }
        const device_info = vk.DeviceCreateInfo{
            .p_next = &timeline_enable,
            .queue_create_info_count = 1,
            .queue_create_infos = @ptrCast(&queue_info),
            .enabled_extension_count = device_extension_count,
            .enabled_extension_names = if (device_extension_count != 0) &device_extension_names else null,
            .enabled_features = &enabled_features,
        };
        var maybe_device: ?vk.Device = null;
        if (instance_functions.create_device(candidate.physical_device, &device_info, null, &maybe_device) != vk.success) {
            return Error.DeviceCreationFailed;
        }
        const device = maybe_device orelse return Error.DeviceCreationFailed;
        const device_functions = try DeviceFunctions.load(instance_functions.get_device_proc_addr, device);
        errdefer device_functions.destroy_device(device, null);
        const swapchain_functions: ?SwapchainFunctions = if (wants_presentation)
            try SwapchainFunctions.load(instance_functions.get_device_proc_addr, device)
        else
            null;

        var maybe_queue: ?vk.Queue = null;
        device_functions.get_device_queue(device, candidate.queue_family_index, 0, &maybe_queue);
        const queue = maybe_queue orelse return Error.QueueUnavailable;

        const semaphore_type = vk.SemaphoreTypeCreateInfo{};
        const semaphore_info = vk.SemaphoreCreateInfo{ .p_next = &semaphore_type };
        var timeline_semaphore: vk.Semaphore = 0;
        if (device_functions.create_semaphore(device, &semaphore_info, null, &timeline_semaphore) != vk.success) {
            return Error.TimelineSemaphoreCreationFailed;
        }
        errdefer device_functions.destroy_semaphore(device, timeline_semaphore, null);

        const pool_info = vk.CommandPoolCreateInfo{
            .flags = vk.command_pool_create_transient_bit | vk.command_pool_create_reset_command_buffer_bit,
            .queue_family_index = candidate.queue_family_index,
        };
        var command_pool: vk.CommandPool = 0;
        if (device_functions.create_command_pool(device, &pool_info, null, &command_pool) != vk.success) {
            return Error.CommandPoolCreationFailed;
        }
        errdefer device_functions.destroy_command_pool(device, command_pool, null);

        // Storage is shared by compute and by graphics attribute / constant
        // buffer MUBUF lowering. Restricting it to compute left guest VS loads
        // unbound and produced a black writeback after V# recovery.
        const storage_binding = vk.DescriptorSetLayoutBinding{
            .binding = 0,
            .descriptor_type = vk.descriptor_type_storage_buffer,
            .descriptor_count = maximum_storage_descriptors,
            .stage_flags = vk.shader_stage_compute_bit |
                vk.shader_stage_vertex_bit |
                vk.shader_stage_fragment_bit,
        };
        const sampled_image_binding = vk.DescriptorSetLayoutBinding{
            .binding = 1,
            .descriptor_type = vk.descriptor_type_combined_image_sampler,
            .descriptor_count = maximum_storage_descriptors,
            .stage_flags = vk.shader_stage_vertex_bit | vk.shader_stage_fragment_bit | vk.shader_stage_compute_bit,
        };
        var descriptor_bindings: [7 + maximum_storage_images]vk.DescriptorSetLayoutBinding = undefined;
        descriptor_bindings[0] = storage_binding;
        descriptor_bindings[1] = sampled_image_binding;
        for (0..maximum_storage_images) |index| {
            descriptor_bindings[2 + index] = .{
                .binding = @intCast(2 + index),
                .descriptor_type = vk.descriptor_type_storage_image,
                .descriptor_count = 1,
                .stage_flags = vk.shader_stage_compute_bit,
            };
        }
        descriptor_bindings[2 + maximum_storage_images] = .{
            .binding = dynamic_scalar_descriptor_binding,
            .descriptor_type = vk.descriptor_type_storage_buffer,
            .descriptor_count = 1,
            .stage_flags = vk.shader_stage_vertex_bit |
                vk.shader_stage_fragment_bit |
                vk.shader_stage_compute_bit,
        };
        descriptor_bindings[3 + maximum_storage_images] = .{
            .binding = sampled_image_3d_descriptor_binding,
            .descriptor_type = vk.descriptor_type_combined_image_sampler,
            .descriptor_count = maximum_storage_descriptors,
            .stage_flags = vk.shader_stage_vertex_bit | vk.shader_stage_fragment_bit | vk.shader_stage_compute_bit,
        };
        descriptor_bindings[4 + maximum_storage_images] = .{
            .binding = sampled_image_cube_descriptor_binding,
            .descriptor_type = vk.descriptor_type_combined_image_sampler,
            .descriptor_count = maximum_storage_descriptors,
            .stage_flags = vk.shader_stage_vertex_bit | vk.shader_stage_fragment_bit | vk.shader_stage_compute_bit,
        };
        descriptor_bindings[5 + maximum_storage_images] = .{
            .binding = sampled_image_2d_array_descriptor_binding,
            .descriptor_type = vk.descriptor_type_combined_image_sampler,
            .descriptor_count = maximum_storage_descriptors,
            .stage_flags = vk.shader_stage_vertex_bit | vk.shader_stage_fragment_bit | vk.shader_stage_compute_bit,
        };
        descriptor_bindings[6 + maximum_storage_images] = .{
            .binding = gds_descriptor_binding,
            .descriptor_type = vk.descriptor_type_storage_buffer,
            .descriptor_count = 1,
            .stage_flags = vk.shader_stage_compute_bit,
        };
        var descriptor_binding_flags: [descriptor_bindings.len]vk.Flags = @splat(0);
        if (descriptor_partially_bound) {
            @memset(&descriptor_binding_flags, vk.descriptor_binding_partially_bound_bit);
        }
        const descriptor_binding_flags_info = vk.DescriptorSetLayoutBindingFlagsCreateInfo{
            .binding_count = descriptor_binding_flags.len,
            .binding_flags = &descriptor_binding_flags,
        };
        const descriptor_layout_info = vk.DescriptorSetLayoutCreateInfo{
            .p_next = if (descriptor_partially_bound) &descriptor_binding_flags_info else null,
            .binding_count = descriptor_bindings.len,
            .bindings = &descriptor_bindings,
        };
        var descriptor_set_layout: vk.DescriptorSetLayout = 0;
        if (device_functions.create_descriptor_set_layout(device, &descriptor_layout_info, null, &descriptor_set_layout) != vk.success) {
            return Error.DescriptorSetLayoutCreationFailed;
        }
        errdefer device_functions.destroy_descriptor_set_layout(device, descriptor_set_layout, null);

        const pool_size = vk.DescriptorPoolSize{
            .descriptor_type = vk.descriptor_type_storage_buffer,
            .descriptor_count = (maximum_storage_descriptors + 2) * maximum_frame_descriptor_sets,
        };
        const image_pool_size = vk.DescriptorPoolSize{
            .descriptor_type = vk.descriptor_type_combined_image_sampler,
            .descriptor_count = maximum_storage_descriptors * 4 * maximum_frame_descriptor_sets,
        };
        const storage_image_pool_size = vk.DescriptorPoolSize{
            .descriptor_type = vk.descriptor_type_storage_image,
            .descriptor_count = maximum_storage_images * maximum_frame_descriptor_sets,
        };
        const pool_sizes = [_]vk.DescriptorPoolSize{ pool_size, image_pool_size, storage_image_pool_size };
        const descriptor_pool_info = vk.DescriptorPoolCreateInfo{
            .max_sets = maximum_frame_descriptor_sets,
            .pool_size_count = pool_sizes.len,
            .pool_sizes = &pool_sizes,
        };
        var descriptor_pool: vk.DescriptorPool = 0;
        if (device_functions.create_descriptor_pool(device, &descriptor_pool_info, null, &descriptor_pool) != vk.success) {
            return Error.DescriptorPoolCreationFailed;
        }
        errdefer device_functions.destroy_descriptor_pool(device, descriptor_pool, null);

        const descriptor_sets = try allocator.alloc(vk.DescriptorSet, maximum_frame_descriptor_sets);
        errdefer allocator.free(descriptor_sets);
        var descriptor_layouts: [maximum_frame_descriptor_sets]vk.DescriptorSetLayout =
            @splat(descriptor_set_layout);
        const descriptor_allocate_info = vk.DescriptorSetAllocateInfo{
            .descriptor_pool = descriptor_pool,
            .descriptor_set_count = maximum_frame_descriptor_sets,
            .set_layouts = &descriptor_layouts,
        };
        if (device_functions.allocate_descriptor_sets(device, &descriptor_allocate_info, descriptor_sets.ptr) != vk.success) {
            return Error.DescriptorSetAllocationFailed;
        }
        const descriptor_set = descriptor_sets[0];

        const pipeline_layout_info = vk.PipelineLayoutCreateInfo{
            .set_layout_count = 1,
            .set_layouts = @ptrCast(&descriptor_set_layout),
        };
        var compute_pipeline_layout: vk.PipelineLayout = 0;
        if (device_functions.create_pipeline_layout(device, &pipeline_layout_info, null, &compute_pipeline_layout) != vk.success) {
            return Error.PipelineLayoutCreationFailed;
        }
        errdefer device_functions.destroy_pipeline_layout(device, compute_pipeline_layout, null);

        // The driver pipeline cache is reused across runs: a previous session's
        // compiled pipelines seed this one, so the first frames of a title do
        // not pay full driver compilation again. Stale or foreign cache bytes
        // are rejected by the driver; any failure falls back to an empty cache.
        const cached_bytes = loadPipelineCacheBytes(allocator);
        defer if (cached_bytes) |bytes| allocator.free(bytes);
        const pipeline_cache_info = vk.PipelineCacheCreateInfo{
            .initial_data_size = if (cached_bytes) |bytes| bytes.len else 0,
            .initial_data = if (cached_bytes) |bytes| bytes.ptr else null,
        };
        var driver_pipeline_cache: vk.PipelineCache = 0;
        if (device_functions.create_pipeline_cache(device, &pipeline_cache_info, null, &driver_pipeline_cache) != vk.success) {
            if (cached_bytes != null) {
                // Invalid payload (wrong driver/device): start over.
                const empty_info = vk.PipelineCacheCreateInfo{};
                if (device_functions.create_pipeline_cache(device, &empty_info, null, &driver_pipeline_cache) != vk.success) {
                    return Error.PipelineCacheCreationFailed;
                }
            } else {
                return Error.PipelineCacheCreationFailed;
            }
        }
        errdefer device_functions.destroy_pipeline_cache(device, driver_pipeline_cache, null);

        var memory_properties: vk.PhysicalDeviceMemoryProperties = undefined;
        instance_functions.get_memory_properties(candidate.physical_device, &memory_properties);

        const window_presentation: ?WindowPresentation = if (options.native_window) |window|
            try createWindowPresentation(
                allocator,
                candidate.physical_device,
                device,
                &device_functions,
                memory_properties,
                window,
                surface,
                surface_functions.?,
                swapchain_functions.?,
            )
        else
            null;
        errdefer if (window_presentation) |presentation| {
            swapchain_functions.?.destroy_swapchain(device, presentation.swapchain, null);
            allocator.free(presentation.images);
            device_functions.destroy_buffer(device, presentation.upload.handle, null);
            device_functions.free_memory(device, presentation.upload.memory, null);
            device_functions.destroy_fence(device, presentation.acquire_fence, null);
        };

        var renderer = Renderer{
            .allocator = allocator,
            .loader = loader,
            .instance_handle = instance_handle,
            .instance_functions = instance_functions,
            .physical_device = candidate.physical_device,
            .device = device,
            .device_functions = device_functions,
            .queue = queue,
            .queue_family_index = candidate.queue_family_index,
            .command_pool = command_pool,
            .timeline_semaphore = timeline_semaphore,
            .descriptor_set_layout = descriptor_set_layout,
            .descriptor_pool = descriptor_pool,
            .descriptor_sets = descriptor_sets,
            .descriptor_set = descriptor_set,
            .compute_pipeline_layout = compute_pipeline_layout,
            .driver_pipeline_cache = driver_pipeline_cache,
            .memory_properties = memory_properties,
            .loader_api_version = loader_api_version,
            .device_info = candidate.info,
            .geometry_shaders_available = geometry_shaders,
            .shader_float64_available = shader_float64,
            .image_float32_atomic_min_max_available = image_float32_atomic_min_max,
            .validation_enabled = validation_enabled,
            .graphics_probe_enabled = options.enable_graphics_probe,
            .capture_first_graphics_frame = options.capture_first_graphics_frame,
            .trace_graphics_frame = options.trace_graphics_frame,
            .force_probe_fragment = options.force_probe_fragment,
            .force_probe_fragment_texture = options.force_probe_fragment_texture,
            .force_probe_fragment_parameter = options.force_probe_fragment_parameter,
            .force_probe_fragment_ui = options.force_probe_fragment_ui,
            .skip_compute_dispatches = options.skip_compute_dispatches,
            .skip_compute_until_flip = options.skip_compute_until_flip,
            .compute_execution_limit = options.compute_execution_limit,
            .sparse_graphics_draws = options.sparse_graphics_draws,
            .translate_compute_only = options.translate_compute_only,
            .dump_compute_spirv = options.dump_compute_spirv,
            .dump_graphics_spirv = options.dump_graphics_spirv,
            .capture_extended_progress_frames = options.capture_extended_progress_frames,
            .shader_ir_enabled = options.enable_shader_ir,
            .shader_ssa_optimization_enabled = options.enable_shader_ssa_optimization,
            .async_pipeline_compilation_enabled = options.enable_async_pipeline_compilation,
            .canonical_image_aliases_enabled = options.enable_canonical_image_aliases,
            .timeline_scheduler_enabled = options.enable_timeline_scheduler,
            .defer_small_storage_writes_enabled = options.defer_small_storage_writes,
            .depth_transfer_enabled = options.enable_depth_transfer,
            .image_state_optimization_enabled = options.enable_image_state_optimization,
            .window_presentation = window_presentation,
        };
        renderer.image_aliases.enabled = options.enable_canonical_image_aliases;
        renderer.image_aliases.canonical_authority_enabled = options.enable_canonical_image_aliases;
        renderer.image_states.optimize_barriers = options.enable_image_state_optimization;
        renderer.dynamic_scalar_buffer = try renderer.createBuffer(
            descriptor_scalar_ring_bytes,
            vk.buffer_usage_storage_buffer_bit,
            vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
        );
        errdefer renderer.destroyBuffer(renderer.dynamic_scalar_buffer.?);
        var scalar_mapping: ?*anyopaque = null;
        if (device_functions.map_memory(
            device,
            renderer.dynamic_scalar_buffer.?.memory,
            0,
            descriptor_scalar_ring_bytes,
            0,
            &scalar_mapping,
        ) != vk.success) return Error.MemoryMapFailed;
        renderer.dynamic_scalar_mapping_base = @ptrCast(@alignCast(scalar_mapping orelse return Error.MemoryMapFailed));
        renderer.dynamic_scalar_mapping = renderer.dynamic_scalar_mapping_base;
        errdefer device_functions.unmap_memory(device, renderer.dynamic_scalar_buffer.?.memory);

        renderer.draw_upload_buffer = try renderer.createBuffer(
            draw_upload_ring_bytes,
            vk.buffer_usage_storage_buffer_bit | vk.buffer_usage_index_buffer_bit,
            vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
        );
        errdefer renderer.destroyBuffer(renderer.draw_upload_buffer.?);
        var draw_upload_mapping: ?*anyopaque = null;
        if (device_functions.map_memory(
            device,
            renderer.draw_upload_buffer.?.memory,
            0,
            draw_upload_ring_bytes,
            0,
            &draw_upload_mapping,
        ) != vk.success) return Error.MemoryMapFailed;
        renderer.draw_upload_mapping = @ptrCast(draw_upload_mapping orelse return Error.MemoryMapFailed);
        errdefer device_functions.unmap_memory(device, renderer.draw_upload_buffer.?.memory);

        for (descriptor_sets, 0..) |set, slot| {
            const scalar_buffer_info = vk.DescriptorBufferInfo{
                .buffer = renderer.dynamic_scalar_buffer.?.handle,
                .offset = slot * descriptor_scalar_stride,
                .range = dynamic_scalar_buffer_bytes,
            };
            const scalar_write = vk.WriteDescriptorSet{
                .destination_set = set,
                .destination_binding = dynamic_scalar_descriptor_binding,
                .destination_array_element = 0,
                .descriptor_count = 1,
                .descriptor_type = vk.descriptor_type_storage_buffer,
                .buffer_info = @ptrCast(&scalar_buffer_info),
            };
            device_functions.update_descriptor_sets(device, 1, @ptrCast(&scalar_write), 0, null);
        }
        try renderer.gds_storage.resize(allocator, 64 * 1024);
        errdefer renderer.gds_storage.deinit(allocator);
        @memset(renderer.gds_storage.items, 0);
        renderer.gds_buffer = try renderer.createBuffer(
            gds_ring_bytes,
            vk.buffer_usage_storage_buffer_bit,
            vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
        );
        errdefer renderer.destroyBuffer(renderer.gds_buffer.?);
        try renderer.writeMapped(renderer.gds_buffer.?, renderer.gds_storage.items);
        renderer.updateGdsDescriptor(renderer.gds_buffer.?);
        renderer.createDetilePass() catch |err| {
            std.debug.print("[vulkan] compute detile unavailable: {s}\n", .{@errorName(err)});
        };
        return renderer;
    }

    pub fn deinit(self: *Renderer) void {
        self.pipeline_compile_queue.waitIdle();
        self.finishDrawBatch() catch {};
        _ = self.device_functions.device_wait_idle(self.device);
        self.completed_tick = self.submitted_tick;
        self.destroyDeferredVulkanObjects();
        self.pending_targetless_draws.deinit(self.allocator);
        for (self.color_passes.items) |pass| self.destroyColorPass(pass);
        self.color_passes.deinit(self.allocator);
        self.color_passes = .empty;
        for (self.resident_image_views.items) |cached| {
            self.device_functions.destroy_image_view(self.device, cached.view, null);
        }
        self.resident_image_views.deinit(self.allocator);
        self.resident_image_views = .empty;
        for (self.resident_samplers.items) |cached| {
            self.device_functions.destroy_sampler(self.device, cached.sampler, null);
        }
        self.resident_samplers.deinit(self.allocator);
        self.resident_samplers = .empty;
        for (self.render_targets.items) |target| self.destroyCachedRenderTarget(target);
        self.render_targets.deinit(self.allocator);
        for (self.depth_targets.items) |target| self.destroyCachedDepthTarget(target);
        self.depth_targets.deinit(self.allocator);
        self.htile_targets.deinit(self.allocator);
        for (self.sampled_image_cache.items) |image| {
            self.device_functions.destroy_sampler(self.device, image.sampler, null);
            self.device_functions.destroy_image_view(self.device, image.view, null);
            self.destroyImage(image.image);
        }
        self.sampled_image_cache.deinit(self.allocator);
        for (self.storage_image_cache.items) |image| {
            if (!image.valid) continue;
            self.device_functions.destroy_image_view(self.device, image.view, null);
            self.destroyImage(image.image);
            self.destroyBuffer(image.transfer);
        }
        self.storage_image_cache.deinit(self.allocator);
        self.image_aliases.deinit(self.allocator);
        self.image_states.deinit(self.allocator);
        for (self.compute_pipelines.items) |entry| {
            self.device_functions.destroy_pipeline(self.device, entry.pipeline, null);
            self.device_functions.destroy_shader_module(self.device, entry.shader, null);
            self.allocator.free(entry.words);
        }
        self.compute_pipelines.deinit(self.allocator);
        for (self.graphics_pipelines.items) |entry| {
            self.device_functions.destroy_pipeline(self.device, entry.pipeline, null);
            self.allocator.free(entry.vertex_words);
            self.allocator.free(entry.fragment_words);
        }
        self.graphics_pipelines.deinit(self.allocator);
        for (self.analyzed_programs.items) |*entry| entry.analysis.deinit(self.allocator);
        self.analyzed_programs.deinit(self.allocator);
        for (self.completed_frames.items) |*frame| frame.pixels.deinit(self.allocator);
        self.completed_frames.deinit(self.allocator);
        self.guest_frame_scratch.deinit(self.allocator);
        self.movie_luma_scratch.deinit(self.allocator);
        self.movie_chroma_scratch.deinit(self.allocator);
        self.movie_rgba_scratch.deinit(self.allocator);
        for (self.guest_buffers.items) |entry| {
            self.destroyBuffer(entry.device_local);
        }
        self.guest_buffers.deinit(self.allocator);
        self.draw_upload_cache.deinit(self.allocator);
        if (self.linear_upload_buffer) |buffer| self.destroyBuffer(buffer);
        if (self.magnify_source_image) |image| self.destroyImage(image);
        if (self.draw_upload_buffer) |buffer| {
            if (self.draw_upload_mapping != null) self.device_functions.unmap_memory(self.device, buffer.memory);
            self.destroyBuffer(buffer);
        }
        if (self.dynamic_scalar_buffer) |buffer| {
            if (self.dynamic_scalar_mapping_base != null) self.device_functions.unmap_memory(self.device, buffer.memory);
            self.destroyBuffer(buffer);
        }
        if (self.gds_buffer) |buffer| self.destroyBuffer(buffer);
        self.gds_storage.deinit(self.allocator);
        // Persist compiled pipelines for the next run before the cache handle
        // is destroyed.
        savePipelineCacheBytes(self);
        self.device_functions.destroy_pipeline_cache(self.device, self.driver_pipeline_cache, null);
        if (self.detile_pipeline != 0) self.device_functions.destroy_pipeline(self.device, self.detile_pipeline, null);
        if (self.detile_shader != 0) self.device_functions.destroy_shader_module(self.device, self.detile_shader, null);
        if (self.detile_pipeline_layout != 0) self.device_functions.destroy_pipeline_layout(self.device, self.detile_pipeline_layout, null);
        if (self.detile_pool != 0) self.device_functions.destroy_descriptor_pool(self.device, self.detile_pool, null);
        if (self.detile_set_layout != 0) self.device_functions.destroy_descriptor_set_layout(self.device, self.detile_set_layout, null);
        self.device_functions.destroy_pipeline_layout(self.device, self.compute_pipeline_layout, null);
        self.frame_command_buffers.deinit(self.allocator);
        self.command_buffer_ticks.deinit(self.allocator);
        self.pending_command_buffers.deinit(self.allocator);
        self.pending_command_slots.deinit(self.allocator);
        self.pending_descriptor_slots.deinit(self.allocator);
        self.deferred_vulkan_objects.deinit(self.allocator);
        self.allocator.free(self.descriptor_sets);
        self.device_functions.destroy_descriptor_pool(self.device, self.descriptor_pool, null);
        self.device_functions.destroy_descriptor_set_layout(self.device, self.descriptor_set_layout, null);
        self.device_functions.destroy_command_pool(self.device, self.command_pool, null);
        if (self.window_presentation) |presentation| {
            presentation.swapchain_functions.destroy_swapchain(self.device, presentation.swapchain, null);
            self.allocator.free(presentation.images);
            self.device_functions.destroy_buffer(self.device, presentation.upload.handle, null);
            self.device_functions.free_memory(self.device, presentation.upload.memory, null);
            self.device_functions.destroy_fence(self.device, presentation.acquire_fence, null);
            presentation.surface_functions.destroy_surface(self.instance_handle, presentation.surface, null);
        }
        self.device_functions.destroy_semaphore(self.device, self.timeline_semaphore, null);
        self.device_functions.destroy_device(self.device, null);
        self.instance_functions.destroy_instance(self.instance_handle, null);
        self.loader.deinit();
        self.* = undefined;
    }

    /// Attaches the renderer to the existing DCB executor boundary. PM4 remains
    /// API-neutral; supported direct compute work is translated and submitted.
    /// Draws remain observable by default. Complete vertex/pixel programs are
    /// translated and submitted; the opt-in fixed-shader probe is only used
    /// when a draw has no guest graphics programs.
    pub fn dcbBackend(self: *Renderer, memory: GuestMemory) gpu.DcbBackend {
        self.guest_memory = memory;
        return .{ .context = self, .vtable = &dcb_vtable };
    }

    /// Installs the host consumer for completed `SetFlip` frames. The sink is
    /// invoked synchronously after all prior Vulkan work and guest target
    /// writeback have completed, so callers may copy or display `pixels`
    /// without owning Vulkan resources.
    pub fn setPresentationSink(self: *Renderer, sink: ?PresentationSink) void {
        self.presentation_sink = sink;
    }

    /// Installs an optional low-frequency FPS consumer. Updates are emitted
    /// once per measured second rather than once per frame.
    pub fn setFrameRateSink(self: *Renderer, sink: ?FrameRateSink) void {
        self.frame_rate_sink = sink;
        self.frame_rate_counter = .{};
    }

    /// Selects the registered display-buffer allocation named by a flip. With
    /// no resolver the most recently completed target is retained for isolated
    /// DCB tests.
    pub fn setDisplayBufferResolver(self: *Renderer, resolver: ?DisplayBufferResolver) void {
        self.display_buffer_resolver = resolver;
    }

    /// A sink that copies completed guest frames into the renderer-owned host
    /// swapchain. It is installed explicitly after `Renderer` reaches its final
    /// address because the callback context points back to this value.
    pub fn windowPresentationSink(self: *Renderer) ?PresentationSink {
        if (self.window_presentation == null) return null;
        return .{ .context = self, .present = presentWindowSink };
    }

    /// Presents one already-linear frame to the optional window swapchain.
    ///
    /// Batched present: the frame becomes the pending frame and is flushed
    /// unless a present is already running. A frame arriving during a flush
    /// replaces the pending one and is shown by the next flush, so a burst of
    /// eager presents and flips collapses to the latest frame instead of
    /// queuing one swapchain round-trip per draw.
    pub fn presentWindowFrame(self: *Renderer, frame: PresentedFrame) bool {
        self.pending_present = frame;
        return self.flushPendingPresent();
    }

    fn flushPendingPresent(self: *Renderer) bool {
        const frame = self.pending_present orelse return true;
        if (self.present_in_flight) return true;
        self.present_in_flight = true;
        defer self.present_in_flight = false;
        self.pending_present = null;
        self.copyFrameToSwapchain(frame) catch |err| {
            self.last_flip_error = err;
            return false;
        };
        return true;
    }

    fn presentWindowSink(context: ?*anyopaque, frame: PresentedFrame) bool {
        const self: *Renderer = @ptrCast(@alignCast(context orelse return false));
        return self.presentWindowFrame(frame);
    }

    fn copyFrameToSwapchain(self: *Renderer, frame: PresentedFrame) anyerror!void {
        const presentation = &(self.window_presentation orelse return Error.PresentationRejected);
        if (frame.width == 0 or frame.height == 0 or frame.row_pitch_bytes < frame.width * 4) {
            return Error.PresentationRejected;
        }
        const minimum_source_bytes = try std.math.add(
            usize,
            try std.math.mul(usize, frame.height - 1, frame.row_pitch_bytes),
            try std.math.mul(usize, frame.width, 4),
        );
        if (frame.pixels.len < minimum_source_bytes) return Error.PresentationRejected;
        const output_bytes_u64 = @as(u64, presentation.extent.width) * presentation.extent.height * 4;
        const output_bytes = std.math.cast(usize, output_bytes_u64) orelse return Error.PresentationRejected;
        if (output_bytes == 0 or output_bytes > maximum_frame_bytes) return Error.PresentationRejected;

        const upload = &presentation.upload;
        if (output_bytes > upload.size) return Error.PresentationRejected;
        var mapped: ?*anyopaque = null;
        if (self.device_functions.map_memory(self.device, upload.memory, 0, output_bytes, 0, &mapped) != vk.success) {
            return Error.MemoryMapFailed;
        }
        const output: [*]u8 = @ptrCast(mapped orelse {
            self.device_functions.unmap_memory(self.device, upload.memory);
            return Error.MemoryMapFailed;
        });
        scalePresentedFrame(
            output[0..output_bytes],
            presentation.extent.width,
            presentation.extent.height,
            presentation.format,
            frame,
        );
        self.device_functions.unmap_memory(self.device, upload.memory);

        // A zero-timeout acquire can repeatedly miss every FIFO release when
        // the guest submits at nearly the display cadence. The swapchain then
        // keeps its first partial frame indefinitely even though newer frames
        // are ready. Wait for several refresh intervals while keeping a hidden
        // or minimized window from blocking guest execution indefinitely.
        if (self.device_functions.reset_fences(self.device, 1, @ptrCast(&presentation.acquire_fence)) != vk.success) {
            return Error.FenceWaitFailed;
        }
        var image_index: u32 = 0;
        const acquired = presentation.swapchain_functions.acquire_next_image(
            self.device,
            presentation.swapchain,
            presentation_acquire_timeout_ns,
            0,
            presentation.acquire_fence,
            &image_index,
        );
        if (acquired == vk.not_ready or acquired == vk.timeout or acquired == vk.error_out_of_date_khr) {
            // Frame dropped, not an error: the swapchain is still showing the
            // previous frame and a newer one will replace this one.
            self.present_dropped += 1;
            return;
        }
        if (acquired != vk.success and acquired != vk.suboptimal_khr) return Error.SwapchainAcquireFailed;
        if (image_index >= presentation.images.len or
            self.device_functions.wait_for_fences(self.device, 1, @ptrCast(&presentation.acquire_fence), vk.true_value, std.math.maxInt(u64)) != vk.success)
        {
            return Error.FenceWaitFailed;
        }

        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        const upload_barrier = vk.ImageMemoryBarrier{
            .source_access_mask = 0,
            .destination_access_mask = vk.access_transfer_write_bit,
            .old_layout = vk.image_layout_undefined,
            .new_layout = vk.image_layout_transfer_dst_optimal,
            .image = presentation.images[image_index],
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_top_of_pipe_bit,
            vk.pipeline_stage_transfer_bit,
            0,
            0,
            null,
            0,
            null,
            1,
            @ptrCast(&upload_barrier),
        );
        const copy = vk.BufferImageCopy{
            .image_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .image_extent = .{ .width = presentation.extent.width, .height = presentation.extent.height, .depth = 1 },
        };
        self.device_functions.cmd_copy_buffer_to_image(
            command_buffer,
            upload.handle,
            presentation.images[image_index],
            vk.image_layout_transfer_dst_optimal,
            1,
            @ptrCast(&copy),
        );
        const present_barrier = vk.ImageMemoryBarrier{
            .source_access_mask = vk.access_transfer_write_bit,
            .destination_access_mask = 0,
            .old_layout = vk.image_layout_transfer_dst_optimal,
            .new_layout = vk.image_layout_present_src_khr,
            .image = presentation.images[image_index],
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_transfer_bit,
            vk.pipeline_stage_bottom_of_pipe_bit,
            0,
            0,
            null,
            0,
            null,
            1,
            @ptrCast(&present_barrier),
        );
        try self.submitOneShot(command_buffer);

        const present_info = vk.PresentInfoKHR{
            .swapchain_count = 1,
            .swapchains = @ptrCast(&presentation.swapchain),
            .image_indices = @ptrCast(&image_index),
        };
        const presented = presentation.swapchain_functions.queue_present(self.queue, &present_info);
        if (presented != vk.success and presented != vk.suboptimal_khr) return Error.SwapchainPresentFailed;
    }

    /// Presents a resident color attachment without a GPU→CPU→GPU round trip.
    /// Vulkan performs format conversion and 1920×1080→window scaling in the
    /// blit; the source returns to attachment layout for the next guest draw.
    fn blitRenderTargetToSwapchain(self: *Renderer, target_index: usize) anyerror!void {
        if (target_index >= self.render_targets.items.len) return Error.MissingPresentedFrame;
        try self.transitionRenderTargetToColorAttachment(target_index);
        const target = self.render_targets.items[target_index];
        // Vulkan transfer/blit commands cannot read a multisampled image.
        // Such an attachment needs an explicit guest resolve before it can be
        // scanned out; treating it as presentable only records an invalid host
        // command and, previously, stopped the guest queue at R_FLIP.
        if (!target.initialized or target.target.descriptor.fragments_log2 != 0) {
            return Error.MissingPresentedFrame;
        }
        const presentation = &(self.window_presentation orelse return Error.PresentationRejected);

        if (self.device_functions.reset_fences(self.device, 1, @ptrCast(&presentation.acquire_fence)) != vk.success) {
            return Error.FenceWaitFailed;
        }
        var image_index: u32 = 0;
        const acquired = presentation.swapchain_functions.acquire_next_image(
            self.device,
            presentation.swapchain,
            presentation_acquire_timeout_ns,
            0,
            presentation.acquire_fence,
            &image_index,
        );
        if (acquired == vk.not_ready or acquired == vk.timeout or acquired == vk.error_out_of_date_khr) {
            self.present_dropped += 1;
            return;
        }
        if (acquired != vk.success and acquired != vk.suboptimal_khr) return Error.SwapchainAcquireFailed;
        if (image_index >= presentation.images.len or
            self.device_functions.wait_for_fences(self.device, 1, @ptrCast(&presentation.acquire_fence), vk.true_value, std.math.maxInt(u64)) != vk.success)
        {
            return Error.FenceWaitFailed;
        }

        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        const source_to_transfer = vk.ImageMemoryBarrier{
            .source_access_mask = vk.access_color_attachment_write_bit,
            .destination_access_mask = vk.access_transfer_read_bit,
            .old_layout = vk.image_layout_color_attachment_optimal,
            .new_layout = vk.image_layout_transfer_src_optimal,
            .image = target.image.handle,
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        const destination_to_transfer = vk.ImageMemoryBarrier{
            .source_access_mask = 0,
            .destination_access_mask = vk.access_transfer_write_bit,
            .old_layout = vk.image_layout_undefined,
            .new_layout = vk.image_layout_transfer_dst_optimal,
            .image = presentation.images[image_index],
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        const before_blit = [_]vk.ImageMemoryBarrier{ source_to_transfer, destination_to_transfer };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_color_attachment_output_bit | vk.pipeline_stage_top_of_pipe_bit,
            vk.pipeline_stage_transfer_bit,
            0,
            0,
            null,
            0,
            null,
            before_blit.len,
            @ptrCast(&before_blit),
        );
        const blit = vk.ImageBlit{
            .source_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .source_offsets = .{
                .{
                    .x = 0,
                    .y = if (target.scanout_flip_vertical) @intCast(target.target.descriptor.height) else 0,
                    .z = 0,
                },
                .{
                    .x = @intCast(target.target.descriptor.width),
                    .y = if (target.scanout_flip_vertical) 0 else @intCast(target.target.descriptor.height),
                    .z = 1,
                },
            },
            .destination_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .destination_offsets = .{
                .{ .x = 0, .y = 0, .z = 0 },
                .{ .x = @intCast(presentation.extent.width), .y = @intCast(presentation.extent.height), .z = 1 },
            },
        };
        self.device_functions.cmd_blit_image(
            command_buffer,
            target.image.handle,
            vk.image_layout_transfer_src_optimal,
            presentation.images[image_index],
            vk.image_layout_transfer_dst_optimal,
            1,
            @ptrCast(&blit),
            vk.filter_nearest,
        );
        const source_to_attachment = vk.ImageMemoryBarrier{
            .source_access_mask = vk.access_transfer_read_bit,
            .destination_access_mask = vk.access_color_attachment_read_bit | vk.access_color_attachment_write_bit,
            .old_layout = vk.image_layout_transfer_src_optimal,
            .new_layout = vk.image_layout_color_attachment_optimal,
            .image = target.image.handle,
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        const destination_to_present = vk.ImageMemoryBarrier{
            .source_access_mask = vk.access_transfer_write_bit,
            .destination_access_mask = 0,
            .old_layout = vk.image_layout_transfer_dst_optimal,
            .new_layout = vk.image_layout_present_src_khr,
            .image = presentation.images[image_index],
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        const after_blit = [_]vk.ImageMemoryBarrier{ source_to_attachment, destination_to_present };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_transfer_bit,
            vk.pipeline_stage_color_attachment_output_bit | vk.pipeline_stage_bottom_of_pipe_bit,
            0,
            0,
            null,
            0,
            null,
            after_blit.len,
            @ptrCast(&after_blit),
        );
        try self.submitOneShot(command_buffer);

        const present_info = vk.PresentInfoKHR{
            .swapchain_count = 1,
            .swapchains = @ptrCast(&presentation.swapchain),
            .image_indices = @ptrCast(&image_index),
        };
        const presented = presentation.swapchain_functions.queue_present(self.queue, &present_info);
        if (presented != vk.success and presented != vk.suboptimal_khr) return Error.SwapchainPresentFailed;
    }

    /// Reuses host/device allocations for an exact guest range. Guest-authored
    /// buffers upload current bytes; large GPU-authored outputs stay resident
    /// until a consumer explicitly needs guest-visible data.
    pub fn stageGuestStorageBuffer(self: *Renderer, guest_address: u64, size: usize) (Error || std.mem.Allocator.Error)!StagedBuffer {
        return self.stageGuestStorageBufferAt(0, guest_address, size);
    }

    /// Uploads one exact guest range and publishes it at a stable element of
    /// set 0 / binding 0. Descriptor-array identity is independent from the
    /// allocation cache, so slots can be rebound between dispatches.
    pub fn stageGuestStorageBufferAt(
        self: *Renderer,
        descriptor_index: u32,
        guest_address: u64,
        size: usize,
    ) (Error || std.mem.Allocator.Error)!StagedBuffer {
        const profile_started = hostTimestampNs();
        defer self.frame_profile.storage_stage_ns +|= elapsedHostNanoseconds(profile_started);
        if (descriptor_index >= maximum_storage_descriptors) return Error.InvalidStorageDescriptor;
        if (size == 0) return Error.GuestMemoryReadFailed;
        if (size > maximum_staged_buffer_bytes) return Error.GuestBufferTooLarge;
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        self.guest_buffer_sequence +%= 1;

        var entry_index: ?usize = null;
        var recycled_entry = false;
        for (self.guest_buffers.items, 0..) |entry, index| {
            if (entry.guest_address == guest_address and entry.size == size) {
                entry_index = index;
                break;
            }
        }
        const cache_hit = entry_index != null;
        if (entry_index == null) {
            // Each descriptor slot owns at most one backing allocation. Guest
            // ring addresses change constantly, but rebinding slot N does not
            // require retaining every address slot N used in prior frames.
            var recycle_index: ?usize = null;
            for (self.guest_buffers.items, 0..) |entry, index| {
                if (entry.descriptor_index == descriptor_index) {
                    recycle_index = index;
                    break;
                }
            }
            // Do not evict a GPU-authored range merely because the next shader
            // binds this descriptor slot to another address. Descriptor-array
            // slots do not own cache allocations: keep the dirty range by
            // address and recycle an old clean allocation first. Unity clears
            // several buffers through the same UAV slot before consuming them;
            // flushing the previous slot owner here otherwise turns a resident
            // render target into a full device -> guest -> device round trip.
            if (recycle_index) |index| {
                if (self.guest_buffers.items[index].gpu_dirty) {
                    recycle_index = null;
                    if (self.guest_buffers.items.len >= maximum_guest_buffers) {
                        var oldest_clean: u64 = std.math.maxInt(u64);
                        for (self.guest_buffers.items, 0..) |entry, candidate_index| {
                            if (!entry.gpu_dirty and entry.last_used_sequence < oldest_clean) {
                                oldest_clean = entry.last_used_sequence;
                                recycle_index = candidate_index;
                            }
                        }
                    }
                }
            }
            if (recycle_index == null and self.guest_buffers.items.len >= maximum_guest_buffers) {
                var oldest_index: usize = 0;
                var oldest: u64 = std.math.maxInt(u64);
                for (self.guest_buffers.items, 0..) |entry, index| {
                    if (entry.last_used_sequence < oldest) {
                        oldest = entry.last_used_sequence;
                        oldest_index = index;
                    }
                }
                recycle_index = oldest_index;
            }

            if (recycle_index == null) {
                try self.guest_buffers.ensureUnusedCapacity(self.allocator, 1);
                const device_local = try self.createBuffer(
                    size,
                    vk.buffer_usage_storage_buffer_bit,
                    vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
                );
                errdefer self.destroyBuffer(device_local);
                self.guest_buffers.appendAssumeCapacity(.{
                    .descriptor_index = descriptor_index,
                    .guest_address = guest_address,
                    .size = size,
                    .device_local = device_local,
                    .last_used_sequence = self.guest_buffer_sequence,
                });
                entry_index = self.guest_buffers.items.len - 1;
            } else {
                // Batched graphics snapshots clean ranges in the frame upload
                // arena; writable resident ranges are fence-completed by the
                // readback below before this backing allocation is recycled.
                const victim_index = recycle_index.?;
                if (self.guest_buffers.items[victim_index].gpu_dirty) {
                    try self.flushGuestStorageBuffer(victim_index);
                }
                const victim = &self.guest_buffers.items[victim_index];
                if (victim.device_local.size < size) {
                    const replacement_device = try self.createBuffer(
                        size,
                        vk.buffer_usage_storage_buffer_bit,
                        vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
                    );
                    errdefer self.destroyBuffer(replacement_device);
                    self.destroyBuffer(victim.device_local);
                    victim.device_local = replacement_device;
                }
                victim.descriptor_index = descriptor_index;
                victim.guest_address = guest_address;
                victim.size = size;
                victim.last_used_sequence = self.guest_buffer_sequence;
                victim.gpu_dirty = false;
                victim.page_generation = 0;
                entry_index = victim_index;
                recycled_entry = true;
            }
            self.buffer_cache_misses += 1;
        } else {
            self.buffer_cache_hits += 1;
        }

        const entry = &self.guest_buffers.items[entry_index.?];
        entry.last_used_sequence = self.guest_buffer_sequence;
        if (!entry.gpu_dirty) {
            try self.flushGuestStorageImageRange(guest_address, size);
            const tracked_generation = if (memory.track_gpu_read) |track|
                track(memory.context, guest_address, size)
            else
                0;
            if (tracked_generation != 0 and (!self.draw_uploads_enabled or cache_hit)) {
                if (entry.page_generation != tracked_generation) {
                    // The backing buffer may still be read by an older timeline
                    // tick. Changed pages are uncommon; wait only on that path,
                    // while unchanged draws bind the persistent copy directly.
                    if (cache_hit or recycled_entry) try self.waitForSubmittedWork();
                    var mapped: ?*anyopaque = null;
                    if (self.device_functions.map_memory(self.device, entry.device_local.memory, 0, size, 0, &mapped) != vk.success) {
                        return Error.MemoryMapFailed;
                    }
                    defer self.device_functions.unmap_memory(self.device, entry.device_local.memory);
                    const destination: [*]u8 = @ptrCast(mapped orelse return Error.MemoryMapFailed);
                    entry.page_generation = 0;
                    var observed_generation = tracked_generation;
                    var attempt: usize = 0;
                    while (true) : (attempt += 1) {
                        if (!memory.read(memory.context, guest_address, destination[0..size])) {
                            return Error.GuestMemoryReadFailed;
                        }
                        self.frame_profile.upload_bytes +%= size;
                        self.frame_profile.storage_upload_bytes +%= size;
                        self.buffer_uploads += 1;
                        const after = if (memory.gpu_generation) |generation|
                            generation(memory.context, guest_address, size)
                        else
                            observed_generation;
                        if (after == observed_generation) {
                            entry.page_generation = observed_generation;
                            break;
                        }
                        if (attempt >= 1) {
                            // A continuously written range is still usable as a
                            // snapshot, but do not cache it as current.
                            entry.page_generation = 0;
                            break;
                        }
                        observed_generation = if (memory.track_gpu_read) |track|
                            track(memory.context, guest_address, size)
                        else
                            0;
                        if (observed_generation == 0) break;
                    }
                } else {
                    self.frame_profile.resident_storage_bytes +%= size;
                }
                self.updateStorageDescriptor(descriptor_index, entry.device_local);
                self.active_descriptor_set = self.descriptor_set;
                return .{
                    .buffer = entry.device_local.handle,
                    .descriptor_set = self.descriptor_set,
                    .descriptor_index = descriptor_index,
                    .size = entry.size,
                    .allocation_cache_hit = cache_hit,
                };
            }
            if (self.draw_uploads_enabled) {
                for (self.draw_upload_cache.items) |cached| {
                    if (cached.guest_address != guest_address or cached.size != size) continue;
                    self.frame_profile.resident_storage_bytes +%= size;
                    self.updateStorageDescriptorRange(
                        descriptor_index,
                        cached.upload.buffer,
                        cached.upload.offset,
                        cached.upload.size,
                    );
                    self.active_descriptor_set = self.descriptor_set;
                    return .{
                        .buffer = cached.upload.buffer,
                        .descriptor_set = self.descriptor_set,
                        .descriptor_index = descriptor_index,
                        .size = size,
                        .allocation_cache_hit = true,
                    };
                }
                const upload = try self.allocateDrawUpload(size);
                const mapping = self.draw_upload_mapping orelse return Error.MemoryMapFailed;
                const destination = mapping[@intCast(upload.offset)..][0..size];
                if (!memory.read(memory.context, guest_address, destination)) {
                    return Error.GuestMemoryReadFailed;
                }
                self.frame_profile.upload_bytes +%= size;
                self.frame_profile.storage_upload_bytes +%= size;
                self.buffer_uploads += 1;
                try self.draw_upload_cache.append(self.allocator, .{
                    .guest_address = guest_address,
                    .size = size,
                    .upload = upload,
                });
                self.updateStorageDescriptorRange(
                    descriptor_index,
                    upload.buffer,
                    upload.offset,
                    upload.size,
                );
                self.active_descriptor_set = self.descriptor_set;
                return .{
                    .buffer = upload.buffer,
                    .descriptor_set = self.descriptor_set,
                    .descriptor_index = descriptor_index,
                    .size = size,
                    .allocation_cache_hit = cache_hit,
                };
            }
            var mapped: ?*anyopaque = null;
            if (self.device_functions.map_memory(self.device, entry.device_local.memory, 0, size, 0, &mapped) != vk.success) {
                return Error.MemoryMapFailed;
            }
            const destination: [*]u8 = @ptrCast(mapped orelse {
                self.device_functions.unmap_memory(self.device, entry.device_local.memory);
                return Error.MemoryMapFailed;
            });
            const read_ok = memory.read(memory.context, guest_address, destination[0..size]);
            self.device_functions.unmap_memory(self.device, entry.device_local.memory);
            if (!read_ok) return Error.GuestMemoryReadFailed;
            self.frame_profile.upload_bytes +%= size;
            self.frame_profile.storage_upload_bytes +%= size;
            self.buffer_uploads += 1;
        } else {
            self.frame_profile.resident_storage_bytes +%= size;
        }
        self.updateStorageDescriptor(descriptor_index, entry.device_local);
        self.active_descriptor_set = self.descriptor_set;
        return .{
            .buffer = entry.device_local.handle,
            .descriptor_set = self.descriptor_set,
            .descriptor_index = descriptor_index,
            .size = entry.size,
            .allocation_cache_hit = cache_hit,
        };
    }

    pub fn readbackGuestStorageBuffer(self: *Renderer, guest_address: u64, destination: []u8) Error!void {
        const entry = for (self.guest_buffers.items) |*candidate| {
            if (candidate.guest_address == guest_address and candidate.size == destination.len) break candidate;
        } else return Error.GuestBufferNotStaged;
        try self.readMapped(entry.device_local, destination);
        self.frame_profile.readback_bytes +%= destination.len;
        self.frame_profile.storage_readback_bytes +%= destination.len;
    }

    fn flushGuestStoragePrefix(self: *Renderer, index: usize, requested_size: usize) (Error || std.mem.Allocator.Error)!void {
        if (index >= self.guest_buffers.items.len) return Error.GuestBufferNotStaged;
        const entry = &self.guest_buffers.items[index];
        if (!entry.gpu_dirty) return;
        const entry_size = std.math.cast(usize, entry.size) orelse return Error.GuestBufferTooLarge;
        const size = @min(requested_size, entry_size);
        if (size == 0) return;
        const bytes = try self.allocator.alloc(u8, size);
        defer self.allocator.free(bytes);
        try self.readMapped(entry.device_local, bytes);
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        if (!memory.write(memory.context, entry.guest_address, bytes)) return Error.GuestMemoryWriteFailed;
        self.frame_profile.readback_bytes +%= size;
        self.frame_profile.storage_readback_bytes +%= size;
        if (size == entry_size) {
            entry.gpu_dirty = false;
            entry.page_generation = if (memory.gpu_generation) |generation|
                generation(memory.context, entry.guest_address, entry_size)
            else
                0;
        }
    }

    fn flushGuestStorageBuffer(self: *Renderer, index: usize) (Error || std.mem.Allocator.Error)!void {
        return self.flushGuestStoragePrefix(index, std.math.maxInt(usize));
    }

    fn flushGuestStorageRange(self: *Renderer, address: u64, size: usize) (Error || std.mem.Allocator.Error)!void {
        for (self.guest_buffers.items, 0..) |entry, index| {
            if (!entry.gpu_dirty) continue;
            // Guest V# record counts are occasionally conservative enough to
            // span unrelated fence/label allocations. A four-byte command
            // processor access inside that declared range is not evidence that
            // the CPU is reading the compute output. Materialize only a read
            // that names the resource itself; sampled-image and presentation
            // paths also use the exact base address.
            if (address == entry.guest_address) try self.flushGuestStoragePrefix(index, size);
        }
    }

    pub fn dispatchSpirv(self: *Renderer, words: []const u32, group_count: [3]u32) (Error || std.mem.Allocator.Error)!DispatchReport {
        const lookup = try self.getComputePipeline(words);
        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        self.device_functions.cmd_bind_pipeline(command_buffer, vk.pipeline_bind_point_compute, lookup.pipeline);
        if (self.active_descriptor_set) |descriptor_set| {
            self.device_functions.cmd_bind_descriptor_sets(
                command_buffer,
                vk.pipeline_bind_point_compute,
                self.compute_pipeline_layout,
                0,
                1,
                @ptrCast(&descriptor_set),
                0,
                null,
            );
        }
        self.device_functions.cmd_dispatch(command_buffer, group_count[0], group_count[1], group_count[2]);
        try self.submitOneShot(command_buffer);
        return .{
            .pipeline_cache_hit = lookup.cache_hit,
            .group_count = group_count,
            .spirv_words = words.len,
        };
    }

    pub fn dispatchRdna2Address(
        self: *Renderer,
        program_address: u64,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!DispatchReport {
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        const reader = gpu.ShaderMemoryReader{ .context = memory.context, .read_fn = memory.read };
        const header_address = if (memory.shader_header) |resolve|
            resolve(memory.context, program_address)
        else
            null;
        const analysis = try self.analyzedProgram(reader, program_address, header_address);
        var module = try analysis.translateSpirv(self.allocator, .{ .stage = .compute, .local_size = local_size });
        defer module.deinit(self.allocator);
        return self.dispatchSpirv(module.words, group_count);
    }

    /// Captures compute user data and AGC resource metadata at the DCB boundary,
    /// stages every declared buffer table entry into the fixed Vulkan array,
    /// maps each executable MUBUF V# to its array element, then writes modified
    /// storage ranges back to guest memory after the synchronous submission.
    pub fn dispatchRdna2State(
        self: *Renderer,
        state: *const gpu.State,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!DispatchReport {
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        const reader = gpu.ShaderMemoryReader{ .context = memory.context, .read_fn = memory.read };
        const program_address = gpu.resources.ShaderStage.compute.programAddress(state) orelse {
            return Error.MissingComputeProgram;
        };
        const header_address = if (memory.shader_header) |resolve|
            resolve(memory.context, program_address)
        else
            null;
        const bindings = try gpu.ShaderBindings.capture(state, .compute, header_address, reader);
        const system_registers = gpu.resources.decodeComputeSystemRegisters(state);
        const analysis = try self.analyzedProgram(reader, program_address, header_address);
        const program_hash = std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(analysis.program.code));
        if (self.device_info.vendor_id == 0x10de and self.reanimal_nvidia_compute_quarantined) {
            self.elided_dispatches += 1;
            return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
        }
        // REANIMAL submits this exact wave-compaction kernel once with four
        // workgroups before reusing it for the small per-view allocations.
        // Remembering that title-specific sequence keeps the later workaround
        // from matching an unrelated game which happens to share the shader.
        if (self.device_info.vendor_id == 0x10de and
            program_hash == 0xb6c9_d14d_22b1_3b42 and
            analysis.program.instructions.items.len == 37 and
            std.meta.eql(group_count, [3]u32{ 4, 1, 1 }) and
            std.meta.eql(local_size, [3]u32{ 64, 1, 1 }))
        {
            self.reanimal_nvidia_wave_compaction_seen = true;
        }
        if (self.compute_execution_limit != null and self.translated_dispatches >= 20) {
            std.debug.print(
                "[vulkan dcb] compute bisection next=#{d} program=0x{x} hash=0x{x} words={d} instructions={d} groups={d}x{d}x{d} local={d}x{d}x{d}\n",
                .{
                    self.translated_dispatches + 1,
                    program_address,
                    program_hash,
                    analysis.program.code.len,
                    analysis.program.instructions.items.len,
                    group_count[0],
                    group_count[1],
                    group_count[2],
                    local_size[0],
                    local_size[1],
                    local_size[2],
                },
            );
        }
        const emulation_started = hostTimestampNs();
        if (try self.tryEmulateGdsInitialization(
            memory,
            state,
            analysis,
            system_registers,
            local_size,
            group_count,
        )) |report| {
            self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
            return report;
        }
        if (try self.tryEmulateGdsReadback(
            memory,
            state,
            analysis,
            system_registers,
            local_size,
            group_count,
        )) |report| {
            self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
            return report;
        }
        if (try self.tryEmulateBufferCopy(
            memory,
            state,
            analysis,
            system_registers,
            local_size,
            group_count,
        )) |report| {
            self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
            return report;
        }
        if (try self.tryEmulateSimpleBufferFill(
            memory,
            state,
            analysis,
            system_registers,
            local_size,
            group_count,
        )) |report| {
            self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
            return report;
        }
        if (try self.tryEmulatePackedColorBufferClear(
            memory,
            state,
            analysis,
            system_registers,
            local_size,
            group_count,
        )) |report| {
            self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
            return report;
        }
        if (try self.tryEmulateImageStoreClear(
            memory,
            &bindings,
            reader,
            analysis,
            system_registers,
            local_size,
            group_count,
        )) |report| {
            self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
            return report;
        }
        if (try self.tryEmulateImageCopy(
            memory,
            &bindings,
            reader,
            analysis,
            system_registers,
            local_size,
            group_count,
        )) |report| {
            self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
            return report;
        }
        if (try self.tryEmulateVolumeBufferCopy(
            memory,
            &bindings,
            reader,
            analysis,
            system_registers,
            local_size,
            group_count,
        )) |report| {
            self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
            return report;
        }
        self.frame_profile.compute_emulation_ns +|= elapsedHostNanoseconds(emulation_started);
        // PPSA26344 needs its startup buffer producers: they build visibility
        // lists and indirect scene state which later frames consume. Skipping
        // every compute dispatch made the title advance quickly but left those
        // one-time allocations permanently empty. During the bounded warm-up,
        // retain buffer/GDS producers and cheap CPU-emulated clears while
        // eliding image-only post-processing. Full compute resumes afterwards.
        if (self.flip_callbacks < self.skip_compute_until_flip and
            !analysis.hasBufferExternalEffects())
        {
            self.elided_dispatches += 1;
            return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
        }
        // The bounded dispatcher and per-invocation CMPX predicate model make
        // the nested reduction and packed-mask kernels finite on NVIDIA. They
        // used to be quarantined here; current-title bisection now runs both
        // through the first presentation without a device reset.
        // This visibility/statistics pass atomically ORs a 256-bit candidate
        // mask into one 32-byte transient result. Its 256-lane Z workgroup
        // relies on EXEC convergence that the current scalar dispatcher cannot
        // yet preserve, and submitting it resets NVIDIA devices before the
        // title's first presentation. Resolve the exact writable V# on the CPU
        // and conservatively keep every candidate visible; leaving the mask at
        // zero makes all later scene-composition passes reject their inputs.
        if (!self.translate_compute_only and self.device_info.vendor_id == 0x10de and matchesYoteiExposureStatisticsCompute(
            program_hash,
            group_count,
            local_size,
            analysis.program.instructions.items.len,
        )) {
            return try self.emulateYoteiVisibilityMaskFallback(
                memory,
                &bindings,
                reader,
                analysis,
                group_count,
                program_address,
            );
        }
        // Ballot compaction and shared-mask initialization are also safe with
        // the bounded dispatcher. Keeping them live is required for the
        // visibility lists consumed by the final composition pass.
        // Yotei's full environment-lighting kernel is now translatable after
        // native 2D-array storage and nested sampler-pointer recovery. Its
        // deeply divergent 3,215-instruction loop still depends on wave-wide
        // EXEC convergence, however, and reproducibly resets NVIDIA before
        // the first draw. Preserve the zero-initialized lighting volume until
        // subgroup control flow can execute this exact program safely.
        const yotei_environment_lighting =
            std.meta.eql(group_count, [3]u32{ 1, 64, 36 }) and
            analysis.program.instructions.items.len == 3215 and
            programHasRawInstruction(analysis, 0x138, &.{ 0xf090_0208, 0x0061_0300 }) and
            programHasRawInstruction(analysis, 0x2b74, &.{ 0xf020_2710, 0x0001_0058 }) and
            programHasRawInstruction(analysis, 0x48b0, &.{ 0xf020_2710, 0x0001_0058 });
        const use_yotei_environment_lighting_fallback = !self.translate_compute_only and
            self.device_info.vendor_id == 0x10de and
            yotei_environment_lighting;
        if (use_yotei_environment_lighting_fallback) {
            return try self.emulateYoteiEnvironmentLightingFallback(
                memory,
                &bindings,
                reader,
                analysis,
                group_count,
                program_address,
            );
        }
        // Yotei's two reduction and two gather passes used to be quarantined
        // here. Correct EXEC state merging and Vulkan-valid dynamic sample
        // offsets make all four safe on NVIDIA, including repeated execution;
        // keep them on the normal translation path because the final composite
        // consumes their outputs.
        // These two REANIMAL kernels must be recognized before descriptor and
        // image preparation. Their preparation path alone records Vulkan work
        // which can reset an NVIDIA device, so matching the eventual SPIR-V
        // module is already too late. The first kernel arms the title-specific
        // sequence using an exact instruction encoding; the follow-up then also
        // requires its unique execution shape.
        if (self.device_info.vendor_id == 0x10de) {
            const bootstrap = matchesReanimalNvidiaBootstrapComputeShape(
                group_count,
                analysis.program.instructions.items.len,
            ) and programHasRawInstruction(
                analysis,
                0x4a8,
                &.{ 0xf020_0f10, 0x0000_0004 },
            );
            if (bootstrap) {
                self.reanimal_nvidia_compute_workaround_active = true;
                if (self.timeline_scheduler_enabled) {
                    self.timeline_scheduler_enabled = false;
                    self.reanimal_restore_timeline_after_flip = self.flip_callbacks +| 1;
                    std.debug.print(
                        "[vulkan dcb] REANIMAL NVIDIA synchronization armed through flip #{d}\n",
                        .{self.reanimal_restore_timeline_after_flip.?},
                    );
                }
                self.reanimal_skip_compute_until_flip = self.flip_callbacks +| 1;
                self.elided_dispatches += 1;
                std.debug.print(
                    "[vulkan dcb] early-elided NVIDIA-unsafe REANIMAL bootstrap compute program=0x{x} groups={d}x{d}x{d}\n",
                    .{ program_address, group_count[0], group_count[1], group_count[2] },
                );
                return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
            }
            if (self.reanimal_nvidia_compute_workaround_active and
                matchesReanimalNvidiaFollowupComputeShape(
                    group_count,
                    analysis.program.instructions.items.len,
                ))
            {
                self.elided_dispatches += 1;
                std.debug.print(
                    "[vulkan dcb] early-elided NVIDIA-unsafe REANIMAL follow-up compute program=0x{x} groups={d}x{d}x{d}\n",
                    .{ program_address, group_count[0], group_count[1], group_count[2] },
                );
                return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
            }
            const unsupported_gather = self.reanimal_nvidia_compute_workaround_active and
                programHasRawInstruction(
                    analysis,
                    0xd4,
                    &.{ 0xf11c_0108, 0x0040_0008 },
                );
            if (unsupported_gather) {
                self.elided_dispatches += 1;
                std.debug.print(
                    "[vulkan dcb] early-elided unsupported REANIMAL image-gather compute program=0x{x} groups={d}x{d}x{d}\n",
                    .{ program_address, group_count[0], group_count[1], group_count[2] },
                );
                return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
            }
        }
        // Conditional-debug state is disabled, so these branches fall through.
        // The remaining large Unreal kernels currently produce a valid module
        // but can still trigger VK_ERROR_DEVICE_LOST on NVIDIA. Preserve the
        // old safe behavior there until their full instruction mix is covered.
        if (self.device_info.vendor_id == 0x10de and programUsesConditionalDebugBranch(analysis)) {
            self.elided_dispatches += 1;
            return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
        }
        // A decoded `.unsupported` instruction guarantees that SPIR-V
        // translation will fail. Detect it before descriptor/image staging:
        // staging large transient resources for a shader that cannot execute
        // can invalidate still-recorded NVIDIA command buffers.
        if (firstUnsupportedInstruction(analysis)) |unsupported| {
            self.elided_dispatches += 1;
            if (self.shouldReportComputeShaderFailure(program_address, error.UnsupportedOpcode)) {
                std.debug.print(
                    "[vulkan dcb] early-elided unsupported compute program=0x{x} pc=0x{x} raw={x:0>8}\n",
                    .{ program_address, unsupported.pc, unsupported.raw[0] },
                );
            }
            return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
        }
        const uses_gds = programUsesGds(analysis);
        if (!analysis.hasExternalEffects()) {
            self.elided_dispatches += 1;
            std.debug.print(
                "[vulkan dcb] elided side-effect-free compute program 0x{x} ({d} instructions, groups={d}x{d}x{d})\n",
                .{
                    program_address,
                    analysis.program.instructions.items.len,
                    group_count[0],
                    group_count[1],
                    group_count[2],
                },
            );
            return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
        }
        try self.beginComputeDispatch();
        var yotei_gds_before: ?[]u8 = null;
        defer if (yotei_gds_before) |bytes| self.allocator.free(bytes);
        const trace_yotei_gds = uses_gds and
            program_address == 0x8000_3f2a_00 and
            self.reported_yotei_gds_dispatches < 8;
        const trace_yotei_visibility = program_address == 0x8000_4101_00 and
            self.reported_yotei_visibility_dispatches < 8;
        if (uses_gds) {
            try self.uploadGdsStorage();
            if (trace_yotei_gds) {
                yotei_gds_before = try self.allocator.dupe(u8, self.gds_storage.items);
                if (self.reported_yotei_gds_dispatches == 0) {
                    std.debug.print(
                        "[vulkan dcb] Yotei GDS culling shader ({d} instructions):\n",
                        .{analysis.program.instructions.items.len},
                    );
                    dumpShaderHead(analysis, analysis.program.instructions.items.len);
                }
            }
        }
        // Graphics already evaluates the whole program so SMEM after a VALU
        // prolog (Yotei's cubemap downsample loads 1/size into VCC at pc=0x14)
        // is specialized. Compute used to stop at the first vector instruction,
        // then SPIR-V zeroed unspecialized s_load — UV collapsed to 0 and the
        // gather of the R8 cube always missed.
        const specialized_scalar_prefix_end: u32 = 0x0010_0000;
        const scalar = gpu.scalar_provenance.evaluateDecodedResourceState(
            reader,
            &bindings,
            analysis.program.instructions.items,
        );
        var resources = blk: {
            const resource_started = hostTimestampNs();
            const prepared = self.prepareComputeResources(
                &bindings,
                reader,
                analysis,
                analysis.program.instructions.items,
                &scalar,
                specialized_scalar_prefix_end,
                null,
            ) catch |err| {
                // Keep NVIDIA's command stream alive if a future kernel exceeds
                // the fixed physical descriptor budget. Unsupported formats
                // and malformed guest descriptors remain hard errors.
                if (err == Error.StorageImageCapacityExceeded and self.device_info.vendor_id == 0x10de) {
                    self.elided_dispatches += 1;
                    std.debug.print(
                        "[vulkan dcb] elided NVIDIA storage-image-capacity kernel program=0x{x} instructions={d}\n",
                        .{ program_address, analysis.program.instructions.items.len },
                    );
                    return .{
                        .pipeline_cache_hit = false,
                        .group_count = group_count,
                        .spirv_words = 0,
                    };
                }
                return err;
            };
            const resource_elapsed_ns = elapsedHostNanoseconds(resource_started);
            self.frame_profile.compute_resource_ns +|= resource_elapsed_ns;
            if (self.traceCurrentGraphicsFrame()) {
                std.debug.print(
                    "[vulkan dcb] compute resource timing program=0x{x} groups={d}x{d}x{d} resource_us={d}\n",
                    .{
                        program_address,
                        group_count[0],
                        group_count[1],
                        group_count[2],
                        resource_elapsed_ns / std.time.ns_per_us,
                    },
                );
            }
            break :blk prepared;
        };
        defer resources.deinit(self);
        if (isYoteiGdsCullingDispatch(uses_gds, group_count, local_size, analysis.program.instructions.items.len)) {
            if (try self.emulateYoteiGdsCulling(memory, &resources, group_count)) |report| {
                return report;
            }
        }
        if (trace_yotei_gds) {
            dumpScalarRegisters(resources.scalar_registers[0..resources.scalar_count]);
            for (resources.mappings[0..resources.mapping_count]) |mapping| {
                const slot: usize = @intCast(mapping.descriptor_index);
                try self.traceGuestBufferContents(
                    memory,
                    resources.addresses[slot],
                    resources.sizes[slot],
                    mapping.descriptor_index,
                );
            }
            if (self.reported_yotei_gds_dispatches == 0) {
                for (analysis.program.instructions.items) |inst| {
                    if (inst.family != .smem) continue;
                    std.debug.print(
                        "[vulkan dcb] Yotei GDS SMEM pc=0x{x} op={s} dst={s}:{d} src0={s}:{d} src1={s}:{d} off={d}\n",
                        .{
                            inst.pc,
                            inst.opcode.mnemonic(),
                            @tagName(inst.dst.kind),
                            inst.dst.reg,
                            @tagName(inst.src0.kind),
                            if (inst.src0.kind == .sgpr) inst.src0.reg else inst.src0.value,
                            @tagName(inst.src1.kind),
                            if (inst.src1.kind == .sgpr) inst.src1.reg else inst.src1.value,
                            inst.memory_offset,
                        },
                    );
                }
                var srt_lo: ?u32 = null;
                var srt_hi: ?u32 = null;
                for (resources.scalar_registers[0..resources.scalar_count]) |scalar_register| {
                    if (scalar_register.producer_pc != null) continue;
                    if (scalar_register.register == 0) srt_lo = scalar_register.value;
                    if (scalar_register.register == 1) srt_hi = scalar_register.value;
                }
                if (srt_lo != null and srt_hi != null) {
                    const srt_address = (@as(u64, srt_hi.?) << 32) | srt_lo.?;
                    var srt_bytes: [0x100]u8 = undefined;
                    if (memory.read(memory.context, srt_address, &srt_bytes)) {
                        std.debug.print("[vulkan dcb] Yotei GDS SRT @0x{x}:", .{srt_address});
                        for (0..srt_bytes.len / 4) |word_index| {
                            const offset = word_index * 4;
                            const value = std.mem.readInt(u32, srt_bytes[offset..][0..4], .little);
                            if (value != 0) std.debug.print(" +0x{x}=0x{x}", .{ offset, value });
                        }
                        std.debug.print("\n", .{});
                    }
                }
            }
        }
        if (trace_yotei_visibility) {
            std.debug.print(
                "[vulkan dcb] Yotei visibility source before dispatch={d} program=0x{x}\n",
                .{ self.reported_yotei_visibility_dispatches + 1, program_address },
            );
            dumpScalarRegisters(resources.scalar_registers[0..resources.scalar_count]);
            for (resources.mappings[0..resources.mapping_count]) |mapping| {
                const slot: usize = @intCast(mapping.descriptor_index);
                try self.traceGuestBufferContents(
                    memory,
                    resources.addresses[slot],
                    resources.sizes[slot],
                    mapping.descriptor_index,
                );
            }
        }
        // The second 64-byte-input reuse of REANIMAL's wave-compaction kernel
        // still depends on cross-lane GCN execution-mask semantics which SPIR-V
        // cannot express per host invocation. Running it writes corrupted view
        // data (a vertically smeared frame) and eventually resets NVIDIA's
        // device. Preserve the earlier 256-byte-input reuse, which produces the
        // readable buoy frame, and quarantine only at this unsafe resource shape.
        if (self.device_info.vendor_id == 0x10de and
            self.reanimal_nvidia_wave_compaction_seen and
            program_hash == 0xb6c9_d14d_22b1_3b42 and
            std.meta.eql(group_count, [3]u32{ 1, 1, 1 }) and
            std.meta.eql(local_size, [3]u32{ 64, 1, 1 }))
        {
            if (resources.mappingForSgpr(4)) |descriptor_index| {
                const slot: usize = @intCast(descriptor_index);
                if (resources.sizes[slot] == 0x40 and !resources.writable[slot]) {
                    self.reanimal_nvidia_compute_quarantined = true;
                    self.elided_dispatches += 1;
                    std.debug.print(
                        "[vulkan dcb] quarantined NVIDIA-unsafe REANIMAL compute after wave-compaction reuse program=0x{x}\n",
                        .{program_address},
                    );
                    return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
                }
            }
        }
        // Resource recovery can prove a syntactically effectful program has no
        // destination that survives this dispatch. The SPIR-V lowerer drops
        // stores through an unrecovered/null V#, and commitComputeWrites uses
        // the same writable flags below. Executing the remaining control flow
        // cannot affect guest state; on large Unreal kernels it can also trip
        // the host GPU watchdog. Elide it before translation/submission while
        // retaining kernels that write GDS, buffers, or storage images.
        if (!uses_gds and !resources.hasWritableExternalState()) {
            self.elided_dispatches += 1;
            if (analysis.program.instructions.items.len >= 256 or log_verbose_gpu) {
                std.debug.print(
                    "[vulkan dcb] elided compute without writable resources program=0x{x} ({d} instructions, groups={d}x{d}x{d})\n",
                    .{
                        program_address,
                        analysis.program.instructions.items.len,
                        group_count[0],
                        group_count[1],
                        group_count[2],
                    },
                );
            }
            return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
        }
        if (self.traceCurrentGraphicsFrame() or
            (self.compute_execution_limit != null and self.translated_dispatches >= 62))
        {
            std.debug.print(
                "[vulkan dcb] traced compute resources dispatch={d} program=0x{x} buffers={d} sampled={d} storage_images={d}\n",
                .{
                    self.frame_profile.dispatches,
                    program_address,
                    resources.mapping_count,
                    resources.sampled_image_mapping_count,
                    resources.storage_image_mapping_count,
                },
            );
            for (resources.mappings[0..resources.mapping_count]) |mapping| {
                const slot: usize = @intCast(mapping.descriptor_index);
                std.debug.print(
                    "  traced buffer slot={d} V#s{d} addr=0x{x} size=0x{x} stride={d} fmt={d} writable={any}\n",
                    .{
                        mapping.descriptor_index,
                        mapping.resource_sgpr,
                        resources.addresses[slot],
                        resources.sizes[slot],
                        mapping.stride,
                        mapping.unified_format,
                        resources.writable[slot],
                    },
                );
            }
            for (resources.storage_images[0..resources.storage_image_count], 0..) |image, index| {
                std.debug.print(
                    "  traced storage image slot={d} addr=0x{x} {d}x{d}x{d} fmt={d} type={s} writable={any} rt={any} cache={any}\n",
                    .{
                        index,
                        image.descriptor.address,
                        image.descriptor.width,
                        image.descriptor.height,
                        image.descriptor.depth_or_layers,
                        image.descriptor.unified_format,
                        @tagName(image.descriptor.image_type),
                        image.writable,
                        image.render_target_index,
                        image.cache_index,
                    },
                );
            }
            for (resources.sampled_image_mappings[0..resources.sampled_image_mapping_count]) |sampled| {
                const desc = resources.sampled_image_descriptors[@intCast(sampled.descriptor_index)];
                std.debug.print(
                    "  traced compute sampled slot={d} T#s{d} S#s{d} pc={any} addr=0x{x} {d}x{d}x{d} type={s} fmt={d}\n",
                    .{
                        sampled.descriptor_index,
                        sampled.resource_sgpr,
                        sampled.sampler_sgpr,
                        sampled.instruction_pc,
                        desc.address,
                        desc.width,
                        desc.height,
                        desc.depth_or_layers,
                        @tagName(desc.image_type),
                        desc.unified_format,
                    },
                );
            }
            // This is the first full-resolution pass whose output becomes
            // black in Yotei. Capture its actual inputs at the producer
            // boundary: descriptor dumps alone cannot distinguish a broken
            // shader from an already-empty visibility/ID surface.
            if (program_address == 0x8000_3d60_00 or
                program_address == 0x8000_3b99_00 or
                program_address == 0x8000_3e54_00)
            {
                std.debug.print(
                    "[vulkan dcb] traced Yotei {s} kernel instructions={d}\n",
                    .{
                        if (program_address == 0x8000_3b99_00)
                            "cubemap-filter"
                        else if (program_address == 0x8000_3e54_00)
                            "cubemap-downsample"
                        else
                            "depth/ID",
                        analysis.program.instructions.items.len,
                    },
                );
                dumpScalarRegisters(resources.scalar_registers[0..resources.scalar_count]);
                dumpShaderHead(
                    analysis,
                    if (program_address == 0x8000_3d60_00)
                        analysis.program.instructions.items.len
                    else
                        80,
                );
                for (resources.storage_images[0..resources.storage_image_count], 0..) |prepared, index| {
                    if (prepared.writable) continue;
                    try self.traceStorageImageContents(memory, prepared, index);
                }
                for (resources.mappings[0..resources.mapping_count]) |mapping| {
                    const slot: usize = @intCast(mapping.descriptor_index);
                    if (resources.writable[slot]) continue;
                    try self.traceGuestBufferContents(
                        memory,
                        resources.addresses[slot],
                        resources.sizes[slot],
                        mapping.descriptor_index,
                    );
                }
            }
        }
        if (self.shouldReportComputeResources(program_address)) {
            std.debug.print(
                "[vulkan dcb] compute resources program=0x{x} groups={d}x{d}x{d} buffers={d} sampled={d} storage_images={d} scalars={d}\n",
                .{
                    program_address,
                    group_count[0],
                    group_count[1],
                    group_count[2],
                    resources.mapping_count,
                    resources.sampled_image_mapping_count,
                    resources.storage_image_mapping_count,
                    resources.scalar_count,
                },
            );
            for (resources.mappings[0..resources.mapping_count]) |mapping| {
                const slot: usize = @intCast(mapping.descriptor_index);
                std.debug.print(
                    "  buffer pc={any} V#s{d} slot={d} addr=0x{x} size=0x{x} writable={any}\n",
                    .{
                        mapping.instruction_pc,
                        mapping.resource_sgpr,
                        mapping.descriptor_index,
                        resources.addresses[slot],
                        resources.sizes[slot],
                        resources.writable[slot],
                    },
                );
            }
            for (resources.storage_images[0..resources.storage_image_count], 0..) |image, index| {
                std.debug.print(
                    "  storage image slot={d} addr=0x{x} {d}x{d}x{d} fmt={d} type={s} writable={any}\n",
                    .{
                        index,
                        image.descriptor.address,
                        image.descriptor.width,
                        image.descriptor.height,
                        image.descriptor.depth_or_layers,
                        image.descriptor.unified_format,
                        @tagName(image.descriptor.image_type),
                        image.writable,
                    },
                );
            }
            for (resources.storage_image_mappings[0..resources.storage_image_mapping_count]) |mapping| {
                std.debug.print(
                    "  storage mapping pc={any} T#s{d} slot={d} fmt={s} dim={s} dst={d}/{d}/{d}/{d}\n",
                    .{
                        mapping.instruction_pc,
                        mapping.resource_sgpr,
                        mapping.descriptor_index,
                        @tagName(mapping.format),
                        @tagName(mapping.dimension),
                        mapping.dst_select[0],
                        mapping.dst_select[1],
                        mapping.dst_select[2],
                        mapping.dst_select[3],
                    },
                );
            }
            for (resources.sampled_image_mappings[0..resources.sampled_image_mapping_count]) |mapping| {
                std.debug.print(
                    "  sampled pc={any} T#s{d} S#s{d} slot={d}\n",
                    .{
                        mapping.instruction_pc,
                        mapping.resource_sgpr,
                        mapping.sampler_sgpr,
                        mapping.descriptor_index,
                    },
                );
            }
            if (log_verbose_gpu or self.dump_compute_spirv) {
                dumpScalarRegisters(resources.scalar_registers[0..resources.scalar_count]);
                dumpShaderHead(analysis, 48);
            }
        }
        const translate_started = hostTimestampNs();
        // The only absolute FLAT read in this Yotei cluster-classification
        // kernel sits below a guest-controlled zero-count loop during current
        // startup. Dynamic resolution changes the dispatch dimensions while
        // retaining this exact program, so key the fallback on the shader shape
        // and three instruction sites rather than one captured group count.
        // Unrelated dynamic-address shaders must continue to fail until their
        // pointed allocations can be staged explicitly.
        const yotei_empty_cluster_flat_read =
            analysis.program.instructions.items.len == 490 and
            programHasRawInstruction(analysis, 0x28, &.{ 0xf000_0308, 0x0001_0500 }) and
            programHasRawInstruction(analysis, 0x6e4, &.{ 0xe034_2000, 0x8005_181d }) and
            programHasRawInstruction(analysis, 0x764, &.{ 0xdc30_8000, 0x197d_0018 });
        var module = analysis.translateSpirv(self.allocator, .{
            .stage = .compute,
            .local_size = local_size,
            .storage_buffers = resources.mappings[0..resources.mapping_count],
            .sampled_images = resources.sampled_image_mappings[0..resources.sampled_image_mapping_count],
            .storage_images = resources.storage_image_mappings[0..resources.storage_image_mapping_count],
            .scalar_registers = resources.scalar_registers[0..resources.scalar_count],
            // Compute user-data values change on nearly every dispatch in
            // modern Unity titles.  Keep the module shape stable and source
            // those values from the persistently mapped scalar buffer instead
            // of baking them into a new SPIR-V module/pipeline every frame.
            .dynamic_scalar_binding = if (resources.scalar_count != 0) .{
                .binding = dynamic_scalar_descriptor_binding,
                .value_base = 0,
            } else null,
            .compute_inputs = .{
                .workgroup_id_sgprs = system_registers.workgroup_id_sgprs,
                .threadgroup_size_sgpr = system_registers.threadgroup_size_sgpr,
                .local_invocation_id_components = system_registers.local_invocation_id_components,
            },
            .workgroup_memory_size_bytes = computeLdsSizeBytes(state),
            .gds_storage = uses_gds,
            .descriptor_array_length = maximum_storage_descriptors,
            .specialized_scalar_prefix_end = resources.specialized_scalar_prefix_end,
            .zero_unmapped_flat_loads = yotei_empty_cluster_flat_read,
            .allow_float64 = self.shader_float64_available,
            .allow_image_float32_atomic_min_max = self.image_float32_atomic_min_max_available,
        }) catch |err| {
            self.frame_profile.compute_translate_ns +|= elapsedHostNanoseconds(translate_started);
            if (self.shouldReportComputeShaderFailure(program_address, err)) {
                std.debug.print(
                    "[vulkan dcb] compute program 0x{x}: {d} instructions, groups={d}x{d}x{d}, local={d}x{d}x{d}, rsrc2=0x{x}\n",
                    .{
                        program_address,
                        analysis.program.instructions.items.len,
                        group_count[0],
                        group_count[1],
                        group_count[2],
                        local_size[0],
                        local_size[1],
                        local_size[2],
                        state.readRegister(.shader, 0x213) orelse 0,
                    },
                );
                std.debug.print("[vulkan dcb] Translation error: {s}\n", .{@errorName(err)});
                // Unique small kernels are cheap and useful to print in full;
                // large programs stay capped. Repeated failures are suppressed
                // by address/error above, avoiding per-frame disassembly spam.
                const dump_limit: usize = if (analysis.program.instructions.items.len <= 64) 64 else 12;
                var printed: usize = 0;
                for (analysis.program.instructions.items) |inst| {
                    if (printed >= dump_limit) {
                        std.debug.print("  ... ({d} more instructions)\n", .{
                            analysis.program.instructions.items.len - printed,
                        });
                        break;
                    }
                    std.debug.print(
                        "  pc=0x{x:0>4} {s} dst={s}:{d} src=",
                        .{ inst.pc, inst.opcode.mnemonic(), @tagName(inst.dst.kind), inst.dst.reg },
                    );
                    const sources = inst.sources();
                    for (sources.slice()) |source| {
                        const source_value = switch (source.kind) {
                            .sgpr, .vgpr => source.reg,
                            else => source.value,
                        };
                        std.debug.print(" {s}:{d}", .{ @tagName(source.kind), source_value });
                    }
                    std.debug.print(
                        " off={d} idx={d} offen={d} opid=0x{x}\n",
                        .{ inst.memory_offset, @intFromBool(inst.index_enable), @intFromBool(inst.offset_enable), inst.opcode_id },
                    );
                    printed += 1;
                }
            }
            return err;
        };
        self.frame_profile.compute_translate_ns +|= elapsedHostNanoseconds(translate_started);
        defer module.deinit(self.allocator);
        if (self.traceCurrentGraphicsFrame() and program_address == 0x8000_3d60_00) {
            dumpComputeSpirv(self.allocator, program_address, module.words);
        }
        if (self.dump_compute_spirv) {
            dumpComputeSpirv(self.allocator, program_address, module.words);
        }
        if (self.translate_compute_only) {
            std.debug.print(
                "[vulkan dcb] compute translated only: program=0x{x} spirv_words={d} groups={d}x{d}x{d}\n",
                .{
                    program_address,
                    module.words.len,
                    group_count[0],
                    group_count[1],
                    group_count[2],
                },
            );
            return .{
                .pipeline_cache_hit = false,
                .group_count = group_count,
                .spirv_words = module.words.len,
            };
        }
        try self.writeComputeScalarValues(resources.scalar_registers[0..resources.scalar_count]);
        if (self.dump_compute_spirv) {
            std.debug.print(
                "[vulkan dcb] compute submit begin program=0x{x} groups={d}x{d}x{d} instructions={d} spirv_words={d}\n",
                .{
                    program_address,
                    group_count[0],
                    group_count[1],
                    group_count[2],
                    analysis.program.instructions.items.len,
                    module.words.len,
                },
            );
        }
        const submit_started = hostTimestampNs();
        const report = try self.dispatchSpirv(module.words, group_count);
        const submit_elapsed_ns = elapsedHostNanoseconds(submit_started);
        self.frame_profile.compute_submit_ns +|= submit_elapsed_ns;
        if (self.traceCurrentGraphicsFrame()) {
            std.debug.print(
                "[vulkan dcb] compute timing program=0x{x} groups={d}x{d}x{d} submit_us={d}\n",
                .{
                    program_address,
                    group_count[0],
                    group_count[1],
                    group_count[2],
                    submit_elapsed_ns / std.time.ns_per_us,
                },
            );
        }
        if (self.dump_compute_spirv) {
            std.debug.print("[vulkan dcb] compute submit complete program=0x{x}\n", .{program_address});
        }
        if (uses_gds) {
            try self.downloadGdsStorage();
            if (yotei_gds_before) |before| {
                var changed: usize = 0;
                var nonzero: usize = 0;
                var printed: usize = 0;
                var offset: usize = 0;
                while (offset + 4 <= self.gds_storage.items.len) : (offset += 4) {
                    const old = std.mem.readInt(u32, before[offset..][0..4], .little);
                    const new = std.mem.readInt(u32, self.gds_storage.items[offset..][0..4], .little);
                    if (new != 0) nonzero += 1;
                    if (old == new) continue;
                    changed += 1;
                    if (printed < 32) {
                        std.debug.print(
                            "  GDS[0x{x:0>4}] 0x{x:0>8}->0x{x:0>8}\n",
                            .{ offset, old, new },
                        );
                        printed += 1;
                    }
                }
                std.debug.print(
                    "[vulkan dcb] Yotei GDS result dispatch={d} changed={d} nonzero_dwords={d}\n",
                    .{ self.reported_yotei_gds_dispatches + 1, changed, nonzero },
                );
                self.reported_yotei_gds_dispatches += 1;
            }
        }
        try self.commitComputeWrites(memory, &resources);
        if (trace_yotei_visibility) {
            for (resources.writable, 0..) |writable, slot| {
                if (!writable or resources.sizes[slot] == 0) continue;
                try self.traceGuestBufferContents(
                    memory,
                    resources.addresses[slot],
                    resources.sizes[slot],
                    @intCast(slot),
                );
            }
            self.reported_yotei_visibility_dispatches += 1;
        }
        try self.commitStorageImages(memory, &resources);
        return report;
    }

    fn tryEmulateGdsInitialization(
        self: *Renderer,
        memory: GuestMemory,
        state: *const gpu.State,
        analysis: *const gpu.ShaderAnalysis,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        const inst = analysis.program.instructions.items;
        if (inst.len != 14 or
            inst[0].opcode != .s_inst_prefetch or
            inst[1].opcode != .v_lshl_add_u32 or
            inst[2].opcode != .s_buffer_load_dword or
            inst[3].opcode != .s_waitcnt or
            inst[4].opcode != .v_cmpx_gt_u32 or
            inst[5].opcode != .s_cbranch_execz or
            inst[6].opcode != .buffer_load_format_x or
            inst[7].opcode != .s_buffer_load_dword or
            inst[8].opcode != .s_waitcnt or
            inst[9].opcode != .v_mov_b32 or
            inst[10].opcode != .s_bfm_b32 or
            inst[11].opcode != .s_waitcnt or
            inst[12].opcode != .ds_write_b32 or
            inst[13].opcode != .s_endpgm)
        {
            return null;
        }
        if (local_size[0] != 64 or local_size[1] != 1 or local_size[2] != 1 or
            group_count[1] != 1 or group_count[2] != 1 or
            system.workgroup_id_sgprs[0] != 8 or
            system.workgroup_id_sgprs[1] != null or system.workgroup_id_sgprs[2] != null or
            system.local_invocation_id_components != 1)
        {
            return null;
        }
        if (!registerOperand(inst[1].dst, .vgpr, 0) or
            !registerOperand(inst[1].src0, .sgpr, 8) or
            inst[1].src1.kind != .integer_inline_constant or inst[1].src1.value != 6 or
            !registerOperand(inst[1].src2, .vgpr, 0) or
            inst[2].dst.kind != .vcc_lo or !registerOperand(inst[2].src0, .sgpr, 4) or inst[2].memory_offset != 0 or
            inst[4].dst.kind != .exec_lo or inst[4].src0.kind != .vcc_lo or !registerOperand(inst[4].src1, .vgpr, 0) or
            !registerOperand(inst[6].dst, .vgpr, 0) or !registerOperand(inst[6].src0, .vgpr, 0) or
            !registerOperand(inst[6].src1, .sgpr, 0) or !inst[6].index_enable or inst[6].offset_enable or
            inst[7].dst.kind != .vcc_lo or !registerOperand(inst[7].src0, .sgpr, 4) or inst[7].memory_offset != 4 or
            !registerOperand(inst[9].dst, .vgpr, 1) or inst[9].src0.kind != .vcc_lo or
            inst[10].dst.kind != .m0 or inst[10].src0.value != 2 or inst[10].src1.value != 14 or
            !inst[12].gds or !registerOperand(inst[12].src0, .vgpr, 0) or !registerOperand(inst[12].src1, .vgpr, 1))
        {
            return null;
        }

        const addresses = try descriptorFromComputeUserData(state, 0);
        const control = try descriptorFromComputeUserData(state, 4);
        if (addresses.stride != 4 or addresses.swizzle_enabled or addresses.add_thread_id or
            addresses.out_of_bounds_select != 0 or addresses.unified_format != 20 or
            addresses.dst_select[0] != 4 or control.address == 0 or control.size_bytes < 8)
        {
            return null;
        }

        const element_count = try readGuestU32(memory, control.address);
        const fill_value = try readGuestU32(memory, control.address + 4);
        const dispatched = std.math.mul(u64, group_count[0], local_size[0]) catch return Error.GuestBufferTooLarge;
        const source_records = if (addresses.stride == 0)
            @as(u64, addresses.record_count)
        else
            addresses.size_bytes / addresses.stride;
        const writes: usize = @intCast(@min(@as(u64, element_count), @min(dispatched, source_records)));

        const gds_bytes: usize = 64 * 1024;
        if (self.gds_storage.items.len == 0) {
            try self.gds_storage.resize(self.allocator, gds_bytes);
            @memset(self.gds_storage.items, 0);
        }
        var address_bytes: [4]u8 = undefined;
        var value_bytes: [4]u8 = undefined;
        std.mem.writeInt(u32, &value_bytes, fill_value, .little);
        for (0..writes) |index| {
            const guest_address = addresses.address + @as(u64, @intCast(index)) * addresses.stride;
            if (!memory.read(memory.context, guest_address, &address_bytes)) return Error.GuestMemoryReadFailed;
            const gds_address: usize = @intCast(std.mem.readInt(u32, &address_bytes, .little) & ~@as(u32, 3));
            if (gds_address > self.gds_storage.items.len or 4 > self.gds_storage.items.len - gds_address) {
                return Error.InvalidStorageDescriptor;
            }
            @memcpy(self.gds_storage.items[gds_address..][0..4], &value_bytes);
        }
        self.emulated_gds_dispatches += 1;
        if (log_verbose_gpu) std.debug.print(
            "[vulkan dcb] emulated GDS initialization: {d} writes, value=0x{x}\n",
            .{ writes, fill_value },
        );
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    /// Executes the matching system kernel which gathers selected GDS dwords
    /// into a guest buffer. GDS already has persistent host backing for DMA and
    /// the initialization kernel above; running this tiny transfer on the CPU
    /// keeps all three producers/consumers coherent without exposing a second,
    /// unsynchronised Vulkan copy of the same 64 KiB address space.
    fn tryEmulateGdsReadback(
        self: *Renderer,
        memory: GuestMemory,
        state: *const gpu.State,
        analysis: *const gpu.ShaderAnalysis,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        const inst = analysis.program.instructions.items;
        if (inst.len != 16 or
            inst[0].opcode != .s_inst_prefetch or
            inst[1].opcode != .v_lshl_add_u32 or
            inst[2].opcode != .s_buffer_load_dword or
            inst[3].opcode != .s_waitcnt or
            inst[4].opcode != .v_cmpx_gt_u32 or
            inst[5].opcode != .s_cbranch_execz or
            inst[6].opcode != .buffer_load_format_x or
            inst[7].opcode != .s_buffer_load_dword or
            inst[8].opcode != .s_waitcnt or
            inst[9].opcode != .v_add_nc_u32 or
            inst[10].opcode != .s_bfm_b32 or
            inst[11].opcode != .s_waitcnt or
            inst[12].opcode != .ds_read_b32 or
            inst[13].opcode != .s_waitcnt or
            inst[14].opcode != .buffer_store_dword or
            inst[15].opcode != .s_endpgm)
        {
            return null;
        }
        if (local_size[0] != 64 or local_size[1] != 1 or local_size[2] != 1 or
            group_count[1] != 1 or group_count[2] != 1 or
            system.workgroup_id_sgprs[0] != 12 or
            system.workgroup_id_sgprs[1] != null or system.workgroup_id_sgprs[2] != null or
            system.local_invocation_id_components != 1)
        {
            return null;
        }
        if (!registerOperand(inst[1].dst, .vgpr, 1) or
            !registerOperand(inst[1].src0, .sgpr, 12) or
            inst[1].src1.kind != .integer_inline_constant or inst[1].src1.value != 6 or
            !registerOperand(inst[1].src2, .vgpr, 0) or
            inst[2].dst.kind != .vcc_lo or !registerOperand(inst[2].src0, .sgpr, 8) or inst[2].memory_offset != 0 or
            inst[4].dst.kind != .exec_lo or inst[4].src0.kind != .vcc_lo or !registerOperand(inst[4].src1, .vgpr, 1) or
            !registerOperand(inst[6].dst, .vgpr, 0) or !registerOperand(inst[6].src0, .vgpr, 1) or
            !registerOperand(inst[6].src1, .sgpr, 0) or !inst[6].index_enable or inst[6].offset_enable or
            inst[7].dst.kind != .vcc_lo or !registerOperand(inst[7].src0, .sgpr, 8) or inst[7].memory_offset != 8 or
            !registerOperand(inst[9].dst, .vgpr, 1) or inst[9].src0.kind != .vcc_lo or !registerOperand(inst[9].src1, .vgpr, 1) or
            inst[10].dst.kind != .m0 or inst[10].src0.value != 2 or inst[10].src1.value != 14 or
            !inst[12].gds or !registerOperand(inst[12].dst, .vgpr, 0) or !registerOperand(inst[12].src0, .vgpr, 0) or
            !registerOperand(inst[14].dst, .vgpr, 0) or !registerOperand(inst[14].src0, .vgpr, 1) or
            !registerOperand(inst[14].src1, .sgpr, 4) or inst[14].index_enable or !inst[14].offset_enable)
        {
            return null;
        }

        const addresses = try descriptorFromComputeUserData(state, 0);
        const destination = try descriptorFromComputeUserData(state, 4);
        const control = try descriptorFromComputeUserData(state, 8);
        if (addresses.address == 0 or addresses.stride != 4 or addresses.swizzle_enabled or
            addresses.add_thread_id or addresses.out_of_bounds_select != 0 or
            addresses.unified_format != 20 or addresses.dst_select[0] != 4 or
            destination.address == 0 or destination.swizzle_enabled or destination.add_thread_id or
            control.address == 0 or control.size_bytes < 12)
        {
            return null;
        }

        try self.flushPendingGuestWrite(control.address, 12);
        const element_count = try readGuestU32(memory, control.address);
        const destination_offset = try readGuestU32(memory, control.address + 8);
        const dispatched = std.math.mul(u64, group_count[0], local_size[0]) catch return Error.GuestBufferTooLarge;
        const source_records = addresses.size_bytes / addresses.stride;
        const writes: usize = @intCast(@min(@as(u64, element_count), @min(dispatched, source_records)));
        if (writes != 0) {
            const source_bytes = std.math.mul(usize, writes, addresses.stride) catch return Error.GuestBufferTooLarge;
            try self.flushPendingGuestWrite(addresses.address, source_bytes);
        }
        if (!self.ensureGdsStorage()) return Error.MemoryAllocationFailed;

        var address_bytes: [4]u8 = undefined;
        var value_bytes: [4]u8 = undefined;
        for (0..writes) |index| {
            const source_address = addresses.address + @as(u64, @intCast(index)) * addresses.stride;
            if (!memory.read(memory.context, source_address, &address_bytes)) return Error.GuestMemoryReadFailed;
            const gds_address: usize = @intCast(std.mem.readInt(u32, &address_bytes, .little) & ~@as(u32, 3));
            if (gds_address > self.gds_storage.items.len or 4 > self.gds_storage.items.len - gds_address) {
                return Error.InvalidStorageDescriptor;
            }
            @memcpy(&value_bytes, self.gds_storage.items[gds_address..][0..4]);

            // The store uses OFFEN rather than IDXEN, so the lane number is a
            // byte offset exactly as on GFX10 (the common one-element path is
            // naturally aligned).
            const byte_offset = std.math.add(u64, destination_offset, index) catch return Error.GuestBufferTooLarge;
            if (byte_offset > destination.size_bytes or 4 > destination.size_bytes - byte_offset) {
                return Error.InvalidStorageDescriptor;
            }
            const destination_address = destination.address + byte_offset;
            try self.flushPendingGuestWrite(destination_address, 4);
            if (!memory.write(memory.context, destination_address, &value_bytes)) return Error.GuestMemoryWriteFailed;
        }
        self.emulated_gds_dispatches += 1;
        if (log_verbose_gpu) std.debug.print(
            "[vulkan dcb] emulated GDS readback: {d} reads, destination_offset=0x{x}\n",
            .{ writes, destination_offset },
        );
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    /// Executes Unity's full-surface 2D image copy without round-tripping two
    /// eight-megabyte tiled images through temporary Vulkan resources.  The
    /// matched kernel only changes the allocation address: source and target
    /// use the same format, dimensions and tile equation, so their guest
    /// payloads are byte-for-byte compatible after the resident source target
    /// has been materialized.
    fn tryEmulateImageCopy(
        self: *Renderer,
        memory: GuestMemory,
        bindings: *const gpu.ShaderBindings,
        reader: gpu.ShaderMemoryReader,
        analysis: *const gpu.ShaderAnalysis,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        const instructions = analysis.program.instructions.items;
        if (!matchesWholeImageCopy(instructions) or
            local_size[0] != 8 or local_size[1] != 8 or local_size[2] != 1)
        {
            return null;
        }
        _ = system;

        const source = (try bindings.inlineImageDescriptor(0)) orelse return null;
        const destination = try imageDescriptorFromUserDataPointer(bindings, reader, 12) orelse return null;
        const control = (try bindings.inlineBufferDescriptor(8)) orelse return null;
        if (control.address == 0 or control.size_bytes < 24 or
            source.address == 0 or destination.address == 0 or source.address == destination.address or
            source.image_type != .color_2d or destination.image_type != .color_2d or
            source.width != destination.width or source.height != destination.height or
            source.depth_or_layers != 1 or destination.depth_or_layers != 1 or
            source.pitch != destination.pitch or source.unified_format != destination.unified_format or
            source.tile_mode != destination.tile_mode or source.samplesLog2() != 0 or
            destination.samplesLog2() != 0 or source.viewBaseLevel() != 0 or
            destination.viewBaseLevel() != 0 or source.viewMipLevels() != 1 or
            destination.viewMipLevels() != 1 or source.dcc_enabled or destination.dcc_enabled or
            source.cmask_fast_clear or destination.cmask_fast_clear or
            source.fmask_compression or destination.fmask_compression)
        {
            return null;
        }

        const bounds_offset = std.math.cast(u64, instructions[2].memory_offset) orelse return null;
        const source_offset = std.math.cast(u64, instructions[9].memory_offset) orelse return null;
        const destination_offset = std.math.cast(u64, instructions[13].memory_offset) orelse return null;
        const last_control_byte = @max(bounds_offset, @max(source_offset, destination_offset)) + 8;
        if (last_control_byte > control.size_bytes) return null;
        const copy_width = try readGuestU32(memory, control.address + bounds_offset);
        const copy_height = try readGuestU32(memory, control.address + bounds_offset + 4);
        const source_x = try readGuestU32(memory, control.address + source_offset);
        const source_y = try readGuestU32(memory, control.address + source_offset + 4);
        const destination_x = try readGuestU32(memory, control.address + destination_offset);
        const destination_y = try readGuestU32(memory, control.address + destination_offset + 4);
        const dispatched_width = std.math.mul(u64, group_count[0], local_size[0]) catch
            return Error.GuestBufferTooLarge;
        const dispatched_height = std.math.mul(u64, group_count[1], local_size[1]) catch
            return Error.GuestBufferTooLarge;
        if (copy_width != source.width or copy_height != source.height or
            source_x != 0 or source_y != 0 or destination_x != 0 or destination_y != 0 or
            dispatched_width < source.width or dispatched_height < source.height)
        {
            return null;
        }

        const source_layout = gpu.TextureLayout.fromImage(source) catch return null;
        const destination_layout = gpu.TextureLayout.fromImage(destination) catch return null;
        if (source_layout.required_source_bytes == 0 or
            source_layout.required_source_bytes != destination_layout.required_source_bytes or
            source_layout.required_source_bytes > maximum_frame_bytes)
        {
            return null;
        }
        const allocation_bytes = std.math.cast(usize, source_layout.required_source_bytes) orelse
            return Error.GuestBufferTooLarge;
        try self.flushPendingGuestWrite(source.address, allocation_bytes);
        const allocation = try self.allocator.alloc(u8, allocation_bytes);
        defer self.allocator.free(allocation);
        if (!memory.read(memory.context, source.address, allocation)) return Error.GuestMemoryReadFailed;
        if (!memory.write(memory.context, destination.address, allocation)) return Error.GuestMemoryWriteFailed;
        self.invalidateDmaDestination(destination.address, allocation_bytes);
        if (self.isVideoSurface(source.address)) self.markVideoSurface(destination.address);

        self.emulated_image_copy_dispatches += 1;
        if (log_verbose_gpu or self.emulated_image_copy_dispatches <= 4 or self.traceCurrentGraphicsFrame()) {
            std.debug.print(
                "[vulkan dcb] emulated whole-image copy: 0x{x} -> 0x{x} {d}x{d} fmt={d} tile={s} bytes=0x{x} (#{d})\n",
                .{
                    source.address,
                    destination.address,
                    source.width,
                    source.height,
                    source.unified_format,
                    @tagName(source.tile_mode),
                    allocation_bytes,
                    self.emulated_image_copy_dispatches,
                },
            );
        }
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    fn tryEmulateBufferCopy(
        self: *Renderer,
        memory: GuestMemory,
        state: *const gpu.State,
        analysis: *const gpu.ShaderAnalysis,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        _ = system;

        const inst = analysis.program.instructions.items;
        if (inst.len != 14 or
            inst[0].opcode != .s_inst_prefetch or
            inst[1].opcode != .v_lshl_add_u32 or
            inst[2].opcode != .s_buffer_load_dword or
            inst[3].opcode != .s_waitcnt or
            inst[4].opcode != .v_cmpx_gt_u32 or
            inst[5].opcode != .s_cbranch_execz or
            inst[6].opcode != .s_buffer_load_dwordx2 or
            inst[7].opcode != .s_waitcnt or
            inst[8].opcode != .v_add_nc_u32 or
            inst[9].opcode != .v_add_nc_u32 or
            inst[10].opcode != .buffer_load_format_x or
            inst[11].opcode != .s_waitcnt or
            inst[12].opcode != .buffer_store_format_x or
            inst[13].opcode != .s_endpgm)
        {
            return null;
        }

        const source_desc = try descriptorFromComputeUserData(state, 0);
        const dest_desc = try descriptorFromComputeUserData(state, 4);
        const control = try descriptorFromComputeUserData(state, 8);
        if (control.address == 0) return null;

        const dest_offset = try readGuestU32(memory, control.address + 0);
        const src_offset = try readGuestU32(memory, control.address + 4);
        const element_count = try readGuestU32(memory, control.address + 8);

        const dispatched = std.math.mul(u64, group_count[0], local_size[0]) catch return Error.GuestBufferTooLarge;
        const copies: usize = @intCast(@min(@as(u64, element_count), dispatched));

        const src_stride = if (source_desc.stride == 0) 4 else source_desc.stride;
        const dest_stride = if (dest_desc.stride == 0) 4 else dest_desc.stride;

        for (0..copies) |i| {
            const value = try readGuestU32(memory, source_desc.address + (src_offset + i) * src_stride);
            try writeGuestU32(memory, dest_desc.address + (dest_offset + i) * dest_stride, value);
        }

        self.elided_dispatches += 1;
        if (log_verbose_gpu) std.debug.print(
            "[vulkan dcb] emulated buffer copy: {d} elements from 0x{x} to 0x{x}\n",
            .{ copies, source_desc.address, dest_desc.address },
        );
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    /// Replaces Yotei's NVIDIA-unsafe 256-lane visibility reduction. The
    /// original shader partitions the 256 candidates into eight dwords and
    /// atomically ORs qualifying bits into a 32-byte V#. A full mask is the
    /// conservative result: it may retain extra candidates, but it cannot
    /// incorrectly cull the scene data consumed by the later composition
    /// passes.
    fn emulateYoteiVisibilityMaskFallback(
        self: *Renderer,
        memory: GuestMemory,
        bindings: *const gpu.ShaderBindings,
        reader: gpu.ShaderMemoryReader,
        analysis: *const gpu.ShaderAnalysis,
        group_count: [3]u32,
        program_address: u64,
    ) anyerror!DispatchReport {
        const instructions = analysis.program.instructions.items;
        const atomic = for (instructions) |inst| {
            if (inst.opcode == .buffer_atomic_or) break inst;
        } else return Error.MissingStorageDescriptor;
        if (atomic.src1.kind != .sgpr) return Error.MissingStorageDescriptor;

        const checkpoint_pcs = [_]u32{atomic.pc};
        var checkpoint_registers: [1]gpu.scalar_provenance.ScalarRegisters = undefined;
        _ = gpu.scalar_provenance.evaluateDecodedResourceStateAtCheckpoints(
            reader,
            bindings,
            instructions,
            &checkpoint_pcs,
            &checkpoint_registers,
        );
        const scalar = gpu.ScalarEvaluation{ .registers = checkpoint_registers[0] };
        const descriptor = (try resolveComputeBufferDescriptor(
            bindings,
            reader,
            analysis,
            &scalar,
            &scalar,
            atomic.src1.reg,
            atomic.pc,
        )) orelse return Error.MissingStorageDescriptor;
        if (descriptor.address == 0 or descriptor.size_bytes < 32 or
            descriptor.swizzle_enabled or descriptor.add_thread_id)
        {
            return Error.InvalidStorageDescriptor;
        }

        try self.flushPendingGuestWrite(descriptor.address, 32);
        const mask: [32]u8 = @splat(0xff);
        if (!memory.write(memory.context, descriptor.address, &mask)) {
            return Error.GuestMemoryWriteFailed;
        }
        self.invalidateDmaDestination(descriptor.address, mask.len);
        self.elided_dispatches += 1;
        std.debug.print(
            "[vulkan dcb] emulated NVIDIA-safe Yotei visibility mask program=0x{x} output=0x{x} groups={d}x{d}x{d}\n",
            .{
                program_address,
                descriptor.address,
                group_count[0],
                group_count[1],
                group_count[2],
            },
        );
        return .{
            .pipeline_cache_hit = false,
            .group_count = group_count,
            .spirv_words = 0,
        };
    }

    /// Yotei's screen-space GDS cull uses ds_append. The current SPIR-V
    /// lowering leaves EXEC empty on NVIDIA, so the kernel never writes.
    /// Build the dense visible list on the CPU (one dword per pixel in each
    /// writable V#) and publish the matching GDS counters.
    fn emulateYoteiGdsCulling(
        self: *Renderer,
        memory: GuestMemory,
        resources: *const ComputeResources,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        var seeded_outputs: usize = 0;
        var list_count: u32 = 0;
        for (resources.mappings[0..resources.mapping_count]) |mapping| {
            const slot: usize = @intCast(mapping.descriptor_index);
            if (!resources.occupied[slot] or !resources.writable[slot] or resources.sizes[slot] < 4) continue;
            const address = resources.addresses[slot];
            const size = resources.sizes[slot];
            try self.flushPendingGuestWrite(address, size);
            const bytes = try self.allocator.alloc(u8, size);
            defer self.allocator.free(bytes);
            var dword: u32 = 0;
            var offset: usize = 0;
            while (offset + 4 <= bytes.len) : (offset += 4) {
                std.mem.writeInt(u32, bytes[offset..][0..4], dword, .little);
                dword += 1;
            }
            if (!memory.write(memory.context, address, bytes)) return Error.GuestMemoryWriteFailed;
            self.invalidateDmaDestination(address, size);
            self.image_aliases.publishGuest(aliasRange(address, size));
            for (self.storage_image_cache.items) |*cached| {
                if (!cached.valid or cached.descriptor.address != address) continue;
                cached.gpu_dirty = false;
            }
            list_count = @max(list_count, dword);
            seeded_outputs += 1;
        }
        if (seeded_outputs == 0) return null;

        if (self.ensureGdsStorage()) {
            var m0_base: u32 = 0x0d18;
            for (resources.scalar_registers[0..resources.scalar_count]) |scalar| {
                if (scalar.register == 2) {
                    m0_base = scalar.value >> 16;
                    break;
                }
            }
            var item: u32 = 0;
            while (item < 3) : (item += 1) {
                const gds_offset = m0_base + item * 4;
                if (gds_offset + 4 > self.gds_storage.items.len) break;
                std.mem.writeInt(
                    u32,
                    self.gds_storage.items[gds_offset..][0..4],
                    list_count,
                    .little,
                );
            }
        }

        self.elided_dispatches += 1;
        if (self.yotei_packed_visibility_seeds < 8 or self.traceCurrentGraphicsFrame()) {
            std.debug.print(
                "[vulkan dcb] emulated Yotei GDS cull outputs={d} list_count={d} groups={d}x{d}x{d}\n",
                .{ seeded_outputs, list_count, group_count[0], group_count[1], group_count[2] },
            );
            self.yotei_packed_visibility_seeds +|= 1;
        }
        return .{
            .pipeline_cache_hit = false,
            .group_count = group_count,
            .spirv_words = 0,
        };
    }

    /// Replaces Yotei's deeply divergent environment-lighting kernel on
    /// NVIDIA. Resolve only its live writable T#s and initialize their tiled
    /// guest allocations before any Vulkan descriptor staging. Preparing the
    /// complete 73-sample descriptor set while earlier dispatches are pending
    /// invalidates those submissions on current NVIDIA drivers just as surely
    /// as executing the kernel itself.
    fn emulateYoteiEnvironmentLightingFallback(
        self: *Renderer,
        memory: GuestMemory,
        bindings: *const gpu.ShaderBindings,
        reader: gpu.ShaderMemoryReader,
        analysis: *const gpu.ShaderAnalysis,
        group_count: [3]u32,
        program_address: u64,
    ) anyerror!DispatchReport {
        const instructions = analysis.program.instructions.items;
        var checkpoint_count: usize = 0;
        for (instructions) |inst| {
            if (needsResourceScalarCheckpoint(inst)) checkpoint_count += 1;
        }
        const checkpoint_pcs = try self.allocator.alloc(u32, checkpoint_count);
        defer self.allocator.free(checkpoint_pcs);
        const checkpoint_registers = try self.allocator.alloc(
            gpu.scalar_provenance.ScalarRegisters,
            checkpoint_count,
        );
        defer self.allocator.free(checkpoint_registers);
        var checkpoint_index: usize = 0;
        for (instructions) |inst| {
            if (!needsResourceScalarCheckpoint(inst)) continue;
            checkpoint_pcs[checkpoint_index] = inst.pc;
            checkpoint_index += 1;
        }
        if (checkpoint_count != 0) {
            _ = gpu.scalar_provenance.evaluateDecodedResourceStateAtCheckpoints(
                reader,
                bindings,
                instructions,
                checkpoint_pcs,
                checkpoint_registers,
            );
        }

        var output_descriptors: [8]gpu.ImageDescriptor = undefined;
        var output_count: usize = 0;
        var fallback_slot: usize = 0;
        for (instructions) |inst| {
            const writable = switch (inst.opcode) {
                .image_store,
                .image_store_mip,
                .image_atomic_add,
                .image_atomic_umin,
                .image_atomic_umax,
                .image_atomic_and,
                .image_atomic_or,
                .image_atomic_xor,
                .image_atomic_fmax,
                => true,
                .image_load => false,
                else => continue,
            };
            if (inst.src1.kind != .sgpr) continue;
            const scalar = gpu.ScalarEvaluation{
                .registers = scalarRegistersAtCheckpoint(
                    checkpoint_pcs,
                    checkpoint_registers,
                    inst.pc,
                ).*,
            };
            const descriptor = (try resolveComputeImageDescriptor(
                bindings,
                reader,
                analysis,
                &scalar,
                inst.src1.reg,
                inst.pc,
                fallback_slot,
            )) orelse {
                fallback_slot += 1;
                continue;
            };
            fallback_slot += 1;
            if (!writable) continue;
            const expected = (descriptor.image_type == .color_3d and
                descriptor.width == 256 and descriptor.height == 144 and
                descriptor.depth_or_layers == 64 and
                (descriptor.unified_format == 36 or descriptor.unified_format == 13)) or
                (descriptor.image_type == .color_2d_array and
                    descriptor.width == 128 and descriptor.height == 128 and
                    descriptor.depth_or_layers == 256 and descriptor.unified_format == 22);
            if (!expected) continue;
            var duplicate = false;
            for (output_descriptors[0..output_count]) |existing| {
                if (existing.address == descriptor.address) {
                    duplicate = true;
                    break;
                }
            }
            if (duplicate or output_count >= output_descriptors.len) continue;
            output_descriptors[output_count] = descriptor;
            output_count += 1;
        }

        var cleared: usize = 0;
        for (output_descriptors[0..output_count]) |descriptor| {
            var pattern: [4]u8 = @splat(0);
            const pattern_length: usize = switch (descriptor.unified_format) {
                // R11G11B10F with RGB=0.25. Using the exact packed texel keeps
                // the neutral fallback deterministic across host formats.
                36 => blk: {
                    std.mem.writeInt(u32, &pattern, 0x681a_0340, .little);
                    break :blk 4;
                },
                // R16F/R32F scalar outputs carry visibility/transmittance-like
                // terms. One is the conservative unoccluded neutral value.
                13 => blk: {
                    std.mem.writeInt(u16, pattern[0..2], @bitCast(@as(f16, 1.0)), .little);
                    break :blk 2;
                },
                22 => blk: {
                    std.mem.writeInt(u32, &pattern, @bitCast(@as(f32, 1.0)), .little);
                    break :blk 4;
                },
                else => continue,
            };
            const texture = gpu.TextureLayout.fromImage(descriptor) catch continue;
            const array_layers = if (descriptor.image_type == .color_2d_array)
                texture.layers
            else
                1;
            const subresource = texture.subresource(
                descriptor.viewBaseLevel(),
                0,
                array_layers,
            ) catch continue;
            const staging_bytes = std.math.cast(usize, subresource.stagingBytes() catch continue) orelse
                continue;
            const allocation_bytes = std.math.cast(usize, texture.required_source_bytes) orelse continue;
            if (staging_bytes == 0 or staging_bytes > maximum_frame_bytes or
                allocation_bytes == 0 or allocation_bytes > maximum_frame_bytes)
            {
                continue;
            }
            const linear = try self.allocator.alloc(u8, staging_bytes);
            defer self.allocator.free(linear);
            fillRepeatedPattern(linear, pattern[0..pattern_length]);
            const allocation = try self.allocator.alloc(u8, allocation_bytes);
            defer self.allocator.free(allocation);
            @memset(allocation, 0);
            subresource.tile(linear, allocation) catch continue;
            if (!memory.write(memory.context, descriptor.address, allocation)) {
                return Error.GuestMemoryWriteFailed;
            }
            self.invalidateDmaDestination(descriptor.address, allocation.len);
            self.image_aliases.publishGuest(aliasRange(descriptor.address, allocation.len));
            // Lighting samples this volume as a T# on the same frame. A guest
            // upload detiles the just-written tiled bytes; publishing the
            // linear 1.0/0.25 pattern into the storage cache lets that T#
            // bind a GPU-resident copy instead.
            self.publishLinearStorageImage(memory, descriptor, linear) catch {};
            cleared += 1;
        }
        if (cleared == 0) return Error.UnsupportedStorageImage;

        self.elided_dispatches += 1;
        std.debug.print(
            "[vulkan dcb] emulated NVIDIA-safe Yotei environment lighting program=0x{x} outputs={d} groups={d}x{d}x{d}\n",
            .{ program_address, cleared, group_count[0], group_count[1], group_count[2] },
        );
        return .{
            .pipeline_cache_hit = false,
            .group_count = group_count,
            .spirv_words = 0,
        };
    }

    fn publishLinearStorageImage(
        self: *Renderer,
        memory: GuestMemory,
        descriptor: gpu.ImageDescriptor,
        linear: []const u8,
    ) anyerror!void {
        const format = storageImageFormat(descriptor.unified_format) orelse
            return Error.UnsupportedStorageImage;
        const texture = gpu.TextureLayout.fromImage(descriptor) catch
            return Error.UnsupportedStorageImage;
        const is_3d = descriptor.image_type == .color_3d;
        const is_2d_array = descriptor.image_type == .color_2d_array;
        const array_layers = if (is_2d_array) texture.layers else 1;
        const subresource = texture.subresource(descriptor.viewBaseLevel(), 0, array_layers) catch
            return Error.UnsupportedStorageImage;
        const staging_bytes = std.math.cast(usize, subresource.stagingBytes() catch
            return Error.UnsupportedStorageImage) orelse return Error.UnsupportedStorageImage;
        if (linear.len != staging_bytes) return Error.UnsupportedStorageImage;
        const allocation_bytes = std.math.cast(usize, texture.required_source_bytes) orelse
            return Error.UnsupportedStorageImage;

        self.storage_image_sequence +%= 1;
        for (self.storage_image_cache.items, 0..) |cached, index| {
            if (!cached.valid or !sameStorageImageDescriptor(cached.descriptor, descriptor)) continue;
            const resident = &self.storage_image_cache.items[index];
            resident.in_use = true;
            resident.last_used_sequence = self.storage_image_sequence;
            try self.uploadCachedStorageImage(index, linear, false);
            resident.gpu_dirty = true;
            resident.guest_content_hash_valid = false;
            _ = self.image_aliases.markWrite(resident.alias_token);
            return;
        }

        var cache_owns_resources = false;
        const transfer = try self.createBuffer(
            staging_bytes,
            vk.buffer_usage_transfer_src_bit | vk.buffer_usage_transfer_dst_bit,
            vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
        );
        errdefer if (!cache_owns_resources) self.destroyBuffer(transfer);
        const image = try self.createImageWithExtent(
            subresource.width,
            subresource.height,
            if (is_3d) subresource.depth_or_layers else 1,
            if (is_2d_array) subresource.depth_or_layers else 1,
            if (is_3d) vk.image_type_3d else vk.image_type_2d,
            0,
            format.vulkan,
            vk.image_usage_transfer_src_bit | vk.image_usage_transfer_dst_bit |
                vk.image_usage_storage_bit | vk.image_usage_sampled_bit,
            vk.sample_count_1_bit,
            1,
        );
        errdefer if (!cache_owns_resources) self.destroyImage(image);
        try self.registerTrackedImage(
            image.handle,
            vk.image_aspect_color_bit,
            1,
            if (is_2d_array) subresource.depth_or_layers else 1,
        );
        errdefer if (!cache_owns_resources) self.image_states.forgetImage(image.handle);
        const view_info = vk.ImageViewCreateInfo{
            .image = image.handle,
            .view_type = if (is_3d)
                vk.image_view_type_3d
            else if (is_2d_array)
                vk.image_view_type_2d_array
            else
                vk.image_view_type_2d,
            .format = format.vulkan,
            .subresource_range = .{
                .aspect_mask = vk.image_aspect_color_bit,
                .layer_count = if (is_2d_array) subresource.depth_or_layers else 1,
            },
        };
        var view: vk.ImageView = 0;
        if (self.device_functions.create_image_view(self.device, &view_info, null, &view) != vk.success) {
            return Error.ImageViewCreationFailed;
        }
        errdefer if (!cache_owns_resources) self.destroyImageView(view);
        const alias_token = try self.image_aliases.register(
            self.allocator,
            .storage_image,
            aliasRange(descriptor.address, allocation_bytes),
            descriptorAliasSignature(descriptor, format.vulkan, 1),
        );
        errdefer if (!cache_owns_resources) self.image_aliases.unregister(alias_token);
        const cache_index = try self.storageImageCacheSlot(memory, staging_bytes);
        self.storage_image_cache.items[cache_index] = .{
            .alias_token = alias_token,
            .descriptor = descriptor,
            .subresource = subresource,
            .image = image,
            .view = view,
            .transfer = transfer,
            .allocation_bytes = allocation_bytes,
            .staging_bytes = staging_bytes,
            .last_used_sequence = self.storage_image_sequence,
            .gpu_dirty = true,
            .in_use = true,
        };
        self.storage_image_cache_bytes +|= staging_bytes;
        cache_owns_resources = true;
        errdefer self.destroyCachedStorageImage(cache_index);
        try self.uploadCachedStorageImage(cache_index, linear, true);
    }

    /// Handles the four-instruction AGC linear UAV fill without compiling a
    /// Vulkan compute pipeline. The kernel maps one 64-thread group to 64 R32
    /// records and stores the same immediate value in every dispatched record.
    fn tryEmulateSimpleBufferFill(
        self: *Renderer,
        memory: GuestMemory,
        state: *const gpu.State,
        analysis: *const gpu.ShaderAnalysis,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        const inst = analysis.program.instructions.items;
        if (inst.len != 4 or
            inst[0].opcode != .v_lshl_add_u32 or
            inst[1].opcode != .v_mov_b32 or
            inst[2].opcode != .buffer_store_format_x or
            inst[3].opcode != .s_endpgm or
            local_size[0] != 64 or local_size[1] != 1 or local_size[2] != 1 or
            group_count[1] != 1 or group_count[2] != 1 or
            system.workgroup_id_sgprs[0] != 4 or
            system.workgroup_id_sgprs[1] != null or system.workgroup_id_sgprs[2] != null or
            system.local_invocation_id_components != 1 or
            !registerOperand(inst[0].dst, .vgpr, 0) or
            !registerOperand(inst[0].src0, .sgpr, 4) or
            inst[0].src1.kind != .integer_inline_constant or inst[0].src1.value != 6 or
            !registerOperand(inst[0].src2, .vgpr, 0) or
            !registerOperand(inst[1].dst, .vgpr, 1) or
            !registerOperand(inst[2].dst, .vgpr, 1) or
            !registerOperand(inst[2].src0, .vgpr, 0) or
            !registerOperand(inst[2].src1, .sgpr, 0) or
            inst[2].offset_enable or inst[2].memory_offset != 0)
        {
            return null;
        }
        const fill_value = switch (inst[1].src0.kind) {
            .integer_inline_constant, .literal_constant, .float_inline_constant, .null => inst[1].src0.value,
            else => return null,
        };
        const descriptor = try descriptorFromComputeUserData(state, 0);
        if (descriptor.address == 0 or descriptor.stride != 4 or descriptor.unified_format != 20 or
            descriptor.swizzle_enabled or descriptor.add_thread_id or
            descriptor.out_of_bounds_select != 0 or descriptor.dst_select[0] != 4)
        {
            return null;
        }
        const dispatched = std.math.mul(u64, group_count[0], local_size[0]) catch
            return Error.GuestBufferTooLarge;
        const records = @min(dispatched, @as(u64, descriptor.record_count));
        const byte_count_u64 = std.math.mul(u64, records, 4) catch return Error.GuestBufferTooLarge;
        const byte_count = std.math.cast(usize, byte_count_u64) orelse return Error.GuestBufferTooLarge;
        if (byte_count == 0 or byte_count > maximum_frame_bytes) return null;

        try self.flushPendingGuestWrite(descriptor.address, byte_count);
        const bytes = try self.allocator.alloc(u8, byte_count);
        defer self.allocator.free(bytes);
        if (fill_value == 0) {
            @memset(bytes, 0);
        } else {
            var offset: usize = 0;
            while (offset < bytes.len) : (offset += 4) {
                std.mem.writeInt(u32, bytes[offset..][0..4], fill_value, .little);
            }
        }
        if (!memory.write(memory.context, descriptor.address, bytes)) return Error.GuestMemoryWriteFailed;
        self.invalidateDmaDestination(descriptor.address, byte_count);
        self.emulated_buffer_clear_dispatches += 1;
        if (log_verbose_gpu or self.emulated_buffer_clear_dispatches <= 4) {
            std.debug.print(
                "[vulkan dcb] emulated linear buffer fill: addr=0x{x} value=0x{x} records={d} (#{d})\n",
                .{ descriptor.address, fill_value, records, self.emulated_buffer_clear_dispatches },
            );
        }
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    /// AGC clears an RGBA8 colour allocation through a formatted V# whose
    /// records each cover four packed pixels. Treating that allocation as a
    /// host-visible SSBO makes a fullscreen clear cross PCIe and also leaves
    /// the aliased Vulkan image stale. Match the complete seven-instruction
    /// kernel and clear the resident attachment directly instead.
    fn tryEmulatePackedColorBufferClear(
        self: *Renderer,
        memory: GuestMemory,
        state: *const gpu.State,
        analysis: *const gpu.ShaderAnalysis,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        const inst = analysis.program.instructions.items;
        if (inst.len != 7 or
            inst[0].opcode != .v_lshl_add_u32 or
            inst[1].opcode != .v_mov_b32 or
            inst[2].opcode != .v_mov_b32 or
            inst[3].opcode != .v_mov_b32 or
            inst[4].opcode != .v_mov_b32 or
            inst[5].opcode != .buffer_store_format_xyzw or
            inst[6].opcode != .s_endpgm)
        {
            return null;
        }
        if (local_size[0] != 64 or local_size[1] != 1 or local_size[2] != 1 or
            group_count[1] != 1 or group_count[2] != 1 or
            system.workgroup_id_sgprs[0] != 8 or
            system.workgroup_id_sgprs[1] != null or system.workgroup_id_sgprs[2] != null or
            system.local_invocation_id_components != 1 or
            !registerOperand(inst[0].dst, .vgpr, 4) or
            !registerOperand(inst[0].src0, .sgpr, 8) or
            inst[0].src1.kind != .integer_inline_constant or inst[0].src1.value != 6 or
            !registerOperand(inst[0].src2, .vgpr, 0))
        {
            return null;
        }
        for (inst[1..5], 0..) |move, index| {
            if (!registerOperand(move.dst, .vgpr, @intCast(index)) or
                !registerOperand(move.src0, .sgpr, @intCast(index + 4))) return null;
        }
        if (!registerOperand(inst[5].dst, .vgpr, 0) or
            !registerOperand(inst[5].src0, .vgpr, 4) or
            !registerOperand(inst[5].src1, .sgpr, 0) or
            inst[5].offset_enable or inst[5].memory_offset != 0)
        {
            return null;
        }

        const descriptor = try descriptorFromComputeUserData(state, 0);
        if (descriptor.address == 0 or descriptor.stride != 16 or descriptor.unified_format != 75 or
            descriptor.swizzle_enabled or descriptor.index_stride != 0 or descriptor.add_thread_id or
            descriptor.out_of_bounds_select != 0 or
            !std.mem.eql(u8, &descriptor.dst_select, &[_]u8{ 4, 5, 6, 7 }))
        {
            return null;
        }
        const dispatched = std.math.mul(u64, group_count[0], local_size[0]) catch
            return Error.GuestBufferTooLarge;
        if (dispatched != descriptor.record_count) return null;

        const packed_value = state.readRegister(.shader, 0x244) orelse return null;
        inline for (0x245..0x248) |register| {
            if ((state.readRegister(.shader, register) orelse return null) != packed_value) return null;
        }

        var target_index: ?usize = null;
        const render = gpu.resources.decodeRenderState(state);
        for (render.color_targets) |maybe_target| {
            const candidate = maybe_target orelse continue;
            if (!candidate.isActive() or candidate.address != descriptor.address or
                candidate.dcc_enabled or candidate.cmask_fast_clear or
                candidate.fmask_compression or candidate.samples_log2 != 0 or
                candidate.fragments_log2 != 0)
            {
                continue;
            }
            const format = colorTargetFormat(candidate) orelse continue;
            if (format.vulkan != vk.format_r8g8b8a8_unorm or format.bytes_per_texel != 4) continue;
            const layout = gpu.SurfaceLayout.fromColorTarget(candidate) catch continue;
            if (layout.required_source_bytes != descriptor.size_bytes or layout.layers != 1) continue;
            target_index = try self.acquireRenderTarget(.{
                .descriptor = candidate,
                .layout = layout,
                .format = format,
            });
            break;
        }

        // Compute clears often run before graphics rebinds this frame's
        // VideoOut attachment. Reuse an exact resident allocation from an
        // earlier frame instead of missing the fast path due to register state.
        if (target_index == null) {
            var newest_sequence: u64 = 0;
            for (self.render_targets.items, 0..) |cached, index| {
                if (cached.target.descriptor.address != descriptor.address or
                    cached.target.format.vulkan != vk.format_r8g8b8a8_unorm or
                    cached.target.format.bytes_per_texel != 4 or
                    cached.target.layout.required_source_bytes != descriptor.size_bytes or
                    cached.target.layout.layers != 1 or
                    cached.target.descriptor.dcc_enabled or
                    cached.target.descriptor.cmask_fast_clear or
                    cached.target.descriptor.fmask_compression or
                    cached.target.descriptor.samples_log2 != 0 or
                    cached.target.descriptor.fragments_log2 != 0 or
                    (target_index != null and cached.last_used_sequence <= newest_sequence))
                {
                    continue;
                }
                target_index = index;
                newest_sequence = cached.last_used_sequence;
            }
        }

        // Post-processing allocations are also commonly materialized as
        // storage images rather than colour attachments. Once an exact cache
        // entry exists, keep the recurring fullscreen clear on the Vulkan
        // queue instead of filling and publishing tens of MiB through the CPU
        // every frame. Restrict this to the two byte formats for which the
        // packed V# pattern and a Vulkan colour clear are exactly equivalent.
        var storage_image_index: ?usize = null;
        if (target_index == null) {
            var newest_sequence: u64 = 0;
            for (self.storage_image_cache.items, 0..) |cached, index| {
                if (!cached.valid or
                    cached.descriptor.address != descriptor.address or
                    cached.allocation_bytes != descriptor.size_bytes or
                    cached.descriptor.image_type != .color_2d or
                    cached.descriptor.viewMipLevels() != 1 or
                    cached.subresource.depth_or_layers != 1)
                {
                    continue;
                }
                const format = storageImageFormat(cached.descriptor.unified_format) orelse continue;
                if (format.vulkan != vk.format_r8_unorm and
                    format.vulkan != vk.format_r8g8b8a8_unorm)
                {
                    continue;
                }
                if (storage_image_index != null and cached.last_used_sequence <= newest_sequence) continue;
                storage_image_index = index;
                newest_sequence = cached.last_used_sequence;
            }
        }

        if (storage_image_index) |resolved_storage_index| {
            const snapshot = self.storage_image_cache.items[resolved_storage_index];
            const command_buffer = try self.beginOneShot();
            defer self.releaseOneShot(command_buffer);
            try self.transitionTrackedImage(
                command_buffer,
                snapshot.image.handle,
                .{ .aspect_mask = vk.image_aspect_color_bit },
                image_state.transfer_destination_usage,
            );
            var bytes: [4]u8 = undefined;
            std.mem.writeInt(u32, &bytes, packed_value, .little);
            const scale: f32 = 1.0 / 255.0;
            const clear = vk.ClearColorValue{ .float32 = .{
                @as(f32, @floatFromInt(bytes[0])) * scale,
                @as(f32, @floatFromInt(bytes[1])) * scale,
                @as(f32, @floatFromInt(bytes[2])) * scale,
                @as(f32, @floatFromInt(bytes[3])) * scale,
            } };
            const range = vk.ImageSubresourceRange{ .aspect_mask = vk.image_aspect_color_bit };
            self.device_functions.cmd_clear_color_image(
                command_buffer,
                snapshot.image.handle,
                vk.image_layout_transfer_dst_optimal,
                &clear,
                1,
                @ptrCast(&range),
            );
            try self.transitionTrackedImage(
                command_buffer,
                snapshot.image.handle,
                .{ .aspect_mask = vk.image_aspect_color_bit },
                image_state.storage_usage,
            );
            try self.submitOneShot(command_buffer);

            self.storage_image_sequence +%= 1;
            const cached = &self.storage_image_cache.items[resolved_storage_index];
            cached.last_used_sequence = self.storage_image_sequence;
            cached.guest_content_hash_valid = false;
            cached.guest_page_generation = 0;
            cached.gpu_dirty = true;
            _ = self.image_aliases.markWrite(cached.alias_token);
            self.emulated_buffer_clear_dispatches += 1;
            if (log_verbose_gpu or self.emulated_buffer_clear_dispatches <= 4) {
                std.debug.print(
                    "[vulkan dcb] emulated packed storage-image clear: addr=0x{x} value=0x{x} bytes=0x{x} records={d} (#{d})\n",
                    .{ descriptor.address, packed_value, descriptor.size_bytes, descriptor.record_count, self.emulated_buffer_clear_dispatches },
                );
            }
            return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
        }

        // The first clear of each swapchain buffer precedes creation of its
        // resident attachment. Publish the identical repeated 16-byte pattern
        // to guest memory once; subsequent clears remain entirely on the GPU.
        if (target_index == null) {
            const byte_count = std.math.cast(usize, descriptor.size_bytes) orelse
                return Error.GuestBufferTooLarge;
            if (byte_count == 0 or byte_count > maximum_frame_bytes or byte_count & 0xf != 0) return null;
            try self.flushPendingGuestWrite(descriptor.address, byte_count);
            const bytes = try self.allocator.alloc(u8, byte_count);
            defer self.allocator.free(bytes);
            var pattern: [16]u8 = undefined;
            inline for (0..4) |index| {
                const value = state.readRegister(.shader, 0x244 + index) orelse return null;
                std.mem.writeInt(u32, pattern[index * 4 ..][0..4], value, .little);
            }
            var offset: usize = 0;
            while (offset < bytes.len) : (offset += pattern.len) {
                @memcpy(bytes[offset..][0..pattern.len], &pattern);
            }
            if (!memory.write(memory.context, descriptor.address, bytes)) return Error.GuestMemoryWriteFailed;
            self.invalidateDmaDestination(descriptor.address, byte_count);
            self.emulated_buffer_clear_dispatches += 1;
            if (log_verbose_gpu or self.emulated_buffer_clear_dispatches <= 4) {
                std.debug.print(
                    "[vulkan dcb] emulated packed buffer fill: addr=0x{x} value=0x{x} bytes=0x{x} records={d} (#{d})\n",
                    .{ descriptor.address, packed_value, descriptor.size_bytes, descriptor.record_count, self.emulated_buffer_clear_dispatches },
                );
            }
            return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
        }

        const resolved_target_index = target_index.?;
        const snapshot = self.render_targets.items[resolved_target_index];

        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.transfer_destination_usage,
        );
        var bytes: [4]u8 = undefined;
        std.mem.writeInt(u32, &bytes, packed_value, .little);
        const scale: f32 = 1.0 / 255.0;
        const clear = vk.ClearColorValue{ .float32 = .{
            @as(f32, @floatFromInt(bytes[0])) * scale,
            @as(f32, @floatFromInt(bytes[1])) * scale,
            @as(f32, @floatFromInt(bytes[2])) * scale,
            @as(f32, @floatFromInt(bytes[3])) * scale,
        } };
        const range = vk.ImageSubresourceRange{ .aspect_mask = vk.image_aspect_color_bit };
        self.device_functions.cmd_clear_color_image(
            command_buffer,
            snapshot.image.handle,
            vk.image_layout_transfer_dst_optimal,
            &clear,
            1,
            @ptrCast(&range),
        );
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.color_attachment_usage,
        );
        try self.submitOneShot(command_buffer);

        self.render_target_sequence +%= 1;
        const cached = &self.render_targets.items[resolved_target_index];
        cached.initialized = true;
        cached.shader_read_layout = false;
        cached.gpu_generation +%= 1;
        _ = self.image_aliases.markWrite(cached.alias_token);
        cached.last_used_sequence = self.render_target_sequence;
        self.latest_render_target_index = resolved_target_index;
        for (self.completed_frames.items) |*frame| {
            if (frame.guest_address == descriptor.address) frame.needs_writeback = false;
        }
        self.emulated_buffer_clear_dispatches += 1;
        if (log_verbose_gpu or self.emulated_buffer_clear_dispatches <= 4) {
            std.debug.print(
                "[vulkan dcb] emulated packed color clear: addr=0x{x} bytes=0x{x} records={d} (#{d})\n",
                .{ descriptor.address, packed_value, descriptor.record_count, self.emulated_buffer_clear_dispatches },
            );
        }
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    /// Executes the compact AGC UAV-clear kernel shapes seen during bootstrap.
    ///
    /// Both kernels form x/y from an 8x8 workgroup, take z from the workgroup
    /// id, load constant texels from the first constant buffer, and issue one or
    /// two image_store operations. Matching the complete instruction shape keeps this
    /// path honest: general MIMG control flow and typed conversion still go
    /// through the translator and remain explicit when unsupported.
    fn tryEmulateImageStoreClear(
        self: *Renderer,
        memory: GuestMemory,
        bindings: *const gpu.ShaderBindings,
        reader: gpu.ShaderMemoryReader,
        analysis: *const gpu.ShaderAnalysis,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        const instructions = analysis.program.instructions.items;
        if (matchesDualImageClear(instructions)) {
            return self.emulateDualImageClear(
                memory,
                bindings,
                reader,
                instructions,
                system,
                local_size,
                group_count,
            );
        }
        const Shape = enum { rgba, scalar };
        const shape: Shape = if (matchesRgbaImageClear(instructions))
            .rgba
        else if (matchesScalarImageClear(instructions))
            .scalar
        else
            return null;
        if (local_size[0] != 8 or local_size[1] != 8 or local_size[2] != 1) return null;

        const image_inst = switch (shape) {
            .rgba => instructions[9],
            .scalar => instructions[6],
        };
        const descriptor = try resolveReadWriteImageDescriptor(bindings, reader, image_inst.src1.reg) orelse
            return null;
        if (descriptor.dcc_enabled or descriptor.cmask_fast_clear or descriptor.fmask_compression or
            descriptor.metadata_address != 0 or descriptor.samplesLog2() != 0 or
            descriptor.viewMipLevels() != 1 or descriptor.viewBaseLevel() != 0 or
            image_inst.image_dimension != .dim_2d_array_alt)
        {
            return null;
        }
        if (shape == .scalar and descriptor.dst_select[0] != 4) return null;

        const constants = (try bindings.inlineBufferDescriptor(8)) orelse blk: {
            const binding = (try bindings.resolve(reader, .constant_buffer, 0)) orelse return null;
            break :blk binding.descriptor.constant_buffer;
        };
        const word_count: usize = if (shape == .rgba) 4 else 1;
        if (constants.address == 0 or constants.size_bytes < word_count * @sizeOf(u32)) return null;
        var values: [4]u32 = @splat(0);
        for (values[0..word_count], 0..) |*value, index| {
            value.* = try readGuestU32(memory, constants.address + index * @sizeOf(u32));
        }
        const texel = packImageStoreTexel(
            descriptor.unified_format,
            values,
            image_inst.data_mask,
            descriptor.dst_select,
        ) orelse return null;

        const texture = gpu.TextureLayout.fromImage(descriptor) catch return null;
        const subresource = texture.subresource(0, 0, texture.layers) catch return null;
        if (texel.length != subresource.block.bytes_per_element) return null;

        const dispatched_width = std.math.mul(u64, group_count[0], local_size[0]) catch
            return Error.GuestBufferTooLarge;
        const dispatched_height = std.math.mul(u64, group_count[1], local_size[1]) catch
            return Error.GuestBufferTooLarge;
        const width: u32 = @intCast(@min(@as(u64, subresource.width), dispatched_width));
        const height: u32 = @intCast(@min(@as(u64, subresource.height), dispatched_height));
        const depth = @min(subresource.depth_or_layers, group_count[2]);

        const full_clear = width == subresource.width and height == subresource.height and
            depth == subresource.depth_or_layers;
        const clear_range = if (full_clear) try contiguousWholeImageClearRange(subresource) else null;
        if (clear_range) |range| {
            const bytes = try self.allocator.alloc(u8, range.length);
            defer self.allocator.free(bytes);
            fillRepeatedPattern(bytes, texel.bytes[0..texel.length]);
            const write_address = try std.math.add(u64, descriptor.address, range.offset);
            if (!memory.write(memory.context, write_address, bytes)) return Error.GuestMemoryWriteFailed;
            self.invalidateDmaDestination(write_address, bytes.len);
        } else {
            // Preserve untouched texels, apply the tiled offsets against one
            // host copy, then publish the allocation once. Calling
            // GuestMemory.write for every texel made large clears cross the
            // checked memory boundary millions of times.
            const allocation_bytes = std.math.cast(usize, subresource.required_source_bytes) orelse
                return Error.GuestBufferTooLarge;
            if (allocation_bytes == 0 or allocation_bytes > maximum_frame_bytes) return null;
            const allocation = try self.allocator.alloc(u8, allocation_bytes);
            defer self.allocator.free(allocation);
            const overwrites_allocation = full_clear and
                try wholeImageClearCoversAllocation(allocation.len, subresource);
            if (!overwrites_allocation and
                !memory.read(memory.context, descriptor.address, allocation))
            {
                return Error.GuestMemoryReadFailed;
            }

            const block_clear = full_clear and try fillWholeImageBlocks(
                allocation,
                subresource,
                texel.bytes[0..texel.length],
            );
            if (!block_clear) {
                for (0..depth) |z_index| {
                    const z: u32 = @intCast(z_index);
                    for (0..height) |y_index| {
                        const y: u32 = @intCast(y_index);
                        for (0..width) |x_index| {
                            const x: u32 = @intCast(x_index);
                            const offset_u64 = try subresource.sourceByteOffset(x, y, z, 0);
                            const offset = std.math.cast(usize, offset_u64) orelse
                                return Error.GuestBufferTooLarge;
                            if (offset > allocation.len or texel.length > allocation.len - offset)
                                return Error.GuestBufferTooLarge;
                            @memcpy(allocation[offset..][0..texel.length], texel.bytes[0..texel.length]);
                        }
                    }
                }
            }
            if (!memory.write(memory.context, descriptor.address, allocation))
                return Error.GuestMemoryWriteFailed;
            self.invalidateDmaDestination(descriptor.address, allocation_bytes);
        }
        const writes: u64 = @as(u64, width) * height * depth;

        self.emulated_image_store_dispatches += 1;
        if (log_verbose_gpu or self.emulated_image_store_dispatches <= 4) {
            std.debug.print(
                "[vulkan dcb] emulated image clear: {d} texels addr=0x{x} fmt={d} tile={s} (#{d})\n",
                .{
                    writes,
                    descriptor.address,
                    descriptor.unified_format,
                    @tagName(descriptor.tile_mode),
                    self.emulated_image_store_dispatches,
                },
            );
        }
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    fn emulateDualImageClear(
        self: *Renderer,
        memory: GuestMemory,
        bindings: *const gpu.ShaderBindings,
        reader: gpu.ShaderMemoryReader,
        instructions: []const gpu.ShaderInstruction,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        if (local_size[0] != 4 or local_size[1] != 4 or local_size[2] != 1 or
            system.workgroup_id_sgprs[0] != 14 or
            system.workgroup_id_sgprs[1] != 15 or
            system.local_invocation_id_components != 2)
        {
            self.reportDualImageClearFallback("compute system registers", null, null);
            return null;
        }

        const first = try resolveReadWriteImageDescriptor(bindings, reader, 0) orelse {
            self.reportDualImageClearFallback("first image descriptor", null, null);
            return null;
        };
        const second = try imageDescriptorFromUserDataPointer(bindings, reader, 12) orelse {
            self.reportDualImageClearFallback("second image descriptor pointer", first, null);
            return null;
        };
        const constants = (try bindings.inlineBufferDescriptor(8)) orelse {
            self.reportDualImageClearFallback("constant buffer descriptor", first, second);
            return null;
        };
        const constant_offset: u64 = 384;
        if (constants.address == 0 or constants.size_bytes < constant_offset + 3 * @sizeOf(u32)) {
            self.reportDualImageClearFallback("constant buffer range", first, second);
            return null;
        }

        var first_values: [4]u32 = .{ 0, 0, 0, @bitCast(@as(f32, -1.0)) };
        for (first_values[0..3], 0..) |*value, index| {
            value.* = try readGuestU32(memory, constants.address + constant_offset + index * @sizeOf(u32));
        }
        const second_values = [4]u32{ 0, 0, 0, @bitCast(@as(f32, -1.0)) };

        const dispatched_width = std.math.mul(u64, group_count[0], local_size[0]) catch
            return Error.GuestBufferTooLarge;
        const dispatched_height = std.math.mul(u64, group_count[1], local_size[1]) catch
            return Error.GuestBufferTooLarge;
        const first_clear = planWholeImageClear(
            first,
            first_values,
            instructions[14].data_mask,
            dispatched_width,
            dispatched_height,
        ) orelse {
            self.reportDualImageClearFallback("first image layout/format", first, second);
            return null;
        };
        const second_clear = planWholeImageClear(
            second,
            second_values,
            instructions[16].data_mask,
            dispatched_width,
            dispatched_height,
        ) orelse {
            self.reportDualImageClearFallback("second image layout/format", first, second);
            return null;
        };
        const first_writes = try self.applyWholeImageClear(memory, first_clear);
        const second_writes = try self.applyWholeImageClear(memory, second_clear);

        self.emulated_image_store_dispatches += 1;
        if (log_verbose_gpu or self.emulated_image_store_dispatches <= 4) {
            std.debug.print(
                "[vulkan dcb] emulated dual image clear: {d}+{d} texels {d}x{d}/{d}x{d} padded={d}x{d}/{d}x{d} fmt={d}/{d} tile={s}/{s} (#{d})\n",
                .{
                    first_writes,
                    second_writes,
                    first_clear.subresource.width,
                    first_clear.subresource.height,
                    second_clear.subresource.width,
                    second_clear.subresource.height,
                    first_clear.subresource.padded_width,
                    first_clear.subresource.padded_height,
                    second_clear.subresource.padded_width,
                    second_clear.subresource.padded_height,
                    first.unified_format,
                    second.unified_format,
                    @tagName(first.tile_mode),
                    @tagName(second.tile_mode),
                    self.emulated_image_store_dispatches,
                },
            );
        }
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    fn reportDualImageClearFallback(
        self: *Renderer,
        reason: []const u8,
        first: ?gpu.ImageDescriptor,
        second: ?gpu.ImageDescriptor,
    ) void {
        if (self.reported_dual_image_clear_fallback) return;
        self.reported_dual_image_clear_fallback = true;
        std.debug.print("[vulkan dcb] dual image clear fallback: {s}\n", .{reason});
        for ([_]?gpu.ImageDescriptor{ first, second }, 0..) |maybe, index| {
            const image = maybe orelse continue;
            std.debug.print(
                "  image[{d}] addr=0x{x} {d}x{d}x{d} pitch={d} fmt={d} type={s} tile={s} levels={d}/{d} samples={d} meta=0x{x} dcc={any} cmask={any} fmask={any}\n",
                .{
                    index,
                    image.address,
                    image.width,
                    image.height,
                    image.depth_or_layers,
                    image.pitch,
                    image.unified_format,
                    @tagName(image.image_type),
                    @tagName(image.tile_mode),
                    image.viewBaseLevel(),
                    image.viewMipLevels(),
                    image.samplesLog2(),
                    image.metadata_address,
                    image.dcc_enabled,
                    image.cmask_fast_clear,
                    image.fmask_compression,
                },
            );
        }
    }

    fn applyWholeImageClear(
        self: *Renderer,
        memory: GuestMemory,
        clear: WholeImageClear,
    ) anyerror!u64 {
        if (try contiguousWholeImageClearRange(clear.subresource)) |range| {
            const bytes = try self.allocator.alloc(u8, range.length);
            defer self.allocator.free(bytes);
            fillRepeatedPattern(bytes, clear.texel.bytes[0..clear.texel.length]);
            const write_address = try std.math.add(u64, clear.descriptor.address, range.offset);
            if (!memory.write(memory.context, write_address, bytes)) return Error.GuestMemoryWriteFailed;
            self.invalidateDmaDestination(write_address, bytes.len);
            return @as(u64, clear.subresource.width) * clear.subresource.height;
        }

        const allocation = try self.allocator.alloc(u8, clear.allocation_bytes);
        defer self.allocator.free(allocation);
        if (!try wholeImageClearCoversAllocation(allocation.len, clear.subresource) and
            !memory.read(memory.context, clear.descriptor.address, allocation))
        {
            return Error.GuestMemoryReadFailed;
        }
        if (!try fillWholeImageBlocks(
            allocation,
            clear.subresource,
            clear.texel.bytes[0..clear.texel.length],
        )) {
            for (0..clear.subresource.height) |y_index| {
                const y: u32 = @intCast(y_index);
                for (0..clear.subresource.width) |x_index| {
                    const x: u32 = @intCast(x_index);
                    const offset_u64 = try clear.subresource.sourceByteOffset(x, y, 0, 0);
                    const offset = std.math.cast(usize, offset_u64) orelse return Error.GuestBufferTooLarge;
                    if (offset > allocation.len or clear.texel.length > allocation.len - offset) {
                        return Error.GuestBufferTooLarge;
                    }
                    @memcpy(
                        allocation[offset..][0..clear.texel.length],
                        clear.texel.bytes[0..clear.texel.length],
                    );
                }
            }
        }
        if (!memory.write(memory.context, clear.descriptor.address, allocation)) return Error.GuestMemoryWriteFailed;
        self.invalidateDmaDestination(clear.descriptor.address, allocation.len);
        return @as(u64, clear.subresource.width) * clear.subresource.height;
    }

    /// Executes the bounded AGC buffer-to-3D-image upload kernel used for
    /// small lookup textures. The exact shader shape is matched separately;
    /// this method only implements its observed R8->RGBA8 and R16->R16 typed
    /// transfers and leaves general image-store programs to the translator.
    fn tryEmulateVolumeBufferCopy(
        self: *Renderer,
        memory: GuestMemory,
        bindings: *const gpu.ShaderBindings,
        reader: gpu.ShaderMemoryReader,
        analysis: *const gpu.ShaderAnalysis,
        system: gpu.resources.ComputeSystemRegisters,
        local_size: [3]u32,
        group_count: [3]u32,
    ) anyerror!?DispatchReport {
        if (!matchesVolumeBufferCopy(analysis.program.instructions.items)) return null;
        if (local_size[0] != 8 or local_size[1] != 8 or local_size[2] != 1 or
            system.workgroup_id_sgprs[0] != 16 or
            system.workgroup_id_sgprs[1] != 17 or
            system.workgroup_id_sgprs[2] != 18 or
            system.local_invocation_id_components != 2)
        {
            return null;
        }

        const source = (try bindings.inlineBufferDescriptor(8)) orelse return null;
        const control = (try bindings.inlineBufferDescriptor(12)) orelse return null;
        const image = try resolveReadWriteImageDescriptor(bindings, reader, 0) orelse return null;
        if (source.address == 0 or source.record_count == 0 or source.swizzle_enabled or
            source.add_thread_id or source.index_stride != 0 or source.out_of_bounds_select != 0 or
            source.dst_select[0] != 4 or control.address == 0 or control.size_bytes < 44 or
            image.image_type != .color_3d or image.dcc_enabled or image.cmask_fast_clear or
            image.fmask_compression or image.metadata_address != 0 or image.samplesLog2() != 0 or
            image.viewMipLevels() != 1 or image.viewBaseLevel() != 0)
        {
            return null;
        }
        const format_supported = (source.unified_format == 5 and source.stride == 1 and
            image.unified_format == 60) or
            (source.unified_format == 11 and source.stride == 2 and image.unified_format == 11);
        if (!format_supported) return null;

        var words: [11]u32 = undefined;
        for (&words, 0..) |*word, index| {
            word.* = try readGuestU32(memory, control.address + index * @sizeOf(u32));
        }
        const texture = gpu.TextureLayout.fromImage(image) catch return null;
        const subresource = texture.subresource(0, 0, 1) catch return null;

        const dispatched_x = std.math.mul(u64, group_count[0], local_size[0]) catch
            return Error.GuestBufferTooLarge;
        const dispatched_y = std.math.mul(u64, group_count[1], local_size[1]) catch
            return Error.GuestBufferTooLarge;
        const dispatched_z = std.math.mul(u64, group_count[2], local_size[2]) catch
            return Error.GuestBufferTooLarge;
        const base_x = words[4];
        const base_y = words[5];
        const base_z = words[6];
        if (base_x > subresource.width or base_y > subresource.height or
            base_z > subresource.depth_or_layers) return null;
        const width: u32 = @intCast(@min(
            @as(u64, @min(words[8], subresource.width - base_x)),
            dispatched_x,
        ));
        const height: u32 = @intCast(@min(
            @as(u64, @min(words[9], subresource.height - base_y)),
            dispatched_y,
        ));
        const depth: u32 = @intCast(@min(
            @as(u64, @min(words[10], subresource.depth_or_layers - base_z)),
            dispatched_z,
        ));
        const texel_count = std.math.mul(u64, width, height) catch return Error.GuestBufferTooLarge;
        const volume_texels = std.math.mul(u64, texel_count, depth) catch return Error.GuestBufferTooLarge;
        if (volume_texels > 16 * 1024 * 1024) return null;

        var writes: u64 = 0;
        for (0..depth) |z_index| {
            const z: u32 = @intCast(z_index);
            for (0..height) |y_index| {
                const y: u32 = @intCast(y_index);
                for (0..width) |x_index| {
                    const x: u32 = @intCast(x_index);
                    const source_index = volumeSourceIndex(words[0..3].*, x, y, z) catch
                        return Error.GuestBufferTooLarge;
                    var values: [4]u32 = @splat(0);
                    for (&values, 0..) |*value, channel| {
                        const index = std.math.add(u64, source_index, channel) catch
                            return Error.GuestBufferTooLarge;
                        value.* = try readTypedBufferValue(memory, source, index);
                    }
                    const texel = packImageStoreTexel(
                        image.unified_format,
                        values,
                        0xf,
                        image.dst_select,
                    ) orelse return null;
                    if (texel.length != subresource.block.bytes_per_element) return null;

                    const target_x = base_x + x;
                    const target_y = base_y + y;
                    const target_z = base_z + z;
                    const offset = try subresource.sourceByteOffset(target_x, target_y, target_z, 0);
                    const address = std.math.add(u64, image.address, offset) catch
                        return Error.GuestMemoryWriteFailed;
                    if (!memory.write(memory.context, address, texel.bytes[0..texel.length])) {
                        return Error.GuestMemoryWriteFailed;
                    }
                    writes += 1;
                }
            }
        }

        self.emulated_volume_copies += 1;
        if (log_verbose_gpu or self.emulated_volume_copies <= 4) {
            std.debug.print(
                "[vulkan dcb] emulated volume upload: {d} texels src_fmt={d} dst_fmt={d} tile={s} (#{d})\n",
                .{
                    writes,
                    source.unified_format,
                    image.unified_format,
                    @tagName(image.tile_mode),
                    self.emulated_volume_copies,
                },
            );
        }
        return .{ .pipeline_cache_hit = false, .group_count = group_count, .spirv_words = 0 };
    }

    fn prepareComputeResources(
        self: *Renderer,
        bindings: *const gpu.ShaderBindings,
        reader: gpu.ShaderMemoryReader,
        analysis: *const gpu.ShaderAnalysis,
        instructions: []const gpu.ShaderInstruction,
        scalar: *const gpu.ScalarEvaluation,
        specialized_scalar_prefix_end: u32,
        reserved_resources: ?*const ComputeResources,
    ) anyerror!ComputeResources {
        var result = ComputeResources{};
        errdefer result.deinit(self);
        result.specialized_scalar_prefix_end = specialized_scalar_prefix_end;
        if (reserved_resources) |reserved| {
            for (reserved.occupied, 0..) |used, index| {
                if (!used) continue;
                result.occupied[index] = true;
                result.addresses[index] = reserved.addresses[index];
                result.sizes[index] = reserved.sizes[index];
            }
        }
        const is_vertex_stage = switch (bindings.stage) {
            .vertex, .geometry, .export_shader, .hull => true,
            .pixel, .compute => false,
        };
        const vertex_table = if (is_vertex_stage)
            (gpu.VertexBindings.capture(bindings, reader) catch null)
        else
            null;
        var used_vertex_attributes: [maximum_vertex_attributes]bool = @splat(false);
        result.scalar_count = collectScalarLoadSpecializations(scalar, &result.scalar_registers);
        result.scalar_count = mergeUserDataScalars(
            bindings,
            bindings.scalar_user_data_base,
            &result.scalar_registers,
            result.scalar_count,
        );
        // Preserve the AGC slot number whenever possible. This makes the host
        // descriptor table stable across shaders that share one SRT layout.
        var iterator = bindings.iterator(reader, .constant_buffer);
        while (true) {
            // Resource-count tables can include an unused/partially populated
            // constant-buffer slot.  A later instruction-local V# is still
            // authoritative, so do not discard the complete kernel merely
            // because that eager SRT sweep encounters one invalid candidate.
            const next_binding = iterator.next() catch |err| switch (err) {
                error.InvalidDescriptor, error.InvalidFormat => continue,
                else => return err,
            };
            const binding = next_binding orelse break;
            const descriptor = binding.descriptor.constant_buffer;
            if (descriptor.isNull() or descriptor.size_bytes == 0) continue;
            const size = std.math.cast(usize, descriptor.size_bytes) orelse return Error.GuestBufferTooLarge;
            if (result.descriptorForRange(descriptor.address, size) != null) continue;
            const descriptor_index: u32 = if (binding.mapping.slot < maximum_storage_descriptors and
                !result.occupied[binding.mapping.slot])
                binding.mapping.slot
            else
                result.freeDescriptor() orelse return Error.InvalidStorageDescriptor;
            _ = try self.stageGuestStorageBufferAt(descriptor_index, descriptor.address, size);
            result.occupied[descriptor_index] = true;
            result.addresses[descriptor_index] = descriptor.address;
            result.sizes[descriptor_index] = size;
        }

        // Resource descriptors are often loaded into the same SGPR window at
        // several points in a shader. Capture all instruction-local states in
        // one scalar execution instead of replaying the whole prolog for every
        // MUBUF/MIMG instruction (quadratic on large Unreal shaders).
        var scalar_checkpoint_count: usize = 0;
        for (instructions) |inst| {
            if (needsResourceScalarCheckpoint(inst)) scalar_checkpoint_count += 1;
        }
        const scalar_checkpoint_pcs = try self.allocator.alloc(u32, scalar_checkpoint_count);
        defer self.allocator.free(scalar_checkpoint_pcs);
        const scalar_checkpoint_registers = try self.allocator.alloc(
            gpu.scalar_provenance.ScalarRegisters,
            scalar_checkpoint_count,
        );
        defer self.allocator.free(scalar_checkpoint_registers);
        var scalar_checkpoint_index: usize = 0;
        for (instructions) |inst| {
            if (!needsResourceScalarCheckpoint(inst)) continue;
            scalar_checkpoint_pcs[scalar_checkpoint_index] = inst.pc;
            scalar_checkpoint_index += 1;
        }
        if (scalar_checkpoint_count != 0) {
            _ = gpu.scalar_provenance.evaluateDecodedResourceStateAtCheckpoints(
                reader,
                bindings,
                instructions,
                scalar_checkpoint_pcs,
                scalar_checkpoint_registers,
            );
        }

        for (instructions) |inst| {
            const is_store = switch (inst.opcode) {
                .buffer_load_ubyte,
                .buffer_load_sbyte,
                .buffer_load_ushort,
                .buffer_load_sshort,
                .buffer_load_dword,
                .buffer_load_dwordx2,
                .buffer_load_dwordx3,
                .buffer_load_dwordx4,
                .buffer_load_format_x,
                .buffer_load_format_xy,
                .buffer_load_format_xyz,
                .buffer_load_format_xyzw,
                .s_buffer_load_dword,
                .s_buffer_load_dwordx2,
                .s_buffer_load_dwordx4,
                .s_buffer_load_dwordx8,
                .s_buffer_load_dwordx16,
                => false,
                .buffer_store_byte,
                .buffer_store_short,
                .buffer_store_dword,
                .buffer_store_dwordx2,
                .buffer_store_dwordx3,
                .buffer_store_dwordx4,
                .buffer_store_format_x,
                .buffer_store_format_xy,
                .buffer_store_format_xyz,
                .buffer_store_format_xyzw,
                .buffer_atomic_swap,
                .buffer_atomic_add,
                .buffer_atomic_sub,
                .buffer_atomic_smin,
                .buffer_atomic_umin,
                .buffer_atomic_smax,
                .buffer_atomic_umax,
                .buffer_atomic_and,
                .buffer_atomic_or,
                .buffer_atomic_xor,
                => true,
                else => continue,
            };
            const resource_operand = if (inst.family == .smem) inst.src0 else inst.src1;
            if (resource_operand.kind != .sgpr) {
                if (log_verbose_gpu) std.debug.print(
                    "[vulkan dcb] MissingStorageDescriptor: pc=0x{x} {s} resource is {s} not sgpr\n",
                    .{ inst.pc, @tagName(inst.opcode), @tagName(resource_operand.kind) },
                );
                return Error.MissingStorageDescriptor;
            }
            const resource_sgpr = resource_operand.reg;
            const formatted_vertex_fetch = is_vertex_stage and inst.family != .smem and !is_store and switch (inst.opcode) {
                .buffer_load_format_x,
                .buffer_load_format_xy,
                .buffer_load_format_xyz,
                .buffer_load_format_xyzw,
                => true,
                else => false,
            };
            // Resolve the descriptor at the instruction itself. Shader prologs
            // reuse the same SGPR quartet for several SMEM-loaded V# values;
            // a final whole-program snapshot (or the first mapping for that
            // SGPR) is not authoritative for a later MUBUF operation.
            const instruction_scalar = gpu.ScalarEvaluation{
                .registers = scalarRegistersAtCheckpoint(
                    scalar_checkpoint_pcs,
                    scalar_checkpoint_registers,
                    inst.pc,
                ).*,
            };
            // The instruction-local scalar state is authoritative. Attribute
            // tables are ordered by semantic/location, while shader fetches
            // are free to consume those attributes in a different order. In
            // particular, JnG2 loads UV before color although its AGC table
            // lists color before UV; pairing both lists by index swaps their
            // V# descriptors and leaves every texture lookup at one corner.
            // Keep the table entry only as a fallback for shaders whose V#
            // producer cannot yet be reconstructed.
            const resolved_descriptor = try resolveComputeBufferDescriptor(
                bindings,
                reader,
                analysis,
                &instruction_scalar,
                &instruction_scalar,
                resource_sgpr,
                inst.pc,
            );
            const vertex_attribute: ?gpu.VertexAttribute = if (resolved_descriptor) |resolved|
                if (vertex_table) |*table|
                    matchVertexAttribute(table, &used_vertex_attributes, resolved)
                else
                    null
            else if (formatted_vertex_fetch)
                if (vertex_table) |*table|
                    takeNextVertexAttribute(table, &used_vertex_attributes)
                else
                    null
            else
                null;
            const descriptor = resolved_descriptor orelse (if (vertex_attribute) |attribute|
                takePlausibleBufferDescriptor(attribute.buffer)
            else
                null) orelse {
                if (log_verbose_gpu) {
                    const full = gpu.scalar_provenance.evaluatePrefix(reader, bindings);
                    std.debug.print(
                        "[vulkan dcb] MissingStorageDescriptor: pc=0x{x} {s} V# s{d}:s{d} unknown (scalar stop={s} @0x{x}, loads={d}, user_data={d}); soft-skip\n",
                        .{
                            inst.pc,
                            @tagName(inst.opcode),
                            resource_sgpr,
                            resource_sgpr + 3,
                            @tagName(full.stop_reason),
                            full.stop_pc,
                            full.load_count,
                            bindings.user_data_count,
                        },
                    );
                }
                // Soft-skip: keep mapping other resources so a single missing
                // V# does not abort the whole draw/dispatch.
                continue;
            };
            if (descriptor.isNull() or descriptor.size_bytes == 0) {
                if (log_verbose_gpu) std.debug.print(
                    "[vulkan dcb] MissingStorageDescriptor: pc=0x{x} {s} V# s{d} null/empty (addr=0x{x} size={d}); soft-skip\n",
                    .{
                        inst.pc,
                        @tagName(inst.opcode),
                        resource_sgpr,
                        descriptor.address,
                        descriptor.size_bytes,
                    },
                );
                continue;
            }
            const size = std.math.cast(usize, descriptor.size_bytes) orelse {
                if (log_verbose_gpu) std.debug.print(
                    "[vulkan dcb] GuestBufferTooLarge: V# s{d} size_bytes=0x{x}; soft-skip\n",
                    .{ resource_sgpr, descriptor.size_bytes },
                );
                continue;
            };
            const descriptor_index = result.descriptorForRange(descriptor.address, size) orelse blk: {
                const free = result.freeDescriptor() orelse {
                    if (log_verbose_gpu) std.debug.print("[vulkan dcb] no free storage slot for V# s{d}; soft-skip\n", .{resource_sgpr});
                    continue;
                };
                _ = self.stageGuestStorageBufferAt(free, descriptor.address, size) catch |err| {
                    if (log_verbose_gpu) std.debug.print(
                        "[vulkan dcb] stage V# s{d} failed: {s} addr=0x{x} size=0x{x} stride={d} records={d}; soft-skip\n",
                        .{
                            resource_sgpr,
                            @errorName(err),
                            descriptor.address,
                            size,
                            descriptor.stride,
                            descriptor.record_count,
                        },
                    );
                    continue;
                };
                result.occupied[free] = true;
                result.addresses[free] = descriptor.address;
                result.sizes[free] = size;
                break :blk free;
            };
            const previous_descriptor_index = result.mappingForSgpr(resource_sgpr);
            // Constant-buffer mappings are interchangeable when the SGPR and
            // staged range match. Vertex attributes are not: several fetches
            // commonly share one V# and buffer while using different table
            // offsets, so every instruction needs its own PC-qualified entry.
            if (canReuseStorageMapping(
                vertex_attribute != null,
                previous_descriptor_index,
                descriptor_index,
            )) {
                if (is_store) result.writable[descriptor_index] = true;
                continue;
            }
            if (result.mapping_count >= result.mappings.len) {
                if (log_verbose_gpu) std.debug.print(
                    "[vulkan dcb] no free V# mapping for pc=0x{x} s{d}; soft-skip\n",
                    .{ inst.pc, resource_sgpr },
                );
                continue;
            }
            result.mappings[result.mapping_count] = .{
                .resource_sgpr = resource_sgpr,
                .descriptor_index = descriptor_index,
                .instruction_pc = if (vertex_attribute != null or
                    previous_descriptor_index != null)
                    inst.pc
                else
                    null,
                .soffset_value = if (vertex_attribute) |attribute| attribute.offset_bytes else null,
                .use_vertex_index = vertex_attribute != null,
                .stride = descriptor.stride,
                .swizzled = descriptor.swizzle_enabled,
                .index_stride = descriptor.index_stride,
                .add_thread_id = descriptor.add_thread_id,
                // AGC's vertex table supplies the element separately and its
                // V# may leave DST_SEL at zero. Those zero selectors are not
                // an instruction to replace every fetched component with 0;
                // formatted vertex fetches use their natural XYZW order. The
                // recovered V# format remains authoritative because AGC's
                // attribute-format numbering is not uniformly identical to
                // the RDNA unified-format enum (values above 182 are common).
                .unified_format = descriptor.unified_format,
                .dst_select = if (vertex_attribute != null or formatted_vertex_fetch)
                    .{ 4, 5, 6, 7 }
                else
                    descriptor.dst_select,
                // The descriptor already says how far the buffer goes, so the
                // shader can be held to it instead of being trusted to stay
                // inside on its own.
                .extent_bytes = std.math.cast(u32, descriptor.size_bytes),
            };
            result.mapping_count += 1;
            if (is_store) result.writable[descriptor_index] = true;
        }

        for (instructions) |inst| {
            const writable = switch (inst.opcode) {
                .image_load => false,
                .image_store,
                .image_store_mip,
                .image_atomic_add,
                .image_atomic_umin,
                .image_atomic_umax,
                .image_atomic_and,
                .image_atomic_or,
                .image_atomic_xor,
                .image_atomic_fmax,
                => true,
                else => continue,
            };
            if (inst.src1.kind != .sgpr) {
                std.debug.print(
                    "[vulkan dcb] storage image pc=0x{x}: resource is {s}, not SGPR\n",
                    .{ inst.pc, @tagName(inst.src1.kind) },
                );
                return Error.UnsupportedStorageImage;
            }
            const resource_sgpr = inst.src1.reg;
            // Compute kernels commonly populate T# SGPRs with SMEM after the
            // scalar specialization prefix. Resolve the state at this image
            // instruction; using the entry snapshot bound late destinations
            // to an unrelated fallback slot (notably a 2D image for a 3D
            // image_store in large volume-processing kernels).
            const image_scalar = gpu.ScalarEvaluation{
                .registers = scalarRegistersAtCheckpoint(
                    scalar_checkpoint_pcs,
                    scalar_checkpoint_registers,
                    inst.pc,
                ).*,
            };
            var descriptor = (try resolveComputeImageDescriptor(
                bindings,
                reader,
                analysis,
                &image_scalar,
                resource_sgpr,
                inst.pc,
                result.storage_image_mapping_count,
            )) orelse {
                std.debug.print(
                    "[vulkan dcb] storage image pc=0x{x}: T# s{d}:s{d} unresolved\n",
                    .{ inst.pc, resource_sgpr, resource_sgpr + 7 },
                );
                return Error.UnsupportedStorageImage;
            };
            // A regular IMAGE_LOAD/STORE addresses the base level even when
            // its T# exposes the complete mip chain. Vulkan storage views are
            // single-level, so bind that exact level instead of rejecting a
            // valid multi-mip resource descriptor.
            if (inst.opcode != .image_store_mip and descriptor.viewMipLevels() > 1) {
                descriptor.last_level = descriptor.viewBaseLevel();
            }
            // Vulkan cannot expose BC-compressed formats as storage images,
            // but a read-only MIMG image_load is exactly representable as
            // OpImageFetch from a sampled BC image. Leave those descriptors to
            // the sampled-image pass below. A resource that is also written in
            // this program must remain a real storage image and is rejected.
            if (!writable and isBlockCompressedUnifiedFormat(descriptor.unified_format) and
                !programStoresImageResource(analysis, resource_sgpr))
            {
                continue;
            }
            const format = storageImageFormat(descriptor.unified_format) orelse {
                std.debug.print(
                    "[vulkan dcb] storage image pc=0x{x}: format {d} is unsupported addr=0x{x} {d}x{d}x{d} type={s} writable={any}\n",
                    .{
                        inst.pc,
                        descriptor.unified_format,
                        descriptor.address,
                        descriptor.width,
                        descriptor.height,
                        descriptor.depth_or_layers,
                        @tagName(descriptor.image_type),
                        writable,
                    },
                );
                return Error.UnsupportedStorageImage;
            };
            var descriptor_index: ?u32 = null;
            for (result.storage_images[0..result.storage_image_count], 0..) |*existing, index| {
                if (existing.descriptor.address == descriptor.address and
                    existing.descriptor.width == descriptor.width and
                    existing.descriptor.height == descriptor.height and
                    existing.descriptor.depth_or_layers == descriptor.depth_or_layers and
                    existing.descriptor.unified_format == descriptor.unified_format and
                    existing.descriptor.tile_mode == descriptor.tile_mode and
                    existing.descriptor.image_type == descriptor.image_type and
                    existing.descriptor.viewBaseLevel() == descriptor.viewBaseLevel() and
                    existing.descriptor.viewMipLevels() == descriptor.viewMipLevels() and
                    existing.descriptor.base_array == descriptor.base_array)
                {
                    if (writable) existing.writable = true;
                    descriptor_index = @intCast(index);
                    break;
                }
            }
            if (descriptor_index == null) {
                if (result.storage_image_count >= maximum_storage_images) {
                    std.debug.print(
                        "[vulkan dcb] storage image pc=0x{x}: physical image table exhausted ({d})\n",
                        .{ inst.pc, maximum_storage_images },
                    );
                    return Error.StorageImageCapacityExceeded;
                }
                const index: u32 = @intCast(result.storage_image_count);
                result.storage_images[result.storage_image_count] = self.stageStorageImage(
                    descriptor,
                    index,
                    writable,
                ) catch |err| {
                    std.debug.print(
                        "[vulkan dcb] storage image pc=0x{x}: stage failed {s} addr=0x{x} {d}x{d}x{d} pitch={d} fmt={d} type={s} tile={s} levels={d}..{d} base_array={d} flags=0x{x} metadata=0x{x} dcc={any} cmask={any} fmask={any}\n",
                        .{
                            inst.pc,
                            @errorName(err),
                            descriptor.address,
                            descriptor.width,
                            descriptor.height,
                            descriptor.depth_or_layers,
                            descriptor.pitch,
                            descriptor.unified_format,
                            @tagName(descriptor.image_type),
                            @tagName(descriptor.tile_mode),
                            descriptor.base_level,
                            descriptor.last_level,
                            descriptor.base_array,
                            descriptor.descriptor_flags,
                            descriptor.metadata_address,
                            descriptor.dcc_enabled,
                            descriptor.cmask_fast_clear,
                            descriptor.fmask_compression,
                        },
                    );
                    return err;
                };
                result.storage_image_count += 1;
                descriptor_index = index;
            }

            // The first descriptor occupying an SGPR range is a generic
            // mapping. If later SMEM replaces that range, retain the generic
            // mapping for the original uses and attach an exact PC mapping to
            // the new state. This avoids both descriptor explosion for the
            // common repeated-image case and binding a late image atomic to an
            // unrelated texture loaded into the same s[0:7].
            var instruction_pc: ?u32 = null;
            for (result.storage_image_mappings[0..result.storage_image_mapping_count]) |mapping| {
                if (mapping.resource_sgpr != resource_sgpr) continue;
                if (mapping.descriptor_index == descriptor_index.?) {
                    if (writable) result.storage_images[descriptor_index.?].writable = true;
                    if (mapping.instruction_pc == null or mapping.instruction_pc.? == inst.pc) {
                        descriptor_index = null;
                        break;
                    }
                }
                if (mapping.instruction_pc == null) instruction_pc = inst.pc;
            }
            if (descriptor_index == null) continue;
            if (result.storage_image_mapping_count >= maximum_storage_descriptors) {
                std.debug.print(
                    "[vulkan dcb] storage image pc=0x{x}: mapping table exhausted ({d})\n",
                    .{ inst.pc, maximum_storage_descriptors },
                );
                return Error.UnsupportedStorageImage;
            }
            result.storage_image_mappings[result.storage_image_mapping_count] = .{
                .resource_sgpr = resource_sgpr,
                .descriptor_index = descriptor_index.?,
                .instruction_pc = instruction_pc,
                .format = format.spirv,
                .dimension = switch (descriptor.image_type) {
                    .color_3d => .three_d,
                    .color_2d_array => .two_d_array,
                    else => .two_d,
                },
                .dst_select = descriptor.dst_select,
            };
            result.storage_image_mapping_count += 1;
        }

        for (instructions) |inst| {
            const image_fetch = inst.opcode == .image_load or inst.opcode == .image_load_mip;
            if (!image_fetch and inst.opcode != .image_sample and inst.opcode != .image_gather4) continue;
            if (inst.src1.kind != .sgpr or inst.src2.kind != .sgpr) {
                std.debug.print(
                    "[vulkan dcb] sampled image pc=0x{x}: T# is {s}, S# is {s}\n",
                    .{ inst.pc, @tagName(inst.src1.kind), @tagName(inst.src2.kind) },
                );
                return Error.UnsupportedSampledImage;
            }
            const resource_sgpr = inst.src1.reg;
            const sampler_sgpr = inst.src2.reg;
            if (result.sampledImageMappingForInstruction(resource_sgpr, sampler_sgpr, inst.pc) != null) continue;
            if (result.sampled_image_mapping_count >= maximum_compute_sampled_mappings) {
                std.debug.print(
                    "[vulkan dcb] sampled image PC mapping table exhausted ({d})\n",
                    .{maximum_compute_sampled_mappings},
                );
                return Error.UnsupportedSampledImage;
            }

            const descriptor_slot = result.sampled_image_mapping_count;
            const sampled_scalar = gpu.ScalarEvaluation{
                .registers = scalarRegistersAtCheckpoint(
                    scalar_checkpoint_pcs,
                    scalar_checkpoint_registers,
                    inst.pc,
                ).*,
            };
            const image_descriptor = (try resolveComputeSampledImageDescriptor(
                bindings,
                reader,
                analysis,
                &sampled_scalar,
                resource_sgpr,
                inst.pc,
                descriptor_slot,
            )) orelse {
                std.debug.print(
                    "[vulkan dcb] sampled image pc=0x{x}: T# s{d}:s{d} unresolved\n",
                    .{ inst.pc, resource_sgpr, resource_sgpr + 7 },
                );
                return Error.UnsupportedSampledImage;
            };
            if (inst.opcode == .image_load and
                (!isBlockCompressedUnifiedFormat(image_descriptor.unified_format) or
                    programStoresImageResource(analysis, resource_sgpr)))
            {
                // Uncompressed fetches were bound through the storage-image
                // pass above. Only compressed, read-only fetches need this
                // sampled-image fallback.
                continue;
            }
            const sampler_descriptor: gpu.resources.SamplerDescriptor = if (image_fetch)
                std.mem.zeroes(gpu.resources.SamplerDescriptor)
            else
                (try resolveComputeSamplerDescriptor(
                    bindings,
                    reader,
                    analysis,
                    &sampled_scalar,
                    sampler_sgpr,
                    inst.pc,
                    descriptor_slot,
                )) orelse {
                    std.debug.print(
                        "[vulkan dcb] sampled image pc=0x{x}: S# s{d}:s{d} unresolved\n",
                        .{ inst.pc, sampler_sgpr, sampler_sgpr + 3 },
                    );
                    return Error.UnsupportedSampledImage;
                };
            const sampled_dimension = sampledImageDimensionForInstruction(
                inst.image_dimension,
                image_descriptor.image_type,
            ) orelse {
                std.debug.print(
                    "[vulkan dcb] sampled image pc=0x{x}: unsupported DIM {s}\n",
                    .{ inst.pc, @tagName(inst.image_dimension) },
                );
                return Error.UnsupportedSampledImage;
            };
            var descriptor_index: ?u32 = null;
            for (
                result.sampled_image_descriptors[0..result.sampled_image_count],
                result.sampled_image_samplers[0..result.sampled_image_count],
                result.sampled_image_dimensions[0..result.sampled_image_count],
                0..,
            ) |existing_image, existing_sampler, existing_dimension, index| {
                if (!std.meta.eql(existing_image, image_descriptor) or
                    !std.meta.eql(existing_sampler, sampler_descriptor) or
                    existing_dimension != sampled_dimension)
                {
                    continue;
                }
                descriptor_index = @intCast(index);
                break;
            }
            if (descriptor_index == null) {
                if (result.sampled_image_count >= maximum_sampled_images) {
                    std.debug.print(
                        "[vulkan dcb] sampled image physical table exhausted ({d})\n",
                        .{maximum_sampled_images},
                    );
                    return Error.UnsupportedSampledImage;
                }
                const physical_index: u32 = @intCast(result.sampled_image_count);
                const sampled_started = hostTimestampNs();
                const image = self.stageSampledImage(
                    image_descriptor,
                    sampler_descriptor,
                    physical_index,
                    sampled_dimension,
                    null,
                ) catch |err| {
                    std.debug.print(
                        "[vulkan dcb] sampled image pc=0x{x}: stage failed {s} dim={s} addr=0x{x} {d}x{d}x{d} pitch={d} fmt={d} type={s} tile={s} levels={d}..{d}\n",
                        .{ inst.pc, @errorName(err), @tagName(sampled_dimension), image_descriptor.address, image_descriptor.width, image_descriptor.height, image_descriptor.depth_or_layers, image_descriptor.pitch, image_descriptor.unified_format, @tagName(image_descriptor.image_type), @tagName(image_descriptor.tile_mode), image_descriptor.base_level, image_descriptor.last_level },
                    );
                    return err;
                };
                self.frame_profile.sampled_stage_ns +|= elapsedHostNanoseconds(sampled_started);
                result.sampled_images[result.sampled_image_count] = image;
                result.sampled_image_descriptors[result.sampled_image_count] = image_descriptor;
                result.sampled_image_samplers[result.sampled_image_count] = sampler_descriptor;
                result.sampled_image_dimensions[result.sampled_image_count] = sampled_dimension;
                result.sampled_image_count += 1;
                descriptor_index = physical_index;
            }
            result.sampled_image_mappings[result.sampled_image_mapping_count] = .{
                .resource_sgpr = resource_sgpr,
                .sampler_sgpr = sampler_sgpr,
                .descriptor_index = descriptor_index.?,
                .dimension = sampled_dimension,
                .instruction_pc = inst.pc,
            };
            result.sampled_image_mapping_count += 1;
        }
        self.updateSampledImageDescriptors(
            result.sampled_images[0..result.sampled_image_count],
            result.sampled_image_mappings[0..result.sampled_image_mapping_count],
        );
        return result;
    }

    fn commitComputeWrites(self: *Renderer, memory: GuestMemory, resources: *const ComputeResources) anyerror!void {
        const profile_started = hostTimestampNs();
        defer self.frame_profile.storage_commit_ns +|= elapsedHostNanoseconds(profile_started);
        for (resources.writable, 0..) |writable, index| {
            if (!writable) continue;
            if (self.defer_small_storage_writes_enabled or
                resources.sizes[index] >= deferred_storage_write_min_bytes)
            {
                for (self.guest_buffers.items) |*entry| {
                    if (entry.guest_address != resources.addresses[index] or
                        entry.size != resources.sizes[index]) continue;
                    entry.gpu_dirty = true;
                    break;
                }
                continue;
            }
            const bytes = try self.allocator.alloc(u8, resources.sizes[index]);
            defer self.allocator.free(bytes);
            try self.readbackGuestStorageBuffer(resources.addresses[index], bytes);
            if (!memory.write(memory.context, resources.addresses[index], bytes)) return Error.GuestMemoryWriteFailed;
        }
    }

    fn getComputePipeline(self: *Renderer, words: []const u32) (Error || std.mem.Allocator.Error)!PipelineLookup {
        self.compute_pipeline_sequence +%= 1;
        const hash = std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(words));
        for (self.compute_pipelines.items) |*entry| {
            if (entry.hash == hash and std.mem.eql(u32, entry.words, words)) {
                self.pipeline_cache_hits += 1;
                self.frame_profile.compute_pipeline_hits += 1;
                entry.last_used_sequence = self.compute_pipeline_sequence;
                return .{ .pipeline = entry.pipeline, .cache_hit = true };
            }
        }

        const build_started = hostTimestampNs();
        defer self.frame_profile.compute_pipeline_build_ns +|= elapsedHostNanoseconds(build_started);
        var work = ComputePipelineCompileJob{
            .renderer = self,
            .words = words,
        };
        const asynchronous = self.async_pipeline_compilation_enabled;
        if (asynchronous) {
            self.pipeline_compile_queue.submit(&work.job);
        } else {
            ComputePipelineCompileJob.run(&work.job);
        }
        const owned_words = self.allocator.dupe(u32, words) catch |err| {
            if (asynchronous) work.job.wait();
            if (work.pipeline != 0) self.device_functions.destroy_pipeline(self.device, work.pipeline, null);
            if (work.shader != 0) self.device_functions.destroy_shader_module(self.device, work.shader, null);
            return err;
        };
        errdefer self.allocator.free(owned_words);
        if (asynchronous) work.job.wait();
        if (work.failure) |failure| return failure;
        const shader = work.shader;
        const pipeline = work.pipeline;
        errdefer self.destroyPipeline(pipeline);
        errdefer self.destroyShaderModule(shader);
        const replacement = ComputePipelineEntry{
            .hash = hash,
            .words = owned_words,
            .shader = shader,
            .pipeline = pipeline,
            .last_used_sequence = self.compute_pipeline_sequence,
        };
        if (self.compute_pipelines.items.len < maximum_compute_pipelines) {
            try self.compute_pipelines.append(self.allocator, replacement);
        } else {
            // Dispatch submissions are fenced before returning, so no cached
            // pipeline remains in flight here. Recycle the coldest specialized
            // variant instead of dropping a required compute dispatch.
            var oldest_index: usize = 0;
            var oldest_sequence = self.compute_pipelines.items[0].last_used_sequence;
            for (self.compute_pipelines.items[1..], 1..) |entry, index| {
                if (entry.last_used_sequence >= oldest_sequence) continue;
                oldest_index = index;
                oldest_sequence = entry.last_used_sequence;
            }
            const evicted = self.compute_pipelines.items[oldest_index];
            self.destroyPipeline(evicted.pipeline);
            self.destroyShaderModule(evicted.shader);
            self.allocator.free(evicted.words);
            self.compute_pipelines.items[oldest_index] = replacement;
        }
        self.pipeline_cache_misses += 1;
        self.frame_profile.compute_pipeline_misses += 1;
        return .{ .pipeline = pipeline, .cache_hit = false };
    }

    /// Compiles one already-translated compute module against the live device.
    ///
    /// This deliberately stops before descriptor allocation or dispatch.  It is
    /// a small offline reproducer for driver compiler failures: game-run can
    /// dump a module at the point of failure and vulkan-smoke can then exercise
    /// precisely that vkCreateComputePipelines call without replaying a title.
    pub fn probeComputeSpirv(self: *Renderer, words: []const u32) Error!void {
        const shader = try self.createShader(words);
        defer self.destroyShaderModule(shader);

        const stage = vk.PipelineShaderStageCreateInfo{
            .stage = vk.shader_stage_compute_bit,
            .module = shader,
            .name = "main",
        };
        const pipeline_info = vk.ComputePipelineCreateInfo{
            .stage = stage,
            .layout = self.compute_pipeline_layout,
        };
        var pipeline: vk.Pipeline = 0;
        if (self.device_functions.create_compute_pipelines(
            self.device,
            0,
            1,
            @ptrCast(&pipeline_info),
            null,
            @ptrCast(&pipeline),
        ) != vk.success) return Error.ComputePipelineCreationFailed;
        self.destroyPipeline(pipeline);
    }

    pub fn smokeTest(self: *Renderer) Error!SmokeReport {
        const word_count = 16;
        const byte_count = word_count * @sizeOf(u32);
        var expected: [word_count]u32 = undefined;
        for (&expected, 0..) |*word, index| word.* = 0x51a9_c000 | @as(u32, @intCast(index));

        const source = try self.createBuffer(
            byte_count,
            vk.buffer_usage_transfer_src_bit,
            vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
        );
        defer self.destroyBuffer(source);
        const target = try self.createBuffer(
            byte_count,
            vk.buffer_usage_transfer_src_bit | vk.buffer_usage_transfer_dst_bit | vk.buffer_usage_storage_buffer_bit,
            0x0000_0001,
        );
        defer self.destroyBuffer(target);
        const readback = try self.createBuffer(
            byte_count,
            vk.buffer_usage_transfer_dst_bit,
            vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
        );
        defer self.destroyBuffer(readback);

        try self.writeMapped(source, std.mem.sliceAsBytes(&expected));

        const shader = try self.createSmokeShader();
        defer self.destroyShaderModule(shader);

        const stage = vk.PipelineShaderStageCreateInfo{
            .stage = vk.shader_stage_compute_bit,
            .module = shader,
            .name = "main",
        };
        const pipeline_info = vk.ComputePipelineCreateInfo{ .stage = stage, .layout = self.compute_pipeline_layout };
        var pipeline: vk.Pipeline = 0;
        if (self.device_functions.create_compute_pipelines(self.device, self.driver_pipeline_cache, 1, @ptrCast(&pipeline_info), null, @ptrCast(&pipeline)) != vk.success) {
            return Error.ComputePipelineCreationFailed;
        }
        defer self.destroyPipeline(pipeline);

        const allocate_info = vk.CommandBufferAllocateInfo{
            .command_pool = self.command_pool,
            .level = vk.command_buffer_level_primary,
            .command_buffer_count = 1,
        };
        var command_buffer: vk.CommandBuffer = undefined;
        if (self.device_functions.allocate_command_buffers(self.device, &allocate_info, @ptrCast(&command_buffer)) != vk.success) {
            return Error.CommandBufferAllocationFailed;
        }
        defer self.releaseOneShot(command_buffer);

        const begin_info = vk.CommandBufferBeginInfo{ .flags = vk.command_buffer_usage_one_time_submit_bit };
        if (self.device_functions.begin_command_buffer(command_buffer, &begin_info) != vk.success) {
            return Error.CommandBufferBeginFailed;
        }
        self.device_functions.cmd_bind_pipeline(command_buffer, vk.pipeline_bind_point_compute, pipeline);
        self.device_functions.cmd_dispatch(command_buffer, 1, 1, 1);

        const source_barrier = vk.BufferMemoryBarrier{
            .source_access_mask = vk.access_host_write_bit,
            .destination_access_mask = vk.access_transfer_read_bit,
            .buffer = source.handle,
            .offset = 0,
            .size = source.size,
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_host_bit,
            vk.pipeline_stage_transfer_bit,
            0,
            0,
            null,
            1,
            @ptrCast(&source_barrier),
            0,
            null,
        );
        const copy = vk.BufferCopy{ .source_offset = 0, .destination_offset = 0, .size = byte_count };
        self.device_functions.cmd_copy_buffer(command_buffer, source.handle, target.handle, 1, @ptrCast(&copy));

        const target_barrier = vk.BufferMemoryBarrier{
            .source_access_mask = vk.access_transfer_write_bit,
            .destination_access_mask = vk.access_transfer_read_bit,
            .buffer = target.handle,
            .offset = 0,
            .size = target.size,
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_transfer_bit,
            vk.pipeline_stage_transfer_bit,
            0,
            0,
            null,
            1,
            @ptrCast(&target_barrier),
            0,
            null,
        );
        self.device_functions.cmd_copy_buffer(command_buffer, target.handle, readback.handle, 1, @ptrCast(&copy));

        const readback_barrier = vk.BufferMemoryBarrier{
            .source_access_mask = vk.access_transfer_write_bit,
            .destination_access_mask = vk.access_host_read_bit,
            .buffer = readback.handle,
            .offset = 0,
            .size = readback.size,
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_transfer_bit,
            vk.pipeline_stage_host_bit,
            0,
            0,
            null,
            1,
            @ptrCast(&readback_barrier),
            0,
            null,
        );
        if (self.device_functions.end_command_buffer(command_buffer) != vk.success) return Error.CommandBufferEndFailed;

        const fence_info = vk.FenceCreateInfo{};
        var fence: vk.Fence = 0;
        if (self.device_functions.create_fence(self.device, &fence_info, null, &fence) != vk.success) {
            return Error.FenceCreationFailed;
        }
        defer self.device_functions.destroy_fence(self.device, fence, null);
        const submit_info = vk.SubmitInfo{
            .command_buffer_count = 1,
            .command_buffers = @ptrCast(&command_buffer),
        };
        if (self.device_functions.queue_submit(self.queue, 1, @ptrCast(&submit_info), fence) != vk.success) {
            return Error.QueueSubmissionFailed;
        }
        if (self.device_functions.wait_for_fences(self.device, 1, @ptrCast(&fence), vk.true_value, ~@as(u64, 0)) != vk.success) {
            return Error.FenceWaitFailed;
        }
        try self.expectMapped(readback, std.mem.sliceAsBytes(&expected));

        return .{
            .bytes_copied = byte_count,
            .compute_dispatches = 1,
            .queue_family_index = self.queue_family_index,
        };
    }

    fn createGraphicsRenderPass(
        self: *Renderer,
        format: u32,
        preserve_color: bool,
        samples: u32,
    ) Error!vk.RenderPass {
        return self.createColorRenderPass(&.{format}, 0, preserve_color, samples);
    }

    /// Colour attachments occupy hardware slots 0..N-1. A zero format is a
    /// hole: the subpass names `ATTACHMENT_UNUSED` so Location *i* still
    /// matches CB *i* without a dummy image.
    fn createColorRenderPass(
        self: *Renderer,
        color_formats: []const u32,
        depth_format: u32,
        preserve_color: bool,
        samples: u32,
    ) Error!vk.RenderPass {
        if (color_formats.len == 0 or color_formats.len > gpu.resources.color_target_count) {
            return Error.UnsupportedGraphicsState;
        }
        var attachments: [gpu.resources.color_target_count + 1]vk.AttachmentDescription = undefined;
        var color_refs: [gpu.resources.color_target_count]vk.AttachmentReference = undefined;
        var attachment_count: u32 = 0;
        for (color_formats, 0..) |format, slot| {
            if (format == 0) {
                color_refs[slot] = .{
                    .attachment = vk.attachment_unused,
                    .layout = vk.image_layout_color_attachment_optimal,
                };
                continue;
            }
            attachments[attachment_count] = .{
                .format = format,
                .samples = samples,
                .load_operation = if (preserve_color) vk.attachment_load_op_load else vk.attachment_load_op_clear,
                .store_operation = vk.attachment_store_op_store,
                .initial_layout = if (preserve_color)
                    vk.image_layout_color_attachment_optimal
                else
                    vk.image_layout_undefined,
                .final_layout = vk.image_layout_color_attachment_optimal,
            };
            color_refs[slot] = .{
                .attachment = attachment_count,
                .layout = vk.image_layout_color_attachment_optimal,
            };
            attachment_count += 1;
        }
        var depth_ref: vk.AttachmentReference = undefined;
        if (depth_format != 0) {
            const has_stencil = depthAttachmentHasStencil(depth_format);
            attachments[attachment_count] = .{
                .format = depth_format,
                .samples = samples,
                .load_operation = vk.attachment_load_op_load,
                .store_operation = vk.attachment_store_op_store,
                .stencil_load_operation = if (has_stencil)
                    vk.attachment_load_op_load
                else
                    vk.attachment_load_op_dont_care,
                .stencil_store_operation = if (has_stencil)
                    vk.attachment_store_op_store
                else
                    vk.attachment_store_op_dont_care,
                .initial_layout = vk.image_layout_depth_stencil_attachment_optimal,
                .final_layout = vk.image_layout_depth_stencil_attachment_optimal,
            };
            depth_ref = .{
                .attachment = attachment_count,
                .layout = vk.image_layout_depth_stencil_attachment_optimal,
            };
            attachment_count += 1;
        }
        if (attachment_count == 0) return Error.UnsupportedGraphicsState;
        const subpass = vk.SubpassDescription{
            .color_attachment_count = @intCast(color_formats.len),
            .color_attachments = &color_refs,
            .depth_stencil_attachment = if (depth_format != 0) &depth_ref else null,
        };
        const info = vk.RenderPassCreateInfo{
            .attachment_count = attachment_count,
            .attachments = &attachments,
            .subpass_count = 1,
            .subpasses = @ptrCast(&subpass),
        };
        var render_pass: vk.RenderPass = 0;
        if (self.device_functions.create_render_pass(self.device, &info, null, &render_pass) != vk.success) {
            return Error.RenderPassCreationFailed;
        }
        return render_pass;
    }

    /// Brings a depth attachment into the layout its render pass expects, and
    /// applies the guest's depth clear when one is pending.
    ///
    /// A freshly created image has undefined contents, so the first use always
    /// clears: a title that enables the depth test before its own clear would
    /// otherwise compare against whatever the allocator left behind. Later
    /// clears happen only when DB_RENDER_CONTROL asks for one.
    fn prepareDepthAttachment(
        self: *Renderer,
        command_buffer: vk.CommandBuffer,
        depth_index: usize,
        clear_requested: bool,
    ) Error!void {
        const cached = &self.depth_targets.items[depth_index];
        const first_use = !cached.initialized;
        const clearing = clear_requested or first_use;
        const range = vk.ImageSubresourceRange{ .aspect_mask = cached.target.aspectMask() };
        try self.transitionTrackedImage(
            command_buffer,
            cached.image.handle,
            range,
            if (clearing) image_state.transfer_destination_usage else image_state.depth_attachment_usage,
        );
        cached.initialized = true;
        cached.shader_read_layout = false;
        if (!clearing) return;

        const clear = vk.ClearDepthStencilValue{
            .depth = std.math.clamp(cached.target.clear_depth, 0, 1),
            .stencil = cached.target.clear_stencil,
        };
        self.device_functions.cmd_clear_depth_stencil_image(
            command_buffer,
            cached.image.handle,
            vk.image_layout_transfer_dst_optimal,
            &clear,
            1,
            @ptrCast(&range),
        );
        try self.transitionTrackedImage(
            command_buffer,
            cached.image.handle,
            range,
            image_state.depth_attachment_usage,
        );
    }

    /// A render pass that keeps both attachments across draws.
    ///
    /// Depth loads rather than clears for the same reason colour does: a title
    /// builds a frame from many draws against one allocation, and a clear baked
    /// into the pass would erase what the previous draw established. The guest's
    /// own depth clear is issued separately, against the image.
    fn createDepthGraphicsRenderPass(
        self: *Renderer,
        color_format: u32,
        depth_format: u32,
        preserve_color: bool,
        samples: u32,
    ) Error!vk.RenderPass {
        return self.createColorRenderPass(&.{color_format}, depth_format, preserve_color, samples);
    }

    /// The colour target's framebuffer paired with one depth attachment,
    /// rebuilt only when the pairing changes.
    fn acquireDepthPass(
        self: *Renderer,
        target_index: usize,
        depth_index: usize,
    ) anyerror!DepthPass {
        const color = self.render_targets.items[target_index];
        const depth = self.depth_targets.items[depth_index];
        if (color.depth_pass) |existing| {
            if (existing.depth_view == depth.view and existing.depth_format == depth.target.format) {
                return existing;
            }
            self.destroyDepthPass(existing);
            self.render_targets.items[target_index].depth_pass = null;
        }

        const color_format = colorTargetFormat(color.target.descriptor) orelse
            return Error.UnsupportedColorTarget;
        const samples = rasterSampleCount(color.target.descriptor.fragments_log2) orelse
            return Error.UnsupportedColorTarget;
        const render_pass = try self.createDepthGraphicsRenderPass(
            color_format.vulkan,
            depth.target.format,
            true,
            samples,
        );
        errdefer self.destroyRenderPass(render_pass);

        const views = [2]vk.ImageView{ color.view, depth.view };
        const framebuffer_info = vk.FramebufferCreateInfo{
            .render_pass = render_pass,
            .attachment_count = views.len,
            .attachments = &views,
            .width = color.target.descriptor.width,
            .height = color.target.descriptor.height,
        };
        var framebuffer: vk.Framebuffer = 0;
        if (self.device_functions.create_framebuffer(self.device, &framebuffer_info, null, &framebuffer) != vk.success) {
            return Error.FramebufferCreationFailed;
        }
        const pass = DepthPass{
            .depth_view = depth.view,
            .depth_format = depth.target.format,
            .render_pass = render_pass,
            .framebuffer = framebuffer,
        };
        self.render_targets.items[target_index].depth_pass = pass;
        return pass;
    }

    fn colorPassMatches(
        pass: ColorPass,
        color_views: [gpu.resources.color_target_count]vk.ImageView,
        color_count: u8,
        depth_view: vk.ImageView,
        depth_format: u32,
    ) bool {
        if (pass.color_count != color_count or
            pass.depth_view != depth_view or
            pass.depth_format != depth_format)
        {
            return false;
        }
        return std.mem.eql(vk.ImageView, &pass.color_views, &color_views);
    }

    fn destroyColorPass(self: *Renderer, pass: ColorPass) void {
        self.destroyFramebuffer(pass.framebuffer);
        self.destroyRenderPass(pass.render_pass);
    }

    fn evictColorPass(self: *Renderer) void {
        if (self.color_passes.items.len == 0) return;
        var oldest_index: usize = 0;
        var oldest_sequence = self.color_passes.items[0].last_used_sequence;
        for (self.color_passes.items[1..], 1..) |entry, index| {
            if (entry.last_used_sequence >= oldest_sequence) continue;
            oldest_index = index;
            oldest_sequence = entry.last_used_sequence;
        }
        self.destroyColorPass(self.color_passes.items[oldest_index]);
        _ = self.color_passes.swapRemove(oldest_index);
    }

    fn invalidateColorPasses(self: *Renderer, view: vk.ImageView) void {
        var index: usize = 0;
        while (index < self.color_passes.items.len) {
            const pass = self.color_passes.items[index];
            var referenced = pass.depth_view == view;
            if (!referenced) {
                for (pass.color_views) |color_view| {
                    if (color_view == view) {
                        referenced = true;
                        break;
                    }
                }
            }
            if (!referenced) {
                index += 1;
                continue;
            }
            self.destroyColorPass(pass);
            _ = self.color_passes.swapRemove(index);
        }
    }

    fn acquireColorPass(
        self: *Renderer,
        color_views: [gpu.resources.color_target_count]vk.ImageView,
        color_formats: [gpu.resources.color_target_count]u32,
        color_count: u8,
        depth_view: vk.ImageView,
        depth_format: u32,
        samples: u32,
        width: u32,
        height: u32,
    ) anyerror!ColorPass {
        self.color_pass_sequence +%= 1;
        for (self.color_passes.items) |*existing| {
            if (!colorPassMatches(existing.*, color_views, color_count, depth_view, depth_format)) continue;
            existing.last_used_sequence = self.color_pass_sequence;
            return existing.*;
        }

        const render_pass = try self.createColorRenderPass(
            color_formats[0..color_count],
            depth_format,
            true,
            samples,
        );
        errdefer self.destroyRenderPass(render_pass);

        var views: [gpu.resources.color_target_count + 1]vk.ImageView = undefined;
        var view_count: u32 = 0;
        for (color_formats[0..color_count], color_views[0..color_count]) |format, view| {
            if (format == 0) continue;
            views[view_count] = view;
            view_count += 1;
        }
        if (depth_view != 0) {
            views[view_count] = depth_view;
            view_count += 1;
        }
        if (view_count == 0) return Error.UnsupportedGraphicsState;
        const framebuffer_info = vk.FramebufferCreateInfo{
            .render_pass = render_pass,
            .attachment_count = view_count,
            .attachments = &views,
            .width = width,
            .height = height,
        };
        var framebuffer: vk.Framebuffer = 0;
        if (self.device_functions.create_framebuffer(self.device, &framebuffer_info, null, &framebuffer) != vk.success) {
            return Error.FramebufferCreationFailed;
        }
        const pass = ColorPass{
            .color_views = color_views,
            .color_count = color_count,
            .depth_view = depth_view,
            .depth_format = depth_format,
            .render_pass = render_pass,
            .framebuffer = framebuffer,
            .last_used_sequence = self.color_pass_sequence,
        };
        if (self.color_passes.items.len >= maximum_color_passes) self.evictColorPass();
        try self.color_passes.append(self.allocator, pass);
        return pass;
    }

    fn applyColorAttachmentState(
        result: *GraphicsPipelineState,
        render: *const gpu.RenderState,
        colors: []const GuestColorTarget,
    ) Error!void {
        result.color_attachment_count = 1;
        result.color_attachment_formats = @splat(0);
        result.color_write_masks = @splat(0);
        result.blend_enables = @splat(0);
        result.source_color_blend_factors = @splat(0);
        result.destination_color_blend_factors = @splat(0);
        result.color_blend_operations = @splat(0);
        result.source_alpha_blend_factors = @splat(0);
        result.destination_alpha_blend_factors = @splat(0);
        result.alpha_blend_operations = @splat(0);

        var highest: u32 = 0;
        for (colors) |color| {
            const slot = color.descriptor.slot;
            if (slot >= gpu.resources.color_target_count) continue;
            highest = @max(highest, slot);
            result.color_attachment_formats[slot] = color.format.vulkan;
            result.color_write_masks[slot] = mapColorWriteMask(
                color.descriptor.write_mask,
                colorTargetExportMapping(color.descriptor),
            );
            const blend = render.blends[slot];
            // Integer attachments reject colour blending; Yotei's ID plane is
            // R32_UINT and the G-buffer pass that fills it has blend off already.
            const integer_color = color.format.vulkan == vk.format_r32_uint or
                color.format.vulkan == vk.format_r32_sint or
                color.format.vulkan == vk.format_r16_uint or
                color.format.vulkan == vk.format_r8g8_uint;
            result.blend_enables[slot] = @intFromBool(blend.enabled and !integer_color);
            if (!blend.enabled) continue;
            result.source_color_blend_factors[slot] = try vulkanBlendFactor(blend.color_source);
            result.destination_color_blend_factors[slot] = try vulkanBlendFactor(blend.color_destination);
            result.color_blend_operations[slot] = try vulkanBlendOperation(blend.color_operation);
            result.source_alpha_blend_factors[slot] = if (blend.separate_alpha)
                try vulkanBlendFactor(blend.alpha_source)
            else
                result.source_color_blend_factors[slot];
            result.destination_alpha_blend_factors[slot] = if (blend.separate_alpha)
                try vulkanBlendFactor(blend.alpha_destination)
            else
                result.destination_color_blend_factors[slot];
            result.alpha_blend_operations[slot] = if (blend.separate_alpha)
                try vulkanBlendOperation(blend.alpha_operation)
            else
                result.color_blend_operations[slot];
        }
        result.color_attachment_count = highest + 1;
    }

    fn guestGraphicsState(render: *const gpu.RenderState, target: gpu.resources.ColorTarget) Error!GraphicsPipelineState {
        var result = GraphicsPipelineState.default(target.width, target.height);
        if (render.viewport) |viewport| {
            const x = viewport.x_offset - viewport.x_scale;
            const y = viewport.y_offset - viewport.y_scale;
            const width = viewport.x_scale * 2.0;
            const height = viewport.y_scale * 2.0;
            const min_depth = viewport.z_offset;
            const max_depth = viewport.z_offset + viewport.z_scale;
            if (!std.math.isFinite(x) or !std.math.isFinite(y) or
                !std.math.isFinite(width) or !std.math.isFinite(height) or
                !std.math.isFinite(min_depth) or !std.math.isFinite(max_depth) or
                width == 0 or height == 0)
            {
                return Error.UnsupportedGraphicsState;
            }
            result.viewport_x_bits = @bitCast(x);
            result.viewport_y_bits = @bitCast(y);
            result.viewport_width_bits = @bitCast(width);
            result.viewport_height_bits = @bitCast(height);
            result.viewport_min_depth_bits = @bitCast(std.math.clamp(min_depth, 0, 1));
            result.viewport_max_depth_bits = @bitCast(std.math.clamp(max_depth, 0, 1));
        }
        if (render.scissor) |scissor| {
            const left: u32 = @min(scissor.left, target.width);
            const top: u32 = @min(scissor.top, target.height);
            const right: u32 = @min(@max(scissor.right, left), target.width);
            const bottom: u32 = @min(@max(scissor.bottom, top), target.height);
            result.scissor_x = @intCast(left);
            result.scissor_y = @intCast(top);
            result.scissor_width = right - left;
            result.scissor_height = bottom - top;
        }
        if (render.raster.polygon_mode != 0 or
            render.raster.depth_bias_front or render.raster.depth_bias_back)
        {
            return Error.UnsupportedGraphicsState;
        }
        // Ignore guest culling on the first host path: attribute fetch and
        // winding often disagree until NGG export is fully correct, and a
        // full cull makes every black writeback look identical.
        result.cull_mode = 0;
        result.front_face = if (render.raster.clockwise_front_face) 0 else 1;
        result.rasterizer_discard = @intFromBool(render.raster.rasterizer_discard);
        return result;
    }

    fn vulkanBlendFactor(factor: u5) Error!u32 {
        return switch (factor) {
            0...3 => factor,
            4 => 6,
            5 => 7,
            6 => 8,
            7 => 9,
            8 => 4,
            9 => 5,
            10 => 14,
            13 => 10,
            14 => 11,
            15 => 15,
            16 => 16,
            17 => 17,
            18 => 18,
            19 => 12,
            20 => 13,
            else => Error.UnsupportedGraphicsState,
        };
    }

    fn vulkanBlendOperation(operation: u3) Error!u32 {
        return switch (operation) {
            0, 1 => operation,
            2 => 3,
            3 => 4,
            4 => 2,
            else => Error.UnsupportedGraphicsState,
        };
    }

    fn createGraphicsPipeline(
        self: *Renderer,
        render_pass: vk.RenderPass,
        pipeline_state: GraphicsPipelineState,
        vertex_words: []const u32,
        fragment_words: []const u32,
    ) Error!vk.Pipeline {
        const vertex = try self.createShader(vertex_words);
        defer self.device_functions.destroy_shader_module(self.device, vertex, null);
        const fragment = try self.createShader(fragment_words);
        defer self.device_functions.destroy_shader_module(self.device, fragment, null);
        var geometry: vk.ShaderModule = 0;
        defer if (geometry != 0) self.device_functions.destroy_shader_module(self.device, geometry, null);
        if (pipeline_state.rectangle_completion != 0) {
            const geometry_words = buildRectangleListGeometrySpirv(
                self.allocator,
                pipeline_state.rectangle_parameter_mask,
                pipeline_state.rectangle_completion,
            ) catch return Error.ShaderModuleCreationFailed;
            defer self.allocator.free(geometry_words);
            if (self.dump_graphics_spirv) dumpGraphicsSpirv(self.allocator, "gs", pipeline_state.rectangle_parameter_mask, geometry_words);
            geometry = try self.createShader(geometry_words);
        }
        var stage_storage = [_]vk.PipelineShaderStageCreateInfo{
            .{ .stage = vk.shader_stage_vertex_bit, .module = vertex, .name = "main" },
            .{ .stage = vk.shader_stage_geometry_bit, .module = geometry, .name = "main" },
            .{ .stage = vk.shader_stage_fragment_bit, .module = fragment, .name = "main" },
        };
        if (geometry == 0) stage_storage[1] = stage_storage[2];
        const stages = stage_storage[0..if (geometry == 0) 2 else 3];
        const vertex_input = vk.PipelineVertexInputStateCreateInfo{};
        const input_assembly = vk.PipelineInputAssemblyStateCreateInfo{
            .topology = pipeline_state.topology,
        };
        const viewport = vk.Viewport{
            .x = @bitCast(pipeline_state.viewport_x_bits),
            .y = @bitCast(pipeline_state.viewport_y_bits),
            .width = @bitCast(pipeline_state.viewport_width_bits),
            .height = @bitCast(pipeline_state.viewport_height_bits),
            .min_depth = @bitCast(pipeline_state.viewport_min_depth_bits),
            .max_depth = @bitCast(pipeline_state.viewport_max_depth_bits),
        };
        const scissor = vk.Rect2D{
            .offset = .{ .x = pipeline_state.scissor_x, .y = pipeline_state.scissor_y },
            .extent = .{ .width = pipeline_state.scissor_width, .height = pipeline_state.scissor_height },
        };
        const viewport_state = vk.PipelineViewportStateCreateInfo{
            .viewport_count = 1,
            .viewports = @ptrCast(&viewport),
            .scissor_count = 1,
            .scissors = @ptrCast(&scissor),
        };
        const rasterization = vk.PipelineRasterizationStateCreateInfo{
            .rasterizer_discard_enable = pipeline_state.rasterizer_discard,
            .cull_mode = pipeline_state.cull_mode,
            .front_face = pipeline_state.front_face,
        };
        const multisample = vk.PipelineMultisampleStateCreateInfo{
            .rasterization_samples = pipeline_state.rasterization_samples,
        };
        var blend_attachments: [gpu.resources.color_target_count]vk.PipelineColorBlendAttachmentState = undefined;
        const blend_count = @min(pipeline_state.color_attachment_count, gpu.resources.color_target_count);
        if (blend_count == 0) return Error.UnsupportedGraphicsState;
        for (0..blend_count) |slot| {
            blend_attachments[slot] = .{
                .blend_enable = pipeline_state.blend_enables[slot],
                .source_color_blend_factor = pipeline_state.source_color_blend_factors[slot],
                .destination_color_blend_factor = pipeline_state.destination_color_blend_factors[slot],
                .color_blend_operation = pipeline_state.color_blend_operations[slot],
                .source_alpha_blend_factor = pipeline_state.source_alpha_blend_factors[slot],
                .destination_alpha_blend_factor = pipeline_state.destination_alpha_blend_factors[slot],
                .alpha_blend_operation = pipeline_state.alpha_blend_operations[slot],
                .color_write_mask = pipeline_state.color_write_masks[slot],
            };
        }
        const color_blend = vk.PipelineColorBlendStateCreateInfo{
            .attachment_count = @intCast(blend_count),
            .attachments = &blend_attachments,
        };
        const depth_stencil = vk.PipelineDepthStencilStateCreateInfo{
            .depth_test_enable = pipeline_state.depth_test_enable,
            .depth_write_enable = pipeline_state.depth_write_enable,
            .depth_compare_operation = pipeline_state.depth_compare_operation,
            .stencil_test_enable = pipeline_state.stencil_test_enable,
            .front = .{
                .fail_operation = pipeline_state.stencil_front_fail,
                .pass_operation = pipeline_state.stencil_front_pass,
                .depth_fail_operation = pipeline_state.stencil_front_depth_fail,
                .compare_operation = pipeline_state.stencil_front_compare,
                .compare_mask = pipeline_state.stencil_front_compare_mask,
                .write_mask = pipeline_state.stencil_front_write_mask,
                .reference = pipeline_state.stencil_front_reference,
            },
            .back = .{
                .fail_operation = pipeline_state.stencil_back_fail,
                .pass_operation = pipeline_state.stencil_back_pass,
                .depth_fail_operation = pipeline_state.stencil_back_depth_fail,
                .compare_operation = pipeline_state.stencil_back_compare,
                .compare_mask = pipeline_state.stencil_back_compare_mask,
                .write_mask = pipeline_state.stencil_back_write_mask,
                .reference = pipeline_state.stencil_back_reference,
            },
        };
        const info = vk.GraphicsPipelineCreateInfo{
            .stage_count = @intCast(stages.len),
            .stages = stages.ptr,
            .vertex_input_state = &vertex_input,
            .input_assembly_state = &input_assembly,
            .viewport_state = &viewport_state,
            .rasterization_state = &rasterization,
            .multisample_state = &multisample,
            .depth_stencil_state = if (pipeline_state.depth_attachment_format != 0) &depth_stencil else null,
            .color_blend_state = &color_blend,
            .layout = self.compute_pipeline_layout,
            .render_pass = render_pass,
        };
        var pipeline: vk.Pipeline = 0;
        if (self.device_functions.create_graphics_pipelines(
            self.device,
            self.driver_pipeline_cache,
            1,
            @ptrCast(&info),
            null,
            @ptrCast(&pipeline),
        ) != vk.success) {
            return Error.GraphicsPipelineCreationFailed;
        }
        return pipeline;
    }

    /// The decoded form of one guest shader program, reused across draws.
    ///
    /// Decoding walks the instruction stream a word at a time out of guest
    /// memory and then lowers it to IR. That result depends on the program's
    /// own bytes and nothing else, so repeating it for every draw of the same
    /// shader is pure cost. A candidate is confirmed by comparing the words it
    /// was decoded from against guest memory, which is a bulk read and a
    /// compare rather than a decode; a program rebuilt at the same address is
    /// therefore picked up instead of being served stale.
    ///
    /// The returned pointer stays valid for the caller's draw: capacity is
    /// reserved up front so entries never move, and the entry just returned
    /// carries the newest sequence, so a later miss in the same draw cannot
    /// choose it as the least-recently-used victim.
    fn analyzedProgram(
        self: *Renderer,
        reader: gpu.ShaderMemoryReader,
        address: u64,
        header_address: ?u64,
    ) anyerror!*const gpu.ShaderAnalysis {
        self.analyzed_program_sequence +%= 1;
        var stale_index: ?usize = null;
        for (self.analyzed_programs.items, 0..) |*entry, index| {
            if (entry.address != address) continue;
            const validation_started = hostTimestampNs();
            const matches = programWordsMatch(reader, address, entry.analysis.code.items);
            self.frame_profile.shader_validation_ns +|= elapsedHostNanoseconds(validation_started);
            if (matches) {
                entry.last_used_sequence = self.analyzed_program_sequence;
                self.frame_profile.shader_analysis_hits += 1;
                return &entry.analysis;
            }
            stale_index = index;
            break;
        }

        const started = hostTimestampNs();
        const byte_limit = shaderProgramByteLimit(reader, header_address, address);
        var analysis = if (byte_limit) |shader_bytes|
            try gpu.shader_analysis.decodeBoundedWithOptions(
                self.allocator,
                reader,
                address,
                @min(maximum_shader_instructions, shader_bytes / @sizeOf(u32)),
                shader_bytes,
                .{
                    .enable_typed_ir = self.shader_ir_enabled,
                    .enable_ssa_optimization = self.shader_ssa_optimization_enabled,
                },
            )
        else
            try gpu.shader_analysis.decodeWithOptions(
                self.allocator,
                reader,
                address,
                headerless_shader_instruction_limit,
                .{
                    .enable_typed_ir = self.shader_ir_enabled,
                    .enable_ssa_optimization = self.shader_ssa_optimization_enabled,
                },
            );
        errdefer analysis.deinit(self.allocator);
        self.frame_profile.shader_analysis_ns +|= elapsedHostNanoseconds(started);
        self.frame_profile.shader_analysis_misses += 1;
        const replacement = AnalyzedProgram{
            .address = address,
            .analysis = analysis,
            .last_used_sequence = self.analyzed_program_sequence,
        };

        const slot = stale_index orelse blk: {
            if (self.analyzed_programs.items.len < maximum_analyzed_programs) {
                try self.analyzed_programs.ensureTotalCapacity(self.allocator, maximum_analyzed_programs);
                self.analyzed_programs.appendAssumeCapacity(replacement);
                return &self.analyzed_programs.items[self.analyzed_programs.items.len - 1].analysis;
            }
            var oldest_index: usize = 0;
            var oldest_sequence = self.analyzed_programs.items[0].last_used_sequence;
            for (self.analyzed_programs.items[1..], 1..) |entry, index| {
                if (entry.last_used_sequence >= oldest_sequence) continue;
                oldest_index = index;
                oldest_sequence = entry.last_used_sequence;
            }
            break :blk oldest_index;
        };
        const victim = &self.analyzed_programs.items[slot];
        victim.analysis.deinit(self.allocator);
        victim.* = replacement;
        return &victim.analysis;
    }

    /// The content probe of one sampled source, taken at most once per frame
    /// per source. See `TextureProbe`.
    fn probeSampledSource(
        self: *Renderer,
        memory: GuestMemory,
        address: u64,
        span: usize,
        source_generation: u64,
        full_content: bool,
    ) u64 {
        for (self.texture_probes[0..self.texture_probe_count]) |probe| {
            if (!probe.valid or probe.address != address or probe.span != span or
                probe.full_content != full_content) continue;
            if (!probe.hash_valid or probe.source_generation != source_generation) break;
            return probe.hash;
        }
        const started = hostTimestampNs();
        const hash = hashGuestMemoryRange(memory, address, span, full_content);
        self.frame_profile.texture_probe_ns +|= elapsedHostNanoseconds(started);

        const entry = TextureProbe{
            .address = address,
            .span = span,
            .full_content = full_content,
            .source_generation = source_generation,
            .hash = hash,
            .hash_valid = true,
            .valid = true,
        };
        for (self.texture_probes[0..self.texture_probe_count]) |*probe| {
            if (probe.address != address or probe.span != span or
                probe.full_content != full_content) continue;
            probe.* = entry;
            return hash;
        }
        if (self.texture_probe_count < self.texture_probes.len) {
            self.texture_probes[self.texture_probe_count] = entry;
            self.texture_probe_count += 1;
        }
        return hash;
    }

    /// Page tracking walks every guest page in a sampled allocation. A frame
    /// may bind the same 32 MiB texture hundreds of times, while guest writes
    /// are serialized through dcbWrite and reset this table. Query each range
    /// once per frame instead of repeating the full walk for every draw.
    fn sampledPageGeneration(self: *Renderer, memory: GuestMemory, address: u64, span: usize) u64 {
        for (self.texture_probes[0..self.texture_probe_count]) |probe| {
            if (probe.valid and probe.address == address and probe.span == span) {
                return probe.page_generation;
            }
        }
        const generation = if (memory.track_gpu_read) |track|
            track(memory.context, address, span)
        else
            0;
        const entry = TextureProbe{
            .address = address,
            .span = span,
            .page_generation = generation,
            .valid = true,
        };
        if (self.texture_probe_count < self.texture_probes.len) {
            self.texture_probes[self.texture_probe_count] = entry;
            self.texture_probe_count += 1;
        }
        return generation;
    }

    fn invalidateTextureProbes(self: *Renderer, address: u64, span: usize) void {
        var index: usize = 0;
        while (index < self.texture_probe_count) {
            const probe = self.texture_probes[index];
            if (!probe.valid or !byteRangesOverlap(address, span, probe.address, probe.span)) {
                index += 1;
                continue;
            }
            self.texture_probe_count -= 1;
            self.texture_probes[index] = self.texture_probes[self.texture_probe_count];
            self.texture_probes[self.texture_probe_count] = .{};
        }
    }

    fn getGraphicsPipeline(
        self: *Renderer,
        render_pass: vk.RenderPass,
        pipeline_state: GraphicsPipelineState,
        vertex_words: []const u32,
        fragment_words: []const u32,
    ) (Error || std.mem.Allocator.Error)!vk.Pipeline {
        self.graphics_pipeline_sequence +%= 1;
        const state_hash = std.hash.Wyhash.hash(0, std.mem.asBytes(&pipeline_state));
        const vertex_hash_only = std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(vertex_words));
        const fragment_hash_only = std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(fragment_words));
        const vertex_hash = std.hash.Wyhash.hash(state_hash, std.mem.sliceAsBytes(vertex_words));
        const hash = std.hash.Wyhash.hash(vertex_hash, std.mem.sliceAsBytes(fragment_words));
        var state_match = false;
        var vertex_match = false;
        var fragment_match = false;
        for (self.graphics_pipelines.items) |*entry| {
            state_match = state_match or entry.state_hash == state_hash;
            vertex_match = vertex_match or entry.vertex_hash == vertex_hash_only;
            fragment_match = fragment_match or entry.fragment_hash == fragment_hash_only;
            if (entry.hash == hash and
                std.mem.eql(u8, std.mem.asBytes(&entry.state), std.mem.asBytes(&pipeline_state)) and
                std.mem.eql(u32, entry.vertex_words, vertex_words) and
                std.mem.eql(u32, entry.fragment_words, fragment_words))
            {
                self.graphics_pipeline_cache_hits += 1;
                self.frame_profile.graphics_pipeline_hits += 1;
                entry.last_used_sequence = self.graphics_pipeline_sequence;
                return entry.pipeline;
            }
        }
        const build_started = hostTimestampNs();
        var work = GraphicsPipelineCompileJob{
            .renderer = self,
            .render_pass = render_pass,
            .state = pipeline_state,
            .vertex_words = vertex_words,
            .fragment_words = fragment_words,
        };
        const asynchronous = self.async_pipeline_compilation_enabled and pipeline_state.rectangle_completion == 0;
        if (asynchronous) self.pipeline_compile_queue.submit(&work.job);
        const owned_vertex = self.allocator.dupe(u32, vertex_words) catch |err| {
            if (asynchronous) {
                work.job.wait();
                if (work.pipeline != 0) self.device_functions.destroy_pipeline(self.device, work.pipeline, null);
            }
            return err;
        };
        errdefer self.allocator.free(owned_vertex);
        const owned_fragment = self.allocator.dupe(u32, fragment_words) catch |err| {
            if (asynchronous) {
                work.job.wait();
                if (work.pipeline != 0) self.device_functions.destroy_pipeline(self.device, work.pipeline, null);
            }
            return err;
        };
        errdefer self.allocator.free(owned_fragment);
        const pipeline = if (asynchronous) blk: {
            work.job.wait();
            if (work.failure) |failure| return failure;
            break :blk work.pipeline;
        } else try self.createGraphicsPipeline(render_pass, pipeline_state, vertex_words, fragment_words);
        self.frame_profile.graphics_pipeline_build_ns +|= elapsedHostNanoseconds(build_started);
        errdefer self.destroyPipeline(pipeline);
        const replacement = GraphicsPipelineEntry{
            .hash = hash,
            .state_hash = state_hash,
            .vertex_hash = vertex_hash_only,
            .fragment_hash = fragment_hash_only,
            .state = pipeline_state,
            .vertex_words = owned_vertex,
            .fragment_words = owned_fragment,
            .pipeline = pipeline,
            .last_used_sequence = self.graphics_pipeline_sequence,
        };
        if (self.graphics_pipelines.items.len < maximum_graphics_pipelines) {
            try self.graphics_pipelines.append(self.allocator, replacement);
        } else {
            // A least-recently-used pipeline may still be named by this
            // frame's recorded commands. destroyPipeline therefore retires it
            // only after the batch fence while the cache slot is reused now.
            var oldest_index: usize = 0;
            var oldest_sequence = self.graphics_pipelines.items[0].last_used_sequence;
            for (self.graphics_pipelines.items[1..], 1..) |entry, index| {
                if (entry.last_used_sequence >= oldest_sequence) continue;
                oldest_index = index;
                oldest_sequence = entry.last_used_sequence;
            }
            const victim = &self.graphics_pipelines.items[oldest_index];
            self.destroyPipeline(victim.pipeline);
            self.allocator.free(victim.vertex_words);
            self.allocator.free(victim.fragment_words);
            victim.* = replacement;
        }
        self.graphics_pipeline_cache_misses += 1;
        self.frame_profile.graphics_pipeline_misses += 1;
        self.frame_profile.graphics_pipeline_miss_state_match += @intFromBool(state_match);
        self.frame_profile.graphics_pipeline_miss_vertex_match += @intFromBool(vertex_match);
        self.frame_profile.graphics_pipeline_miss_fragment_match += @intFromBool(fragment_match);
        return pipeline;
    }

    fn colorTargetFrameBytes(target: GuestColorTarget) Error!usize {
        const bytes = std.math.cast(usize, target.layout.staging_bytes) orelse
            return Error.UnsupportedColorTarget;
        if (bytes == 0 or bytes > maximum_frame_bytes) return Error.UnsupportedColorTarget;
        return bytes;
    }

    /// Whether two bound colour targets are the same surface.
    ///
    /// A target is the memory it occupies, not every register that describes
    /// how that memory is read. One allocation is routinely bound twice with a
    /// different channel swap, a forced destination alpha, or a pitch left
    /// implied rather than stated, and treating each binding as its own
    /// surface gives one guest allocation two host images. A frame then splits
    /// across them: whatever the scene pass drew is invisible to the pass that
    /// presents, which reads as a black screen behind a command stream that
    /// looks perfectly healthy. Registers that change interpretation without
    /// changing storage therefore do not make a different target — the host
    /// format, which is what interpretation actually reaches, is still
    /// compared, as is every field that changes the bytes.
    fn sameRenderTarget(a: GuestColorTarget, b: GuestColorTarget) bool {
        // A pitch of zero is the width restated, so it names the same rows.
        const same_pitch = a.descriptor.pitch == b.descriptor.pitch or
            a.descriptor.pitch == 0 or b.descriptor.pitch == 0;
        return a.descriptor.address == b.descriptor.address and
            a.descriptor.width == b.descriptor.width and
            a.descriptor.height == b.descriptor.height and
            same_pitch and
            a.descriptor.format == b.descriptor.format and
            a.descriptor.tile_mode == b.descriptor.tile_mode and
            a.descriptor.samples_log2 == b.descriptor.samples_log2 and
            a.descriptor.fragments_log2 == b.descriptor.fragments_log2 and
            a.descriptor.base_array_slice == b.descriptor.base_array_slice and
            a.descriptor.last_array_slice == b.descriptor.last_array_slice and
            a.descriptor.mip_level == b.descriptor.mip_level and
            a.format.vulkan == b.format.vulkan and
            a.format.bytes_per_texel == b.format.bytes_per_texel and
            a.layout.required_source_bytes == b.layout.required_source_bytes and
            a.layout.staging_bytes == b.layout.staging_bytes;
    }

    fn sameRenderTargetMetadata(a: gpu.resources.ColorTarget, b: gpu.resources.ColorTarget) bool {
        return a.dcc_enabled == b.dcc_enabled and
            a.cmask_fast_clear == b.cmask_fast_clear and
            a.cmask_linear == b.cmask_linear and
            a.fmask_compression == b.fmask_compression and
            a.cmask_address == b.cmask_address and
            a.cmask_slice_bytes == b.cmask_slice_bytes and
            a.fmask_address == b.fmask_address and
            a.dcc_address == b.dcc_address;
    }

    fn uniformDccCode(
        self: *Renderer,
        dcc_address: u64,
        surface_bytes: u64,
    ) anyerror!?u8 {
        if (dcc_address == 0 or surface_bytes == 0) return null;
        const key_bytes_u64 = std.math.divCeil(u64, surface_bytes, dcc_block_bytes) catch return null;
        if (key_bytes_u64 == 0 or key_bytes_u64 > maximum_dcc_key_bytes) return null;
        const key_bytes: usize = @intCast(key_bytes_u64);
        const key = try self.allocator.alloc(u8, key_bytes);
        defer self.allocator.free(key);
        const memory = self.guest_memory orelse return null;
        if (!memory.read(memory.context, dcc_address, key)) return null;
        const code = key[0];
        for (key[1..]) |byte| {
            if (byte != code) return null;
        }
        return code;
    }

    fn readUniformDccSingleTexel(
        self: *Renderer,
        address: u64,
        surface_bytes: u64,
        bytes_per_texel: u8,
    ) anyerror!?DccClearTexel {
        if (bytes_per_texel == 0 or bytes_per_texel > 16 or surface_bytes < bytes_per_texel) return null;
        const byte_count = std.math.cast(usize, surface_bytes) orelse return null;
        if (byte_count > maximum_frame_bytes) return null;
        const surface = try self.allocator.alloc(u8, byte_count);
        defer self.allocator.free(surface);
        const memory = self.guest_memory orelse return null;
        if (!memory.read(memory.context, address, surface)) return null;
        return uniformDccSingleTexel(surface, bytes_per_texel);
    }

    /// Resolves what a DCC-compressed colour target actually reads as.
    ///
    /// A target with DCC enabled does not hold plain texels: the key holds one
    /// byte per 256-byte block saying whether that block was fast cleared, and
    /// the base allocation only holds compressed data for blocks something has
    /// since rendered into. Staging the base allocation as an image is
    /// therefore only meaningful when the key reads uncompressed everywhere;
    /// a uniform clear code means the hardware returns the clear colour for
    /// every texel, whatever the bytes underneath happen to be.
    ///
    /// Returns null when the raw allocation is the honest source: no DCC, a
    /// key we cannot read, a mixed key, or a code this does not model.
    fn colorTargetFastClearTexel(self: *Renderer, target: GuestColorTarget) anyerror!?DccClearTexel {
        const descriptor = target.descriptor;
        if (!descriptor.dcc_enabled or descriptor.dcc_address == 0) return null;
        const code = (try self.uniformDccCode(
            descriptor.dcc_address,
            target.layout.required_source_bytes,
        )) orelse return null;
        // GFX9/GFX10 comp-to-single stores the native clear texel at the
        // beginning of every 256-byte colour block and marks those blocks with
        // DCC code 0x10. The base allocation is therefore not a pixel array:
        // detiling it directly exposes one value followed by compression
        // padding as the repeating stripes seen in Yotei. Materialize a
        // fullscreen value when all blocks carry the same native texel.
        if (code == 0x10) return self.readUniformDccSingleTexel(
            descriptor.address,
            target.layout.required_source_bytes,
            target.format.bytes_per_texel,
        );
        return colorDccClearTexel(code, descriptor);
    }

    fn sampledDccSingleTexel(
        self: *Renderer,
        descriptor: gpu.resources.ImageDescriptor,
        surface_bytes: u64,
        bytes_per_texel: u8,
    ) anyerror!?DccClearTexel {
        if (!descriptor.dcc_enabled or descriptor.dcc_address == 0 or
            descriptor.samplesLog2() != 0 or descriptor.viewMipLevels() != 1 or
            descriptor.depth_or_layers != 1)
        {
            return null;
        }
        const code = (try self.uniformDccCode(descriptor.dcc_address, surface_bytes)) orelse return null;
        if (code != 0x10) return null;
        return self.readUniformDccSingleTexel(
            descriptor.address,
            surface_bytes,
            bytes_per_texel,
        );
    }

    fn stageCmaskFastClear(
        self: *Renderer,
        target: GuestColorTarget,
        reader: gpu.ShaderMemoryReader,
        frame: []u8,
    ) anyerror!?CmaskSeed {
        const descriptor = target.descriptor;
        if (!descriptor.cmask_fast_clear or descriptor.cmask_address == 0 or descriptor.dcc_enabled) return null;
        const texel = clearWordTexel(descriptor) orelse return null;
        const layout = gpu.CmaskLayout.fromColorTarget(descriptor) catch return null;
        const byte_count = std.math.cast(usize, layout.required_bytes) orelse return null;
        if (byte_count == 0 or byte_count > maximum_cmask_bytes) return null;
        const metadata = try self.allocator.alloc(u8, byte_count);
        defer self.allocator.free(metadata);
        const memory = self.guest_memory orelse return null;
        if (!memory.read(memory.context, descriptor.cmask_address, metadata)) return null;

        const stats = classifyCmaskBlocks(layout, metadata) orelse {
            if (log_verbose_gpu) std.debug.print(
                "[vulkan dcb] CMASK contains an unsupported compressed state @0x{x}\n",
                .{descriptor.cmask_address},
            );
            return null;
        };
        if (stats.expanded_blocks == 0) {
            fillRgba8(frame, texel);
        } else {
            try self.stageColorTarget(target, reader, frame);
            applyCmaskClearBlocks(layout, metadata, frame, texel);
        }
        return .{
            .texel = texel,
            .clear_blocks = stats.clear_blocks,
            .expanded_blocks = stats.expanded_blocks,
        };
    }

    /// Stage a color target without issuing one checked guest-memory read per
    /// texel. Large tiled 4K targets otherwise spend minutes crossing the
    /// MemoryReader callback roughly 8.3 million times before the first draw.
    fn stageColorTarget(
        self: *Renderer,
        target: GuestColorTarget,
        reader: gpu.ShaderMemoryReader,
        frame: []u8,
    ) anyerror!void {
        if (target.layout.block.tile_mode.isLinear()) {
            try target.layout.stage(reader, target.descriptor.address, frame);
            return;
        }

        const source_bytes = std.math.cast(usize, target.layout.required_source_bytes) orelse
            return Error.UnsupportedColorTarget;
        const tiled = try self.allocator.alloc(u8, source_bytes);
        defer self.allocator.free(tiled);
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        if (!memory.read(memory.context, target.descriptor.address, tiled))
            return Error.GuestMemoryReadFailed;
        try target.layout.detile(tiled, frame);
    }

    fn stageInitialColorTarget(
        self: *Renderer,
        target: GuestColorTarget,
        reader: gpu.ShaderMemoryReader,
        frame: []u8,
    ) anyerror!void {
        if (try self.colorTargetFastClearTexel(target)) |texel| {
            fillTexels(frame, texel.bytes[0..texel.length]);
            self.reportDccFastClearSeed(target, texel);
            return;
        }
        if (try self.stageCmaskFastClear(target, reader, frame)) |seed| {
            if (seed.clear_blocks != 0) self.reportCmaskFastClearSeed(target, seed);
            return;
        }
        try self.stageColorTarget(target, reader, frame);
    }

    fn reportDccFastClearSeed(self: *Renderer, target: GuestColorTarget, texel: DccClearTexel) void {
        if (self.reported_fast_clear_seeds >= 4 and !log_verbose_gpu) return;
        self.reported_fast_clear_seeds += 1;
        std.debug.print(
            "[vulkan dcb] dcc fast-clear target @0x{x} {d}x{d} key@0x{x} fmt={d} texel_bytes={d} raw={x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}\n",
            .{
                target.descriptor.address,
                target.descriptor.width,
                target.descriptor.height,
                target.descriptor.dcc_address,
                target.descriptor.format,
                texel.length,
                texel.bytes[0],
                texel.bytes[1],
                texel.bytes[2],
                texel.bytes[3],
                texel.bytes[4],
                texel.bytes[5],
                texel.bytes[6],
                texel.bytes[7],
            },
        );
    }

    fn reportCmaskFastClearSeed(self: *Renderer, target: GuestColorTarget, seed: CmaskSeed) void {
        if (self.reported_fast_clear_seeds >= 4 and !log_verbose_gpu) return;
        self.reported_fast_clear_seeds += 1;
        std.debug.print(
            "[vulkan dcb] cmask fast-clear target @0x{x} {d}x{d} meta@0x{x} blocks={d}/{d} rgba={d},{d},{d},{d}\n",
            .{
                target.descriptor.address,
                target.descriptor.width,
                target.descriptor.height,
                target.descriptor.cmask_address,
                seed.clear_blocks,
                seed.clear_blocks + seed.expanded_blocks,
                seed.texel[0],
                seed.texel[1],
                seed.texel[2],
                seed.texel[3],
            },
        );
    }

    fn sameHtileTarget(a: gpu.resources.DepthTarget, b: gpu.resources.DepthTarget) bool {
        return a.read_address == b.read_address and
            a.write_address == b.write_address and
            a.stencil_read_address == b.stencil_read_address and
            a.stencil_write_address == b.stencil_write_address and
            a.htile_address == b.htile_address and
            a.width == b.width and a.height == b.height and
            a.format == b.format and a.stencil_format == b.stencil_format and
            a.tile_mode == b.tile_mode and a.stencil_tile_mode == b.stencil_tile_mode and
            a.samples_log2 == b.samples_log2 and a.maximum_mip == b.maximum_mip and
            a.base_array_slice == b.base_array_slice and
            a.last_array_slice == b.last_array_slice and a.mip_level == b.mip_level and
            a.htile_enabled == b.htile_enabled and
            a.htile_pipe_aligned == b.htile_pipe_aligned and
            a.tile_stencil_disabled == b.tile_stencil_disabled;
    }

    fn acquireHtileTarget(self: *Renderer, target: gpu.resources.DepthTarget) !usize {
        self.htile_target_sequence +%= 1;
        for (self.htile_targets.items, 0..) |*cached, index| {
            if (!sameHtileTarget(cached.target, target)) continue;
            cached.target = target;
            cached.last_used_sequence = self.htile_target_sequence;
            return index;
        }
        const entry = CachedHtileTarget{
            .target = target,
            .last_used_sequence = self.htile_target_sequence,
        };
        if (self.htile_targets.items.len < maximum_depth_targets) {
            try self.htile_targets.append(self.allocator, entry);
            return self.htile_targets.items.len - 1;
        }
        var oldest_index: usize = 0;
        for (self.htile_targets.items[1..], 1..) |cached, index| {
            if (cached.last_used_sequence < self.htile_targets.items[oldest_index].last_used_sequence) {
                oldest_index = index;
            }
        }
        self.htile_targets.items[oldest_index] = entry;
        return oldest_index;
    }

    /// Materializes the only HTILE states which can make the base allocation
    /// stale: exact 0.0/1.0 fast clears. Ordinary Z-range words are left in
    /// place because their base depth/stencil texels are already authoritative.
    fn resolveHtileTarget(self: *Renderer, target: gpu.resources.DepthTarget) anyerror!void {
        if (!target.htile_enabled or target.htile_address == 0) return;
        const index = try self.acquireHtileTarget(target);
        if (self.htile_targets.items[index].resolved) return;
        const stats = try self.expandHtileFastClears(target);
        self.htile_targets.items[index].resolved = true;
        const resolved = stats orelse return;
        if (resolved.clearBlocks() == 0) return;
        if (self.reported_htile_resolves >= 4 and !log_verbose_gpu) return;
        self.reported_htile_resolves += 1;
        std.debug.print(
            "[vulkan dcb] htile fast-clear resolve depth@0x{x} {d}x{d} meta@0x{x} zero={d} one={d} base={d}\n",
            .{
                if (target.write_address != 0) target.write_address else target.read_address,
                target.width,
                target.height,
                target.htile_address,
                resolved.clear_zero_blocks,
                resolved.clear_one_blocks,
                resolved.base_blocks,
            },
        );
    }

    fn expandHtileFastClears(
        self: *Renderer,
        target: gpu.resources.DepthTarget,
    ) anyerror!?HtileResolveStats {
        const htile = gpu.HtileLayout.fromDepthTarget(target) catch return null;
        const metadata_bytes = std.math.cast(usize, htile.required_bytes) orelse return null;
        if (metadata_bytes == 0 or metadata_bytes > maximum_htile_bytes) return null;
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        const metadata = try self.allocator.alloc(u8, metadata_bytes);
        defer self.allocator.free(metadata);
        if (!memory.read(memory.context, target.htile_address, metadata)) {
            return Error.GuestMemoryReadFailed;
        }

        const stats = classifyHtileBlocks(htile, metadata, target.tile_stencil_disabled) orelse return null;
        if (stats.clearBlocks() == 0) return stats;

        const depth_texture = gpu.TextureLayout.fromDepthTarget(target) catch return null;
        const depth = depth_texture.base() catch return null;
        const depth_bytes = std.math.cast(usize, depth_texture.required_source_bytes) orelse return null;
        if (depth_bytes == 0 or depth_bytes > maximum_frame_bytes) return null;
        var depth_addresses: [2]u64 = @splat(0);
        var depth_count: usize = 0;
        for ([_]u64{ target.read_address, target.write_address }) |address| {
            if (address == 0) continue;
            var duplicate = false;
            for (depth_addresses[0..depth_count]) |present| {
                if (present == address) duplicate = true;
            }
            if (!duplicate) {
                depth_addresses[depth_count] = address;
                depth_count += 1;
            }
        }
        if (depth_count == 0) return null;
        for (depth_addresses[0..depth_count]) |address| {
            const allocation = try self.allocator.alloc(u8, depth_bytes);
            defer self.allocator.free(allocation);
            if (!memory.read(memory.context, address, allocation)) return Error.GuestMemoryReadFailed;
            try applyHtileDepthFastClears(htile, metadata, target, depth, allocation);
            if (!memory.write(memory.context, address, allocation)) return Error.GuestMemoryWriteFailed;
        }

        if (!target.tile_stencil_disabled and target.stencil_format != 0) {
            const stencil_texture = gpu.TextureLayout.fromStencilTarget(target) catch return null;
            const stencil = stencil_texture.base() catch return null;
            const stencil_bytes = std.math.cast(usize, stencil_texture.required_source_bytes) orelse return null;
            if (stencil_bytes == 0 or stencil_bytes > maximum_frame_bytes) return null;
            var stencil_addresses: [2]u64 = @splat(0);
            var stencil_count: usize = 0;
            for ([_]u64{ target.stencil_read_address, target.stencil_write_address }) |address| {
                if (address == 0) continue;
                var duplicate = false;
                for (stencil_addresses[0..stencil_count]) |present| {
                    if (present == address) duplicate = true;
                }
                if (!duplicate) {
                    stencil_addresses[stencil_count] = address;
                    stencil_count += 1;
                }
            }
            // Expanding the shared depth/stencil word without publishing the
            // stencil clear would expose stale stencil bytes.
            if (stencil_count == 0) return null;
            for (stencil_addresses[0..stencil_count]) |address| {
                const allocation = try self.allocator.alloc(u8, stencil_bytes);
                defer self.allocator.free(allocation);
                if (!memory.read(memory.context, address, allocation)) return Error.GuestMemoryReadFailed;
                try applyHtileStencilFastClears(htile, metadata, target, stencil, allocation);
                if (!memory.write(memory.context, address, allocation)) return Error.GuestMemoryWriteFailed;
            }
        }

        for (0..htile.layers) |layer_index| {
            var y: u32 = 0;
            while (y < htile.height) : (y += gpu.HtileLayout.region_height) {
                var x: u32 = 0;
                while (x < htile.width) : (x += gpu.HtileLayout.region_width) {
                    const layer: u32 = @intCast(layer_index);
                    const word = try htile.word(metadata, x, y, layer);
                    if (gpu.HtileLayout.fastClearDepth(word, target.tile_stencil_disabled) == null) continue;
                    try htile.setWord(
                        metadata,
                        x,
                        y,
                        layer,
                        gpu.HtileLayout.expandedWord(target.tile_stencil_disabled),
                    );
                }
            }
        }
        if (!memory.write(memory.context, target.htile_address, metadata)) {
            return Error.GuestMemoryWriteFailed;
        }
        return stats;
    }

    fn materializeHtileTargetAt(self: *Renderer, address: u64, size: usize) anyerror!bool {
        for (self.htile_targets.items) |cached| {
            if (cached.resolved) continue;
            const target = cached.target;
            const depth = gpu.TextureLayout.fromDepthTarget(target) catch continue;
            const depth_hit = (target.read_address != 0 and byteRangesOverlap(
                address,
                size,
                target.read_address,
                depth.required_source_bytes,
            )) or (target.write_address != 0 and byteRangesOverlap(
                address,
                size,
                target.write_address,
                depth.required_source_bytes,
            ));
            var stencil_hit = false;
            if (!depth_hit and target.stencil_format != 0) {
                const stencil = gpu.TextureLayout.fromStencilTarget(target) catch continue;
                stencil_hit = (target.stencil_read_address != 0 and byteRangesOverlap(
                    address,
                    size,
                    target.stencil_read_address,
                    stencil.required_source_bytes,
                )) or (target.stencil_write_address != 0 and byteRangesOverlap(
                    address,
                    size,
                    target.stencil_write_address,
                    stencil.required_source_bytes,
                ));
            }
            if (!depth_hit and !stencil_hit) continue;
            try self.resolveHtileTarget(target);
            return true;
        }
        return false;
    }

    fn registerTrackedImage(
        self: *Renderer,
        image: vk.Image,
        aspect_mask: vk.Flags,
        mip_levels: u32,
        array_layers: u32,
    ) image_state.Error!void {
        return self.image_states.registerImage(self.allocator, image, .{
            .aspect_mask = aspect_mask,
            .level_count = mip_levels,
            .layer_count = array_layers,
        });
    }

    /// Emits the exact per-aspect/mip/layer barriers required by the tracked
    /// prior usage. Queue recording is serialized, so committing tracker state
    /// here mirrors the order in which Vulkan will execute the commands.
    fn transitionTrackedImage(
        self: *Renderer,
        command_buffer: vk.CommandBuffer,
        image: vk.Image,
        range: vk.ImageSubresourceRange,
        usage: image_state.Usage,
    ) Error!void {
        var transitions: [256]image_state.Transition = undefined;
        const count = self.image_states.transition(
            image,
            image_state.SubresourceRange.fromVulkan(range),
            usage,
            &transitions,
        ) catch return Error.UnsupportedGraphicsState;
        for (transitions[0..count]) |*transition| {
            self.device_functions.cmd_pipeline_barrier(
                command_buffer,
                transition.source_stages,
                transition.destination_stages,
                0,
                0,
                null,
                0,
                null,
                1,
                @ptrCast(&transition.barrier),
            );
        }
    }

    fn createCachedRenderTarget(self: *Renderer, target: GuestColorTarget) anyerror!CachedRenderTarget {
        const frame_bytes = try colorTargetFrameBytes(target);
        const samples = rasterSampleCount(target.descriptor.fragments_log2) orelse
            return Error.UnsupportedColorTarget;
        const image = try self.createImageWithExtent(
            target.descriptor.width,
            target.descriptor.height,
            1,
            1,
            vk.image_type_2d,
            vk.image_create_mutable_format_bit,
            target.format.vulkan,
            vk.image_usage_color_attachment_bit |
                vk.image_usage_transfer_src_bit |
                vk.image_usage_transfer_dst_bit |
                vk.image_usage_sampled_bit |
                vk.image_usage_storage_bit,
            samples,
            1,
        );
        errdefer self.destroyImage(image);
        try self.registerTrackedImage(image.handle, vk.image_aspect_color_bit, 1, 1);
        errdefer self.image_states.forgetImage(image.handle);

        const view_info = vk.ImageViewCreateInfo{
            .image = image.handle,
            .format = target.format.vulkan,
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        var view: vk.ImageView = 0;
        if (self.device_functions.create_image_view(self.device, &view_info, null, &view) != vk.success) {
            return Error.ImageViewCreationFailed;
        }
        errdefer self.destroyImageView(view);

        const render_pass = try self.createGraphicsRenderPass(target.format.vulkan, true, samples);
        errdefer self.destroyRenderPass(render_pass);
        const framebuffer_info = vk.FramebufferCreateInfo{
            .render_pass = render_pass,
            .attachment_count = 1,
            .attachments = @ptrCast(&view),
            .width = target.descriptor.width,
            .height = target.descriptor.height,
        };
        var framebuffer: vk.Framebuffer = 0;
        if (self.device_functions.create_framebuffer(self.device, &framebuffer_info, null, &framebuffer) != vk.success) {
            return Error.FramebufferCreationFailed;
        }
        errdefer self.destroyFramebuffer(framebuffer);

        const readback = try self.createBuffer(
            frame_bytes,
            vk.buffer_usage_transfer_dst_bit,
            vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
        );
        errdefer self.destroyBuffer(readback);
        const alias_token = try self.image_aliases.register(
            self.allocator,
            .color_target,
            aliasRange(target.descriptor.address, target.layout.required_source_bytes),
            colorTargetAliasSignature(target),
        );
        return .{
            .alias_token = alias_token,
            .target = target,
            .image = image,
            .view = view,
            .render_pass = render_pass,
            .framebuffer = framebuffer,
            .readback = readback,
        };
    }

    fn destroyCachedRenderTarget(self: *Renderer, target: CachedRenderTarget) void {
        self.image_aliases.unregister(target.alias_token);
        self.image_states.forgetImage(target.image.handle);
        self.invalidateResidentImageViews(target.image.handle);
        self.invalidateColorPasses(target.view);
        self.destroyDepthPass(target.depth_pass);
        self.destroyFramebuffer(target.framebuffer);
        self.destroyRenderPass(target.render_pass);
        self.destroyImageView(target.view);
        self.destroyBuffer(target.readback);
        self.destroyImage(target.image);
    }

    fn destroyDepthPass(self: *Renderer, pass: ?DepthPass) void {
        const active = pass orelse return;
        self.destroyFramebuffer(active.framebuffer);
        self.destroyRenderPass(active.render_pass);
    }

    fn destroyCachedDepthTarget(self: *Renderer, target: CachedDepthTarget) void {
        self.image_aliases.unregister(target.alias_token);
        if (target.stencil_alias_token) |token| self.image_aliases.unregister(token);
        self.image_states.forgetImage(target.image.handle);
        self.invalidateResidentImageViews(target.image.handle);
        self.destroyImageView(target.view);
        if (target.readback) |buffer| self.destroyBuffer(buffer);
        self.destroyImage(target.image);
    }

    fn transitionRenderTargetToShaderRead(self: *Renderer, index: usize) anyerror!void {
        if (index >= self.render_targets.items.len) return Error.MissingPresentedFrame;
        const snapshot = self.render_targets.items[index];
        if (!snapshot.initialized) return;
        // `shader_read_layout` is also set after a storage-image alias, which
        // leaves the VkImage in GENERAL. Sampling still needs
        // SHADER_READ_ONLY_OPTIMAL; skipping that barrier made Yotei's
        // cubemap downsample gather an all-zero R8 cube.
        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.shader_read_usage,
        );
        try self.submitOneShot(command_buffer);
        self.render_targets.items[index].shader_read_layout = true;
    }

    fn transitionRenderTargetToColorAttachment(self: *Renderer, index: usize) anyerror!void {
        if (index >= self.render_targets.items.len) return Error.MissingPresentedFrame;
        const snapshot = self.render_targets.items[index];
        if (!snapshot.initialized or !snapshot.shader_read_layout) return;
        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.color_attachment_usage,
        );
        try self.submitOneShot(command_buffer);
        self.render_targets.items[index].shader_read_layout = false;
    }

    fn transitionRenderTargetToStorage(self: *Renderer, index: usize) anyerror!void {
        if (index >= self.render_targets.items.len) return Error.MissingPresentedFrame;
        const snapshot = self.render_targets.items[index];
        if (!snapshot.initialized) return Error.MissingPresentedFrame;
        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.storage_usage,
        );
        try self.submitOneShot(command_buffer);
        // Reuse the existing non-attachment marker so the normal return path
        // transitions GENERAL back to COLOR_ATTACHMENT_OPTIMAL.
        self.render_targets.items[index].shader_read_layout = true;
    }

    fn findResidentRenderTargetIndex(
        self: *Renderer,
        descriptor: gpu.resources.ImageDescriptor,
        image_format: u32,
    ) ?usize {
        for (self.render_targets.items, 0..) |cached, index| {
            // A VkImageView cannot start at an arbitrary byte inside another
            // image allocation. Reuse only a render target that describes the
            // same image exactly; overlap and equal texel size are insufficient
            // proof and can silently sample an unrelated attachment.
            if (cached.initialized and
                cached.target.descriptor.fragments_log2 == 0 and
                cached.target.descriptor.address == descriptor.address and
                cached.target.descriptor.width == descriptor.width and
                cached.target.descriptor.height == descriptor.height and
                (sampledViewFormatCompatible(cached.target.format.vulkan, image_format) or
                    cached.target.format.bytes_per_texel == storageImageBytesPerTexel(descriptor.unified_format)))
            {
                return index;
            }
        }
        return null;
    }

    fn stageResidentRenderTarget(
        self: *Renderer,
        descriptor: gpu.resources.ImageDescriptor,
        sampler_descriptor: gpu.resources.SamplerDescriptor,
        image_format: u32,
        dimension: rdna2.spirv.SampledImageDimension,
    ) anyerror!?PreparedSampledImage {
        const index = self.findResidentRenderTargetIndex(descriptor, image_format) orelse return null;
        const cached = self.render_targets.items[index];
        try self.transitionRenderTargetToShaderRead(index);
        const components = try sampledImageComponents(descriptor.dst_select);
        const view = try self.residentImageView(
            cached.image.handle,
            if (dimension == .two_d_array) vk.image_view_type_2d_array else vk.image_view_type_2d,
            image_format,
            components,
            vk.image_aspect_color_bit,
            1,
        );
        const sampler = try self.residentSampler(sampler_descriptor);
        if (!self.reported_resident_rt_sample or self.traceCurrentGraphicsFrame()) {
            self.reported_resident_rt_sample = true;
            std.debug.print(
                "[vulkan dcb] resident render-target sample @0x{x} {d}x{d} fmt={d} -> gpu @0x{x} {d}x{d}\n",
                .{
                    descriptor.address,
                    descriptor.width,
                    descriptor.height,
                    descriptor.unified_format,
                    cached.target.descriptor.address,
                    cached.target.descriptor.width,
                    cached.target.descriptor.height,
                },
            );
        }
        return .{
            .image = cached.image,
            .view = view,
            .sampler = sampler,
            .owns_view = false,
            .owns_sampler = false,
        };
    }

    fn transitionDepthTargetToShaderRead(self: *Renderer, index: usize) anyerror!void {
        if (index >= self.depth_targets.items.len) return Error.MissingPresentedFrame;
        const snapshot = self.depth_targets.items[index];
        if (!snapshot.initialized or snapshot.shader_read_layout) return;
        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = snapshot.target.aspectMask() },
            image_state.shader_read_usage,
        );
        try self.submitOneShot(command_buffer);
        self.depth_targets.items[index].shader_read_layout = true;
    }

    fn stageResidentDepthTarget(
        self: *Renderer,
        descriptor: gpu.resources.ImageDescriptor,
        sampler_descriptor: gpu.resources.SamplerDescriptor,
        image_format: u32,
    ) anyerror!?PreparedSampledImage {
        if (descriptor.tile_mode != .depth) return null;
        for (self.depth_targets.items, 0..) |cached, index| {
            if (!cached.initialized or
                cached.target.address != descriptor.address or
                cached.target.width != descriptor.width or
                cached.target.height != descriptor.height or
                !depthSampledFormatCompatible(cached.target.format, image_format))
            {
                continue;
            }
            if (self.resident_depth_sample_reports < 8 or self.traceCurrentGraphicsFrame()) {
                std.debug.print(
                    "[vulkan dcb] sampled resident depth @0x{x} {d}x{d} fmt={d}->{d}\n",
                    .{
                        descriptor.address,
                        descriptor.width,
                        descriptor.height,
                        cached.target.format,
                        image_format,
                    },
                );
                self.resident_depth_sample_reports +|= 1;
            }
            try self.transitionDepthTargetToShaderRead(index);
            const components = try sampledImageComponents(descriptor.dst_select);
            const view = try self.residentImageView(
                cached.image.handle,
                vk.image_view_type_2d,
                cached.target.format,
                components,
                vk.image_aspect_depth_bit,
                1,
            );
            const sampler = try self.residentSampler(sampler_descriptor);
            return .{
                .image = cached.image,
                .view = view,
                .sampler = sampler,
                .owns_view = false,
                .owns_sampler = false,
            };
        }
        return null;
    }

    /// Reduces the bound depth registers to the plane a Vulkan attachment can
    /// represent, or reports that this draw has no usable depth.
    fn guestDepthTarget(descriptor: gpu.resources.DepthTarget) ?GuestDepthTarget {
        const address = if (descriptor.write_address != 0)
            descriptor.write_address
        else
            descriptor.read_address;
        if (address == 0 or descriptor.width == 0 or descriptor.height == 0) return null;
        if (rasterSampleCount(descriptor.samples_log2) == null) return null;
        const format = depthTargetFormat(descriptor) orelse return null;
        const depth_bytes_per_sample: u64 = if (descriptor.format == 1) 2 else 4;
        const texel_count = std.math.mul(u64, descriptor.width, descriptor.height) catch return null;
        const sample_count = @as(u64, 1) << @intCast(descriptor.samples_log2);
        const fallback_bytes = std.math.mul(
            u64,
            std.math.mul(u64, texel_count, depth_bytes_per_sample) catch return null,
            sample_count,
        ) catch return null;
        // Some legal MSAA register combinations are not importable by the
        // current texture detiler yet. Alias tracking still needs a safe byte
        // interval, so fall back to the unpadded texel footprint instead of
        // rejecting an attachment the raster path itself supports.
        const allocation_bytes = if (gpu.TextureLayout.fromDepthTarget(descriptor)) |layout|
            layout.required_source_bytes
        else |_|
            fallback_bytes;
        const has_stencil = depthAttachmentHasStencil(format);
        const stencil_address = if (descriptor.stencil_write_address != 0)
            descriptor.stencil_write_address
        else
            descriptor.stencil_read_address;
        const stencil_allocation_bytes = if (has_stencil and stencil_address != 0)
            if (gpu.TextureLayout.fromStencilTarget(descriptor)) |layout|
                layout.required_source_bytes
            else |_|
                0
        else
            0;
        return .{
            .descriptor = descriptor,
            .address = address,
            .allocation_bytes = allocation_bytes,
            .stencil_address = stencil_address,
            .stencil_allocation_bytes = stencil_allocation_bytes,
            .width = descriptor.width,
            .height = descriptor.height,
            .guest_format = descriptor.format,
            .format = format,
            .tile_mode = descriptor.tile_mode,
            .base_array_slice = descriptor.base_array_slice,
            .mip_level = descriptor.mip_level,
            .samples_log2 = descriptor.samples_log2,
            .has_stencil = has_stencil,
            .clear_depth = descriptor.clear_depth,
            .clear_stencil = descriptor.clear_stencil,
        };
    }

    fn createCachedDepthTarget(self: *Renderer, target: GuestDepthTarget) anyerror!CachedDepthTarget {
        const samples = rasterSampleCount(target.samples_log2) orelse
            return Error.UnsupportedGraphicsState;
        const image = try self.createImageWithExtent(
            target.width,
            target.height,
            1,
            1,
            vk.image_type_2d,
            0,
            target.format,
            vk.image_usage_depth_stencil_attachment_bit | vk.image_usage_transfer_src_bit |
                vk.image_usage_transfer_dst_bit | vk.image_usage_sampled_bit,
            samples,
            1,
        );
        errdefer self.destroyImage(image);
        try self.registerTrackedImage(image.handle, target.aspectMask(), 1, 1);
        errdefer self.image_states.forgetImage(image.handle);

        const view_info = vk.ImageViewCreateInfo{
            .image = image.handle,
            .format = target.format,
            .subresource_range = .{ .aspect_mask = target.aspectMask() },
        };
        var view: vk.ImageView = 0;
        if (self.device_functions.create_image_view(self.device, &view_info, null, &view) != vk.success) {
            return Error.ImageViewCreationFailed;
        }
        errdefer self.destroyImageView(view);
        const readback: ?OwnedBuffer = if (self.depth_transfer_enabled)
            if (depthTransferPlan(target)) |plan|
                try self.createBuffer(
                    plan.total_bytes,
                    vk.buffer_usage_transfer_src_bit | vk.buffer_usage_transfer_dst_bit,
                    vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
                )
            else
                null
        else
            null;
        errdefer if (readback) |buffer| self.destroyBuffer(buffer);
        const alias_token = try self.image_aliases.register(
            self.allocator,
            .depth_target,
            aliasRange(target.address, target.allocation_bytes),
            depthTargetAliasSignature(target),
        );
        errdefer self.image_aliases.unregister(alias_token);
        const stencil_alias_token = if (target.stencil_address != 0 and target.stencil_allocation_bytes != 0)
            try self.image_aliases.register(
                self.allocator,
                .depth_target,
                aliasRange(target.stencil_address, target.stencil_allocation_bytes),
                depthTargetAliasSignature(target),
            )
        else
            null;
        return .{
            .alias_token = alias_token,
            .stencil_alias_token = stencil_alias_token,
            .target = target,
            .image = image,
            .view = view,
            .readback = readback,
        };
    }

    fn depthSubresource(target: GuestDepthTarget, stencil: bool) anyerror!gpu.TextureSubresourceLayout {
        const texture = if (stencil)
            try gpu.TextureLayout.fromStencilTarget(target.descriptor)
        else
            try gpu.TextureLayout.fromDepthTarget(target.descriptor);
        return texture.subresource(target.mip_level, 0, 1);
    }

    /// Imports the guest depth and optional stencil planes into their packed
    /// Vulkan attachment. Unsupported multisample layouts retain the legacy
    /// first-use clear path instead of pretending stale host contents are valid.
    fn importDepthTarget(self: *Renderer, index: usize) anyerror!bool {
        if (!self.depth_transfer_enabled) return false;
        if (index >= self.depth_targets.items.len) return false;
        const snapshot = self.depth_targets.items[index];
        const plan = depthTransferPlan(snapshot.target) orelse return false;
        const transfer = snapshot.readback orelse return false;
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        const reader = gpu.ShaderMemoryReader{ .context = memory.context, .read_fn = memory.read };
        const depth_layout = try depthSubresource(snapshot.target, false);
        const guest_depth_bytes = std.math.cast(usize, try depth_layout.stagingBytes()) orelse
            return Error.UnsupportedGraphicsState;
        var transfer_bytes = try self.allocator.alloc(u8, plan.total_bytes);
        defer self.allocator.free(transfer_bytes);
        @memset(transfer_bytes, 0);
        const guest_depth = try self.allocator.alloc(u8, guest_depth_bytes);
        defer self.allocator.free(guest_depth);
        const depth_read_address = if (snapshot.target.descriptor.read_address != 0)
            snapshot.target.descriptor.read_address
        else
            snapshot.target.address;
        try depth_layout.stage(reader, depth_read_address, guest_depth);
        if (snapshot.target.format == vk.format_d24_unorm_s8_uint) {
            if (!expandDepth16To24(guest_depth, transfer_bytes[0..plan.depth_bytes])) {
                return Error.UnsupportedGraphicsState;
            }
        } else {
            if (guest_depth.len != plan.depth_bytes) return Error.UnsupportedGraphicsState;
            @memcpy(transfer_bytes[0..plan.depth_bytes], guest_depth);
        }

        if (snapshot.target.has_stencil) {
            if (snapshot.target.stencil_address == 0 or plan.stencil_bytes == 0) return false;
            const stencil_layout = try depthSubresource(snapshot.target, true);
            const stencil_bytes = std.math.cast(usize, try stencil_layout.stagingBytes()) orelse
                return Error.UnsupportedGraphicsState;
            if (stencil_bytes != plan.stencil_bytes) return Error.UnsupportedGraphicsState;
            try stencil_layout.stage(
                reader,
                if (snapshot.target.descriptor.stencil_read_address != 0)
                    snapshot.target.descriptor.stencil_read_address
                else
                    snapshot.target.stencil_address,
                transfer_bytes[plan.stencil_offset..][0..plan.stencil_bytes],
            );
        }
        try self.writeMapped(transfer, transfer_bytes);

        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = snapshot.target.aspectMask() },
            image_state.transfer_destination_usage,
        );
        var copies: [2]vk.BufferImageCopy = undefined;
        copies[0] = .{
            .image_subresource = .{ .aspect_mask = vk.image_aspect_depth_bit },
            .image_extent = .{ .width = snapshot.target.width, .height = snapshot.target.height, .depth = 1 },
        };
        var copy_count: u32 = 1;
        if (snapshot.target.has_stencil) {
            copies[1] = .{
                .buffer_offset = plan.stencil_offset,
                .image_subresource = .{ .aspect_mask = vk.image_aspect_stencil_bit },
                .image_extent = .{ .width = snapshot.target.width, .height = snapshot.target.height, .depth = 1 },
            };
            copy_count = 2;
        }
        self.device_functions.cmd_copy_buffer_to_image(
            command_buffer,
            transfer.handle,
            snapshot.image.handle,
            vk.image_layout_transfer_dst_optimal,
            copy_count,
            @ptrCast(&copies),
        );
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = snapshot.target.aspectMask() },
            image_state.depth_attachment_usage,
        );
        try self.submitOneShot(command_buffer);
        const cached = &self.depth_targets.items[index];
        cached.initialized = true;
        cached.shader_read_layout = false;
        _ = self.image_aliases.markSynchronized(cached.alias_token);
        if (cached.stencil_alias_token) |token| _ = self.image_aliases.markSynchronized(token);
        self.frame_profile.upload_bytes +|= plan.total_bytes;
        self.frame_profile.target_upload_bytes +|= plan.total_bytes;
        return true;
    }

    fn writeDepthPlane(
        self: *Renderer,
        memory: GuestMemory,
        target: GuestDepthTarget,
        stencil: bool,
        linear: []const u8,
    ) anyerror!void {
        const layout = try depthSubresource(target, stencil);
        const allocation_bytes = std.math.cast(usize, layout.required_source_bytes) orelse
            return Error.UnsupportedGraphicsState;
        if (allocation_bytes == 0 or allocation_bytes > maximum_frame_bytes) {
            return Error.UnsupportedGraphicsState;
        }
        const allocation = try self.allocator.alloc(u8, allocation_bytes);
        defer self.allocator.free(allocation);
        const address = if (stencil) target.stencil_address else target.address;
        if (address == 0 or !memory.read(memory.context, address, allocation)) {
            return Error.GuestMemoryReadFailed;
        }
        try layout.tile(linear, allocation);
        if (!memory.write(memory.context, address, allocation)) return Error.GuestMemoryWriteFailed;
    }

    /// Publishes a resident depth/stencil writer only at a guest-visibility or
    /// eviction boundary. The attachment remains resident and returns to its
    /// render layout, matching the colour/storage cache policy.
    fn materializeDepthTarget(self: *Renderer, index: usize) anyerror!void {
        if (!self.depth_transfer_enabled) return;
        if (index >= self.depth_targets.items.len) return;
        const snapshot = self.depth_targets.items[index];
        if (!snapshot.initialized or snapshot.gpu_generation == snapshot.host_generation) return;
        const plan = depthTransferPlan(snapshot.target) orelse return;
        const transfer = snapshot.readback orelse return;
        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = snapshot.target.aspectMask() },
            image_state.transfer_source_usage,
        );
        var copies: [2]vk.BufferImageCopy = undefined;
        copies[0] = .{
            .image_subresource = .{ .aspect_mask = vk.image_aspect_depth_bit },
            .image_extent = .{ .width = snapshot.target.width, .height = snapshot.target.height, .depth = 1 },
        };
        var copy_count: u32 = 1;
        if (snapshot.target.has_stencil) {
            copies[1] = .{
                .buffer_offset = plan.stencil_offset,
                .image_subresource = .{ .aspect_mask = vk.image_aspect_stencil_bit },
                .image_extent = .{ .width = snapshot.target.width, .height = snapshot.target.height, .depth = 1 },
            };
            copy_count = 2;
        }
        self.device_functions.cmd_copy_image_to_buffer(
            command_buffer,
            snapshot.image.handle,
            vk.image_layout_transfer_src_optimal,
            transfer.handle,
            copy_count,
            @ptrCast(&copies),
        );
        const host_barrier = vk.BufferMemoryBarrier{
            .source_access_mask = vk.access_transfer_write_bit,
            .destination_access_mask = vk.access_host_read_bit,
            .buffer = transfer.handle,
            .offset = 0,
            .size = transfer.size,
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_transfer_bit,
            vk.pipeline_stage_host_bit,
            0,
            0,
            null,
            1,
            @ptrCast(&host_barrier),
            0,
            null,
        );
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = snapshot.target.aspectMask() },
            image_state.depth_attachment_usage,
        );
        try self.submitOneShot(command_buffer);

        const bytes = try self.allocator.alloc(u8, plan.total_bytes);
        defer self.allocator.free(bytes);
        try self.readMapped(transfer, bytes);
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        const depth_layout = try depthSubresource(snapshot.target, false);
        const guest_depth_bytes = std.math.cast(usize, try depth_layout.stagingBytes()) orelse
            return Error.UnsupportedGraphicsState;
        if (snapshot.target.format == vk.format_d24_unorm_s8_uint) {
            const guest_depth = try self.allocator.alloc(u8, guest_depth_bytes);
            defer self.allocator.free(guest_depth);
            if (!compactDepth24To16(bytes[0..plan.depth_bytes], guest_depth)) {
                return Error.UnsupportedGraphicsState;
            }
            try self.writeDepthPlane(memory, snapshot.target, false, guest_depth);
        } else {
            if (guest_depth_bytes != plan.depth_bytes) return Error.UnsupportedGraphicsState;
            try self.writeDepthPlane(memory, snapshot.target, false, bytes[0..plan.depth_bytes]);
        }
        if (snapshot.target.has_stencil and snapshot.target.stencil_address != 0) {
            try self.writeDepthPlane(
                memory,
                snapshot.target,
                true,
                bytes[plan.stencil_offset..][0..plan.stencil_bytes],
            );
        }
        const cached = &self.depth_targets.items[index];
        cached.host_generation = snapshot.gpu_generation;
        cached.shader_read_layout = false;
        self.image_aliases.publishGuest(aliasRange(snapshot.target.address, snapshot.target.allocation_bytes));
        if (snapshot.target.stencil_address != 0) self.image_aliases.publishGuest(aliasRange(
            snapshot.target.stencil_address,
            snapshot.target.stencil_allocation_bytes,
        ));
        self.frame_profile.readback_bytes +|= plan.total_bytes;
        self.frame_profile.target_readback_bytes +|= plan.total_bytes;
    }

    fn acquireDepthTarget(self: *Renderer, target: GuestDepthTarget) anyerror!usize {
        for (self.depth_targets.items, 0..) |cached_snapshot, index| {
            if (!cached_snapshot.target.sameAllocation(target)) continue;
            const cached = &self.depth_targets.items[index];
            // The clear value lives in its own register and moves without the
            // allocation changing; keep the newest one for the next clear.
            cached.target.clear_depth = target.clear_depth;
            cached.target.clear_stencil = target.clear_stencil;
            self.depth_target_sequence +%= 1;
            cached.last_used_sequence = self.depth_target_sequence;
            return index;
        }

        const create_started = hostTimestampNs();
        var cached = try self.createCachedDepthTarget(target);
        self.frame_profile.depth_target_create_ns +|= elapsedHostNanoseconds(create_started);
        self.depth_target_sequence +%= 1;
        cached.last_used_sequence = self.depth_target_sequence;
        if (self.depth_targets.items.len < maximum_depth_targets) {
            try self.depth_targets.append(self.allocator, cached);
            const index = self.depth_targets.items.len - 1;
            if (self.depth_transfer_enabled) _ = try self.importDepthTarget(index);
            if (!self.reported_depth_attachment) {
                self.reported_depth_attachment = true;
                std.debug.print(
                    "[vulkan dcb] depth attachment: first @0x{x} {d}x{d} format={d}\n",
                    .{ target.address, target.width, target.height, target.guest_format },
                );
            }
            return index;
        }

        // Every draw is fenced before it returns, so the least-recently-used
        // attachment cannot still be in flight when it is recycled.
        var oldest_index: usize = 0;
        var oldest_sequence = self.depth_targets.items[0].last_used_sequence;
        for (self.depth_targets.items[1..], 1..) |entry, index| {
            if (entry.last_used_sequence >= oldest_sequence) continue;
            oldest_index = index;
            oldest_sequence = entry.last_used_sequence;
        }
        try self.materializeDepthTarget(oldest_index);
        const victim = &self.depth_targets.items[oldest_index];
        self.invalidateDepthPasses(victim.view);
        self.destroyCachedDepthTarget(victim.*);
        victim.* = cached;
        if (self.depth_transfer_enabled) _ = try self.importDepthTarget(oldest_index);
        return oldest_index;
    }

    /// Drops any colour framebuffer still paired with a depth view that is
    /// about to be destroyed.
    fn invalidateDepthPasses(self: *Renderer, view: vk.ImageView) void {
        self.invalidateColorPasses(view);
        for (self.render_targets.items) |*cached| {
            const pass = cached.depth_pass orelse continue;
            if (pass.depth_view != view) continue;
            self.destroyDepthPass(pass);
            cached.depth_pass = null;
        }
    }

    /// Frees the slot of the least-recently-used colour attachment.
    ///
    /// Without this the cache froze on whichever allocations it happened to see
    /// first: once full it refused every later target outright, so a scene that
    /// works through more attachments than the bound has draws silently dropped
    /// from that point on and never recovers. Every other resource cache here
    /// recycles instead, and colour targets only differ in owing their contents
    /// to the guest — so the victim is published before it goes away, and a
    /// later sample or flip still reads what was drawn into it.
    ///
    /// Every draw is fenced before it returns, so the recycled attachment
    /// cannot still be executing.
    fn evictRenderTarget(self: *Renderer) anyerror!usize {
        var oldest_index: usize = 0;
        var oldest_sequence = self.render_targets.items[0].last_used_sequence;
        for (self.render_targets.items[1..], 1..) |entry, index| {
            if (entry.last_used_sequence >= oldest_sequence) continue;
            oldest_index = index;
            oldest_sequence = entry.last_used_sequence;
        }
        try self.materializeRenderTarget(oldest_index);
        const victim = self.render_targets.items[oldest_index];
        self.destroyCachedRenderTarget(victim);
        // The evicted slot is about to hold an unrelated attachment, so a
        // recorded "most recent" index pointing at it would name the wrong one.
        if (self.latest_render_target_index) |latest| {
            if (latest == oldest_index) self.latest_render_target_index = null;
        }
        if (self.latest_video_render_target_index) |latest| {
            if (latest == oldest_index) self.latest_video_render_target_index = null;
        }
        return oldest_index;
    }

    fn acquireRenderTarget(self: *Renderer, target: GuestColorTarget) anyerror!usize {
        for (self.render_targets.items, 0..) |cached_snapshot, index| {
            if (!sameRenderTarget(cached_snapshot.target, target)) continue;
            const metadata_changed = !sameRenderTargetMetadata(cached_snapshot.target.descriptor, target.descriptor);
            if (self.traceCurrentGraphicsFrame()) {
                std.debug.print(
                    "[vulkan dcb] traced target hit slot={d} addr=0x{x} initialized={any} metadata_changed={any} generation={d}/{d} layout={s}\n",
                    .{
                        index,
                        target.descriptor.address,
                        cached_snapshot.initialized,
                        metadata_changed,
                        cached_snapshot.gpu_generation,
                        cached_snapshot.host_generation,
                        if (cached_snapshot.shader_read_layout) "sampled" else "attachment",
                    },
                );
            }
            const cached = &self.render_targets.items[index];
            // DCC/CMASK register bindings describe how guest memory would be
            // interpreted, but a resident VkImage already contains the
            // decompressed colour result. Merely rebinding metadata must not
            // force that image through guest memory and upload it again. An
            // actual metadata write still invalidates the target through
            // prepareCmaskWrite/alias tracking.
            if (metadata_changed) cached.scanout_flip_vertical = false;
            // Clear registers can change without changing the allocation.
            // Keep the newest descriptor for a subsequent metadata resolve.
            cached.target = target;
            self.render_target_sequence +%= 1;
            cached.last_used_sequence = self.render_target_sequence;
            self.frame_profile.render_target_hits += 1;
            return index;
        }
        const create_started = hostTimestampNs();
        var cached = try self.createCachedRenderTarget(target);
        self.frame_profile.render_target_create_ns +|= elapsedHostNanoseconds(create_started);
        self.render_target_sequence +%= 1;
        cached.last_used_sequence = self.render_target_sequence;
        if (self.render_targets.items.len >= maximum_render_targets) {
            const victim_index = try self.evictRenderTarget();
            self.render_targets.items[victim_index] = cached;
            self.frame_profile.render_target_misses += 1;
            return victim_index;
        }
        try self.render_targets.ensureUnusedCapacity(self.allocator, 1);
        self.render_targets.appendAssumeCapacity(cached);
        self.frame_profile.render_target_misses += 1;
        if (self.render_targets.items.len == 1) {
            std.debug.print(
                "[vulkan dcb] render target cache: first @0x{x} {d}x{d}\n",
                .{ target.descriptor.address, target.layout.width, target.layout.height },
            );
        }
        return self.render_targets.items.len - 1;
    }

    /// Copies one persistent attachment to host memory only when something
    /// outside the GPU needs it (flip, CPU visibility, or texture staging).
    /// Consecutive draws therefore stay resident and compose in-order.
    fn materializeRenderTarget(self: *Renderer, index: usize) anyerror!void {
        const profile_started = hostTimestampNs();
        defer self.frame_profile.target_materialize_ns +|= elapsedHostNanoseconds(profile_started);
        if (index >= self.render_targets.items.len) return Error.MissingPresentedFrame;
        const snapshot = self.render_targets.items[index];
        if (!snapshot.initialized) return;
        // Multisampled attachments cannot be copied to a linear buffer. The
        // guest resolve packet publishes the 1x destination instead.
        if (snapshot.target.descriptor.fragments_log2 != 0) return;
        if (snapshot.gpu_generation == snapshot.host_generation) {
            try self.transitionRenderTargetToColorAttachment(index);
            return;
        }
        const frame_bytes = try colorTargetFrameBytes(snapshot.target);

        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.transfer_source_usage,
        );
        const copy = vk.BufferImageCopy{
            .image_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .image_extent = .{
                .width = snapshot.target.descriptor.width,
                .height = snapshot.target.descriptor.height,
                .depth = 1,
            },
        };
        self.device_functions.cmd_copy_image_to_buffer(
            command_buffer,
            snapshot.image.handle,
            vk.image_layout_transfer_src_optimal,
            snapshot.readback.handle,
            1,
            @ptrCast(&copy),
        );
        const host_barrier = vk.BufferMemoryBarrier{
            .source_access_mask = vk.access_transfer_write_bit,
            .destination_access_mask = vk.access_host_read_bit,
            .buffer = snapshot.readback.handle,
            .offset = 0,
            .size = snapshot.readback.size,
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_transfer_bit,
            vk.pipeline_stage_host_bit,
            0,
            0,
            null,
            1,
            @ptrCast(&host_barrier),
            0,
            null,
        );
        try self.transitionTrackedImage(
            command_buffer,
            snapshot.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.color_attachment_usage,
        );
        try self.submitOneShot(command_buffer);

        const frame = try self.allocator.alloc(u8, frame_bytes);
        defer self.allocator.free(frame);
        try self.readMapped(snapshot.readback, frame);
        self.frame_profile.readback_bytes += frame_bytes;
        self.frame_profile.target_readback_bytes += frame_bytes;
        if (snapshot.scanout_flip_vertical and snapshot.target.format.bytes_per_texel == 4) {
            flipRgba8Rows(frame, snapshot.target.descriptor.width, snapshot.target.descriptor.height);
        }
        if (snapshot.target.descriptor.force_destination_alpha_one) {
            forceColorTargetAlphaOne(frame, snapshot.target.format);
        }
        try self.recordGuestColorTarget(snapshot.target, frame);
        self.render_targets.items[index].host_generation = snapshot.gpu_generation;
        self.render_targets.items[index].shader_read_layout = false;

        const colored = countNonzeroTexels(frame, snapshot.target.format.bytes_per_texel);
        self.graphics_probe_colored_pixels = colored;
        if (self.traceCurrentGraphicsFrame()) {
            std.debug.print(
                "[vulkan dcb] traced render-target result addr=0x{x} fmt={d} nonzero_texels={d}/{d} peak={d}\n",
                .{
                    snapshot.target.descriptor.address,
                    snapshot.target.descriptor.format,
                    colored,
                    snapshot.target.descriptor.width * snapshot.target.descriptor.height,
                    peakColorValue(frame, snapshot.target.format),
                },
            );
        }
        if (snapshot.target.format.bytes_per_texel == 4) {
            if (self.frame_dumps == 0 and colored != 0) {
                dumpFramePpm("out\\first-frame.ppm", snapshot.target.descriptor.width, snapshot.target.descriptor.height, frame);
                self.frame_dumps += 1;
            }
            if (colored != 0) switch (self.frame_sequence) {
                32, 64, 128 => {
                    var path_buffer: [64]u8 = undefined;
                    const path: ?[:0]u8 = std.fmt.bufPrintZ(
                        &path_buffer,
                        "out\\render-{d:0>4}.ppm",
                        .{self.frame_sequence},
                    ) catch null;
                    if (path) |name| dumpFramePpm(
                        name.ptr,
                        snapshot.target.descriptor.width,
                        snapshot.target.descriptor.height,
                        frame,
                    );
                },
                else => {},
            };
        } else if (log_verbose_gpu or self.reported_non_rgba_materializations < 4) {
            self.reported_non_rgba_materializations += 1;
            std.debug.print(
                "[vulkan dcb] materialized color target @0x{x} fmt={d} nonzero_texels={d}/{d}\n",
                .{
                    snapshot.target.descriptor.address,
                    snapshot.target.descriptor.format,
                    colored,
                    snapshot.target.descriptor.width * snapshot.target.descriptor.height,
                },
            );
        }
    }

    fn materializeRenderTargetAt(self: *Renderer, address: u64) anyerror!bool {
        var selected: ?usize = null;
        var selected_sequence: u64 = 0;
        for (self.render_targets.items, 0..) |cached, index| {
            if (!cached.initialized or cached.target.descriptor.address != address) continue;
            if (selected == null or cached.last_used_sequence > selected_sequence) {
                selected = index;
                selected_sequence = cached.last_used_sequence;
            }
        }
        const index = selected orelse return false;
        try self.materializeRenderTarget(index);
        return true;
    }

    /// CB_COLOR_CONTROL.MODE=RESOLVE uses slot 0 as the multisampled source and
    /// slot 1 as the single-sample destination.
    fn resolveColorTargets(self: *Renderer, render_state: gpu.resources.RenderState) anyerror!bool {
        if (render_state.color_control.mode != 3) return false;
        const source_descriptor = render_state.color_targets[0] orelse return false;
        const destination_descriptor = render_state.color_targets[1] orelse return false;
        if (source_descriptor.address == destination_descriptor.address) return false;

        const source = try guestColorTarget(source_descriptor);
        const destination = try guestColorTarget(destination_descriptor);
        if (source.descriptor.width != destination.descriptor.width or
            source.descriptor.height != destination.descriptor.height or
            source.format.vulkan != destination.format.vulkan)
        {
            return Error.UnsupportedColorTarget;
        }

        const source_samples = colorTargetSamplesLog2(source.descriptor) orelse
            return Error.UnsupportedColorTarget;
        const destination_samples = colorTargetSamplesLog2(destination.descriptor) orelse
            return Error.UnsupportedColorTarget;
        if (destination_samples != 0) return Error.UnsupportedColorTarget;

        if (source_samples == 0) {
            return self.resolveSingleSampleColorTarget(source, destination);
        }

        const source_index = try self.acquireRenderTarget(source);
        try self.transitionRenderTargetToColorAttachment(source_index);
        if (!self.render_targets.items[source_index].initialized) return false;
        const destination_index = try self.acquireRenderTarget(destination);
        try self.transitionRenderTargetToColorAttachment(destination_index);

        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        const source_image = self.render_targets.items[source_index].image.handle;
        const destination_image = self.render_targets.items[destination_index].image.handle;
        try self.transitionTrackedImage(
            command_buffer,
            source_image,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.transfer_source_usage,
        );
        try self.transitionTrackedImage(
            command_buffer,
            destination_image,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.transfer_destination_usage,
        );
        const region = vk.ImageResolve{
            .source_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .destination_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .extent = .{
                .width = source.descriptor.width,
                .height = source.descriptor.height,
                .depth = 1,
            },
        };
        self.device_functions.cmd_resolve_image(
            command_buffer,
            source_image,
            vk.image_layout_transfer_src_optimal,
            destination_image,
            vk.image_layout_transfer_dst_optimal,
            1,
            @ptrCast(&region),
        );
        try self.transitionTrackedImage(
            command_buffer,
            source_image,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.color_attachment_usage,
        );
        try self.transitionTrackedImage(
            command_buffer,
            destination_image,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.color_attachment_usage,
        );
        try self.submitOneShot(command_buffer);

        self.render_target_sequence +%= 1;
        const dest = &self.render_targets.items[destination_index];
        dest.initialized = true;
        dest.shader_read_layout = false;
        dest.gpu_generation +%= 1;
        _ = self.image_aliases.markWrite(dest.alias_token);
        dest.last_used_sequence = self.render_target_sequence;
        self.render_targets.items[source_index].shader_read_layout = false;
        self.render_targets.items[source_index].last_used_sequence = self.render_target_sequence;

        if (self.reported_color_resolves < 4 or log_verbose_gpu) {
            self.reported_color_resolves += 1;
            std.debug.print(
                "[vulkan dcb] color resolve 0x{x} -> 0x{x} {d}x{d} samples={d}\n",
                .{
                    source.descriptor.address,
                    destination.descriptor.address,
                    destination.descriptor.width,
                    destination.descriptor.height,
                    source.descriptor.fragments_log2,
                },
            );
        }
        return true;
    }

    fn resolveSingleSampleColorTarget(
        self: *Renderer,
        source: GuestColorTarget,
        destination: GuestColorTarget,
    ) anyerror!bool {
        var source_index: ?usize = null;
        for (self.render_targets.items, 0..) |cached, index| {
            if (cached.target.descriptor.address != source.descriptor.address or
                cached.target.descriptor.width != source.descriptor.width or
                cached.target.descriptor.height != source.descriptor.height or
                cached.target.format.vulkan != source.format.vulkan)
            {
                continue;
            }
            source_index = index;
            break;
        }
        const index = source_index orelse return Error.MissingPresentedFrame;
        if (try self.blitResidentColorTarget(index, destination, false)) |_| return true;
        try self.materializeRenderTarget(index);

        var resolved_index: ?usize = null;
        var resolved_sequence: u64 = 0;
        for (self.completed_frames.items, 0..) |cached, frame_index| {
            if (cached.guest_address != source.descriptor.address or
                cached.width != source.descriptor.width or
                cached.height != source.descriptor.height or
                cached.sequence < resolved_sequence)
            {
                continue;
            }
            resolved_index = frame_index;
            resolved_sequence = cached.sequence;
        }
        const frame_index = resolved_index orelse return Error.MissingPresentedFrame;
        const pixels = try self.allocator.dupe(u8, self.completed_frames.items[frame_index].pixels.items);
        defer self.allocator.free(pixels);
        try self.recordGuestColorTarget(destination, pixels);

        for (self.render_targets.items) |*cached| {
            if (cached.target.descriptor.address != destination.descriptor.address) continue;
            cached.initialized = false;
            cached.gpu_generation = 0;
            cached.host_generation = 0;
        }
        return true;
    }

    /// Copies an exact single-sample colour attachment entirely on the GPU.
    /// Both guest resolves and Unity's identity compositor use this shape;
    /// materializing the source and immediately uploading identical bytes to
    /// another attachment is an avoidable full-frame device/host round trip.
    fn blitResidentColorTarget(
        self: *Renderer,
        source_index: usize,
        destination: GuestColorTarget,
        flip_vertical: bool,
    ) anyerror!?usize {
        if (source_index >= self.render_targets.items.len) return null;
        const initial_source = self.render_targets.items[source_index];
        if (!initial_source.initialized or
            initial_source.target.descriptor.fragments_log2 != 0 or
            destination.descriptor.fragments_log2 != 0 or
            initial_source.target.descriptor.address == destination.descriptor.address or
            initial_source.target.descriptor.width != destination.descriptor.width or
            initial_source.target.descriptor.height != destination.descriptor.height)
        {
            return null;
        }

        // Make the source ineligible for LRU eviction while acquiring a cache
        // slot for a destination which may not have been seen before.
        self.render_target_sequence +%= 1;
        self.render_targets.items[source_index].last_used_sequence = self.render_target_sequence;
        const destination_index = try self.acquireRenderTarget(destination);
        if (destination_index == source_index) return destination_index;

        const source = self.render_targets.items[source_index];
        const dest = self.render_targets.items[destination_index];
        // A cache eviction during destination acquisition must never leave us
        // recording a transfer from the replacement image in the old slot.
        if (!source.initialized or source.image.handle != initial_source.image.handle) return null;

        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        try self.transitionTrackedImage(
            command_buffer,
            source.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.transfer_source_usage,
        );
        try self.transitionTrackedImage(
            command_buffer,
            dest.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.transfer_destination_usage,
        );
        const blit = vk.ImageBlit{
            .source_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .source_offsets = .{
                .{ .x = 0, .y = 0, .z = 0 },
                .{
                    .x = @intCast(source.target.descriptor.width),
                    .y = @intCast(source.target.descriptor.height),
                    .z = 1,
                },
            },
            .destination_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .destination_offsets = .{
                .{ .x = 0, .y = 0, .z = 0 },
                .{
                    .x = @intCast(destination.descriptor.width),
                    .y = @intCast(destination.descriptor.height),
                    .z = 1,
                },
            },
        };
        self.device_functions.cmd_blit_image(
            command_buffer,
            source.image.handle,
            vk.image_layout_transfer_src_optimal,
            dest.image.handle,
            vk.image_layout_transfer_dst_optimal,
            1,
            @ptrCast(&blit),
            vk.filter_nearest,
        );
        try self.transitionTrackedImage(
            command_buffer,
            source.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            if (source.shader_read_layout) image_state.shader_read_usage else image_state.color_attachment_usage,
        );
        try self.transitionTrackedImage(
            command_buffer,
            dest.image.handle,
            .{ .aspect_mask = vk.image_aspect_color_bit },
            image_state.color_attachment_usage,
        );
        try self.submitOneShot(command_buffer);

        self.render_target_sequence +%= 1;
        const cached_destination = &self.render_targets.items[destination_index];
        cached_destination.initialized = true;
        cached_destination.shader_read_layout = false;
        cached_destination.gpu_generation +%= 1;
        _ = self.image_aliases.markWrite(cached_destination.alias_token);
        cached_destination.last_used_sequence = self.render_target_sequence;
        if (flip_vertical) cached_destination.scanout_flip_vertical = true;
        self.render_targets.items[source_index].last_used_sequence = self.render_target_sequence;
        self.latest_render_target_index = destination_index;
        for (self.completed_frames.items) |*frame| {
            if (frame.guest_address == destination.descriptor.address) frame.needs_writeback = false;
        }
        return destination_index;
    }

    fn drawPersistentGraphicsShaders(
        self: *Renderer,
        vertex_words: []const u32,
        fragment_words: []const u32,
        vertex_scalars: []const gpu.ShaderSpirvScalarRegister,
        fragment_scalars: []const gpu.ShaderSpirvScalarRegister,
        pipeline_state: GraphicsPipelineState,
        target: GuestColorTarget,
        extra_colors: []const GuestColorTarget,
        depth: ?GuestDepthTarget,
        depth_clear_requested: bool,
        bind_graphics_descriptors: bool,
        draw: GuestDraw,
    ) anyerror!void {
        const setup_started = hostTimestampNs();
        const pinned_sequence = std.math.maxInt(u64);
        const target_index = try self.acquireRenderTarget(target);
        try self.transitionRenderTargetToColorAttachment(target_index);
        self.render_targets.items[target_index].last_used_sequence = pinned_sequence;
        var extra_indices: [gpu.resources.color_target_count - 1]usize = undefined;
        for (extra_colors, 0..) |extra, extra_index| {
            const index = try self.acquireRenderTarget(extra);
            try self.transitionRenderTargetToColorAttachment(index);
            self.render_targets.items[index].last_used_sequence = pinned_sequence;
            extra_indices[extra_index] = index;
        }
        const cached_snapshot = self.render_targets.items[target_index];
        const frame_bytes = try colorTargetFrameBytes(target);
        const report_checkpoints = !self.reported_first_graphics_draw_checkpoints;
        if (report_checkpoints) std.debug.print(
            "[vulkan dcb] first graphics draw: target ready bytes={d} initialized={any}\n",
            .{ frame_bytes, cached_snapshot.initialized },
        );

        var initial_upload: ?OwnedBuffer = null;
        defer if (initial_upload) |buffer| self.destroyBuffer(buffer);
        const multisampled = target.descriptor.fragments_log2 != 0;
        if (!cached_snapshot.initialized and !multisampled) {
            try self.flushPendingGuestWrite(target.descriptor.address, frame_bytes);
            const frame = try self.allocator.alloc(u8, frame_bytes);
            defer self.allocator.free(frame);
            const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
            const reader = gpu.ShaderMemoryReader{ .context = memory.context, .read_fn = memory.read };
            try self.stageInitialColorTarget(target, reader, frame);
            initial_upload = try self.createBuffer(
                frame_bytes,
                vk.buffer_usage_transfer_src_bit,
                vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
            );
            try self.writeMapped(initial_upload.?, frame);
            self.frame_profile.upload_bytes += frame_bytes;
            self.frame_profile.target_upload_bytes += frame_bytes;
            if (report_checkpoints) std.debug.print("[vulkan dcb] first graphics draw: initial target staged\n", .{});
        }

        var index_upload: ?DrawUploadSlice = null;
        if (draw.index_count) |index_count| {
            if (index_count != 0) {
                const index_stride: u64 = if (draw.index_uint32) 4 else 2;
                const index_bytes = std.math.mul(u64, index_count, index_stride) catch
                    return Error.GuestBufferTooLarge;
                if (index_bytes == 0 or index_bytes > maximum_frame_bytes) return Error.GuestBufferTooLarge;
                const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
                const bytes: usize = @intCast(index_bytes);
                const indices = try self.allocator.alloc(u8, bytes);
                defer self.allocator.free(indices);
                if (!memory.read(memory.context, draw.index_address, indices)) return Error.GuestMemoryReadFailed;
                index_upload = try self.allocateDrawUpload(bytes);
                const upload_mapping = self.draw_upload_mapping orelse return Error.MemoryMapFailed;
                const destination = upload_mapping[@intCast(index_upload.?.offset)..][0..bytes];
                @memcpy(destination, indices);
                self.frame_profile.upload_bytes += bytes;
                self.frame_profile.index_upload_bytes += bytes;
            }
        }

        if (report_checkpoints) std.debug.print(
            "[vulkan dcb] first graphics draw: compiling pipeline vs_words={d} ps_words={d}\n",
            .{ vertex_words.len, fragment_words.len },
        );
        if (report_checkpoints) std.debug.print(
            "[vulkan dcb] first graphics draw: viewport={d}x{d} scissor={d}x{d} discard={d} colors={d} write=0x{x} blend={d} extras={d}\n",
            .{
                @as(f32, @bitCast(pipeline_state.viewport_width_bits)),
                @as(f32, @bitCast(pipeline_state.viewport_height_bits)),
                pipeline_state.scissor_width,
                pipeline_state.scissor_height,
                pipeline_state.rasterizer_discard,
                pipeline_state.color_attachment_count,
                pipeline_state.color_write_masks[0],
                pipeline_state.blend_enables[0],
                extra_colors.len,
            },
        );
        if (report_checkpoints) {
            for (extra_colors) |extra| {
                std.debug.print(
                    "  extra color slot={d} addr=0x{x} {d}x{d} fmt={d}/{d} write=0x{x}\n",
                    .{
                        extra.descriptor.slot,
                        extra.descriptor.address,
                        extra.descriptor.width,
                        extra.descriptor.height,
                        extra.descriptor.format,
                        extra.descriptor.number_type,
                        extra.descriptor.write_mask,
                    },
                );
            }
        }
        var extra_uploads: [gpu.resources.color_target_count - 1]?OwnedBuffer = @splat(null);
        defer for (extra_uploads) |buffer| if (buffer) |owned| self.destroyBuffer(owned);
        for (extra_colors, extra_indices[0..extra_colors.len], 0..) |extra, extra_index, upload_index| {
            const extra_cached = self.render_targets.items[extra_index];
            if (extra_cached.initialized or extra.descriptor.fragments_log2 != 0) continue;
            const extra_bytes = try colorTargetFrameBytes(extra);
            try self.flushPendingGuestWrite(extra.descriptor.address, extra_bytes);
            const frame = try self.allocator.alloc(u8, extra_bytes);
            defer self.allocator.free(frame);
            const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
            const reader = gpu.ShaderMemoryReader{ .context = memory.context, .read_fn = memory.read };
            try self.stageInitialColorTarget(extra, reader, frame);
            extra_uploads[upload_index] = try self.createBuffer(
                extra_bytes,
                vk.buffer_usage_transfer_src_bit,
                vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
            );
            try self.writeMapped(extra_uploads[upload_index].?, frame);
            self.frame_profile.upload_bytes += extra_bytes;
            self.frame_profile.target_upload_bytes += extra_bytes;
        }
        // A depth attachment changes the render pass a pipeline must be
        // compatible with, so it has to be resolved before the pipeline is
        // looked up rather than at the point the pass begins.
        const depth_index: ?usize = if (depth) |plane| try self.acquireDepthTarget(plane) else null;
        const multi_color = pipeline_state.color_attachment_count > 1;
        var color_pass: ?ColorPass = null;
        const depth_pass: ?DepthPass = if (!multi_color) blk: {
            break :blk if (depth_index) |index|
                try self.acquireDepthPass(target_index, index)
            else
                null;
        } else blk: {
            var color_views: [gpu.resources.color_target_count]vk.ImageView = @splat(0);
            var color_formats: [gpu.resources.color_target_count]u32 = @splat(0);
            color_views[target.descriptor.slot] = self.render_targets.items[target_index].view;
            color_formats[target.descriptor.slot] = target.format.vulkan;
            for (extra_colors, extra_indices[0..extra_colors.len]) |extra, extra_index| {
                color_views[extra.descriptor.slot] = self.render_targets.items[extra_index].view;
                color_formats[extra.descriptor.slot] = extra.format.vulkan;
            }
            const depth_view: vk.ImageView = if (depth_index) |index|
                self.depth_targets.items[index].view
            else
                0;
            const depth_format: u32 = if (depth) |plane| plane.format else 0;
            color_pass = try self.acquireColorPass(
                color_views,
                color_formats,
                @intCast(pipeline_state.color_attachment_count),
                depth_view,
                depth_format,
                pipeline_state.rasterization_samples,
                pipeline_state.width,
                pipeline_state.height,
            );
            break :blk null;
        };
        const pass_handle = if (color_pass) |pass|
            pass.render_pass
        else if (depth_pass) |pass|
            pass.render_pass
        else
            cached_snapshot.render_pass;
        const framebuffer_handle = if (color_pass) |pass|
            pass.framebuffer
        else if (depth_pass) |pass|
            pass.framebuffer
        else
            cached_snapshot.framebuffer;
        self.frame_profile.graphics_setup_ns +|= elapsedHostNanoseconds(setup_started);
        const pipeline_lookup_started = hostTimestampNs();
        const pipeline = try self.getGraphicsPipeline(
            pass_handle,
            pipeline_state,
            vertex_words,
            fragment_words,
        );
        self.frame_profile.graphics_pipeline_lookup_ns +|= elapsedHostNanoseconds(pipeline_lookup_started);
        const scalar_upload_started = hostTimestampNs();
        try self.writeGraphicsScalarValues(vertex_scalars, fragment_scalars);
        self.frame_profile.graphics_scalar_upload_ns +|= elapsedHostNanoseconds(scalar_upload_started);
        if (report_checkpoints) std.debug.print("[vulkan dcb] first graphics draw: pipeline ready\n", .{});
        const record_started = hostTimestampNs();
        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);

        if (initial_upload) |upload| {
            try self.transitionTrackedImage(
                command_buffer,
                cached_snapshot.image.handle,
                .{ .aspect_mask = vk.image_aspect_color_bit },
                image_state.transfer_destination_usage,
            );
            const upload_copy = vk.BufferImageCopy{
                .image_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
                .image_extent = .{
                    .width = target.descriptor.width,
                    .height = target.descriptor.height,
                    .depth = 1,
                },
            };
            self.device_functions.cmd_copy_buffer_to_image(
                command_buffer,
                upload.handle,
                cached_snapshot.image.handle,
                vk.image_layout_transfer_dst_optimal,
                1,
                @ptrCast(&upload_copy),
            );
            try self.transitionTrackedImage(
                command_buffer,
                cached_snapshot.image.handle,
                .{ .aspect_mask = vk.image_aspect_color_bit },
                image_state.color_attachment_usage,
            );
        } else if (!cached_snapshot.initialized) {
            try self.transitionTrackedImage(
                command_buffer,
                cached_snapshot.image.handle,
                .{ .aspect_mask = vk.image_aspect_color_bit },
                image_state.color_attachment_usage,
            );
        }

        for (extra_colors, extra_indices[0..extra_colors.len], extra_uploads[0..extra_colors.len]) |extra, extra_index, extra_upload| {
            const extra_cached = self.render_targets.items[extra_index];
            if (extra_upload) |upload| {
                try self.transitionTrackedImage(
                    command_buffer,
                    extra_cached.image.handle,
                    .{ .aspect_mask = vk.image_aspect_color_bit },
                    image_state.transfer_destination_usage,
                );
                const upload_copy = vk.BufferImageCopy{
                    .image_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
                    .image_extent = .{
                        .width = extra.descriptor.width,
                        .height = extra.descriptor.height,
                        .depth = 1,
                    },
                };
                self.device_functions.cmd_copy_buffer_to_image(
                    command_buffer,
                    upload.handle,
                    extra_cached.image.handle,
                    vk.image_layout_transfer_dst_optimal,
                    1,
                    @ptrCast(&upload_copy),
                );
                try self.transitionTrackedImage(
                    command_buffer,
                    extra_cached.image.handle,
                    .{ .aspect_mask = vk.image_aspect_color_bit },
                    image_state.color_attachment_usage,
                );
            } else if (!extra_cached.initialized) {
                try self.transitionTrackedImage(
                    command_buffer,
                    extra_cached.image.handle,
                    .{ .aspect_mask = vk.image_aspect_color_bit },
                    image_state.color_attachment_usage,
                );
            }
        }

        if (depth_index) |index| {
            try self.prepareDepthAttachment(command_buffer, index, depth_clear_requested);
        }
        const begin_info = vk.RenderPassBeginInfo{
            .render_pass = pass_handle,
            .framebuffer = framebuffer_handle,
            .render_area = .{
                .offset = .{ .x = 0, .y = 0 },
                .extent = .{ .width = pipeline_state.width, .height = pipeline_state.height },
            },
            .clear_value_count = 0,
            .clear_values = undefined,
        };
        self.device_functions.cmd_begin_render_pass(command_buffer, &begin_info, vk.subpass_contents_inline);
        self.device_functions.cmd_bind_pipeline(command_buffer, vk.pipeline_bind_point_graphics, pipeline);
        if (bind_graphics_descriptors or vertex_scalars.len != 0 or fragment_scalars.len != 0) {
            self.device_functions.cmd_bind_descriptor_sets(
                command_buffer,
                vk.pipeline_bind_point_graphics,
                self.compute_pipeline_layout,
                0,
                1,
                @ptrCast(&self.descriptor_set),
                0,
                null,
            );
        }

        if (draw.index_count) |index_count| {
            if (index_count != 0) {
                self.device_functions.cmd_bind_index_buffer(
                    command_buffer,
                    index_upload.?.buffer,
                    index_upload.?.offset,
                    if (draw.index_uint32) vk.index_type_uint32 else vk.index_type_uint16,
                );
                self.device_functions.cmd_draw_indexed(
                    command_buffer,
                    index_count,
                    draw.instance_count,
                    0,
                    draw.vertex_offset,
                    draw.first_instance,
                );
            }
        } else if (draw.vertex_count != 0) {
            self.device_functions.cmd_draw(
                command_buffer,
                draw.vertex_count,
                draw.instance_count,
                draw.first_vertex,
                draw.first_instance,
            );
        }
        self.device_functions.cmd_end_render_pass(command_buffer);
        try self.submitOneShot(command_buffer);
        self.frame_profile.graphics_record_ns +|= elapsedHostNanoseconds(record_started);
        if (report_checkpoints) {
            std.debug.print("[vulkan dcb] first graphics draw: submitted\n", .{});
            self.reported_first_graphics_draw_checkpoints = true;
        }

        self.render_target_sequence +%= 1;
        const cached = &self.render_targets.items[target_index];
        cached.initialized = true;
        cached.gpu_generation +%= 1;
        _ = self.image_aliases.markWrite(cached.alias_token);
        cached.last_used_sequence = self.render_target_sequence;
        for (extra_indices[0..extra_colors.len]) |extra_index| {
            self.render_target_sequence +%= 1;
            const extra_cached = &self.render_targets.items[extra_index];
            extra_cached.initialized = true;
            extra_cached.gpu_generation +%= 1;
            _ = self.image_aliases.markWrite(extra_cached.alias_token);
            extra_cached.last_used_sequence = self.render_target_sequence;
        }
        if (depth_index) |index| {
            const depth_cached = &self.depth_targets.items[index];
            depth_cached.gpu_generation +%= 1;
            _ = self.image_aliases.markWrite(depth_cached.alias_token);
            if (depth_cached.stencil_alias_token) |token| _ = self.image_aliases.markWrite(token);
        }
        self.latest_render_target_index = target_index;
        if (report_checkpoints and self.capture_first_graphics_frame) {
            try self.materializeRenderTarget(target_index);
            std.debug.print(
                "[vulkan dcb] first graphics draw: readback colored_pixels={d}\n",
                .{self.graphics_probe_colored_pixels},
            );
        }
    }

    fn drawGraphicsShaders(
        self: *Renderer,
        vertex_words: []const u32,
        fragment_words: []const u32,
        vertex_scalars: []const gpu.ShaderSpirvScalarRegister,
        fragment_scalars: []const gpu.ShaderSpirvScalarRegister,
        pipeline_state: GraphicsPipelineState,
        guest_target: ?GuestColorTarget,
        extra_colors: []const GuestColorTarget,
        depth: ?GuestDepthTarget,
        depth_clear_requested: bool,
        bind_graphics_descriptors: bool,
        validate_diagnostic_color: bool,
        draw: GuestDraw,
    ) anyerror!void {
        if (guest_target) |target| {
            return self.drawPersistentGraphicsShaders(
                vertex_words,
                fragment_words,
                vertex_scalars,
                fragment_scalars,
                pipeline_state,
                target,
                extra_colors,
                depth,
                depth_clear_requested,
                bind_graphics_descriptors,
                draw,
            );
        }
        const width = pipeline_state.width;
        const height = pipeline_state.height;
        const frame_pixels = std.math.mul(usize, @as(usize, width), @as(usize, height)) catch {
            return Error.UnsupportedColorTarget;
        };
        const frame_bytes = std.math.mul(usize, frame_pixels, 4) catch return Error.UnsupportedColorTarget;
        if (frame_bytes == 0 or frame_bytes > maximum_frame_bytes) return Error.UnsupportedColorTarget;
        var frame = try self.allocator.alloc(u8, frame_bytes);
        defer self.allocator.free(frame);
        var upload: ?OwnedBuffer = null;
        defer if (upload) |buffer| self.destroyBuffer(buffer);
        if (guest_target) |target| {
            if (target.layout.staging_bytes != frame_bytes) return Error.UnsupportedColorTarget;
            const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
            const reader = gpu.ShaderMemoryReader{ .context = memory.context, .read_fn = memory.read };
            try self.stageColorTarget(target, reader, frame);
            upload = try self.createBuffer(
                frame_bytes,
                vk.buffer_usage_transfer_src_bit,
                vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
            );
            try self.writeMapped(upload.?, frame);
        }
        const color = try self.createImage(
            width,
            height,
            vk.format_r8g8b8a8_unorm,
            vk.image_usage_color_attachment_bit | vk.image_usage_transfer_src_bit |
                (if (guest_target != null) vk.image_usage_transfer_dst_bit else 0),
        );
        defer self.destroyImage(color);

        const view_info = vk.ImageViewCreateInfo{
            .image = color.handle,
            .format = vk.format_r8g8b8a8_unorm,
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        var view: vk.ImageView = 0;
        if (self.device_functions.create_image_view(self.device, &view_info, null, &view) != vk.success) {
            return Error.ImageViewCreationFailed;
        }
        defer self.destroyImageView(view);

        // The non-persistent path doubles as the compatibility colour
        // attachment for a guest depth-only draw.  Keep the private RGBA image
        // (with writes masked off by the caller), but pair it with the real DB
        // allocation so the raster work is not mistaken for a VideoOut pass.
        const depth_index: ?usize = if (depth) |plane| try self.acquireDepthTarget(plane) else null;
        const render_pass = if (depth) |plane|
            try self.createDepthGraphicsRenderPass(
                vk.format_r8g8b8a8_unorm,
                plane.format,
                guest_target != null,
                vk.sample_count_1_bit,
            )
        else
            try self.createGraphicsRenderPass(
                vk.format_r8g8b8a8_unorm,
                guest_target != null,
                vk.sample_count_1_bit,
            );
        defer self.destroyRenderPass(render_pass);
        var framebuffer_views = [2]vk.ImageView{ view, 0 };
        if (depth_index) |index| framebuffer_views[1] = self.depth_targets.items[index].view;
        const framebuffer_info = vk.FramebufferCreateInfo{
            .render_pass = render_pass,
            .attachment_count = if (depth_index != null) 2 else 1,
            .attachments = &framebuffer_views,
            .width = width,
            .height = height,
        };
        var framebuffer: vk.Framebuffer = 0;
        if (self.device_functions.create_framebuffer(self.device, &framebuffer_info, null, &framebuffer) != vk.success) {
            return Error.FramebufferCreationFailed;
        }
        defer self.destroyFramebuffer(framebuffer);

        const pipeline = try self.getGraphicsPipeline(render_pass, pipeline_state, vertex_words, fragment_words);
        const readback = try self.createBuffer(
            frame_bytes,
            vk.buffer_usage_transfer_dst_bit,
            vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
        );
        defer self.destroyBuffer(readback);

        const command_buffer = try self.beginOneShot();
        defer self.releaseOneShot(command_buffer);
        if (upload) |upload_buffer| {
            const transfer_barrier = vk.ImageMemoryBarrier{
                .source_access_mask = 0,
                .destination_access_mask = vk.access_transfer_write_bit,
                .old_layout = vk.image_layout_undefined,
                .new_layout = vk.image_layout_transfer_dst_optimal,
                .image = color.handle,
                .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
            };
            self.device_functions.cmd_pipeline_barrier(
                command_buffer,
                vk.pipeline_stage_top_of_pipe_bit,
                vk.pipeline_stage_transfer_bit,
                0,
                0,
                null,
                0,
                null,
                1,
                @ptrCast(&transfer_barrier),
            );
            const upload_copy = vk.BufferImageCopy{
                .image_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
                .image_extent = .{ .width = width, .height = height, .depth = 1 },
            };
            self.device_functions.cmd_copy_buffer_to_image(
                command_buffer,
                upload_buffer.handle,
                color.handle,
                vk.image_layout_transfer_dst_optimal,
                1,
                @ptrCast(&upload_copy),
            );
            const attachment_barrier = vk.ImageMemoryBarrier{
                .source_access_mask = vk.access_transfer_write_bit,
                .destination_access_mask = vk.access_color_attachment_read_bit | vk.access_color_attachment_write_bit,
                .old_layout = vk.image_layout_transfer_dst_optimal,
                .new_layout = vk.image_layout_color_attachment_optimal,
                .image = color.handle,
                .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
            };
            self.device_functions.cmd_pipeline_barrier(
                command_buffer,
                vk.pipeline_stage_transfer_bit,
                vk.pipeline_stage_color_attachment_output_bit,
                0,
                0,
                null,
                0,
                null,
                1,
                @ptrCast(&attachment_barrier),
            );
        }
        if (depth_index) |index| {
            try self.prepareDepthAttachment(command_buffer, index, depth_clear_requested);
        }
        const clear = vk.ClearValue{ .color = .{ .float32 = .{ 0, 0, 0, 1 } } };
        const begin_info = vk.RenderPassBeginInfo{
            .render_pass = render_pass,
            .framebuffer = framebuffer,
            .render_area = .{
                .offset = .{ .x = 0, .y = 0 },
                .extent = .{ .width = width, .height = height },
            },
            .clear_value_count = if (guest_target == null) 1 else 0,
            .clear_values = @ptrCast(&clear),
        };
        self.device_functions.cmd_begin_render_pass(command_buffer, &begin_info, vk.subpass_contents_inline);
        self.device_functions.cmd_bind_pipeline(command_buffer, vk.pipeline_bind_point_graphics, pipeline);
        if (bind_graphics_descriptors) {
            self.device_functions.cmd_bind_descriptor_sets(
                command_buffer,
                vk.pipeline_bind_point_graphics,
                self.compute_pipeline_layout,
                0,
                1,
                @ptrCast(&self.descriptor_set),
                0,
                null,
            );
        }
        var index_upload: ?OwnedBuffer = null;
        defer if (index_upload) |buffer| self.destroyBuffer(buffer);
        if (draw.index_count) |index_count| {
            if (index_count != 0) {
                const index_stride: u64 = if (draw.index_uint32) 4 else 2;
                const index_bytes = std.math.mul(u64, index_count, index_stride) catch {
                    return Error.GuestBufferTooLarge;
                };
                if (index_bytes == 0 or index_bytes > maximum_frame_bytes) {
                    return Error.GuestBufferTooLarge;
                }
                const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
                const bytes: usize = @intCast(index_bytes);
                const indices = try self.allocator.alloc(u8, bytes);
                defer self.allocator.free(indices);
                if (!memory.read(memory.context, draw.index_address, indices)) {
                    return Error.GuestMemoryReadFailed;
                }
                index_upload = try self.createBuffer(
                    bytes,
                    vk.buffer_usage_index_buffer_bit | vk.buffer_usage_transfer_dst_bit,
                    vk.memory_property_host_visible_bit | vk.memory_property_host_coherent_bit,
                );
                try self.writeMapped(index_upload.?, indices);
                self.device_functions.cmd_bind_index_buffer(
                    command_buffer,
                    index_upload.?.handle,
                    0,
                    if (draw.index_uint32) vk.index_type_uint32 else vk.index_type_uint16,
                );
                self.device_functions.cmd_draw_indexed(
                    command_buffer,
                    index_count,
                    draw.instance_count,
                    0,
                    draw.vertex_offset,
                    draw.first_instance,
                );
            }
        } else if (draw.vertex_count != 0) {
            self.device_functions.cmd_draw(
                command_buffer,
                draw.vertex_count,
                draw.instance_count,
                draw.first_vertex,
                draw.first_instance,
            );
        }
        self.device_functions.cmd_end_render_pass(command_buffer);

        const image_barrier = vk.ImageMemoryBarrier{
            .source_access_mask = vk.access_color_attachment_write_bit,
            .destination_access_mask = vk.access_transfer_read_bit,
            .old_layout = vk.image_layout_color_attachment_optimal,
            .new_layout = vk.image_layout_transfer_src_optimal,
            .image = color.handle,
            .subresource_range = .{ .aspect_mask = vk.image_aspect_color_bit },
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_color_attachment_output_bit,
            vk.pipeline_stage_transfer_bit,
            0,
            0,
            null,
            0,
            null,
            1,
            @ptrCast(&image_barrier),
        );
        const copy = vk.BufferImageCopy{
            .image_subresource = .{ .aspect_mask = vk.image_aspect_color_bit },
            .image_extent = .{ .width = width, .height = height, .depth = 1 },
        };
        self.device_functions.cmd_copy_image_to_buffer(
            command_buffer,
            color.handle,
            vk.image_layout_transfer_src_optimal,
            readback.handle,
            1,
            @ptrCast(&copy),
        );
        const host_barrier = vk.BufferMemoryBarrier{
            .source_access_mask = vk.access_transfer_write_bit,
            .destination_access_mask = vk.access_host_read_bit,
            .buffer = readback.handle,
            .offset = 0,
            .size = readback.size,
        };
        self.device_functions.cmd_pipeline_barrier(
            command_buffer,
            vk.pipeline_stage_transfer_bit,
            vk.pipeline_stage_host_bit,
            0,
            0,
            null,
            1,
            @ptrCast(&host_barrier),
            0,
            null,
        );
        try self.submitOneShot(command_buffer);
        if (depth_index) |index| {
            const depth_cached = &self.depth_targets.items[index];
            depth_cached.gpu_generation +%= 1;
            _ = self.image_aliases.markWrite(depth_cached.alias_token);
            if (depth_cached.stencil_alias_token) |token| _ = self.image_aliases.markWrite(token);
        }
        try self.readMapped(readback, frame);
        if (guest_target) |target| {
            if (target.descriptor.force_destination_alpha_one) forceDestinationAlphaOne(frame);
            try self.recordGuestColorTarget(target, frame);
        }
        if (frame.len == self.graphics_probe_frame.len) @memcpy(&self.graphics_probe_frame, frame);

        const center = (@as(usize, height / 2) * width + width / 2) * 4;
        const corner = frame[0..4];
        const center_pixel = frame[center..][0..4];
        if (validate_diagnostic_color and
            (!std.mem.eql(u8, corner, &.{ 0, 0, 0, 255 }) or
                center_pixel[0] < 200 or center_pixel[1] < 40 or center_pixel[1] > 100 or
                center_pixel[2] > 80 or center_pixel[3] != 255))
        {
            return Error.GraphicsProbeReadbackMismatch;
        }
        var colored: u32 = 0;
        var pixel: usize = 0;
        while (pixel < frame.len) : (pixel += 4) {
            if (frame[pixel] != 0 or frame[pixel + 1] != 0 or frame[pixel + 2] != 0) {
                colored += 1;
            }
        }
        if (validate_diagnostic_color and
            (colored == 0 or colored >= width * height))
        {
            return Error.GraphicsProbeReadbackMismatch;
        }
        self.graphics_probe_colored_pixels = colored;

        if (guest_target) |target| {
            if (log_verbose_gpu) std.debug.print(
                "[vulkan dcb] writeback: {d}x{d} @0x{x} colored={d}/{d} corner=({d},{d},{d},{d}) center=({d},{d},{d},{d})\n",
                .{
                    width,
                    height,
                    target.descriptor.address,
                    colored,
                    width * height,
                    corner[0],
                    corner[1],
                    corner[2],
                    corner[3],
                    center_pixel[0],
                    center_pixel[1],
                    center_pixel[2],
                    center_pixel[3],
                },
            );
            // Guest PS often leaves alpha at 0 for premultiplied/unused paths;
            // force opaque so the host window and PPM dump show RGB content.
            makePresentationOpaque(frame);
            // Dump the first non-black guest frame for offline inspection.
            if (self.frame_dumps == 0 and colored != 0) {
                dumpFramePpm("out\\first-frame.ppm", width, height, frame);
                self.frame_dumps += 1;
            }
            // Present immediately so the window shows the render target even if
            // the title never reaches SetFlip (e.g. managed null faults mid-init).
            self.eagerPresentFrame(.{
                .pixels = frame,
                .width = width,
                .height = height,
                .row_pitch_bytes = width * 4,
                .guest_address = target.descriptor.address,
                .flip = .{
                    .video_out_handle = 0,
                    .display_buffer_index = 0,
                    .mode = 0,
                    .argument = 0,
                },
            });
        }
    }

    fn eagerPresentFrame(self: *Renderer, frame: PresentedFrame) void {
        const sink = self.presentation_sink orelse return;
        if (frame.width == 0 or frame.height == 0 or frame.pixels.len == 0) return;
        if (!sink.present(sink.context, frame)) {
            std.debug.print(
                "[vulkan dcb] eager present rejected (err={s})\n",
                .{if (self.last_flip_error) |err| @errorName(err) else "unknown"},
            );
            return;
        }
        self.eager_presents += 1;
        self.presented_frames += 1;
        if (log_verbose_gpu) std.debug.print(
            "[vulkan dcb] eager present ok: {d}x{d} @0x{x} (#{d})\n",
            .{ frame.width, frame.height, frame.guest_address, self.eager_presents },
        );
    }

    /// Lazy writeback: tiles `frame` into the guest allocation `target` names.
    /// Called only when the guest is about to observe the target — at flip,
    /// before a guest readback or a sampled-image staging of that address, or
    /// at a synchronization packet — never after every draw.
    fn commitGuestColorTarget(self: *Renderer, target: GuestColorTarget, frame: []const u8) anyerror!void {
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        const allocation_bytes = std.math.cast(usize, target.layout.required_source_bytes) orelse {
            return Error.UnsupportedColorTarget;
        };
        if (allocation_bytes > maximum_frame_bytes) return Error.UnsupportedColorTarget;
        const tiled = try self.allocator.alloc(u8, allocation_bytes);
        defer self.allocator.free(tiled);
        if (!memory.read(memory.context, target.descriptor.address, tiled)) return Error.GuestMemoryReadFailed;
        try target.layout.tile(frame, tiled);
        if (!memory.write(memory.context, target.descriptor.address, tiled)) return Error.GuestMemoryWriteFailed;
        try self.commitExpandedCmask(target);
        self.image_aliases.publishGuest(aliasRange(
            target.descriptor.address,
            target.layout.required_source_bytes,
        ));
        self.guest_color_target_writes += 1;
    }

    /// Host rendering publishes ordinary base-surface texels. Mark every
    /// active CMASK block expanded so a later cache miss never re-applies an
    /// obsolete fast clear over those newly written pixels.
    fn commitExpandedCmask(self: *Renderer, target: GuestColorTarget) anyerror!void {
        const descriptor = target.descriptor;
        if (!descriptor.cmask_fast_clear or descriptor.cmask_address == 0 or descriptor.dcc_enabled) return;
        const layout = gpu.CmaskLayout.fromColorTarget(descriptor) catch return;
        const byte_count = std.math.cast(usize, layout.required_bytes) orelse return;
        if (byte_count == 0 or byte_count > maximum_cmask_bytes) return;
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        const metadata = try self.allocator.alloc(u8, byte_count);
        defer self.allocator.free(metadata);
        if (!memory.read(memory.context, descriptor.cmask_address, metadata)) return Error.GuestMemoryReadFailed;

        var changed = false;
        for (0..layout.layers) |layer_index| {
            var y: u32 = 0;
            while (y < layout.height) : (y += 8) {
                var x: u32 = 0;
                while (x < layout.width) : (x += 8) {
                    const layer: u32 = @intCast(layer_index);
                    if (try layout.value(metadata, x, y, layer) == 0xf) continue;
                    try layout.setValue(metadata, x, y, layer, 0xf);
                    changed = true;
                }
            }
        }
        if (changed and !memory.write(memory.context, descriptor.cmask_address, metadata)) {
            return Error.GuestMemoryWriteFailed;
        }
    }

    /// Records a completed render in host memory without touching the guest
    /// allocation. The frame is presented from this host copy; the guest copy
    /// is produced by `flushPendingGuestWrites` only when it is actually
    /// needed, so a frame with many draws costs one tile+writeback instead of
    /// one per draw.
    fn recordGuestColorTarget(self: *Renderer, target: GuestColorTarget, frame: []const u8) anyerror!void {
        var frame_index: ?usize = null;
        for (self.completed_frames.items, 0..) |cached, index| {
            if (cached.guest_address != target.descriptor.address) continue;
            const previous = cached.target orelse continue;
            if (previous.descriptor.base_array_slice != target.descriptor.base_array_slice or
                previous.descriptor.last_array_slice != target.descriptor.last_array_slice or
                previous.descriptor.mip_level != target.descriptor.mip_level)
            {
                continue;
            }
            frame_index = index;
            break;
        }
        if (frame_index == null) {
            if (self.completed_frames.items.len < maximum_completed_frames) {
                try self.completed_frames.append(self.allocator, .{});
                frame_index = self.completed_frames.items.len - 1;
            } else {
                // Evicting a slot whose writeback is still pending would lose
                // the rendered frame for good; flush it before reuse.
                var oldest_index: usize = 0;
                for (self.completed_frames.items[1..], 1..) |cached, index| {
                    if (cached.sequence < self.completed_frames.items[oldest_index].sequence) oldest_index = index;
                }
                const evicted = &self.completed_frames.items[oldest_index];
                if (evicted.needs_writeback) {
                    if (evicted.target) |evicted_target| {
                        try self.commitGuestColorTarget(evicted_target, evicted.pixels.items);
                    }
                    evicted.needs_writeback = false;
                }
                frame_index = oldest_index;
            }
        }
        const cached = &self.completed_frames.items[frame_index.?];
        cached.pixels.clearRetainingCapacity();
        try cached.pixels.appendSlice(self.allocator, frame);
        self.frame_sequence +%= 1;
        cached.width = target.descriptor.width;
        cached.height = target.descriptor.height;
        cached.guest_address = target.descriptor.address;
        cached.sequence = self.frame_sequence;
        cached.target = target;
        cached.needs_writeback = true;
        self.latest_frame_index = frame_index;
    }

    /// Publishes every deferred guest writeback. Cheap when nothing is
    /// pending, which is the common case between synchronization packets.
    /// This is also the explicit host-observation boundary used by standalone
    /// DCB tests whose synthetic streams do not contain RELEASE_MEM or a flip.
    pub fn flushPendingGuestWrites(self: *Renderer) anyerror!void {
        try self.finishDrawBatch();
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        var storage_image_index: usize = 0;
        while (storage_image_index < self.storage_image_cache.items.len) : (storage_image_index += 1) {
            try self.flushCachedStorageImage(memory, storage_image_index);
        }
        var storage_buffer_index: usize = 0;
        while (storage_buffer_index < self.guest_buffers.items.len) : (storage_buffer_index += 1) {
            try self.flushGuestStorageBuffer(storage_buffer_index);
        }
        var target_index: usize = 0;
        while (target_index < self.render_targets.items.len) : (target_index += 1) {
            try self.materializeRenderTarget(target_index);
        }
        var depth_index: usize = 0;
        while (depth_index < self.depth_targets.items.len) : (depth_index += 1) {
            try self.materializeDepthTarget(depth_index);
        }
        for (self.completed_frames.items) |*cached| {
            if (!cached.needs_writeback) continue;
            const target = cached.target orelse continue;
            try self.commitGuestColorTarget(target, cached.pixels.items);
            cached.needs_writeback = false;
        }
    }

    /// Publishes dirty image writers whose allocation intersects a resource
    /// about to be reconstructed from guest memory. Exact base-address tests
    /// miss mip/subresource views and reinterpretations that start inside the
    /// same allocation; the common alias registry supplies the byte-range
    /// relation for every image cache.
    fn flushAliasedImageWrites(self: *Renderer, address: u64, visible_bytes: usize) anyerror!void {
        if (!self.canonical_image_aliases_enabled) return;
        const requested = aliasRange(address, visible_bytes);
        if (!requested.valid()) return;
        const authority = self.image_aliases.authorityForRange(requested);
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        for (self.storage_image_cache.items, 0..) |cached, index| {
            if (!cached.valid or !cached.gpu_dirty or
                (authority != 0 and cached.alias_token != authority) or
                !self.image_aliases.tokenOverlaps(cached.alias_token, requested))
            {
                continue;
            }
            try self.flushCachedStorageImage(memory, index);
        }
        for (self.render_targets.items, 0..) |cached, index| {
            if (!cached.initialized or cached.gpu_generation == cached.host_generation or
                (authority != 0 and cached.alias_token != authority) or
                !self.image_aliases.tokenOverlaps(cached.alias_token, requested))
            {
                continue;
            }
            try self.materializeRenderTarget(index);
        }
        for (self.depth_targets.items, 0..) |cached, index| {
            if (!cached.initialized or cached.gpu_generation == cached.host_generation) continue;
            const authoritative = authority == 0 or cached.alias_token == authority or
                (cached.stencil_alias_token != null and cached.stencil_alias_token.? == authority);
            if (!authoritative) continue;
            const depth_overlap = self.image_aliases.tokenOverlaps(cached.alias_token, requested);
            const stencil_overlap = if (cached.stencil_alias_token) |token|
                self.image_aliases.tokenOverlaps(token, requested)
            else
                false;
            if (depth_overlap or stencil_overlap) try self.materializeDepthTarget(index);
        }
    }

    /// Publishes only the deferred writeback for one guest address, used
    /// before guest memory at that address is staged or read.
    fn flushPendingGuestWrite(self: *Renderer, address: u64, visible_bytes: usize) anyerror!void {
        try self.flushAliasedImageWrites(address, visible_bytes);
        try self.flushGuestStorageImageRange(address, visible_bytes);
        try self.flushGuestStorageRange(address, visible_bytes);
        _ = try self.materializeRenderTargetAt(address);
        _ = try self.materializeHtileTargetAt(address, visible_bytes);
        for (self.completed_frames.items) |*cached| {
            if (!cached.needs_writeback or cached.guest_address != address) continue;
            const target = cached.target orelse continue;
            try self.commitGuestColorTarget(target, cached.pixels.items);
            cached.needs_writeback = false;
            return;
        }
    }

    fn drawGraphicsProbe(self: *Renderer) anyerror!void {
        try self.beginFrameDraw();
        return self.drawGraphicsShaders(
            &graphics_probe_vertex_spirv,
            &graphics_probe_fragment_spirv,
            &.{},
            &.{},
            GraphicsPipelineState.default(graphics_probe_width, graphics_probe_height),
            null,
            &.{},
            null,
            false,
            false,
            true,
            .{ .vertex_count = 3 },
        );
    }

    fn drawGuestGraphics(
        self: *Renderer,
        state: *const gpu.State,
        draw: GuestDraw,
        vertex_stage: gpu.resources.ShaderStage,
        target_override: ?gpu.resources.ColorTarget,
    ) anyerror!void {
        try self.beginFrameDraw();
        const memory = self.guest_memory orelse return Error.GuestMemoryUnavailable;
        const render_state = gpu.resources.decodeRenderState(state);
        if (!self.reported_first_scissor_state) {
            std.debug.print(
                "[vulkan dcb] first scissor state decoded={any} screen={any}/{any} window={any}/{any} generic={any}/{any} viewport={any}/{any} mode={any}\n",
                .{
                    render_state.scissor,
                    state.readRegister(.context, 0x00c),
                    state.readRegister(.context, 0x00d),
                    state.readRegister(.context, 0x081),
                    state.readRegister(.context, 0x082),
                    state.readRegister(.context, 0x090),
                    state.readRegister(.context, 0x091),
                    state.readRegister(.context, 0x094),
                    state.readRegister(.context, 0x095),
                    state.readRegister(.context, 0x292),
                },
            );
            self.reported_first_scissor_state = true;
        }
        // Exact HTILE fast clears are materialized into the base
        // depth/stencil allocations so later CPU or texture reads never
        // observe stale tiles.
        if (render_state.depth_target) |depth| {
            self.resolveHtileTarget(depth) catch |err| {
                if (log_verbose_gpu) std.debug.print(
                    "[vulkan dcb] HTILE resolve failed @0x{x}: {s}\n",
                    .{ depth.htile_address, @errorName(err) },
                );
            };
        }
        // Depth is attached only when the guest both binds a usable allocation
        // and asks for the test or the write. A title that leaves stale DB
        // registers bound while drawing its UI would otherwise pay for an
        // attachment nothing reads.
        // A targetless packet is replayed later as a VideoOut compositor pass.
        // Its captured DB registers can already belong to the following
        // offscreen phase (Tetris aliases the sampled 4K color source through
        // that stale address). Attaching and clearing it as depth rejects the
        // fullscreen compositor, leaving the exact scanout target black.
        const depth_wanted = target_override == null and
            (render_state.depth_control.test_enabled or
                render_state.depth_control.write_enabled or
                render_state.depth_control.clear_enabled or
                render_state.depth_control.stencil_enabled or
                render_state.depth_control.stencil_clear_enabled);
        var depth_plane: ?GuestDepthTarget = if (depth_wanted) blk: {
            var bound = render_state.depth_target orelse break :blk null;
            // SDK11 can leave DB_DEPTH_SIZE_XY at its reset 1x1 value while
            // the viewport, scissor, and the following sampled-depth descriptor
            // carry the real extent. SharpEmu uses the same conservative
            // recovery: only expand the exact reset sentinel, never an
            // arbitrary undersized attachment.
            if (bound.width == 1 and bound.height == 1) {
                if (recoverResetDepthExtent(&bound, render_state) and
                    (self.traceCurrentGraphicsFrame() or self.depth_only_draw_reports < 8))
                {
                    std.debug.print(
                        "[vulkan dcb] inferred reset depth extent @0x{x}: 1x1 -> {d}x{d}\n",
                        .{
                            if (bound.write_address != 0) bound.write_address else bound.read_address,
                            bound.width,
                            bound.height,
                        },
                    );
                }
            }
            break :blk guestDepthTarget(bound);
        } else null;
        if (depth_wanted and depth_plane == null) {
            if (log_verbose_gpu) std.debug.print(
                "[vulkan dcb] draw: depth requested but not representable (bound={any})\n",
                .{render_state.depth_target != null},
            );
        }
        var bound_colors: [gpu.resources.color_target_count]GuestColorTarget = undefined;
        var bound_color_count: usize = 0;
        var depth_only = false;
        if (target_override) |override| {
            bound_colors[0] = try guestColorTarget(override);
            bound_color_count = 1;
        } else {
            for (render_state.color_targets) |candidate| {
                const descriptor = candidate orelse continue;
                if (!descriptor.isActive()) {
                    if (self.skipped_extra_color_reports < 8) {
                        std.debug.print(
                            "[vulkan dcb] skipping inactive colour slot {d} addr=0x{x} {d}x{d} fmt={d}/{d} write=0x{x}\n",
                            .{
                                descriptor.slot,
                                descriptor.address,
                                descriptor.width,
                                descriptor.height,
                                descriptor.format,
                                descriptor.number_type,
                                descriptor.write_mask,
                            },
                        );
                        self.skipped_extra_color_reports +|= 1;
                    }
                    continue;
                }
                const color = guestColorTarget(descriptor) catch |err| {
                    if (self.skipped_extra_color_reports < 8 or log_verbose_gpu) {
                        std.debug.print(
                            "[vulkan dcb] draw: skipping colour slot {d} addr=0x{x} {d}x{d} fmt={d}/{d}: {s}\n",
                            .{
                                descriptor.slot,
                                descriptor.address,
                                descriptor.width,
                                descriptor.height,
                                descriptor.format,
                                descriptor.number_type,
                                @errorName(err),
                            },
                        );
                        self.skipped_extra_color_reports +|= 1;
                    }
                    continue;
                };
                if (bound_color_count != 0) {
                    const primary = bound_colors[0];
                    if (color.descriptor.width != primary.descriptor.width or
                        color.descriptor.height != primary.descriptor.height)
                    {
                        if (log_verbose_gpu or self.traceCurrentGraphicsFrame()) {
                            std.debug.print(
                                "[vulkan dcb] ignoring mismatched colour slot {d} {d}x{d} for {d}x{d}\n",
                                .{
                                    color.descriptor.slot,
                                    color.descriptor.width,
                                    color.descriptor.height,
                                    primary.descriptor.width,
                                    primary.descriptor.height,
                                },
                            );
                        }
                        continue;
                    }
                    const extra_samples = colorTargetSamplesLog2(color.descriptor) orelse continue;
                    const primary_samples = colorTargetSamplesLog2(primary.descriptor) orelse continue;
                    if (extra_samples != primary_samples) {
                        if (log_verbose_gpu or self.traceCurrentGraphicsFrame()) {
                            std.debug.print(
                                "[vulkan dcb] ignoring colour slot {d} with unmatched samples extra={d} primary={d}\n",
                                .{ color.descriptor.slot, extra_samples, primary_samples },
                            );
                        }
                        continue;
                    }
                    var duplicate = color.descriptor.address == primary.descriptor.address;
                    if (!duplicate) {
                        for (bound_colors[1..bound_color_count]) |bound| {
                            if (bound.descriptor.address == color.descriptor.address) {
                                duplicate = true;
                                break;
                            }
                        }
                    }
                    if (duplicate) continue;
                }
                bound_colors[bound_color_count] = color;
                bound_color_count += 1;
            }
        }
        if (bound_color_count == 0) {
            const plane = depth_plane orelse return Error.MissingColorTarget;
            // Vulkan accepts a fragment shader with its exports masked, but
            // the existing graphics translator and pipeline cache are built
            // around one colour slot. Supply a private compatibility target;
            // drawGraphicsShaders keeps it off guest memory and attaches the
            // persistent depth image below.
            var compatibility = std.mem.zeroes(gpu.resources.ColorTarget);
            compatibility.width = plane.width;
            compatibility.height = plane.height;
            compatibility.depth = 1;
            compatibility.pitch = plane.width;
            compatibility.format = 10; // DATA_FORMAT_8_8_8_8
            compatibility.tile_mode = .render_target;
            compatibility.write_mask = 0;
            bound_colors[0] = try guestColorTarget(compatibility);
            bound_color_count = 1;
            depth_only = true;
            if (self.depth_only_draw_reports < 8 or self.traceCurrentGraphicsFrame()) {
                std.debug.print(
                    "[vulkan dcb] depth-only pass @0x{x} {d}x{d} fmt={d} test={any} write={any}\n",
                    .{
                        plane.address,
                        plane.width,
                        plane.height,
                        plane.guest_format,
                        render_state.depth_control.test_enabled,
                        render_state.depth_control.write_enabled,
                    },
                );
                self.depth_only_draw_reports +|= 1;
            }
        }
        const target = bound_colors[0];
        const extra_colors = bound_colors[1..bound_color_count];
        const descriptor = target.descriptor;
        const color_samples = colorTargetSamplesLog2(descriptor) orelse
            return Error.UnsupportedColorTarget;
        if (depth_plane) |plane| {
            // Vulkan framebuffers cannot be wider or taller than any of their
            // attachments. Guest command streams commonly leave a tiny stale
            // DB allocation bound across fullscreen colour/UI passes; pairing
            // that allocation with the new colour target is invalid and can
            // surface as VK_ERROR_DEVICE_LOST during the draw.
            if (plane.width < descriptor.width or plane.height < descriptor.height) {
                if (log_verbose_gpu or self.traceCurrentGraphicsFrame()) {
                    std.debug.print(
                        "[vulkan dcb] ignoring undersized depth attachment @0x{x} {d}x{d} for color {d}x{d}\n",
                        .{ plane.address, plane.width, plane.height, descriptor.width, descriptor.height },
                    );
                }
                depth_plane = null;
            } else if (plane.samples_log2 != color_samples) {
                if (log_verbose_gpu or self.traceCurrentGraphicsFrame()) {
                    std.debug.print(
                        "[vulkan dcb] ignoring depth attachment with unmatched samples depth={d} color={d}\n",
                        .{ plane.samples_log2, color_samples },
                    );
                }
                depth_plane = null;
            }
        }
        // The persistent target path resolves uniform DCC and CMASK-only
        // clear/expanded blocks during its initial upload. FMASK and other
        // compressed states still fall back to raw tiles rather than blocking
        // otherwise usable title draws.
        if (descriptor.dcc_enabled or descriptor.cmask_fast_clear or descriptor.fmask_compression) {
            if (log_verbose_gpu) std.debug.print(
                "[vulkan dcb] draw metadata dcc={any} cmask={any} fmask={any} fmt={d}\n",
                .{
                    descriptor.dcc_enabled,
                    descriptor.cmask_fast_clear,
                    descriptor.fmask_compression,
                    descriptor.format,
                },
            );
        }
        if (log_verbose_gpu) std.debug.print(
            "[vulkan dcb] draw color format={d} number={d} -> vk={d} bytes_per_texel={d}\n",
            .{ descriptor.format, descriptor.number_type, target.format.vulkan, target.format.bytes_per_texel },
        );
        var pipeline_state = try guestGraphicsState(&render_state, descriptor);
        try applyColorAttachmentState(&pipeline_state, &render_state, bound_colors[0..bound_color_count]);
        pipeline_state.topology = guestPrimitiveTopology(render_state.primitive_type, draw);
        pipeline_state.rasterization_samples = rasterSampleCount(color_samples) orelse
            return Error.UnsupportedColorTarget;
        if (depth_plane) |plane| {
            pipeline_state.depth_attachment_format = plane.format;
            pipeline_state.depth_test_enable = @intFromBool(render_state.depth_control.test_enabled);
            pipeline_state.depth_write_enable = @intFromBool(render_state.depth_control.write_enabled);
            pipeline_state.depth_compare_operation =
                depthCompareOperation(render_state.depth_control.compare_function);
            const stencil_active = plane.has_stencil and render_state.depth_control.stencil_enabled;
            pipeline_state.stencil_test_enable = @intFromBool(stencil_active);
            if (stencil_active) {
                const front_write: u8 = if (render_state.depth_control.stencil_clear_enabled)
                    0
                else
                    render_state.stencil.front.write_mask;
                const back_write: u8 = if (render_state.depth_control.stencil_clear_enabled)
                    0
                else
                    render_state.stencil.back.write_mask;
                pipeline_state.stencil_front_fail = hostStencilOperation(
                    render_state.stencil.front.fail,
                    front_write,
                    render_state.stencil.front.op_value,
                );
                pipeline_state.stencil_front_pass = hostStencilOperation(
                    render_state.stencil.front.pass,
                    front_write,
                    render_state.stencil.front.op_value,
                );
                pipeline_state.stencil_front_depth_fail = hostStencilOperation(
                    render_state.stencil.front.depth_fail,
                    front_write,
                    render_state.stencil.front.op_value,
                );
                pipeline_state.stencil_front_compare =
                    depthCompareOperation(render_state.depth_control.stencil_compare);
                pipeline_state.stencil_front_compare_mask = render_state.stencil.front.compare_mask;
                pipeline_state.stencil_front_write_mask = front_write;
                pipeline_state.stencil_front_reference = render_state.stencil.front.reference;
                if (render_state.depth_control.backface_enabled) {
                    pipeline_state.stencil_back_fail = hostStencilOperation(
                        render_state.stencil.back.fail,
                        back_write,
                        render_state.stencil.back.op_value,
                    );
                    pipeline_state.stencil_back_pass = hostStencilOperation(
                        render_state.stencil.back.pass,
                        back_write,
                        render_state.stencil.back.op_value,
                    );
                    pipeline_state.stencil_back_depth_fail = hostStencilOperation(
                        render_state.stencil.back.depth_fail,
                        back_write,
                        render_state.stencil.back.op_value,
                    );
                    pipeline_state.stencil_back_compare =
                        depthCompareOperation(render_state.depth_control.stencil_compare_back);
                    pipeline_state.stencil_back_compare_mask = render_state.stencil.back.compare_mask;
                    pipeline_state.stencil_back_write_mask = back_write;
                    pipeline_state.stencil_back_reference = render_state.stencil.back.reference;
                } else {
                    pipeline_state.stencil_back_fail = pipeline_state.stencil_front_fail;
                    pipeline_state.stencil_back_pass = pipeline_state.stencil_front_pass;
                    pipeline_state.stencil_back_depth_fail = pipeline_state.stencil_front_depth_fail;
                    pipeline_state.stencil_back_compare = pipeline_state.stencil_front_compare;
                    pipeline_state.stencil_back_compare_mask = pipeline_state.stencil_front_compare_mask;
                    pipeline_state.stencil_back_write_mask = pipeline_state.stencil_front_write_mask;
                    pipeline_state.stencil_back_reference = pipeline_state.stencil_front_reference;
                }
            }
        }
        if (bound_color_count > 1 and !self.reported_mrt_draw) {
            self.reported_mrt_draw = true;
            std.debug.print("[vulkan dcb] multiple colour targets:", .{});
            for (bound_colors[0..bound_color_count]) |color| {
                std.debug.print(
                    " slot{d}@0x{x} {d}x{d} vk={d}",
                    .{
                        color.descriptor.slot,
                        color.descriptor.address,
                        color.descriptor.width,
                        color.descriptor.height,
                        color.format.vulkan,
                    },
                );
            }
            std.debug.print("\n", .{});
        }
        const vertex_address = vertex_stage.programAddress(state) orelse {
            return Error.MissingGraphicsProgram;
        };
        const fragment_address = gpu.resources.ShaderStage.pixel.programAddress(state) orelse {
            return Error.MissingGraphicsProgram;
        };
        if (self.traceCurrentGraphicsFrame()) {
            std.debug.print(
                "[vulkan dcb] draw trace next_flip={d} draw={d} target=0x{x} VS=0x{x} PS=0x{x} indices={any} vertices={d} viewport={d}x{d} scissor={d},{d}+{d}x{d} discard={d} write=0x{x} blend={d} color_mode={d} target_mask=0x{x} clip={any} cb0={any}/{any}/{any}/{any}/{any}\n",
                .{
                    self.flip_callbacks + 1,
                    self.frame_profile.draws,
                    descriptor.address,
                    vertex_address,
                    fragment_address,
                    draw.index_count,
                    draw.vertex_count,
                    @as(f32, @bitCast(pipeline_state.viewport_width_bits)),
                    @as(f32, @bitCast(pipeline_state.viewport_height_bits)),
                    pipeline_state.scissor_x,
                    pipeline_state.scissor_y,
                    pipeline_state.scissor_width,
                    pipeline_state.scissor_height,
                    pipeline_state.rasterizer_discard,
                    pipeline_state.color_write_masks[0],
                    pipeline_state.blend_enables[0],
                    render_state.color_control.mode,
                    render_state.target_mask,
                    state.readRegister(.context, 0x204),
                    state.readRegister(.context, 0x318),
                    state.readRegister(.context, 0x390),
                    state.readRegister(.context, 0x31c),
                    state.readRegister(.context, 0x3b0),
                    state.readRegister(.context, 0x3b8),
                },
            );
        }
        const reader = gpu.ShaderMemoryReader{ .context = memory.context, .read_fn = memory.read };
        const vertex_header = if (memory.shader_header) |resolve|
            resolve(memory.context, vertex_address)
        else
            null;
        const fragment_header = if (memory.shader_header) |resolve|
            resolve(memory.context, fragment_address)
        else
            null;
        const vertex_analysis = self.analyzedProgram(reader, vertex_address, vertex_header) catch |err| {
            traceShaderAnalysisFailure(reader, vertex_stage, vertex_address, vertex_header, err);
            return err;
        };
        const fragment_analysis = self.analyzedProgram(reader, fragment_address, fragment_header) catch |err| {
            traceShaderAnalysisFailure(reader, .pixel, fragment_address, fragment_header, err);
            return err;
        };
        const vertex_bindings = try gpu.ShaderBindings.capture(state, vertex_stage, vertex_header, reader);
        const fragment_bindings = try gpu.ShaderBindings.capture(state, .pixel, fragment_header, reader);
        var vertex_instruction_storage: std.ArrayList(gpu.ShaderInstruction) = .empty;
        defer vertex_instruction_storage.deinit(self.allocator);
        var vertex_instructions = vertex_analysis.program.instructions.items;
        if (vertex_bindings.direct_pointers.fetch_shader) |fetch_address| {
            if (fetch_address != 0 and fetch_address != vertex_address) {
                if (self.analyzedProgram(reader, fetch_address, null)) |fetch_analysis| {
                    if (gpu.shader_analysis.inlineFetchShader(
                        self.allocator,
                        vertex_analysis.program.instructions.items,
                        fetch_analysis.program.instructions.items,
                        &vertex_instruction_storage,
                    ) catch false) {
                        vertex_instructions = vertex_instruction_storage.items;
                    }
                } else |_| {}
            }
        }
        var vertex_export_mask: u64 = 0;
        var vertex_parameter_mask: u32 = 0;
        for (vertex_instructions) |inst| {
            if (inst.opcode != .exp) continue;
            vertex_export_mask |= @as(u64, 1) << inst.export_target;
            if (inst.export_target >= 0x20) {
                vertex_parameter_mask |= @as(u32, 1) << @intCast(inst.export_target - 0x20);
            }
        }
        var fragment_attribute_mask: u32 = 0;
        var fragment_attribute_components: [32]u4 = @splat(0);
        for (fragment_analysis.program.instructions.items) |inst| {
            if (inst.opcode == .exp and inst.export_target < gpu.resources.color_target_count) {
                const needed = @as(u32, inst.export_target) + 1;
                if (needed > pipeline_state.color_attachment_count) {
                    pipeline_state.color_attachment_count = needed;
                }
            }
            switch (inst.opcode) {
                .v_interp_p1_f32, .v_interp_p2_f32, .v_interp_mov_f32 => {
                    if (inst.src1.kind == .integer_inline_constant and inst.src1.value < 32) {
                        const attribute: usize = @intCast(inst.src1.value);
                        fragment_attribute_mask |= @as(u32, 1) << @intCast(attribute);
                        const component_value = if (inst.opcode == .v_interp_mov_f32)
                            inst.src0.value
                        else
                            inst.src2.value;
                        if (component_value < 4) {
                            fragment_attribute_components[attribute] |= @as(u4, 1) << @intCast(component_value);
                        }
                    }
                },
                else => {},
            }
        }
        var fragment_input_controls: [32]u32 = undefined;
        var mapped_fragment_attribute_mask: u32 = 0;
        var parameter_components: [32]u4 = @splat(0);
        for (0..fragment_input_controls.len) |attribute| {
            const control = state.readRegister(.context, 0x191 + @as(u32, @intCast(attribute))) orelse
                @as(u32, @intCast(attribute));
            fragment_input_controls[attribute] = control;
            const attribute_bit = @as(u32, 1) << @intCast(attribute);
            if (fragment_attribute_mask & attribute_bit == 0) continue;
            const parameter: u5 = @truncate(control);
            const parameter_bit = @as(u32, 1) << parameter;
            mapped_fragment_attribute_mask |= parameter_bit;
            parameter_components[parameter] |= fragment_attribute_components[attribute];
        }

        var ngg_lds_exports: [33]gpu.ShaderSpirvNggLdsExport = undefined;
        const ngg_lds_export_count = inferNggLdsExports(
            vertex_instructions,
            &parameter_components,
            &ngg_lds_exports,
        );
        if (ngg_lds_export_count != 0) {
            for (ngg_lds_exports[0..ngg_lds_export_count]) |ngg_export| {
                vertex_export_mask |= @as(u64, 1) << ngg_export.target;
                if (ngg_export.target >= 0x20) {
                    vertex_parameter_mask |= @as(u32, 1) << @intCast(ngg_export.target - 0x20);
                }
            }
        }
        var fragment_parameter_mask: u32 = 0;
        for (0..fragment_input_controls.len) |attribute| {
            const attribute_bit = @as(u32, 1) << @intCast(attribute);
            if (fragment_attribute_mask & attribute_bit == 0) continue;
            const parameter: u5 = @truncate(fragment_input_controls[attribute]);
            if (vertex_parameter_mask & (@as(u32, 1) << parameter) != 0) {
                fragment_parameter_mask |= attribute_bit;
            }
        }
        // NGG export shaders communicate through LDS and therefore expose no
        // ordinary PARAM EXP before their continuation is implemented. For the
        // common single-PARAM fullscreen pass, pair the guest PS with the probe
        // VS's explicit UV location instead of synthesizing interpolation in PS.
        var probe_parameter_mask: u32 = if (vertex_parameter_mask == 0 and fragment_attribute_mask == 1) 1 else 0;
        if (probe_parameter_mask != 0) fragment_input_controls[0] = 0;
        var paired_parameter_mask = if (probe_parameter_mask != 0)
            probe_parameter_mask
        else
            fragment_parameter_mask;
        const trace_interface = self.traceCurrentGraphicsFrame();
        if (trace_interface or
            (self.reported_interface_pairs < 2 and
                (self.last_interface_vertex_address != vertex_address or
                    self.last_interface_fragment_address != fragment_address)))
        {
            std.debug.print(
                "[vulkan dcb] shader interface VS=0x{x} exports=0x{x} params=0x{x} ngg_lds={d} PS=0x{x} attrs=0x{x}->params=0x{x}\n",
                .{ vertex_address, vertex_export_mask, vertex_parameter_mask, ngg_lds_export_count, fragment_address, fragment_attribute_mask, mapped_fragment_attribute_mask },
            );
            var remaining_attributes = fragment_attribute_mask;
            while (remaining_attributes != 0) {
                const attribute: u5 = @intCast(@ctz(remaining_attributes));
                const control = fragment_input_controls[attribute];
                std.debug.print(
                    "  PS attr{d} -> PARAM{d} cntl=0x{x} flat={any}\n",
                    .{ attribute, control & 0x1f, control, control & 0x400 != 0 },
                );
                remaining_attributes &= remaining_attributes - 1;
            }
            if (!trace_interface) {
                self.last_interface_vertex_address = vertex_address;
                self.last_interface_fragment_address = fragment_address;
                self.reported_interface_pairs += 1;
            }
        }
        if (vertex_header == null and memory.shader_header != null) {
            // Registry miss: dump nearby entries once to diagnose mapping gaps.
            std.debug.print(
                "[vulkan dcb] no shader header for VS program 0x{x} stage={s}\n",
                .{ vertex_address, @tagName(vertex_stage) },
            );
        }
        const resource_started = hostTimestampNs();
        var graphics_resources = try self.prepareGraphicsResources(
            &fragment_bindings,
            reader,
            fragment_analysis,
            target,
        );
        defer graphics_resources.deinit(self);
        const fragment_mapping_count = graphics_resources.mapping_count;
        const fragment_image_count = graphics_resources.image_count;
        try self.appendGraphicsResources(
            &graphics_resources,
            &vertex_bindings,
            reader,
            vertex_analysis,
            target,
        );
        self.updateSampledImageDescriptors(
            graphics_resources.images[0..graphics_resources.image_count],
            graphics_resources.mappings[0..graphics_resources.mapping_count],
        );
        self.frame_profile.graphics_resource_ns +|= elapsedHostNanoseconds(resource_started);
        if (self.traceCurrentGraphicsFrame()) {
            for (graphics_resources.mappings[0..graphics_resources.mapping_count]) |mapping| {
                const sampled = graphics_resources.descriptors[@intCast(mapping.descriptor_index)];
                std.debug.print(
                    "[vulkan dcb] traced sampled image draw={d} slot={d} addr=0x{x} {d}x{d} pitch={d} fmt={d} tile={s}\n",
                    .{
                        self.frame_profile.draws,
                        mapping.descriptor_index,
                        sampled.address,
                        sampled.width,
                        sampled.height,
                        sampled.pitch,
                        sampled.unified_format,
                        @tagName(sampled.tile_mode),
                    },
                );
            }
        }

        // Full scalar evaluation (not only the straight prolog cut): vertex
        // programs interleave SMEM loads after a few VALU ops. Preserve each
        // recovered load at its producer PC; a final SGPR snapshot is invalid
        // for NGG shaders which reuse the same registers many times.
        const vertex_provenance_started = hostTimestampNs();
        const vertex_scalar = gpu.scalar_provenance.evaluateDecodedResourceState(
            reader,
            &vertex_bindings,
            vertex_instructions,
        );
        self.frame_profile.scalar_provenance_ns +|= elapsedHostNanoseconds(vertex_provenance_started);
        const vertex_scalar_end: u32 = 0x0010_0000;
        var vertex_scalar_regs: [gpu.scalar_provenance.maximum_scalar_specializations]gpu.ShaderSpirvScalarRegister = undefined;
        var vertex_scalar_count = collectScalarLoadSpecializations(&vertex_scalar, &vertex_scalar_regs);
        vertex_scalar_count = mergeUserDataScalars(
            &vertex_bindings,
            vertex_bindings.scalar_user_data_base,
            &vertex_scalar_regs,
            vertex_scalar_count,
        );
        if (vertex_stage == .export_shader and vertex_scalar_count < vertex_scalar_regs.len) {
            // GFX10 merged shaders reserve s0:s7 for SPI inputs. Unity's NGG
            // prolog reads the active ES/GS lane counts from the low two bytes
            // of s3 before it touches USER_DATA at s8. Vulkan invokes exactly
            // the live vertices, so a full 64/64 wave is the stable equivalent;
            // copying USER_DATA[3] here corrupts EXEC and collapses geometry.
            vertex_scalar_regs[vertex_scalar_count] = .{
                .register = 3,
                .value = 0x0000_4040,
            };
            vertex_scalar_count += 1;
        }
        // Recover attribute V#s from the AGC vertex buffer table into the SGPRs
        // the VS MUBUF instructions name (typically s4 for Unity NGG).
        var vertex_scalar_mut = vertex_scalar;
        vertex_scalar_count = seedVertexBufferScalars(
            &vertex_bindings,
            reader,
            vertex_instructions,
            &vertex_scalar_regs,
            vertex_scalar_count,
            &vertex_scalar_mut,
        );

        const fragment_provenance_started = hostTimestampNs();
        const fragment_scalar = gpu.scalar_provenance.evaluateDecodedResourceState(
            reader,
            &fragment_bindings,
            fragment_analysis.program.instructions.items,
        );
        self.frame_profile.scalar_provenance_ns +|= elapsedHostNanoseconds(fragment_provenance_started);
        const fragment_scalar_end: u32 = 0x0010_0000;
        var fragment_scalar_regs: [gpu.scalar_provenance.maximum_scalar_specializations]gpu.ShaderSpirvScalarRegister = undefined;
        var fragment_scalar_count = collectScalarLoadSpecializations(&fragment_scalar, &fragment_scalar_regs);
        fragment_scalar_count = mergeUserDataScalars(
            &fragment_bindings,
            fragment_bindings.scalar_user_data_base,
            &fragment_scalar_regs,
            fragment_scalar_count,
        );
        // T#/S# descriptor payloads select host descriptor-array elements;
        // they are not shader constants. Specializing their changing guest
        // addresses creates a new Vulkan pipeline for every streamed texture.
        for (graphics_resources.mappings[0..fragment_mapping_count]) |mapping| {
            fragment_scalar_count = removeScalarRegisterRange(
                &fragment_scalar_regs,
                fragment_scalar_count,
                mapping.resource_sgpr,
                8,
            );
            fragment_scalar_count = removeScalarRegisterRange(
                &fragment_scalar_regs,
                fragment_scalar_count,
                mapping.sampler_sgpr,
                4,
            );
        }

        // Attribute / constant buffer MUBUF in the vertex program needs the
        // same storage-descriptor array as compute. Missing V#s are non-fatal:
        // translate without storage and skip MUBUF rather than abort the draw.
        const vertex_storage_started = hostTimestampNs();
        var vertex_storage = self.prepareComputeResources(
            &vertex_bindings,
            reader,
            vertex_analysis,
            vertex_instructions,
            &vertex_scalar_mut,
            vertex_scalar_end,
            null,
        ) catch |err| blk: {
            if (log_verbose_gpu) std.debug.print(
                "[vulkan dcb] vertex storage incomplete: {s}; translating without buffers\n",
                .{@errorName(err)},
            );
            break :blk ComputeResources{};
        };
        self.frame_profile.graphics_storage_ns +|= elapsedHostNanoseconds(vertex_storage_started);
        defer vertex_storage.deinit(self);
        validateVertexIndexMappings(reader, &vertex_storage, draw);
        // V# payloads are runtime descriptor data, not shader constants.  The
        // resource preparation above has already decoded them and assigned
        // stable host descriptor slots.  Leaving their guest addresses in the
        // scalar specialization bakes each streamed vertex buffer into SPIR-V,
        // so sprite-heavy games build a fresh Vulkan pipeline for nearly every
        // draw and again every frame.
        for (vertex_storage.mappings[0..vertex_storage.mapping_count]) |mapping| {
            vertex_scalar_count = removeScalarRegisterRange(
                &vertex_scalar_regs,
                vertex_scalar_count,
                mapping.resource_sgpr,
                4,
            );
        }
        // Detect only the decoder's tightly constrained NV12/I420 layouts so
        // their padded allocation width can be handled without affecting
        // ordinary sampled draws.
        const planar_video = recognizePlanarVideoPass(
            descriptor.width,
            descriptor.height,
            graphics_resources.descriptors[0..fragment_image_count],
        );
        const planar_video_pass = if (planar_video) |video| video.fills_target else false;
        if (planar_video) |video| {
            if (!self.reported_planar_video_pass) {
                std.debug.print(
                    "[vulkan dcb] planar {s} video pass target=0x{x} {d}x{d} luma={d}x{d}/pitch={d} visible={d}x{d}\n",
                    .{
                        video.layoutName(),
                        descriptor.address,
                        descriptor.width,
                        descriptor.height,
                        video.luma.width,
                        video.luma.height,
                        video.luma.pitch,
                        video.source_width,
                        video.source_height,
                    },
                );
                self.reported_planar_video_pass = true;
            }
            if (video.fills_target) {
                if (self.trace_graphics_frame == 0 and self.auto_trace_graphics_frame == null) {
                    self.auto_trace_graphics_frame = self.flip_callbacks +% 121;
                    std.debug.print(
                        "[vulkan dcb] armed delayed video/UI composite trace at flip {d}\n",
                        .{self.auto_trace_graphics_frame.?},
                    );
                }
                self.markVideoSurface(target.descriptor.address);
                self.video_surface_last_flip = self.flip_callbacks;
                // Fullscreen decoder planes use a procedural rectangle. An
                // embedded movie keeps the Unity quad and its placement
                // matrix, while sharing the same NV12/I420 fragment path.
                probe_parameter_mask = 3;
                fragment_input_controls[0] = 0;
                fragment_input_controls[1] = 1;
                paired_parameter_mask = 3;
            }
        }
        if (fragment_image_count == 2 and
            draw.index_count != null and draw.index_count.? == 6 and
            matchesCrtComposite(fragment_analysis.program.instructions.items))
        {
            for (graphics_resources.descriptors[0..fragment_image_count]) |source| {
                if (try self.emulateIntegerScaledSampleBlit(memory, target, source)) {
                    if (!self.reported_crt_composite_fallback) {
                        self.reported_crt_composite_fallback = true;
                        std.debug.print(
                            "[vulkan dcb] emulated CRT composite: 0x{x} {d}x{d} -> 0x{x} {d}x{d}\n",
                            .{
                                source.address,
                                source.width,
                                source.height,
                                target.descriptor.address,
                                target.descriptor.width,
                                target.descriptor.height,
                            },
                        );
                    }
                    return;
                }
            }
        }
        const fullscreen_corner = vertex_stage == .export_shader and
            render_state.primitive_type == 4 and
            isFullscreenCornerTriangle(reader, &vertex_storage, draw);
        if (self.traceCurrentGraphicsFrame() and fragment_image_count == 1 and
            graphics_resources.descriptors[0].unified_format == 50 and
            target.format.vulkan == vk.format_a2b10g10r10_unorm_pack32 and
            hasFullscreenSampleBlitGeometry(draw))
        {
            std.debug.print(
                "[vulkan dcb] traced 10-bit fullscreen PS=0x{x} instructions={d}\n",
                .{ fragment_address, fragment_analysis.program.instructions.items.len },
            );
            dumpShaderHead(fragment_analysis, 96);
        }
        // REANIMAL applies two multi-tap blur passes and one final curve pass
        // to the already complete 10-bit menu image. Their guest full-screen
        // vertex program currently collapses the quad into a magnified strip,
        // destroying the correctly rendered video, logo and UI underneath.
        // Preserve that resident image for these exact pixel-program shapes;
        // the UI remains interactive while the missing blur is preferable to
        // an unreadable frame.
        if (fragment_image_count == 1 and pipeline_state.blend_enables[0] == 0 and
            hasFullscreenSampleBlitGeometry(draw) and
            matchesRgb10MenuPostProcess(fragment_analysis.program.instructions.items) and
            try self.emulateFullscreenSampleBlit(
                memory,
                target,
                graphics_resources.descriptors[0],
                false,
            ))
        {
            // This target now contains the complete menu, not merely the
            // earlier camera/video layer.  Make it the presentation anchor so
            // a stale alternating scanout buffer cannot hide the logo behind
            // a black deferred-composite surface.
            self.deferred_composite_ui_address = target.descriptor.address;
            self.deferred_composite_ui_last_flip = self.flip_callbacks;
            if (!self.reported_rgb10_menu_postprocess_fallback) {
                self.reported_rgb10_menu_postprocess_fallback = true;
                std.debug.print(
                    "[vulkan dcb] preserving complete RGB10 menu across malformed post-process\n",
                    .{},
                );
            }
            return;
        }
        // Tetris keeps the composited UI layer immediately below its packed
        // HDR scene allocation.  Until the title's large deferred-composite
        // pixel program is translated exactly, preserve the already rendered
        // RGBA layer instead of feeding its malformed HDR result into the
        // final tone mapper.
        if (fragment_mapping_count == 4 and paired_parameter_mask == 0xf and
            target.descriptor.width == 3840 and target.descriptor.height == 2160)
        {
            const scene = graphics_resources.descriptors[0];
            if (scene.unified_format == 36 and scene.address >= 0x200_0000) {
                var ui_layer = scene;
                ui_layer.address -= 0x200_0000;
                ui_layer.unified_format = 56;
                if (!self.reported_ui_composite) {
                    if (self.deferred_composite_ui_address != ui_layer.address) {
                        std.debug.print(
                            "[vulkan dcb] deferred-composite presentation anchor @0x{x}\n",
                            .{ui_layer.address},
                        );
                    }
                    self.deferred_composite_ui_address = ui_layer.address;
                    self.deferred_composite_ui_last_flip = self.flip_callbacks;
                }
                if (self.findResidentRenderTargetIndex(ui_layer, vk.format_r8g8b8a8_unorm)) |source_index| {
                    if (try self.blitResidentColorTarget(source_index, target, false) != null) {
                        if (self.flip_callbacks < 24 or log_verbose_gpu) {
                            std.debug.print(
                                "[vulkan dcb] preserved Tetris UI layer: 0x{x} -> 0x{x}\n",
                                .{ ui_layer.address, target.descriptor.address },
                            );
                        }
                        return;
                    }
                }
            }
        }
        // A four-PARAM full-screen pass is not necessarily a copy. Tetris uses
        // this shape for its five-texture tone-map/composite shader. Bypassing
        // it with a copy of descriptor zero discards the UI and post-processing
        // inputs, so only take the copy fast path for the single-image cases
        // below.
        if (fragment_image_count == 1 and fullscreen_corner and
            target.descriptor.width == 3840 and target.descriptor.height == 2160 and
            try self.emulateFullscreenSampleBlit(
                memory,
                target,
                graphics_resources.descriptors[0],
                false,
            ))
        {
            return;
        }
        if (fragment_image_count == 1 and
            hasFullscreenSampleBlitGeometry(draw) and
            matchesFullscreenSampleBlit(fragment_analysis.program.instructions.items))
        {
            const viewport_height: f32 = @bitCast(pipeline_state.viewport_height_bits);
            if (try self.emulateFullscreenSampleBlit(
                memory,
                target,
                graphics_resources.descriptors[0],
                viewport_height < 0,
            )) return;
        }
        if (fragment_attribute_mask == 1 and vertex_storage.mapping_count == 0) {
            probe_parameter_mask = 1;
            fragment_input_controls[0] = 0;
            paired_parameter_mask = 1;
        }
        // prepareComputeResources soft-skips missing V#s; rebuild its scalar
        // list from the seeded specialization so SPIR-V and staging agree.
        if (vertex_storage.scalar_count == 0 and vertex_scalar_count != 0) {
            // already filled from evaluation; merge seeds into result scalars
        }
        for (vertex_scalar_regs[0..vertex_scalar_count]) |seeded| {
            var found = false;
            for (vertex_storage.scalar_registers[0..vertex_storage.scalar_count]) |*entry| {
                if (entry.register == seeded.register and entry.producer_pc == seeded.producer_pc) {
                    entry.value = seeded.value;
                    found = true;
                    break;
                }
            }
            if (!found and vertex_storage.scalar_count < vertex_storage.scalar_registers.len) {
                vertex_storage.scalar_registers[vertex_storage.scalar_count] = seeded;
                vertex_storage.scalar_count += 1;
            }
        }
        if (!self.reported_vertex_storage_bindings) {
            std.debug.print("[vulkan dcb] first vertex storage mappings={d}\n", .{vertex_storage.mapping_count});
            for (vertex_storage.mappings[0..vertex_storage.mapping_count]) |mapping| {
                const slot: usize = @intCast(mapping.descriptor_index);
                std.debug.print(
                    "  pc={any} V#s{d} slot={d} addr=0x{x} size=0x{x} stride={d} fmt={d} dst={any} soffset={any}\n",
                    .{
                        mapping.instruction_pc,
                        mapping.resource_sgpr,
                        mapping.descriptor_index,
                        vertex_storage.addresses[slot],
                        vertex_storage.sizes[slot],
                        mapping.stride,
                        mapping.unified_format,
                        mapping.dst_select,
                        mapping.soffset_value,
                    },
                );
            }
            self.reported_vertex_storage_bindings = true;
        }
        if (log_verbose_gpu) std.debug.print(
            "[vulkan dcb] vertex storage: mappings={d} scalars={d}\n",
            .{ vertex_storage.mapping_count, vertex_storage.scalar_count },
        );
        if (self.shouldReportVertexResources(vertex_address)) {
            std.debug.print(
                "[vulkan dcb] vertex resources program=0x{x} mappings={d} scalars={d} index=0x{x}/{any} vertices={any} cfg={d}/{d} back={d}\n",
                .{
                    vertex_address,
                    vertex_storage.mapping_count,
                    vertex_storage.scalar_count,
                    draw.index_address,
                    draw.index_count,
                    draw.vertex_count,
                    vertex_analysis.graph.blocks.items.len,
                    vertex_analysis.graph.selections.items.len,
                    vertex_analysis.graph.back_edge_count,
                },
            );
            for (vertex_storage.mappings[0..vertex_storage.mapping_count]) |mapping| {
                const slot: usize = @intCast(mapping.descriptor_index);
                std.debug.print(
                    "  pc={any} V#s{d} slot={d} addr=0x{x} size=0x{x} stride={d} fmt={d} dst={any} soffset={any} vertex_attribute={any}\n",
                    .{
                        mapping.instruction_pc,
                        mapping.resource_sgpr,
                        mapping.descriptor_index,
                        vertex_storage.addresses[slot],
                        vertex_storage.sizes[slot],
                        mapping.stride,
                        mapping.unified_format,
                        mapping.dst_select,
                        mapping.soffset_value,
                        mapping.use_vertex_index,
                    },
                );
                if (mapping.use_vertex_index) {
                    var first_record: [8]u32 = undefined;
                    if (reader.readWords(vertex_storage.addresses[slot], &first_record)) |_| {
                        std.debug.print(
                            "    first={x:0>8} {x:0>8} {x:0>8} {x:0>8} as_f32={d:.3},{d:.3},{d:.3},{d:.3}\n",
                            .{
                                first_record[0],
                                first_record[1],
                                first_record[2],
                                first_record[3],
                                @as(f32, @bitCast(first_record[0])),
                                @as(f32, @bitCast(first_record[1])),
                                @as(f32, @bitCast(first_record[2])),
                                @as(f32, @bitCast(first_record[3])),
                            },
                        );
                    } else |_| {}
                }
            }
            if (draw.index_address != 0 and draw.index_count != null and draw.index_count.? != 0) {
                var index_bytes: [16]u8 = undefined;
                if (reader.read(draw.index_address, &index_bytes)) |_| {
                    std.debug.print("  indices", .{});
                    var index: usize = 0;
                    while (index < index_bytes.len) : (index += 2) {
                        std.debug.print(" {d}", .{std.mem.readInt(u16, index_bytes[index..][0..2], .little)});
                    }
                    std.debug.print("\n", .{});
