test "compute local size defaults to one and preserves the programmed count" {
    var state = gpu.State{};
    try std.testing.expectEqual(@as(u32, 1), computeLocalSize(&state, 0x207));
    try state.writeRegister(.shader, 0x207, 0);
    try state.writeRegister(.shader, 0x208, 32);
    try std.testing.expectEqual(@as(u32, 1), computeLocalSize(&state, 0x207));
    try std.testing.expectEqual(@as(u32, 32), computeLocalSize(&state, 0x208));
}

test "thread-dimension dispatches convert to Vulkan workgroup counts" {
    try std.testing.expectEqual(
        [3]u32{ 32_640, 1, 1 },
        dispatchGroupCounts(.{ 2_088_960, 1, 1 }, .{ 64, 1, 1 }, 0x61),
    );
    try std.testing.expectEqual(
        [3]u32{ 2, 3, 4 },
        dispatchGroupCounts(.{ 65, 5, 4 }, .{ 64, 2, 1 }, dispatch_initiator_use_thread_dimensions),
    );
    try std.testing.expectEqual(
        [3]u32{ 0, 1, 1 },
        dispatchGroupCounts(.{ 0, 1, 1 }, .{ 64, 1, 1 }, dispatch_initiator_use_thread_dimensions),
    );
}

test "group-dimension dispatches are preserved" {
    try std.testing.expectEqual(
        [3]u32{ 7, 5, 3 },
        dispatchGroupCounts(.{ 7, 5, 3 }, .{ 64, 2, 1 }, 0x41),
    );
}

test "CRT composite matcher is narrow and rejects an incomplete signature" {
    var instructions = [_]gpu.ShaderInstruction{.{}} ** 32;
    instructions[0].opcode = .v_mul_hi_i32;
    instructions[1].opcode = .v_mul_hi_i32;
    instructions[2].opcode = .v_cvt_flr_i32_f32;
    for (3..8) |index| instructions[index].opcode = .image_sample;
    instructions[8].opcode = .exp;
    instructions[8].export_target = 0;
    instructions[8].export_done = true;
    try std.testing.expect(matchesCrtComposite(&instructions));
    instructions[1].opcode = .v_mul_hi_u32;
    try std.testing.expect(!matchesCrtComposite(&instructions));
}

test "NGG LDS export inference accepts dynamic clip depth" {
    const reg = struct {
        fn make(kind: gpu.ShaderOperandKind, index: u32) gpu.ShaderOperand {
            return .{ .kind = kind, .reg = index };
        }
    }.make;
    var instructions = [_]gpu.ShaderInstruction{.{}} ** 3;
    instructions[0] = .{
        .opcode = .ds_write_b128,
        .src0 = reg(.vgpr, 0),
        .src1 = reg(.vgpr, 10),
        .memory_offset = 0,
    };
    instructions[1] = .{
        .opcode = .ds_write_b96,
        .src0 = reg(.vgpr, 0),
        .src1 = reg(.vgpr, 14),
        .memory_offset = 16,
    };
    instructions[2] = .{
        .opcode = .s_setpc_b64,
        .src0 = reg(.sgpr, 6),
    };
    var parameter_components: [32]u4 = @splat(0);
    parameter_components[0] = 0x7;
    var exports: [33]gpu.ShaderSpirvNggLdsExport = undefined;
    const count = inferNggLdsExports(&instructions, &parameter_components, &exports);
    try std.testing.expectEqual(@as(usize, 2), count);
    try std.testing.expectEqual(@as(u32, 10), exports[0].sources[0].reg);
    try std.testing.expectEqual(@as(u32, 11), exports[0].sources[1].reg);
    try std.testing.expectEqual(@as(u32, 15), exports[0].sources[2].reg);
    try std.testing.expectEqual(@as(u32, 16), exports[0].sources[3].reg);
    try std.testing.expectEqual(@as(u8, 0x7), exports[1].enable);
}

