test "NGG auto rectangle uses a triangle strip topology" {
    try std.testing.expectEqual(
        vk.primitive_topology_triangle_strip,
        guestPrimitiveTopology(7, .{ .vertex_count = 4 }),
    );
    try std.testing.expectEqual(
        vk.primitive_topology_triangle_list,
        guestPrimitiveTopology(7, .{ .index_count = 6 }),
    );
    try std.testing.expectEqual(
        vk.primitive_topology_triangle_list,
        guestPrimitiveTopology(4, .{ .vertex_count = 3 }),
    );
    try std.testing.expectEqual(
        @as(u32, 0),
        rectangleCompletionMode(.export_shader, 4, .{ .index_count = 3 }, false),
    );
    try std.testing.expectEqual(
        @as(u32, 0),
        rectangleCompletionMode(.vertex, 4, .{ .index_count = 3 }, false),
    );
    try std.testing.expectEqual(
        @as(u32, 1),
        rectangleCompletionMode(.vertex, 17, .{ .vertex_count = 3 }, false),
    );
    try std.testing.expectEqual(
        @as(u32, 2),
        rectangleCompletionMode(.export_shader, 4, .{ .index_count = 3 }, true),
    );
    try std.testing.expectEqual(
        @as(u32, 0),
        rectangleCompletionMode(.vertex, 4, .{ .index_count = 3 }, true),
    );

    const ngg = expandRectangleListDraw(7, .{ .vertex_count = 3, .first_vertex = 9 });
    try std.testing.expectEqual(@as(u32, 4), ngg.vertex_count);
    try std.testing.expectEqual(@as(u32, 9), ngg.first_vertex);
    const legacy = expandRectangleListDraw(17, .{ .vertex_count = 3 });
    try std.testing.expectEqual(@as(u32, 4), legacy.vertex_count);
    const indexed = expandRectangleListDraw(7, .{ .vertex_count = 3, .index_count = 3 });
    try std.testing.expectEqual(@as(u32, 3), indexed.vertex_count);
}

test "direct indexed draw honors persistent index type" {
    const body = [_]u32{ 0xffff, 0x1234_5000, 0x20, 6, 0 };
    const packet = gpu.pm4.Packet{
        .kind = .command,
        .opcode = gpu.pm4.draw_index_2,
        .header = 0,
        .body = &body,
    };
    var state = gpu.State{};
    state.instance_count = 5;
    try state.writeRegister(.uconfig, 0x24a, @bitCast(@as(i32, -7)));

    const u16_draw = Renderer.decodeDirectGuestDraw(packet, &state).?;
    try std.testing.expect(!u16_draw.index_uint32);
    try std.testing.expectEqual(@as(u32, 5), u16_draw.instance_count);
    try std.testing.expectEqual(@as(i32, -7), u16_draw.vertex_offset);
    try std.testing.expectEqual(@as(u64, 0x20_1234_5000), u16_draw.index_address);
    try std.testing.expectEqual(@as(?u32, 6), u16_draw.index_count);

    state.index_type = 1;
    const u32_draw = Renderer.decodeDirectGuestDraw(packet, &state).?;
    try std.testing.expect(u32_draw.index_uint32);

    const multi_body = [_]u32{
        12,
        0xabcd_0000,
        0x20,
        3,
        0x1111_0000,
        0x20,
        3,
        0x80,
    };
    const multi_packet = gpu.pm4.Packet{
        .kind = .command,
        .opcode = gpu.pm4.dispatch_draw_preamble,
        .header = 0,
        .body = &multi_body,
    };
    const multi = Renderer.decodeDirectGuestDraw(multi_packet, &state).?;
    try std.testing.expectEqual(@as(?u32, 12), multi.index_count);
    try std.testing.expectEqual(@as(u32, 3), multi.instance_count);
    try std.testing.expectEqual(@as(u64, 0x20_abcd_0000), multi.index_address);
    try std.testing.expect(multi.index_uint32);
}

test "depth attachment formats follow the stored precision" {
    var descriptor = std.mem.zeroes(gpu.resources.DepthTarget);
    descriptor.format = 1;
    try std.testing.expectEqual(@as(?u32, vk.format_d16_unorm), depthTargetFormat(descriptor));
    descriptor.format = 3;
    try std.testing.expectEqual(@as(?u32, vk.format_d32_sfloat), depthTargetFormat(descriptor));
    // A precision this path cannot reproduce is refused rather than rounded to
    // a nearby one, which would silently change which fragments survive.
    descriptor.format = 2;
    try std.testing.expectEqual(@as(?u32, null), depthTargetFormat(descriptor));
}

test "depth attachments can be sampled through matching scalar formats" {
    try std.testing.expect(depthSampledFormatCompatible(vk.format_d16_unorm, vk.format_r16_unorm));
    try std.testing.expect(depthSampledFormatCompatible(vk.format_d32_sfloat, vk.format_r32_sfloat));
    try std.testing.expect(!depthSampledFormatCompatible(vk.format_d32_sfloat, vk.format_r16_unorm));
    try std.testing.expect(!depthSampledFormatCompatible(vk.format_r32_sfloat, vk.format_r32_sfloat));
}

test "integrated Vulkan device preference reverses the default adapter order" {
    try std.testing.expect(
        physicalDeviceScore(vk.physical_device_type_discrete_gpu, false) >
            physicalDeviceScore(vk.physical_device_type_integrated_gpu, false),
    );
    try std.testing.expect(
        physicalDeviceScore(vk.physical_device_type_integrated_gpu, true) >
            physicalDeviceScore(vk.physical_device_type_discrete_gpu, true),
    );
}

test "guest depth compare selectors map onto the host operations" {
    // Both enumerations run never, less, equal, less-or-equal, greater,
    // not-equal, greater-or-equal, always.
    for (0..8) |function| {
        try std.testing.expectEqual(
            @as(u32, @intCast(function)),
            depthCompareOperation(@intCast(function)),
        );
    }
}

test "a depth attachment keeps its sample count and packed stencil format" {
    var descriptor = std.mem.zeroes(gpu.resources.DepthTarget);
    descriptor.format = 3;
    descriptor.width = 1920;
    descriptor.height = 1080;
    descriptor.write_address = 0x2000;

    const plane = Renderer.guestDepthTarget(descriptor) orelse return error.TestFailed;
    try std.testing.expectEqual(@as(u64, 0x2000), plane.address);
    try std.testing.expectEqual(vk.format_d32_sfloat, plane.format);
    try std.testing.expectEqual(@as(u8, 0), plane.samples_log2);
    try std.testing.expect(!plane.has_stencil);

    var multisample = descriptor;
    multisample.samples_log2 = 2;
    const msaa = Renderer.guestDepthTarget(multisample) orelse return error.TestFailed;
    try std.testing.expectEqual(@as(u8, 2), msaa.samples_log2);
    try std.testing.expectEqual(vk.format_d32_sfloat, msaa.format);

    var with_stencil = descriptor;
    with_stencil.stencil_format = 1;
    with_stencil.stencil_read_address = 0x4000;
    const packed_plane = Renderer.guestDepthTarget(with_stencil) orelse return error.TestFailed;
    try std.testing.expect(packed_plane.has_stencil);
    try std.testing.expectEqual(vk.format_d32_sfloat_s8_uint, packed_plane.format);

    var depth16 = descriptor;
    depth16.format = 1;
    depth16.stencil_format = 1;
    depth16.stencil_read_address = 0x4000;
    const packed16 = Renderer.guestDepthTarget(depth16) orelse return error.TestFailed;
    try std.testing.expectEqual(vk.format_d24_unorm_s8_uint, packed16.format);

    var rejected = descriptor;
    rejected.samples_log2 = 4;
    try std.testing.expect(Renderer.guestDepthTarget(rejected) == null);

    // Read-only bindings still name the allocation through the read address.
    var read_only = descriptor;
    read_only.write_address = 0;
    read_only.read_address = 0x3000;
    const fallback = Renderer.guestDepthTarget(read_only) orelse return error.TestFailed;
    try std.testing.expectEqual(@as(u64, 0x3000), fallback.address);
}

test "D16 guest depth round-trips through packed D24 transfer words" {
    const guest = [_]u8{ 0, 0, 0, 0x80, 0xff, 0xff };
    var transfer_words: [12]u8 = undefined;
    try std.testing.expect(expandDepth16To24(&guest, &transfer_words));
    try std.testing.expectEqual(@as(u32, 0), std.mem.readInt(u32, transfer_words[0..4], .little));
    try std.testing.expectEqual(@as(u32, 0x00ff_ffff), std.mem.readInt(u32, transfer_words[8..12], .little));
    var restored: [6]u8 = undefined;
    try std.testing.expect(compactDepth24To16(&transfer_words, &restored));
    try std.testing.expectEqualSlices(u8, &guest, &restored);
}

test "depth transfer plan separates and aligns a stencil plane" {
    const target = GuestDepthTarget{
        .address = 0x1000,
        .allocation_bytes = 64,
        .width = 3,
        .height = 2,
        .guest_format = 1,
        .format = vk.format_d24_unorm_s8_uint,
        .tile_mode = .linear,
        .base_array_slice = 0,
        .mip_level = 0,
        .has_stencil = true,
        .clear_depth = 1,
    };
    const plan = depthTransferPlan(target).?;
    try std.testing.expectEqual(@as(usize, 24), plan.depth_bytes);
    try std.testing.expectEqual(@as(usize, 24), plan.stencil_offset);
    try std.testing.expectEqual(@as(usize, 6), plan.stencil_bytes);
    try std.testing.expectEqual(@as(usize, 30), plan.total_bytes);
}

test "frame upload ring aligns snapshots and rejects overflow" {
    var cursor: usize = 0;
    try std.testing.expectEqual(@as(?usize, 0), reserveAlignedRange(&cursor, 1024, 17, 256));
    try std.testing.expectEqual(@as(usize, 17), cursor);
    try std.testing.expectEqual(@as(?usize, 256), reserveAlignedRange(&cursor, 1024, 32, 256));
    try std.testing.expectEqual(@as(usize, 288), cursor);
    try std.testing.expectEqual(@as(?usize, null), reserveAlignedRange(&cursor, 300, 32, 256));
    try std.testing.expectEqual(@as(usize, 288), cursor);
}

test "guest stencil operations map to the host set the rasterizer can run" {
    try std.testing.expectEqual(vk.stencil_op_keep, hostStencilOperation(0, 0xff, 0));
    try std.testing.expectEqual(vk.stencil_op_zero, hostStencilOperation(1, 0xff, 0));
    try std.testing.expectEqual(vk.stencil_op_replace, hostStencilOperation(3, 0xff, 0));
    try std.testing.expectEqual(vk.stencil_op_replace, hostStencilOperation(4, 0xff, 0xaa));
    try std.testing.expectEqual(vk.stencil_op_increment_and_clamp, hostStencilOperation(5, 0xff, 0));
    try std.testing.expectEqual(vk.stencil_op_decrement_and_clamp, hostStencilOperation(6, 0xff, 0));
    try std.testing.expectEqual(vk.stencil_op_invert, hostStencilOperation(7, 0xff, 0));
    try std.testing.expectEqual(vk.stencil_op_increment_and_wrap, hostStencilOperation(8, 0xff, 0));
    try std.testing.expectEqual(vk.stencil_op_decrement_and_wrap, hostStencilOperation(9, 0xff, 0));
    try std.testing.expectEqual(vk.stencil_op_invert, hostStencilOperation(0xc, 0x0f, 0x0f));
    try std.testing.expectEqual(vk.stencil_op_keep, hostStencilOperation(0xc, 0xff, 0x0f));
    try std.testing.expectEqual(vk.stencil_op_keep, hostStencilOperation(5, 0, 0));
}

test "color attachments keep matching sample and fragment counts" {
    var descriptor = std.mem.zeroes(gpu.resources.ColorTarget);
    descriptor.samples_log2 = 2;
    descriptor.fragments_log2 = 2;
    try std.testing.expectEqual(@as(u8, 2), colorTargetSamplesLog2(descriptor).?);
    try std.testing.expectEqual(vk.sample_count_4_bit, rasterSampleCount(2).?);

    descriptor.fragments_log2 = 1;
    try std.testing.expect(colorTargetSamplesLog2(descriptor) == null);
    try std.testing.expect(rasterSampleCount(4) == null);
}

test "depth allocations compare by surface, not by clear value" {
    const base = GuestDepthTarget{
        .address = 0x4000,
        .allocation_bytes = 1280 * 720 * 4,
        .width = 1280,
        .height = 720,
        .guest_format = 3,
        .format = vk.format_d32_sfloat,
        .tile_mode = .depth,
        .base_array_slice = 0,
        .mip_level = 0,
        .clear_depth = 1.0,
    };
    var recleared = base;
    recleared.clear_depth = 0.0;
    try std.testing.expect(base.sameAllocation(recleared));

    var resized = base;
    resized.height = 1080;
    try std.testing.expect(!base.sameAllocation(resized));
}
